def bool_from_config(value, default: bool) -> bool:
    """Parse permissive bool config without making YAML null mean false."""
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.lower() in ("1", "true", "yes", "on")
    return bool(value)


