compat_cfg = config.get("model_compatibility", {})
MODEL_COMPAT_ENABLED = bool_from_config(
    get_env("AZIZAM_MODEL_COMPAT_ENABLED", compat_cfg.get("enabled")),
    True,
)
OPENAI_MODEL_ALIASES_FILE = config_path(
    os.environ.get("OPENAI_MODEL_ALIASES_FILE", compat_cfg.get("generated_aliases_file")),
    "openai_model_aliases.generated.yml",
)
OPENAI_MODELS_API_URL = compat_cfg.get("openai_models_api_url", "https://api.openai.com/v1/models")
OPENAI_MODEL_DISCOVERY_INCLUDE_PRIVATE = bool_from_config(
    os.environ.get("OPENAI_MODEL_DISCOVERY_INCLUDE_PRIVATE", compat_cfg.get("include_private")),
    False,
)
MODEL_COMPAT_DEFAULTS = compat_cfg.get("defaults", {})
MODEL_COMPAT_ALIASES = compat_cfg.get("aliases", {})
TTS_BACKEND_MODEL = MODEL_COMPAT_DEFAULTS.get("speech") or tts_cfg.get("default_model", "mistralai/Voxtral-4B-TTS-2603")
SUPPORTED_TTS_RESPONSE_FORMATS = {"wav", "mp3", "opus", "aac", "flac", "pcm"}
TTS_RESPONSE_MEDIA_TYPES = {
    "wav": "audio/wav",
    "mp3": "audio/mpeg",
    "opus": "audio/ogg",
    "aac": "audio/aac",
    "flac": "audio/flac",
    "pcm": "audio/pcm",
}
STT_BACKEND_MODEL = MODEL_COMPAT_DEFAULTS.get("transcriptions") or stt_cfg.get("default_model", "parakeet-tdt-0.6b-v3")
EMBEDDINGS_MODEL = MODEL_COMPAT_DEFAULTS.get("embeddings") or EMBEDDINGS_BACKEND_MODEL
IMAGE_EDIT_DEFAULT_MODEL = MODEL_COMPAT_DEFAULTS.get("image_edits", "qwen-image-2.1-edit")

OPENAI_STATIC_MODEL_CATEGORIES = {
    "dall-e-2": "images",
    "dall-e-3": "images",
    "tts-1": "speech",
    "tts-1-hd": "speech",
    "whisper-1": "transcriptions",
}

OPERATION_COMPATIBLE_CATEGORIES = {
    "chat": {"chat", "unknown"},
    "completions": {"chat", "unknown"},
    "embeddings": {"embeddings", "unknown"},
    "speech": {"speech", "unknown"},
    "transcriptions": {"transcriptions", "unknown"},
    "translations": {"transcriptions", "translations", "unknown"},
    "images": {"images", "unknown"},
    "image_edits": {"images", "unknown"},
    # `video` is the OpenAI category for sora-* models (see infer_openai_model_category).
    # Local Wan/LTX names without an OpenAI category fall through as "unknown".
    "videos": {"video", "unknown"},
}
OPENAI_PUBLIC_MODEL_OWNERS = {"openai", "openai-internal", "system"}


class ModelCompatibilityError(Exception):
    def __init__(self, message: str = "", *, code: str | None = None, details: Mapping[str, Any] | None = None):
        super().__init__(message)
        self.code = code
        self.details = dict(details or {})


@dataclass(frozen=True)
class ModelResolution:
    requested_model: str
    effective_model: str
    operation: str
    category: Optional[str] = None
    is_openai_alias: bool = False
    # Set when the name came from the two-layer alias table (model_aliases).
    alias: Optional[stable_aliases.AliasResolution] = None


def normalize_model_id(model_name: str) -> str:
    return (model_name or "").strip().lower()


def load_generated_openai_model_aliases() -> dict[str, str]:
    """Load generated OpenAI model IDs and their inferred categories."""
    if not OPENAI_MODEL_ALIASES_FILE.exists():
        return {}

    try:
        with open(OPENAI_MODEL_ALIASES_FILE) as f:
            data = yaml.safe_load(f) or {}
    except Exception as e:
        print(f"[proxy] Warning: Failed to load OpenAI model aliases: {e}", flush=True)
        return {}

    aliases = {}
    models = data.get("models", []) if isinstance(data, dict) else []
    for item in models:
        if not isinstance(item, dict):
            continue
        model_id = normalize_model_id(item.get("id", ""))
        if model_id:
            aliases[model_id] = item.get("category") or "unknown"
    return aliases


def configured_model_alias_category(model_name: str) -> Optional[str]:
    if not isinstance(MODEL_COMPAT_ALIASES, dict):
        return None

    alias_cfg = MODEL_COMPAT_ALIASES.get(model_name) or MODEL_COMPAT_ALIASES.get(normalize_model_id(model_name))
    if isinstance(alias_cfg, dict):
        return alias_cfg.get("category") or alias_cfg.get("operation")
    if isinstance(alias_cfg, str):
        return alias_cfg
    return None


def infer_openai_model_category(model_name: str) -> Optional[str]:
    """Infer an OpenAI model family from stable naming conventions."""
    model_id = normalize_model_id(model_name)
    if not model_id:
        return None

    configured_category = configured_model_alias_category(model_id)
    if configured_category:
        return configured_category

    if model_id in OPENAI_STATIC_MODEL_CATEGORIES:
        return OPENAI_STATIC_MODEL_CATEGORIES[model_id]

    if model_id.startswith(("dall-e-", "gpt-image-")) or model_id.startswith("chatgpt-image"):
        return "images"

    if "embedding" in model_id:
        return "embeddings"

    if "transcribe" in model_id or "diarize" in model_id or model_id.startswith("whisper"):
        return "transcriptions"

    if model_id.startswith("tts-") or model_id.endswith("-tts") or "-tts-" in model_id:
        return "speech"

    if model_id.startswith("sora"):
        return "video"

    if "moderation" in model_id:
        return "moderation"

    if "deep-research" in model_id:
        return "deep_research"

    if model_id.startswith(("gpt-", "chatgpt-", "o1", "o3", "o4", "codex-", "computer-use-")):
        if "realtime" in model_id or model_id.startswith("gpt-audio"):
            return "audio_chat"
        return "chat"

    generated_aliases = load_generated_openai_model_aliases()
    return generated_aliases.get(model_id)


def is_openai_model_alias(model_name: str) -> bool:
    return infer_openai_model_category(model_name) is not None


def default_model_for_operation(operation: str, requested_model: str = "") -> str:
    configured_default = MODEL_COMPAT_DEFAULTS.get(operation)
    if configured_default:
        return configured_default

    if operation in ("chat", "completions"):
        return requested_model
    if operation == "speech":
        return TTS_BACKEND_MODEL
    if operation == "transcriptions":
        return STT_BACKEND_MODEL
    if operation == "translations":
        return STT_BACKEND_MODEL
    if operation == "images":
        return COMFY_DEFAULT_MODEL
    if operation == "image_edits":
        return IMAGE_EDIT_DEFAULT_MODEL
    if operation == "videos":
        return VIDEO_DEFAULT_WORKFLOW
    if operation == "embeddings":
        return EMBEDDINGS_MODEL if EMBEDDINGS_ENABLED else ""
    return requested_model


def _alias_engine_available_for(operation: str) -> stable_aliases.EngineAvailable:
    """Engine is usable when its service is enabled in the live registry.

    STT routing follows the multipart ``model``, from an early peek or the
    parsed upload, so any enabled service is served by its own backend.
    """

    def available(_engine_id: str, spec: Mapping[str, Any]) -> bool:
        service_id = str(spec.get("service") or "")
        service = (config.get("backends") or {}).get(service_id)
        if not isinstance(service, Mapping):
            return False
        if not bool_from_config(service.get("enabled"), True):
            return False
        if service_registry.is_remote_provider_config(service):
            return True
        if not service.get("host") or not service.get("port"):
            return False
        return True

    return available


def resolve_stable_alias(
    operation: str, requested_model: Any
) -> stable_aliases.AliasResolution | None:
    """Resolve through ``model_aliases``; raises AliasUnavailableError."""
    if isinstance(requested_model, str):
        provider_id, separator, _ = requested_model.partition("/")
        if separator:
            if providers.canonical_provider_id(provider_id) in providers.provider_refs(ADMIN_STORE.get_service_registry()):
                return None
            # Only a prefix that is no known provider is looked up among the services the registry leaves out.
            left_out = next((item for item in ADMIN_STORE.get_service_registry_exclusions()
                             if item.section == "services" and item.id == service_registry.normalize_id(provider_id)), None)
            if left_out is not None:
                raise stable_aliases.AliasUnavailableError(
                    f"Service {left_out.id!r} is left out of the gateway's registry because it does not validate "
                    f"({left_out.error}). The operator can fix or remove it under Services.",
                    code="model_not_deployed", details={"service": left_out.id},
                )
    return stable_aliases.resolve_alias(
        config.get("model_aliases"),
        operation,
        requested_model,
        engine_available=_alias_engine_available_for(operation),
    )


def resolve_model_for_operation(operation: str, requested_model: str) -> ModelResolution:
    """Resolve public OpenAI model names to local operation defaults."""
    try:
        alias = resolve_stable_alias(operation, requested_model)
    except stable_aliases.AliasUnavailableError as exc:
        raise ModelCompatibilityError(str(exc), code=exc.code, details=exc.details) from exc
    if alias is not None:
        return ModelResolution(
            requested_model=requested_model,
            effective_model=(alias.upstream_model if alias.engine else alias.target) or alias.target,
            operation=operation,
            category=stable_aliases.section_for_operation(operation),
            is_openai_alias=True,
            alias=alias,
        )
    # Speech only accepts names declared by the alias data above. Passing an
    # unknown name through here used to select the configured default engine,
    # which made a typo look like a successful request to a different model.
    if operation in {"speech", "transcriptions", "translations"}:
        raise ModelCompatibilityError(
            f"Model '{requested_model}' is not available for {operation} requests.",
            code="model_not_found",
        )
    if not MODEL_COMPAT_ENABLED or not requested_model:
        return ModelResolution(
            requested_model=requested_model,
            effective_model=requested_model,
            operation=operation,
        )

    category = infer_openai_model_category(requested_model)
    if not category:
        return ModelResolution(
            requested_model=requested_model,
            effective_model=requested_model,
            operation=operation,
        )

    compatible_categories = OPERATION_COMPATIBLE_CATEGORIES.get(operation, set())
    if category not in compatible_categories:
        raise ModelCompatibilityError(
            f"Model '{requested_model}' is an OpenAI {category} model and cannot be used for {operation} requests."
        )

    effective_model = default_model_for_operation(operation, requested_model)
    if not effective_model:
        raise ModelCompatibilityError(
            f"No local default model is configured for {operation} requests."
        )

    return ModelResolution(
        requested_model=requested_model,
        effective_model=effective_model,
        operation=operation,
        category=category,
        is_openai_alias=True,
    )


def model_compatibility_error(error: "str | Exception") -> Response:
    code = getattr(error, "code", None)
    status_code = 503 if code == "model_not_deployed" else 404 if code == "model_not_found" else 400
    body: dict[str, Any] = {
        "message": str(error),
        "type": "service_unavailable" if status_code == 503 else "invalid_request_error",
    }
    if code:
        body["param"] = "model"
        body["code"] = code
    details = getattr(error, "details", None)
    if details:
        body["details"] = details
    return Response(
        content=json.dumps({"error": body}),
        status_code=status_code,
        media_type="application/json",
    )


def openai_error_response(
    message: str,
    *,
    status_code: int = 400,
    error_type: str = "invalid_request_error",
    param: str | None = None,
    code: str | None = None,
) -> Response:
    # OpenAI error objects always carry all four keys; param and code are null when not applicable.
    error: dict[str, Any] = {
        "message": message,
        "type": error_type,
        "param": param,
        "code": code,
    }
    return Response(
        content=json.dumps({"error": error}),
        status_code=status_code,
        media_type="application/json",
    )


def parse_openai_json_body(body: bytes) -> tuple[dict[str, Any] | None, Response | None]:
    try:
        body_json = json.loads(body)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return None, openai_error_response(
            "Malformed JSON body.",
            status_code=400,
            error_type="invalid_request_error",
            code="invalid_json",
        )
    if not isinstance(body_json, dict):
        return None, openai_error_response(
            "JSON body must be an object.",
            status_code=400,
            error_type="invalid_request_error",
            code="invalid_request",
        )
    return body_json, None


def _service_model_records(service_cfg: Mapping[str, Any]) -> list[Mapping[str, Any]]:
    return _pure_service_model_records(service_cfg)


@dataclass(frozen=True)
class LocalModelActivation:
    """Resolved identity and backend-facing name for one local model target."""

    backend: str
    model: Optional[str]
    mmproj: Optional[str] = None
    profile: Optional[str] = None
    backend_model: Optional[str] = None
    offering_id: Optional[str] = None


def _lifecycle_driver_config(service_cfg: Mapping[str, Any] | None) -> Mapping[str, Any]:
    """The service's lifecycle ``driver_config`` (service data), or an empty mapping."""
    lifecycle = service_cfg.get("lifecycle") if isinstance(service_cfg, Mapping) else None
    driver_config = lifecycle.get("driver_config") if isinstance(lifecycle, Mapping) else None
    return driver_config if isinstance(driver_config, Mapping) else {}


def _backend_default_model_to_load(backend: str) -> Optional[str]:
    backend_cfg = (config.get("backends") or {}).get(backend, {})
    if not isinstance(backend_cfg, Mapping):
        return None
    configured = str(
        backend_cfg.get("activation_model")
        or backend_cfg.get("model_id")
        or backend_cfg.get("default_model")
        or ""
    ).strip()
    if configured:
        return configured
    return None


def _configured_litellm_local_model_target(
    requested_model: str,
    *,
    service_id: str | None = None,
) -> Optional[LocalModelActivation]:
    """Return the local backend activation target for a LiteLLM model group.

    LiteLLM owns execution, but the gateway still owns local service readiness.
    This helper recognizes model groups generated from local service data and
    returns the backend/model/mmproj/profile that must be hot before forwarding.
    Unknown model groups are left for LiteLLM to handle.
    """
    normalized = normalize_model_id(requested_model)
    backends = config.get("backends") if isinstance(config.get("backends"), Mapping) else {}

    for backend in LLM_BACKEND_HOSTS:
        if service_id is not None and backend != service_id:
            continue
        service_cfg = backends.get(backend, {})
        if not isinstance(service_cfg, Mapping):
            continue

        service_model = str(service_cfg.get("model_id") or "").strip()
        if service_model and normalize_model_id(service_model) == normalized:
            profile = str(service_cfg.get("activation_profile") or "").strip()
            return LocalModelActivation(
                backend=backend,
                model=_backend_default_model_to_load(backend),
                profile=profile or None,
            )

        for item in _service_model_records(service_cfg):
            # LiteLLM registers one public route name per deployment. Match
            # that exact name so unknown aliases do not trigger local backend
            # activation before LiteLLM rejects them.
            registered_name = str(
                item.get("model_group")
                or item.get("id")
                or item.get("upstream_model")
                or ""
            ).strip()
            if normalize_model_id(registered_name) != normalized:
                continue

            activation_model = str(
                item.get("activation_model")
                or item.get("model_path")
                or item.get("path")
                or ""
            ).strip()
            activation_mmproj = str(
                item.get("activation_mmproj")
                or item.get("mmproj")
                or ""
            ).strip()
            activation_profile = str(item.get("activation_profile") or "").strip()
            if (
                _lifecycle_driver_config(service_cfg).get("activation_requires_absolute_path") is True
                and activation_model
                and not os.path.isabs(activation_model)
            ):
                activation_model = ""
            return LocalModelActivation(
                backend=backend,
                model=activation_model or None,
                mmproj=activation_mmproj or None,
                profile=activation_profile or None,
            )

    return None


def _litellm_activation_failure_response(
    *,
    requested_model: str,
    backend: str,
    target_model: Optional[str],
) -> Response:
    return Response(
        content=json.dumps({
            "error": {
                "message": (
                    f"Failed to satisfy request for model '{requested_model}': "
                    f"could not start backend '{backend}'"
                    + (f" or load model '{target_model}'." if target_model else ".")
                ),
                "type": "service_unavailable",
                "code": "backend_unavailable",
            }
        }),
        status_code=503,
        media_type="application/json",
        headers={"Retry-After": "10"},
    )


async def _ensure_litellm_local_backend_target(
    auth_context: AuthContext,
    *,
    requested_model: str,
    backend: Optional[str],
    target_model: Optional[str],
    target_mmproj: Optional[str] = None,
    target_profile: Optional[str] = None,
    enforce_gateway_policy: bool = True,
) -> Response | None:
    if not backend:
        return None
    availability = (await asyncio.to_thread(_service_availability_response, backend, service_label=backend))
    if availability is not None:
        return availability
    try:
        ready = await ensure_target(
            backend,
            target_model,
            target_mmproj,
            profile=target_profile,
        )
    except SwapDeferred as deferred:
        return _swap_deferred_response(requested_model, deferred)
    except SwapRecoveryFailed as failed:
        return _swap_recovery_failed_response(requested_model, failed)
    if ready:
        return None
    return _litellm_activation_failure_response(
        requested_model=requested_model,
        backend=backend,
        target_model=target_model,
    )


async def _prepare_litellm_local_llm_request(
    auth_context: AuthContext,
    *,
    request_path: str,
    body_json: Mapping[str, Any],
    enforce_gateway_policy: bool = True,
    activate_target: bool = True,
) -> tuple[Response | None, Mapping[str, Any]]:
    """Apply gateway-owned local readiness before LiteLLM execution.

    Unknown model names are intentionally not rejected here: they may be model
    groups supplied by a non-local LiteLLM provider. Only gateway-declared local
    targets are activated.
    """
    body = copy.deepcopy(dict(body_json))
    model_name = body.get("model", "")
    if not isinstance(model_name, str) or not model_name:
        return openai_error_response(
            "Missing required parameter: 'model'.",
            status_code=400,
            param="model",
            code="missing_required_parameter",
        ), body

    try:
        resolved_target = _resolve_request_target(model_name, aliases_only=True)
    except AliasPolicyResolutionError as error:
        return _alias_policy_configuration_response(error), body
    local_activation = _configured_litellm_local_model_target(
        model_name,
        service_id=(resolved_target.logical_service_id if resolved_target else None),
    )
    target_backend = local_activation.backend if local_activation else None
    target_model = local_activation.model if local_activation else None
    target_mmproj = local_activation.mmproj if local_activation else None
    target_profile = local_activation.profile if local_activation else None
    if resolved_target is None:
        try:
            resolved_target = _resolve_request_target(model_name, service_id=target_backend)
        except AliasPolicyResolutionError as error:
            return _alias_policy_configuration_response(error), body

    policy_service_id = resolved_target.logical_service_id if resolved_target else target_backend
    if policy_service_id:
        schema_error = _model_policy_schema_error(policy_service_id)
        if schema_error is not None:
            return _model_policy_schema_configuration_response(schema_error), body

    vision_needed = (
        request_path == "/v1/chat/completions"
        and has_vision_content(body.get("messages"))
    )
    if vision_needed and not target_backend:
        active = await get_active_backend()
        # vision_capable_llm_backends() answers the membership question: which
        # backends in LLM_BACKEND_HOSTS carry the "vision" capability?  For
        # a backend declaring vision=True, [] otherwise.  The kobold mmproj
        # check is orchestration-level logic that stays unchanged.
        _vision_members = vision_capable_llm_backends()
        active_can_serve_vision = (
            active in _vision_members
        ) or (
            _aux_grants_vision(active)
            and loaded_aux_present(active) is True
        )
        if active_can_serve_vision:
            return None, body

    if vision_needed and target_backend:
        _vision_members = vision_capable_llm_backends()
        target_can_serve_vision = (
            target_backend in _vision_members
        ) or (
            _aux_grants_vision(target_backend)
            and bool(target_mmproj)
        )
        if not target_can_serve_vision:
            return Response(
                content=json.dumps({
                    "error": {
                        "message": (
                            "Request includes images but the selected local model "
                            "group is not configured with a vision-capable target."
                        ),
                        "type": "invalid_request_error",
                        "code": "vision_unsupported",
                    }
                }),
                status_code=400,
                media_type="application/json",
                headers={"X-Vision-Routed": "false"},
            ), body

    if request_path in ("/v1/chat/completions", "/v1/completions"):
        role_cfg = ROLES.get(model_name) if isinstance(ROLES, dict) else None
        if isinstance(role_cfg, Mapping):
            sampling = role_cfg.get("sampling")
            if isinstance(sampling, Mapping):
                for field, value in sampling.items():
                    if field not in body:
                        body[field] = value

    policy_error, body, _ = _prepare_resolved_openai_request(
        body,
        request_path=request_path,
        target=resolved_target,
        execution_service_id=target_backend or "",
    )
    if policy_error is not None:
        return policy_error, body

    if not activate_target or not target_backend or (
        enforce_gateway_policy and _target_activation(auth_context) == "existing_only"
    ):
        return None, body

    response = await _ensure_litellm_local_backend_target(
        auth_context,
        requested_model=model_name,
        backend=target_backend,
        target_model=target_model,
        target_mmproj=target_mmproj,
        target_profile=target_profile,
        enforce_gateway_policy=enforce_gateway_policy,
    )
    return response, body


async def _activate_prepared_litellm_local_target(
    auth_context: AuthContext,
    *,
    requested_model: str,
    enforce_gateway_policy: bool,
) -> Response | None:
    """Activate only after preparation has made the accepted receipt durable."""
    try:
        resolved_target = _resolve_request_target(requested_model, aliases_only=True)
    except AliasPolicyResolutionError as error:
        return _alias_policy_configuration_response(error)
    local_activation = _configured_litellm_local_model_target(
        requested_model,
        service_id=(resolved_target.logical_service_id if resolved_target else None),
    )
    target_backend = local_activation.backend if local_activation else None
    target_model = local_activation.model if local_activation else None
    target_mmproj = local_activation.mmproj if local_activation else None
    target_profile = local_activation.profile if local_activation else None
    if not target_backend or (
        enforce_gateway_policy and _target_activation(auth_context) == "existing_only"
    ):
        return None
    return await _ensure_litellm_local_backend_target(
        auth_context,
        requested_model=requested_model,
        backend=target_backend,
        target_model=target_model,
        target_mmproj=target_mmproj,
        target_profile=target_profile,
        enforce_gateway_policy=enforce_gateway_policy,
    )


async def get_served_model_id(base_url: str) -> str:
    """The first model id an OpenAI-compatible server lists at ``base_url``."""
    try:
        async with httpx.AsyncClient(verify=tls_context()) as client:
            resp = await client.get(f"{base_url}/v1/models", timeout=HEALTH_CHECK_TIMEOUT)
            if resp.status_code != 200:
                return ""
            data = resp.json().get("data", [])
            if data and isinstance(data[0], dict):
                return data[0].get("id") or ""
    except Exception:
        pass
    return ""


async def effective_llm_model_for_host(target_host: str) -> str:
    if any(_backend_base_url(backend) == target_host for backend in _path_identity_backends()):
        return await get_served_model_id(target_host)
    return ""


@dataclass(frozen=True)
class CurrentLoadedLlmTarget:
    backend: str
    host: str
    model: str


def _is_use_loaded_model_alias(value: Any) -> bool:
    return (
        isinstance(value, str)
        and normalize_model_id(value) in USE_LOADED_MODEL_ALIASES
    )


async def current_llm_model_for_backend(backend: str) -> str:
    """Return the model actually loaded on a backend, never a configured fallback."""
    backend = str(backend or "").strip()
    if _backend_reports_loaded_model_as_path(backend):
        loaded_path = currently_loaded_model(backend)
        if not loaded_path:
            return ""
        loaded_id = await get_served_model_id(_backend_base_url(backend))
        return loaded_id or os.path.basename(loaded_path) or loaded_path

    host = LLM_BACKEND_HOSTS.get(backend)
    backend_cfg = (config.get("backends") or {}).get(backend, {})
    if not host or not isinstance(backend_cfg, Mapping):
        return ""
    state_type = str(backend_cfg.get("state_type") or "openai_compatible")
    strategy = _BACKEND_STATE_STRATEGIES.get(state_type)
    if not strategy:
        return ""
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(2.0), verify=tls_context()) as client:
            resp = await client.get(f"{host}{strategy['endpoint']}")
        if resp.status_code != 200:
            return ""
        data = resp.json()
        if not isinstance(data, dict):
            return ""
        return _resolve_dot_path(data, str(strategy["model_key"])) or ""
    except Exception:
        return ""


def _current_model_unavailable_response(backend: str) -> Response:
    return openai_error_response(
        f"model 'current' requested, but backend {backend!r} has no loaded model.",
        status_code=503,
        error_type="service_unavailable",
        code="current_model_unavailable",
    )


async def _current_loaded_llm_target(
    auth_context: AuthContext,
    *,
    enforce_gateway_policy: bool = True,
) -> tuple[CurrentLoadedLlmTarget | None, Response | None]:
    active = await get_active_backend()
    if not active:
        return None, openai_error_response(
            "model 'current' requested, but no local LLM backend is active.",
            status_code=503,
            error_type="service_unavailable",
            code="current_model_unavailable",
        )
    if active not in LLM_BACKEND_HOSTS:
        return None, openai_error_response(
            f"model 'current' requested, but active backend {active!r} is not an OpenAI-compatible LLM backend.",
            status_code=503,
            error_type="service_unavailable",
            code="current_model_unavailable",
        )
    availability = (await asyncio.to_thread(_service_availability_response, active, service_label=active))
    if availability is not None:
        return None, availability

    loaded_model = await current_llm_model_for_backend(active)
    if not loaded_model:
        return None, _current_model_unavailable_response(active)
    return CurrentLoadedLlmTarget(
        backend=active,
        host=LLM_BACKEND_HOSTS[active],
        model=loaded_model,
    ), None


async def refresh_openai_model_aliases() -> int:
    """Fetch available OpenAI model IDs and cache inferred categories locally."""
    api_key = os.environ.get("OPENAI_MODEL_DISCOVERY_API_KEY") or os.environ.get("OPENAI_API_KEY")
    if not api_key:
        print("Set OPENAI_MODEL_DISCOVERY_API_KEY or OPENAI_API_KEY to refresh model aliases.", file=sys.stderr)
        return 2

    async with httpx.AsyncClient(timeout=httpx.Timeout(30, connect=10)) as client:
        resp = await client.get(
            OPENAI_MODELS_API_URL,
            headers={"Authorization": f"Bearer {api_key}"},
        )
    if resp.status_code != 200:
        print(f"OpenAI model refresh failed: HTTP {resp.status_code} {resp.text[:300]}", file=sys.stderr)
        return 1

    data = resp.json()
    model_entries = []
    for item in data.get("data", []):
        model_id = item.get("id", "")
        if not model_id:
            continue
        if not OPENAI_MODEL_DISCOVERY_INCLUDE_PRIVATE:
            owned_by = item.get("owned_by", "")
            is_private_fine_tune = ":" in model_id or model_id.startswith("ft:")
            if owned_by not in OPENAI_PUBLIC_MODEL_OWNERS or is_private_fine_tune:
                continue
        model_entries.append({
            "id": model_id,
            "category": infer_openai_model_category(model_id) or "unknown",
            "created": item.get("created"),
            "owned_by": item.get("owned_by"),
        })

    output = {
        "generated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "source": OPENAI_MODELS_API_URL,
        "models": sorted(model_entries, key=lambda entry: entry["id"]),
    }
    with open(OPENAI_MODEL_ALIASES_FILE, "w") as f:
        yaml.safe_dump(output, f, sort_keys=False)
    print(f"Wrote {len(model_entries)} OpenAI model aliases to {OPENAI_MODEL_ALIASES_FILE}.")
    return 0


