async def check_tts_health() -> bool:
    """Check if TTS backend is healthy."""
    if not TTS_ENABLED:
        return False
    return await check_service_health("tts")


def convert_wav_to_mp3(wav_content: bytes) -> bytes:
    """Convert WAV bytes to MP3 bytes using the local ffmpeg binary."""
    with tempfile.NamedTemporaryFile(suffix=".wav") as wav_file, tempfile.NamedTemporaryFile(suffix=".mp3") as mp3_file:
        wav_file.write(wav_content)
        wav_file.flush()
        result = subprocess.run(
            [
                "ffmpeg",
                "-hide_banner",
                "-loglevel",
                "error",
                "-y",
                "-i",
                wav_file.name,
                "-codec:a",
                "libmp3lame",
                "-f",
                "mp3",
                mp3_file.name,
            ],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if result.returncode != 0:
            detail = result.stderr.strip() or "ffmpeg failed"
            raise RuntimeError(detail)
        return Path(mp3_file.name).read_bytes()


def convert_wav_to_audio_format(wav_content: bytes, audio_format: str) -> bytes:
    """Convert WAV bytes to a supported OpenAI speech response encoding."""
    output_options = {
        "opus": (".ogg", ["-c:a", "libopus", "-f", "ogg"]),
        "aac": (".aac", ["-c:a", "aac", "-f", "adts"]),
        "flac": (".flac", ["-c:a", "flac", "-f", "flac"]),
        "pcm": (".pcm", ["-c:a", "pcm_s16le", "-ar", "24000", "-ac", "1", "-f", "s16le"]),
    }
    if audio_format not in output_options:
        raise ValueError(f"Unsupported audio format: {audio_format}")

    suffix, options = output_options[audio_format]
    with tempfile.NamedTemporaryFile(suffix=".wav") as wav_file, tempfile.NamedTemporaryFile(suffix=suffix) as output_file:
        wav_file.write(wav_content)
        wav_file.flush()
        result = subprocess.run(
            ["ffmpeg", "-hide_banner", "-loglevel", "error", "-y", "-i", wav_file.name, *options, output_file.name],
            capture_output=True,
            text=True,
            timeout=30,
        )
        if result.returncode != 0:
            raise RuntimeError(result.stderr.strip() or "ffmpeg failed")
        return Path(output_file.name).read_bytes()


def _speech_voice_aliases() -> dict[str, str]:
    """Older voice spellings -> the spelling each means (``model_aliases.speech.voice_aliases``)."""
    raw = (((config.get("model_aliases") or {}).get("speech") or {}).get("voice_aliases"))
    return {str(k).lower(): str(v).lower() for k, v in raw.items()} if isinstance(raw, Mapping) else {}


def _builtin_voice_names() -> frozenset[str]:
    """Voice names of the default speech engine and their older spellings, which a custom voice may not take."""
    records = speech_voices.voice_records(_speech_engine_for_service("tts"))
    return frozenset(record["id"].lower() for record in records) | frozenset(_speech_voice_aliases())


def _speech_engine_for_service(service_id: str) -> Mapping[str, Any]:
    """The first speech engine served by ``service_id``: its voices serve requests and listings that name no engine."""
    return next((spec for spec in _speech_engines().values()
                 if isinstance(spec, Mapping) and str(spec.get("service") or "") == service_id), {})


def _speech_voice_choices(model: str) -> "speech_voices.SpeechVoiceCatalog | None":
    """Try's voice choices for a speech model: the voices its engines list; None when it names no engine.

    Raises ModelCompatibilityError for a model that is not deployed.
    """
    resolution = resolve_model_for_operation("speech", model)
    if resolution.alias is None or resolution.alias.engine_spec is None:
        return None
    return speech_voices.speech_voice_catalog(*(spec for _engine, spec in _speech_model_engines(resolution)))


def _speech_model_engines(resolution: ModelResolution) -> list[tuple[str | None, Mapping[str, Any]]]:
    """The deployed engines that serve a speech model, in the configured order, as (engine id, record).

    A tier is its picked engine and then its fallbacks; an engine named directly is itself. A model
    resolved to no engine is served by the default speech service, so that engine's record (id None).
    """
    alias = resolution.alias
    if alias is None or not alias.engine or alias.engine_spec is None:
        return [(None, _speech_engine_for_service("tts"))]
    engines = _speech_engines()
    return [(alias.engine, alias.engine_spec),
            *((engine, engines.get(engine) or {}) for engine, _service in alias.fallbacks)]


# ---- custom (user-created) voices -------------------------------------------
# Storage, validation and the HTTP routes live in gateway/custom_voices.py,
# gateway/voice_audio.py and gateway/voices_api.py; this block only wires them
# to the config, the engines and the auth model.

_VOICE_STORES: dict[tuple[str, custom_voices.VoiceLimits], custom_voices.VoiceStore] = {}


def _voice_settings() -> Mapping[str, Any]:
    section = config.get("voices")
    return section if isinstance(section, Mapping) else {}


def _voice_store() -> custom_voices.VoiceStore:
    settings = _voice_settings()
    root = Path(str(settings.get("dir") or "data/voices"))
    if not root.is_absolute():
        root = CONFIG_PATH.parent / root
    mode = str(settings.get("consent_mode") or "optional")
    limits = custom_voices.VoiceLimits(
        max_voices=int(settings.get("max_voices_per_key", 20)),
        max_consents=int(settings.get("max_consents_per_key", 50)),
        max_bytes=int(settings.get("max_bytes_per_key", 200 * 1024 * 1024)),
        consent_mode=mode if mode in custom_voices.CONSENT_MODES else "optional",
    )
    key = (str(root), limits)
    store = _VOICE_STORES.get(key)
    if store is None:
        from gateway.ownership import credential_owner_keys
        store = _VOICE_STORES[key] = custom_voices.VoiceStore(
            root, limits, legacy_owners=lambda owner: credential_owner_keys(owner, path=ADMIN_STORE.path),
        )
    return store


def _voice_sample_limits() -> voice_audio.SampleLimits:
    settings = _voice_settings()
    defaults = voice_audio.SampleLimits()
    return voice_audio.SampleLimits(
        min_seconds=float(settings.get("min_seconds", defaults.min_seconds)),
        max_seconds=float(settings.get("max_seconds", defaults.max_seconds)),
        min_speech_seconds=float(settings.get("min_speech_seconds", defaults.min_speech_seconds)),
        target_seconds=float(settings.get("target_seconds", defaults.target_seconds)),
        max_bytes=int(settings.get("max_upload_bytes", defaults.max_bytes)),
    )


def _speech_engines() -> Mapping[str, Any]:
    section = (config.get("model_aliases") or {}).get("speech") or {}
    engines = section.get("engines")
    return engines if isinstance(engines, Mapping) else {}


def _custom_voice_engines() -> list[str]:
    """Deployed speech engines that accept a user-created voice."""
    available = _alias_engine_available_for("speech")
    usable = [
        str(engine_id)
        for engine_id, spec in _speech_engines().items()
        if isinstance(spec, Mapping) and bool_from_config(spec.get("custom_voices"), False) and available(str(engine_id), spec)
    ]
    # Same order as the default `tts` tier, so the first one is what `tts` would pick.
    tier = [str(e) for e in (((config.get("model_aliases") or {}).get("speech") or {}).get("stable") or {}).get("tts") or []]
    return sorted(usable, key=lambda engine_id: (tier.index(engine_id) if engine_id in tier else len(tier), engine_id))


def _speech_engine_endpoint(engine_id: str) -> tuple[str, str] | None:
    """(service id, base URL) of a speech engine, or None when it is not deployed (unknown or disabled)."""
    spec = _speech_engines().get(engine_id)
    if not isinstance(spec, Mapping) or not _alias_engine_available_for("speech")(engine_id, spec):
        return None  # unknown, or disabled in the registry: never start a disabled engine's unit
    service_id = str(spec.get("service") or "")
    service = (config.get("backends") or {}).get(service_id)
    if not isinstance(service, Mapping) or not service.get("host") or not service.get("port"):
        return None
    return service_id, f"http://{service['host']}:{service['port']}"


async def _probe_voice_quality(reference: Path) -> dict[str, Any] | None:
    """Speaker similarity of a test synthesis made from the clip.

    Advisory: returns ``{"error": reason}`` when the engine cannot run it (not deployed, would not
    start, GPU0 busy after retries), never raises. A 503 from the engine (GPU0 full or still loading)
    is retried twice, five seconds apart.
    """
    engine_id = str(_voice_settings().get("quality_engine") or "chatterbox")
    endpoint = _speech_engine_endpoint(engine_id)
    if endpoint is None:
        return {"error": "engine_not_deployed"}
    service_id, base_url = endpoint
    reason = "engine_unavailable"
    for attempt in range(3):
        if await _ensure_speech_service_ready(service_id, label="TTS engine") is not None:
            reason = "engine_would_not_start"
        else:
            try:
                async with httpx.AsyncClient(timeout=httpx.Timeout(120, connect=10)) as client:
                    resp = await client.post(f"{base_url}/v1/audio/voice-check", json={"voice_ref": str(reference)})
                if resp.status_code == 200:
                    data = resp.json()
                    return {"speaker_similarity": float(data["speaker_similarity"]), "encoder": data.get("encoder"), "engine": engine_id}
                reason = "gpu_busy" if resp.status_code == 503 else f"engine_http_{resp.status_code}"
                if resp.status_code != 503:
                    break
            except (httpx.HTTPError, ValueError, KeyError, TypeError) as exc:
                reason = f"engine_error: {type(exc).__name__}"
        if attempt < 2:
            await asyncio.sleep(5)
    return {"error": reason}


def _voice_design_settings() -> Mapping[str, Any] | None:
    """The ``voice_design`` data of the speech engine that ``voices.design_engine`` names."""
    spec = _speech_engines().get(str(_voice_settings().get("design_engine") or ""))
    settings = spec.get("voice_design") if isinstance(spec, Mapping) else None
    return settings if isinstance(settings, Mapping) else None


async def _design_voice(instruct: str, script: str, seed: int) -> bytes:
    """Render a designed voice once on the configured design engine; the result becomes that voice's reference clip."""
    engine_id = str(_voice_settings().get("design_engine") or "")
    if not engine_id:
        raise custom_voices.VoiceError(503, "backend_unavailable", "Voice design is not configured: set voices.design_engine to a speech engine.")
    endpoint = _speech_engine_endpoint(engine_id)
    if endpoint is None:
        raise custom_voices.VoiceError(503, "backend_unavailable", f"Voice design needs the {engine_id} engine, which is not deployed.")
    service_id, base_url = endpoint
    not_ready = await _ensure_speech_service_ready(service_id, label="Voice design engine")
    if not_ready is not None:
        raise custom_voices.VoiceError(503, "backend_unavailable", "The voice design engine could not be started.")
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(180, connect=10)) as client:
            resp = await client.post(
                f"{base_url}/v1/audio/speech",
                json=voice_design.design_request(_voice_design_settings(), script=script, instructions=instruct, seed=seed),
            )
    except httpx.HTTPError as exc:
        raise custom_voices.VoiceError(502, "backend_error", f"Voice design failed: {exc}") from exc
    if resp.status_code == 400:
        raise custom_voices.VoiceError(400, "invalid_prompt", "The voice design engine rejected this description.", param="prompt")
    if resp.status_code != 200:
        raise custom_voices.VoiceError(502, "backend_error", f"Voice design failed with HTTP {resp.status_code}.")
    return resp.content


async def _reference_transcript(owner: str | None, meta: Mapping[str, Any], reference: Path) -> str:
    """Transcript of a voice's reference clip (OmniVoice clones from audio plus its exact text); cached in the voice record."""
    if meta.get("transcript"):
        return str(meta["transcript"])
    stt = (config.get("backends") or {}).get("stt")
    if not isinstance(stt, Mapping) or not stt.get("host"):
        raise custom_voices.VoiceError(503, "backend_unavailable", "Transcribing the voice sample needs the stt service.")
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(120, connect=10)) as client:
            resp = await client.post(
                f"http://{stt['host']}:{stt['port']}/v1/audio/transcriptions",
                files={"file": ("reference.wav", reference.read_bytes(), "audio/wav")},
                data={"model": str(stt.get("default_model") or "parakeet-tdt-0.6b-v3")},
            )
        text = str(resp.json().get("text") or "").strip() if resp.status_code == 200 else ""
    except (httpx.HTTPError, ValueError, OSError):
        text = ""
    if not text:
        raise custom_voices.VoiceError(503, "backend_unavailable", "The voice sample could not be transcribed for this engine.")
    _voice_store().update_voice(owner, str(meta["id"]), {"transcript": text})
    return text


_VOICE_ROUTE_POLICY_PATH = "/v1/audio/voices"


def _enforce_voice_route_policy(auth_context: AuthContext, _path: str) -> Response | None:
    # Every voice-management route shares the policy of GET /v1/audio/voices.
    return _enforce_runtime_route_policy(auth_context, _VOICE_ROUTE_POLICY_PATH)


def _purge_voices_for_credential(credential: Mapping[str, Any]) -> None:
    # Rotation revokes authentication, never the principal's voices. Keep old
    # folders too: they remain readable through trusted credential aliases.
    return None



async def _apply_custom_voice(
    body_json: dict[str, Any],
    voice_id: str,
    engine: Mapping[str, Any] | None,
    auth_context: AuthContext,
    engine_id: str | None,
) -> Response | None:
    """Point a speech request at a user-created voice. Returns an error response, or None when the body is ready."""
    owner = _asset_owner_key(auth_context)
    store = _voice_store()
    try:
        meta = store.get_voice(owner, voice_id)
    except custom_voices.VoiceError as exc:
        return openai_error_response(exc.message, status_code=exc.status, param="voice", code=exc.code)
    if engine is None or not bool_from_config(engine.get("custom_voices"), False):
        usable = ", ".join(_custom_voice_engines()) or "none deployed"
        return openai_error_response(
            f"The selected speech engine cannot use a custom voice. Engines that can: {usable}. Set model to one of those engine ids.",
            status_code=400,
            param="voice",
            code="custom_voice_engine_unsupported",
        )
    reference = store.reference_path(owner, voice_id)
    body_json["voice"] = "alloy"          # ignored by the engine when voice_ref is present
    body_json["voice_ref"] = str(reference)
    if engine_id == "omnivoice":
        try:
            body_json["ref_text"] = await _reference_transcript(owner, meta, reference)
        except custom_voices.VoiceError as exc:
            return openai_error_response(exc.message, status_code=exc.status, code=exc.code)
    return None


def _service_has_managed_lifecycle(service_id: str) -> bool:
    lifecycle = ((config.get("backends") or {}).get(service_id) or {}).get("lifecycle")
    driver = str((lifecycle or {}).get("driver") or "external").strip().lower() if isinstance(lifecycle, Mapping) else "external"
    return driver != "external"


async def _ensure_speech_service_ready(service_id: str, *, label: str) -> Response | None:
    """Start an on-demand speech service through its lifecycle driver.

    Always-on (``external``) services are not probed. For a managed service a
    single health GET decides whether the unit is up; only a down service pays
    the ``systemctl start`` + health poll in ``ensure_target``.
    """
    if not _service_has_managed_lifecycle(service_id):
        return None
    from gateway.lifecycle_drivers import _poll_health

    bcfg = (config.get("backends") or {}).get(service_id) or {}
    if await _poll_health(bcfg, 0.0):
        return None
    if await ensure_target(service_id, None):
        return None
    return Response(
        content=json.dumps({"error": {
            "message": f"{label} could not be started.",
            "type": "service_unavailable",
            "code": "backend_unavailable",
            "service": service_id,
        }}),
        status_code=503,
        media_type="application/json",
        headers={"Retry-After": "5"},
    )


def _tts_error(message: str, status_code: int, code: str | None = None) -> Response:
    error: dict[str, Any] = {"message": message, "type": "api_error"}
    if code:
        error["code"] = code
    return Response(
        content=json.dumps({"error": error}),
        status_code=status_code,
        media_type="application/json",
    )


def _tts_gpu_memory_response() -> Response:
    response = openai_error_response(
        "The GPU is out of memory right now. Retry the speech request later.",
        status_code=503,
        error_type="api_error",
        code="gpu_memory_unavailable",
    )
    response.headers["Retry-After"] = "30"
    return response


async def _stream_tts_upstream(
    *,
    url: str,
    headers: Mapping[str, str],
    body: bytes,
    stream_format: str,
    response_format: str,
    native_rate: int,
) -> Response:
    """Forward an engine's PCM stream to the client while it is still synthesizing.

    ``stream_format`` is ``audio`` (chunked audio in ``response_format``) or
    ``sse`` (``speech.audio.delta`` events). An upstream error status is
    returned as a normal response before any streaming starts.
    """
    upstream = None
    streaming = False
    # Until the body is handed to the StreamingResponse this function owns the
    # adapter's stream (its upstream response and client), on every exit
    # including cancellation.
    try:
        try:
            upstream = await _TTS_ADAPTER.invoke(
                _tts_connection(url.removesuffix(tts_adapter.SPEECH_PATH)), "speech.stream",
                AdapterRequest(op="speech.stream", headers=headers, raw_body=body),
            )
            if isinstance(upstream, AdapterReply):
                refused, upstream = upstream, None
                if _speech_allocation_failed(refused.status, refused.raw.decode("utf-8", "replace")):
                    return _tts_gpu_memory_response()
                retry_after = refused.headers.get("retry-after")
                return Response(
                    content=refused.raw,
                    status_code=refused.status,
                    media_type=refused.headers.get("content-type", "application/json"),
                    headers={"Retry-After": retry_after} if retry_after else None,
                )
        except TransportFailure as e:
            if e.kind == "timeout":
                return _tts_error("TTS request timeout", 504)
            if e.kind == "unreachable":
                return _tts_error(f"TTS backend unavailable at {url}", 502, "tts_backend_unavailable")
            return _tts_error(f"TTS proxy error: {e}", 502)
        except Exception as e:  # noqa: BLE001
            return _tts_error(f"TTS proxy error: {e}", 502)

        # An engine that loads its model lazily (a cold audio.cpp or Python unit) sends "200 chunked"
        # first and fails inside the stream when GPU0 is full, so the status alone cannot be
        # trusted. Read the first chunk before committing a 200 to the client: a stream that
        # dies before any audio becomes a 503 and the tier falls back to its next engine.
        raw_chunks = upstream.__aiter__()
        try:
            first_chunk = await anext(raw_chunks, b"")
        except TransportFailure as e:
            print(f"[proxy] TTS engine at {url} dropped the stream before any audio: {e}", flush=True)
            return _tts_error("TTS engine failed before sending audio (likely GPU0 memory pressure)", 503, "tts_engine_stream_failed")
        if not first_chunk:
            return _tts_error("TTS engine returned no audio", 502, "tts_engine_empty_stream")

        async def with_first_chunk() -> AsyncIterator[bytes]:
            yield first_chunk
            async for chunk in raw_chunks:
                yield chunk

        async def frames():
            try:
                source = speech_stream.align_samples(with_first_chunk())
                if stream_format == "sse" or speech_stream.needs_transcode(native_rate, response_format):
                    source = speech_stream.transcode_pcm_stream(
                        source, src_rate=native_rate, response_format=response_format
                    )
                if stream_format == "sse":
                    source = speech_stream.pcm_to_sse(source)
                async for chunk in source:
                    yield chunk
            finally:
                await upstream.aclose()

        media_type = "text/event-stream" if stream_format == "sse" else TTS_RESPONSE_MEDIA_TYPES[response_format]
        response = StreamingResponse(
            frames(),
            media_type=media_type,
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )
        streaming = True
        return response
    finally:
        if not streaming and upstream is not None:
            await upstream.aclose()


async def proxy_tts_request(request: Request, auth_context: AuthContext, *, receipt: RouteReceipt | None = None) -> Response:
    """Forward a TTS request; a tier falls back to its next engine when the first cannot serve it.

    Fallback rules are those of STT (``_speech_fallback_reason``): start failure, connection refused,
    503 and a 5xx that names an allocation failure. An engine id by name has no fallbacks. The
    fallback engine applies its own voice map, so the voice can differ; ``x-azizam-fallback`` says so.
    """
    fallbacks, notes, start_engine = await _tts_tier_fallbacks(request)
    response = await _proxy_tts_once(request, auth_context, model_override=start_engine, receipt=receipt)
    if receipt is not None:
        for note in notes:
            receipt.add_fallback_reason(note)
    engine_id, _ = fallbacks.pop(0) if fallbacks else (None, None)
    for next_engine, _service in fallbacks:
        reason = _speech_fallback_reason(response)
        if reason is None:
            break
        attempt = await _proxy_tts_once(request, auth_context, model_override=next_engine, receipt=receipt)
        if attempt.status_code == 403:
            continue  # The caller's plan does not cover that engine: keep the earlier answer.
        note = f"{engine_id}->{next_engine} ({reason})"
        notes.append(note)
        if receipt is not None:
            receipt.add_fallback_reason(note)
        print(f"[proxy] TTS fallback {note}", flush=True)
        response, engine_id = attempt, next_engine
    return _with_fallback_header(response, notes)


async def _tts_tier_fallbacks(request: Request) -> tuple[list[tuple[str, str | None]], list[str], str | None]:
    """Return tier engines, notes for primary candidates skipped before dispatch, and the engine to start with.

    The engines are empty when the body is not a JSON object, the model is not a tier, or it names
    an engine. A named voice only goes to the engines whose data accept it, so the tier starts with
    the first of them (None when that is the tier's own pick); when none does, the pick refuses it.
    A custom voice only goes to engines that accept one.
    """
    try:
        body_json = json.loads(await request.body())
        resolution = resolve_model_for_operation("speech", body_json.get("model", "tts-1"))
    except (ValueError, AttributeError, ModelCompatibilityError):
        return [], [], None
    alias = resolution.alias
    if alias is None or not alias.engine or not alias.fallbacks:
        return [], _speech_skipped_engine_notes(resolution), None
    notes = _speech_skipped_engine_notes(resolution)
    tier = [(alias.engine, alias.service), *alias.fallbacks]
    specs = dict(_speech_model_engines(resolution))
    if voices_api.custom_voice_id(body_json.get("voice")) is not None:
        usable = [tier[0], *((engine, service) for engine, service in tier[1:]
                             if bool_from_config(specs[engine].get("custom_voices"), False))]
        return usable, notes, None
    requested_voice = str(body_json.get("voice", "") or "").lower()
    aliases = _speech_voice_aliases()
    accepting = [(engine, service) for engine, service in tier
                 if speech_voices.resolve_voice(specs[engine], aliases, requested_voice) is not None]
    if not accepting:
        return tier[:1], notes, None
    return accepting, notes, accepting[0][0] if accepting[0][0] != alias.engine else None


async def _proxy_tts_once(request: Request, auth_context: AuthContext, *, model_override: str | None = None, receipt: RouteReceipt | None = None) -> Response:
    """Forward TTS request to one TTS engine."""
    if not TTS_ENABLED:
        return openai_error_response(
            "TTS not enabled",
            status_code=503,
            error_type="service_unavailable",
        )
    admission = _dispatch_admission_response(
        "speech.synthesis", auth_context=auth_context, service_id="tts",
        service_available=TTS_ENABLED, resource_class="audio", receipt=receipt,
    )
    if admission is not None:
        return admission
    service_response = (await asyncio.to_thread(_service_availability_response, "tts", service_label="TTS"))
    if service_response is not None:
        return service_response

    # Voice mapping is module-scoped (single source of truth shared with /v1/voices).
    body = await request.body()
    headers = prepare_downstream_headers(request.headers, auth_context, "tts")
    tts_service_id = "tts"

    # Map voice in request body
    requested_response_format = "mp3"
    body_json = None
    stream_format: str | None = None
    stream_mode: str | None = None  # "audio" | "sse" | None (buffered)
    native_rate = speech_stream.OPENAI_PCM_RATE
    try:
        body_json = json.loads(body)
        # Gateway-level control; engines never see the extensions envelope.
        _begin_media_delivery(auth_context, receipt).capture_embedded_prompt = False
        if isinstance(body_json, dict):
            metadata_error = _note_media_metadata_body(body_json)
            if metadata_error is not None:
                return metadata_error
            body_json.pop("extensions", None)
        response_format = str(body_json.get("response_format", "") or "mp3").lower()
        if response_format not in SUPPORTED_TTS_RESPONSE_FORMATS:
            return openai_error_response(
                "response_format must be one of wav, mp3, opus, aac, flac, or pcm.",
                status_code=400,
                param="response_format",
                code="unsupported_response_format",
            )
        requested_response_format = response_format
        if body_json.get("stream_format") is not None:
            stream_format = str(body_json["stream_format"]).lower()
            if stream_format not in {"audio", "sse"}:
                return openai_error_response(
                    "stream_format must be audio or sse.",
                    status_code=400,
                    param="stream_format",
                    code="unsupported_stream_format",
                )

        requested_model = model_override or body_json.get("model", "tts-1")
        try:
            model_resolution = resolve_model_for_operation("speech", requested_model)
        except ModelCompatibilityError as e:
            return model_compatibility_error(e)
        denial = _speech_model_policy_denial(
            auth_context, model_resolution, requested=str(body_json.get("model", "tts-1")), receipt=receipt)
        if denial is not None:
            return _policy_denied_response(denial)

        engine = model_resolution.alias.engine_spec if model_resolution.alias else None
        custom_voice = voices_api.custom_voice_id(body_json.get("voice"))
        if custom_voice is not None:
            body_json.pop("voice_ref", None)  # only the gateway sets these
            body_json.pop("ref_text", None)
            custom_error = await _apply_custom_voice(
                body_json, custom_voice, engine, auth_context,
                model_resolution.alias.engine if model_resolution.alias else None,
            )
            if custom_error is not None:
                return custom_error
        else:
            requested_voice = str(body_json.get("voice", "") or "").lower()
            body_json.pop("voice_ref", None)
            body_json.pop("ref_text", None)
            voice = speech_voices.resolve_voice(
                engine if engine is not None else _speech_engine_for_service(tts_service_id),
                _speech_voice_aliases(), requested_voice,
            )
            if voice is None:
                return openai_error_response(
                    f"Voice '{requested_voice}' is not available for model '{requested_model}'. "
                    "GET /v1/audio/voices lists the voices.",
                    status_code=400, param="voice", code="voice_not_available",
                )
            body_json["voice"] = voice
        if engine is not None:
            tts_service_id = model_resolution.alias.service or "tts"
            if tts_service_id != "tts":
                admission = _dispatch_admission_response(
                    "speech.synthesis", auth_context=auth_context, service_id=tts_service_id,
                    resource_class="audio", receipt=receipt,
                )
                if admission is not None:
                    return admission
                service_response = (await asyncio.to_thread(_service_availability_response, tts_service_id, service_label=tts_service_id))
                if service_response is not None:
                    return service_response
                headers = prepare_downstream_headers(request.headers, auth_context, tts_service_id)
        body_json["model"] = model_resolution.effective_model or TTS_BACKEND_MODEL

        engine_streams = engine is not None and bool_from_config(engine.get("streaming"), False)
        if engine_streams:
            native_rate = int(engine.get("native_sample_rate") or speech_stream.OPENAI_PCM_RATE)
            if stream_format == "sse" or stream_format == "audio" or requested_response_format == "pcm":
                stream_mode = stream_format or "audio"
        if stream_mode:
            # Engines of this kind speak one contract: raw PCM, chunked.
            body_json["response_format"] = "pcm"
            body_json["stream_format"] = "audio"
        else:
            body_json["response_format"] = "wav"
            body_json.pop("stream_format", None)
        body = json.dumps(body_json).encode()
        pop_header(headers, "content-type")
        headers["content-type"] = "application/json"
    except (json.JSONDecodeError, AttributeError):
        pass

    admission = _dispatch_admission_response(
        'speech.synthesis', auth_context=auth_context, service_id=tts_service_id,
        service_available=TTS_ENABLED, resource_class='audio', receipt=receipt,
    )
    if admission is not None:
        return admission

    not_ready = await _ensure_speech_service_ready(tts_service_id, label="TTS engine")
    if not_ready is not None:
        return not_ready

    _tts_host = host_for_capability("audio.speech") or (TTS_HOST if TTS_ENABLED else None) or TTS_HOST
    if tts_service_id != "tts":
        _engine_service = (config.get("backends") or {}).get(tts_service_id) or {}
        _tts_host = f"http://{_engine_service.get('host')}:{_engine_service.get('port')}"
    admission = _dispatch_admission_response(
        "speech.synthesis", auth_context=auth_context, service_id=tts_service_id,
        service_available=TTS_ENABLED, resource_class="audio", receipt=receipt,
    )
    if admission is not None:
        return admission

    url = f"{_tts_host}/v1/audio/speech"
    if receipt is not None:
        receipt.backend = tts_service_id
        receipt.resolved_model = body_json.get("model") if isinstance(body_json, dict) else None

    if stream_mode:
        return await _stream_tts_upstream(
            url=url,
            headers=headers,
            body=body,
            stream_format=stream_mode,
            response_format=requested_response_format,
            native_rate=native_rate,
        )

    try:
        # The adapter owns the HTTP client; the answer handling below is unchanged.
        resp = await _TTS_ADAPTER.invoke(
            _tts_connection(_tts_host), "speech.synthesize",
            AdapterRequest(op="speech.synthesize", headers=headers, raw_body=body),
        )

        if not 200 <= resp.status < 300:
            if _speech_allocation_failed(resp.status, resp.raw.decode("utf-8", "replace")):
                return _tts_gpu_memory_response()
            return openai_error_response(
                "TTS backend rejected the speech request.",
                status_code=resp.status if 400 <= resp.status < 600 else 502,
                error_type="invalid_request_error" if 400 <= resp.status < 500 else "api_error",
                code="tts_backend_error",
            )

        # TTS returns audio data, stream it back
        content = resp.raw
        content_type = resp.headers.get("content-type", TTS_RESPONSE_MEDIA_TYPES["wav"])
        if 200 <= resp.status < 300 and requested_response_format not in {"wav", "mp3"}:
            try:
                content = await asyncio.to_thread(
                    convert_wav_to_audio_format,
                    resp.raw,
                    requested_response_format,
                )
                content_type = TTS_RESPONSE_MEDIA_TYPES[requested_response_format]
            except Exception as e:
                return Response(
                    content=json.dumps({"error": {"message": f"TTS audio conversion failed: {e}", "type": "api_error"}}),
                    status_code=502,
                    media_type="application/json",
                )
        elif 200 <= resp.status < 300 and requested_response_format == "mp3":
            try:
                content = await asyncio.to_thread(convert_wav_to_mp3, resp.raw)
                content_type = TTS_RESPONSE_MEDIA_TYPES["mp3"]
            except Exception as e:
                return Response(
                    content=json.dumps({"error": {"message": f"TTS audio conversion failed: {e}", "type": "api_error"}}),
                    status_code=502,
                    media_type="application/json",
                )
        elif 200 <= resp.status < 300:
            content_type = TTS_RESPONSE_MEDIA_TYPES.get(requested_response_format, content_type)
        if 200 <= resp.status < 300 and receipt is not None and stream_format != "sse":
            from gateway import media_ingestion
            await asyncio.to_thread(media_ingestion.store_audio_response, content, content_type, receipt, store_asset=store_asset_bytes)
        if 200 <= resp.status < 300 and stream_format == "sse":
            # Engine cannot stream: still answer in the SSE shape, as one delta.
            async def one_delta():
                yield content
            return StreamingResponse(
                speech_stream.pcm_to_sse(one_delta()),
                media_type="text/event-stream",
                headers={"Cache-Control": "no-cache"},
            )
        if (
            200 <= resp.status < 300
            and media_delivery.current_mode() == provenance.METADATA_NONE
        ):
            # Buffered (non-streaming) speech only: strip container tags
            # losslessly. Streams are delivered as the engine produced them.
            try:
                content = await asyncio.to_thread(
                    media_delivery.deliver_bytes, content, content_type, provenance.METADATA_NONE
                )
            except media_metadata.MediaMetadataError as exc:
                print(f"[proxy] speech metadata strip failed: {exc}", flush=True)
                return _tts_error("Could not prepare audio for delivery", 502)
        return Response(
            content=content,
            status_code=resp.status,
            media_type=content_type
        )

    except TransportFailure as e:
        if e.kind == "timeout":
            return _tts_error("TTS request timeout", 504)
        if e.kind == "unreachable":
            return _tts_error(f"TTS backend unavailable at {_tts_host}", 502, "tts_backend_unavailable")
        return _tts_error(f"TTS proxy error: {str(e)}", 502)
    except Exception as e:
        return _tts_error(f"TTS proxy error: {str(e)}", 502)


# =============================================================================
# STT Backend
# =============================================================================

async def check_stt_health() -> bool:
    """Check if STT backend is healthy."""
    if not STT_ENABLED:
        return False
    return await check_service_health("stt")


def stt_backend_supports_translation() -> bool:
    stt_backend = config.get("backends", {}).get("stt", {})
    capabilities = stt_backend.get("capabilities", []) if isinstance(stt_backend, dict) else []
    backend_caps = {str(cap).lower() for cap in capabilities if isinstance(cap, str)}
    return bool({"translation", "translations"} & backend_caps)


def audio_translation_unsupported_response() -> Response:
    return openai_error_response(
        (
            "Audio translation is not supported by the configured local STT backend. "
            "This gateway will not return transcription output from the translations route."
        ),
        status_code=400,
        error_type="invalid_request_error",
        param="file",
        code="unsupported_audio_translation",
    )


def _stt_execution_snapshot(
    operation: str, service_id: str | None = None
) -> stt_chunking.SttExecutionConfig | None:
    """Capture one STT service from effective hot-reload data.

    ``service_id`` is the service a model alias selected; without it the
    highest-priority service for the capability is used.
    """
    if service_id is not None:
        service_config = (config.get("backends") or {}).get(service_id)
        if not isinstance(service_config, Mapping):
            return None
    else:
        selected = service_for_capability(f"audio.{operation}")
        if selected is None:
            return None
        service_id, service_config = selected
    return stt_chunking.SttExecutionConfig.from_service(
        service_id=service_id,
        service_config=service_config,
        config_directory=CONFIG_PATH.parent,
    )


_SAFE_STT_RECEIPT_INPUTS = frozenset(
    {
        "file",
        "model",
        "language",
        "prompt",
        "response_format",
        "temperature",
        "timestamp_granularities",
        "include",
        "stream",
        "chunking_strategy",
    }
)


def _speech_model_policy_denial(
    auth_context: AuthContext,
    resolution: ModelResolution,
    *,
    requested: str,
    receipt: RouteReceipt | None = None,
) -> PolicyDecision | None:
    """Hold a speech request to the engine its model name resolved to.

    The route check passes a plan that lists any speech model; this one names the
    engine, so a plan or category that lists one engine is not a key to the rest.
    """
    route_policy = _RUNTIME_ROUTE_POLICY.get("/v1/audio/speech")
    alias = resolution.alias
    if route_policy is None or alias is None or not alias.engine:
        return None
    decision = evaluate_and_apply(
        auth_context.identity,
        make_policy_request(**{**route_policy, "model": alias.engine, "requested_model": requested}),
        receipt,
    )
    return decision if decision.denied else None


def _apply_selected_stt_policy(
    receipt: RouteReceipt,
    auth_context: AuthContext,
    *,
    operation: str,
    model: str | None = None,
    requested_model: str | None = None,
) -> PolicyDecision | None:
    """Evaluate the route policy against the immutable, selected service id.

    ``model`` is the engine the name resolved to and ``requested_model`` the name
    the caller sent, so a plan or category that lists one engine is held to it.
    """
    path = f"/v1/audio/{operation}"
    route_policy = _RUNTIME_ROUTE_POLICY.get(path)
    if route_policy is None:
        return None
    selected_policy = dict(route_policy)
    selected_policy["backend"] = receipt.backend
    if model:
        selected_policy.update(model=model, requested_model=requested_model)
    return evaluate_and_apply(
        auth_context.identity,
        make_policy_request(**selected_policy),
        receipt,
    )


def _record_stt_input_shape(
    receipt: RouteReceipt,
    fields: Sequence[tuple[str, str]],
    uploads: Sequence[tuple[str, Any]],
) -> None:
    """Persist only allowlisted structural input facts, never caller values."""
    for name in {name for name, _value in fields} & _SAFE_STT_RECEIPT_INPUTS:
        receipt.accept_input(name)
    if uploads:
        receipt.accept_input("file")
    receipt.metadata["stt"] = {
        "field_count": len(fields),
        "file_count": len(uploads),
        "attempts_started": 0,
        "chunked": False,
    }


_RESOURCE_ERROR = re.compile(
    r"alloc|out of memory|\boom\b|cudamalloc|cuda error|insufficient (?:vram|memory)|not enough (?:vram|memory)",
    re.IGNORECASE,
)


def _speech_allocation_failed(status: int, text: str) -> bool:
    return status in (500, 502, 507) and bool(_RESOURCE_ERROR.search(text[:4096]))


# 503s the gateway itself raises: another engine behind the same gateway would hit them too.
_GATEWAY_OWN_503_CODES = {"stt_cancellation_capacity", "stt_configuration_invalid"}


def _speech_fallback_reason(response: Response) -> str | None:
    """Why a speech engine's answer lets the tier try its next engine, or None when it does not.

    A tier falls back on: the engine refusing the connection, 503 (busy, still loading, drained),
    and a 5xx whose body names an allocation or out-of-memory failure (GPU0 full). A 4xx, bad audio,
    a timeout and any other 5xx are returned to the caller: another engine would not fix them.
    """
    status = response.status_code
    raw = getattr(response, "body", b"")
    text = raw[:4096].decode("utf-8", "replace") if isinstance(raw, (bytes, bytearray)) else ""
    try:
        error = json.loads(text).get("error")
    except (ValueError, AttributeError):
        error = None
    error = error if isinstance(error, Mapping) else {}
    code = str(error.get("code") or "")
    if code in {"stt_backend_unavailable", "tts_backend_unavailable"}:
        return "connection_refused"
    if code == "stt_backend_connection_lost":
        return "connection_lost"
    if status == 503 and code == "gpu_memory_unavailable":
        return "gpu_oom"
    if status == 503:
        if code == "backend_unavailable":  # the gateway's own: operator drain carries a `state`, else the unit would not start
            return "unavailable" if error.get("state") else "start_failed"
        return None if code in _GATEWAY_OWN_503_CODES else "busy"
    if _speech_allocation_failed(status, text):
        return "gpu_oom"
    return None


def _with_fallback_header(response: Response, notes: Sequence[str]) -> Response:
    """Make a speech fallback visible to old and canonical clients."""
    if notes:
        value = ", ".join(notes)
        response.headers["x-azizam-fallback"] = value
    return response


def _speech_skipped_engine_notes(
    resolution: ModelResolution | None,
) -> list[str]:
    alias = resolution.alias if resolution is not None else None
    if alias is None or not alias.skipped_engines or not alias.engine:
        return []
    return [f"{engine}->{alias.engine} (not_deployed)" for engine in alias.skipped_engines]


class _ReplayableBody:
    """Replays a request body to a second attempt without holding it in memory.

    Every body message the first attempt reads is also written to a temp file (spilled to disk
    above 8 MiB). ``request()`` then returns a request that yields the recorded messages first and
    the rest of the live stream after.
    """

    def __init__(self, request: Request, spool_dir: Path) -> None:
        spool_dir.mkdir(parents=True, exist_ok=True)
        self._scope = request.scope
        self._receive = request.receive
        self._file = tempfile.SpooledTemporaryFile(max_size=8 * 1024 * 1024, dir=spool_dir)
        self._log: list[tuple[int, int, bool]] = []  # (offset, size, more_body)
        self._end = 0

    def request(self) -> Request:
        index = 0

        async def receive() -> Mapping[str, Any]:
            nonlocal index
            if index < len(self._log):
                offset, size, more = self._log[index]
                index += 1
                self._file.seek(offset)
                return {"type": "http.request", "body": self._file.read(size), "more_body": more}
            message = await self._receive()
            if message["type"] == "http.request":
                data = message.get("body", b"")
                self._file.seek(self._end)
                self._file.write(data)
                self._log.append((self._end, len(data), bool(message.get("more_body", False))))
                self._end += len(data)
                index += 1
            return message

        return Request(self._scope, receive)

    def close(self) -> None:
        self._file.close()


async def _dispatch_selected_stt_route(
    request: Request,
    auth_context: AuthContext,
    *,
    operation: str,
) -> Response:
    """Select and authorize an STT service before route dispatch.

    The service follows the multipart ``model`` field (an engine alias picks
    its own service); with no readable ``model`` the capability default admits
    the upload, and execution selects the final service after parsing.
    """
    selected_service: str | None = None
    peeked_engine: str | None = None
    fallbacks: tuple[tuple[str, str | None], ...] = ()
    skipped_notes: list[str] = []
    model_unpeeked = False
    peeked_model: str | None = None
    if "multipart/form-data" in request.headers.get("content-type", ""):
        peeked_model, request = await speech_stream.peek_multipart_field(request, "model")
        model_unpeeked = not peeked_model
        if peeked_model:
            try:
                peeked = resolve_model_for_operation(operation, peeked_model.strip())
            except ModelCompatibilityError as error:
                return model_compatibility_error(error)
            if peeked.alias is not None and peeked.alias.engine:
                selected_service = peeked.alias.service
                peeked_engine = peeked.alias.engine
                fallbacks = peeked.alias.fallbacks
                skipped_notes = _speech_skipped_engine_notes(peeked)
    try:
        execution = _stt_execution_snapshot(operation, selected_service)
    except stt_chunking.SttConfigurationError:
        return _stt_error("The selected STT service has invalid execution limits.", status_code=503, code="stt_configuration_invalid")
    if execution is None:
        # No service can be dispatched. Preserve the generic route gate for
        # this no-target case; once a target exists, policy always uses its id.
        denied = (await asyncio.to_thread(_enforce_runtime_route_policy, auth_context, f"/v1/audio/{operation}"))
        if denied is not None:
            return denied
        return await proxy_stt_request(request, auth_context, operation=operation)
    receipt = _stt_receipt(request=request, auth_context=auth_context, operation=operation, service_id=execution.service_id)
    requested_name = peeked_model.strip() if peeked_model else None
    decision = None if model_unpeeked else _apply_selected_stt_policy(
        receipt, auth_context, operation=operation, model=peeked_engine, requested_model=requested_name)
    if decision is not None and decision.denied:
        return _policy_denied_response(decision)
    remaining = [(engine, service) for engine, service in fallbacks if service]
    body = _ReplayableBody(request, execution.spool_dir) if remaining else None
    engine_id = peeked_engine
    model_override: str | None = None
    notes: list[str] = list(skipped_notes)
    for note in notes:
        receipt.add_fallback_reason(note)
    try:
        while True:
            admission = _dispatch_admission_response(
                "speech.transcription" if operation == "transcriptions" else "speech.translation",
                auth_context=auth_context, service_id=execution.service_id,
                resource_class="audio", receipt=receipt,
            )
            if admission is not None:
                return admission
            not_ready = None if model_unpeeked else await _ensure_speech_service_ready(execution.service_id, label="STT engine")
            if not_ready is None:
                response = await proxy_stt_request(
                    body.request() if body is not None else request,
                    auth_context,
                    operation=operation,
                    execution_snapshot=execution,
                    route_receipt=receipt,
                    model_unpeeked=model_unpeeked,
                    model_override=model_override,
                )
                reason = _speech_fallback_reason(response) if body is not None else None
            else:
                response, reason = not_ready, "start_failed"
            if reason is None:
                break
            # Chunk attempts that began mean the engine failed part-way through a long file;
            # the next engine restarts the whole file.
            chunks_started = int((receipt.metadata.get("stt") or {}).get("attempts_started") or 0)
            if chunks_started:
                reason = f"{reason}@chunk{chunks_started}"
            # The engine could not serve this request for a reason another engine may not share.
            # Try the tier's next engine; a 4xx or any other error is the caller's and is returned as is.
            chosen = None
            while remaining and chosen is None:
                next_engine, next_service = remaining.pop(0)
                try:
                    next_execution = _stt_execution_snapshot(operation, next_service)
                except stt_chunking.SttConfigurationError:
                    continue
                if next_execution is None:
                    continue
                next_receipt = _stt_receipt(request=request, auth_context=auth_context, operation=operation, service_id=next_execution.service_id)
                next_decision = _apply_selected_stt_policy(
                    next_receipt, auth_context, operation=operation, model=next_engine, requested_model=requested_name)
                if next_decision is not None and next_decision.denied:
                    continue
                chosen = (next_engine, next_execution, next_receipt)
            if chosen is None:
                break
            next_engine, execution, receipt = chosen
            note = f"{engine_id or execution.service_id}->{next_engine} ({reason})"
            notes.append(note)
            for earlier in notes:
                receipt.add_fallback_reason(earlier)
            print(f"[proxy] STT fallback {note}", flush=True)
            engine_id, model_override = next_engine, next_engine
    finally:
        if body is not None:
            body.close()
    return _with_fallback_header(response, notes)


def _stt_receipt(
    *,
    request: Request,
    auth_context: AuthContext,
    operation: str,
    service_id: str,
) -> RouteReceipt:
    access = _access_for_auth_context(auth_context)
    return RouteReceipt(
        protocol="openai.audio",
        path=request.url.path,
        intent=f"audio.{operation}",
        backend=service_id,
        app_profile=plan_ref(auth_context.identity),
        app_id=auth_context.identity.app_id if auth_context.identity else None,
        owner_key_hash=auth_context.identity.key_hash if auth_context.identity else None,
        api_key_name=auth_context.identity.name if auth_context.identity else None,
        visibility=access.receipt_detail,
    )


def _stt_response_from_upstream(response: stt_chunking.UpstreamResponse) -> Response:
    """Return an upstream STT response without dropping safe response metadata."""
    headers = stt_chunking.filtered_response_headers(response.headers)
    body = response.body
    content_type = response.headers.get("content-type", "application/json")

    # Silence/very short audio legitimately transcribes to "". OpenAI returns
    # {"text": ""} and so do we -- but a falsy-truthiness client treats that as a
    # failed request. LibreChat v0.8.8-rc2 does exactly this in
    # api/server/services/Files/Audio/STTService.js:331
    #   if (!response.data || !response.data.text) throw new Error('Missing data ...')
    # which surfaces to the user as the misleading red banner "An error occurred
    # while processing the audio, maybe the audio was too short". Every brief mic
    # tap hits it. Substitute a single space: still falsy-safe for such clients,
    # renders as nothing, and keeps the 200/JSON shape byte-compatible otherwise.
    # Only applies to a successful JSON body whose "text" is exactly empty.
    if response.status_code == 200 and "json" in content_type.lower():
        try:
            parsed = json.loads(body)
        except (ValueError, TypeError):
            parsed = None
        if isinstance(parsed, dict) and parsed.get("text") == "":
            parsed["text"] = " "
            body = json.dumps(parsed).encode("utf-8")
            headers = {k: v for k, v in headers.items() if k.lower() != "content-length"}

    return Response(
        content=body,
        status_code=response.status_code,
        headers=headers,
        media_type=content_type,
    )


def _stt_error(message: str, *, status_code: int, code: str) -> Response:
    return openai_error_response(
        message,
        status_code=status_code,
        error_type="api_error" if status_code >= 500 else "invalid_request_error",
        code=code,
    )


async def proxy_stt_request(
    request: Request,
    auth_context: AuthContext,
    *,
    operation: str = "transcriptions",
    execution_snapshot: stt_chunking.SttExecutionConfig | None = None,
    route_receipt: RouteReceipt | None = None,
    model_unpeeked: bool = False,
    model_override: str | None = None,
) -> Response:
    """Forward one bounded STT request using one selected service snapshot.

    ``model_unpeeked`` is set when the dispatcher could not read the ``model``
    field before choosing the service. After parsing, execution can switch to
    the model's service while retaining the upload workspace and cleanup owner.
    """
    if operation not in {"transcriptions", "translations"}:
        return openai_error_response(f"Unsupported STT operation: {operation}", status_code=400, code="unsupported_stt_operation")
    if execution_snapshot is None:
        try:
            execution = _stt_execution_snapshot(operation)
        except stt_chunking.SttConfigurationError:
            return _stt_error("The selected STT service has invalid execution limits.", status_code=503, code="stt_configuration_invalid")
    else:
        execution = execution_snapshot
    if execution is None:
        return audio_translation_unsupported_response() if operation == "translations" else openai_error_response("STT not enabled", status_code=503, error_type="service_unavailable")

    receipt = route_receipt or _stt_receipt(request=request, auth_context=auth_context, operation=operation, service_id=execution.service_id)
    if route_receipt is None and not model_unpeeked:
        decision = _apply_selected_stt_policy(receipt, auth_context, operation=operation)
        if decision is not None and decision.denied:
            return _policy_denied_response(decision)
    unavailable = None if model_unpeeked else (await asyncio.to_thread(_service_availability_response, execution.service_id, service_label=execution.service_id))
    if unavailable is not None:
        return unavailable

    owner = ReceiptLifecycleOwner(receipt)
    cleanup = stt_chunking.SttCleanupOwner()
    cancellation: Any | None = None
    cancellation_signalled = False
    cleanup_deferred = False  # a streamed response closes cleanup when its body ends

    def signal_cancellation() -> None:
        nonlocal cancellation_signalled
        if not cancellation_signalled:
            cancellation_signalled = True
            cancellation_registry().signal(receipt.request_id)

    async def execute() -> Response:
        nonlocal execution
        try:
            if "multipart/form-data" not in request.headers.get("content-type", ""):
                return openai_error_response("No file part in the request.", status_code=400, param="file", code="missing_file")
            started_at = time.monotonic()
            deadline_at = started_at + execution.deadline_seconds
            lease = stt_chunking.GLOBAL_STT_RESOURCE_GATE.acquire(request_id=receipt.request_id, config=execution)
            receipt.resource_decision = lease.decision.details.as_dict(lease.decision.status.value)
            # Follow a replacement lease without changing cleanup order: the
            # reservation must outlive the form, files, and workspace.
            cleanup.add("capacity_lease", lambda: lease.release())
            workspace = stt_chunking.create_request_workspace(execution)
            cleanup.add("request_workspace", lambda: stt_chunking.remove_request_workspace(workspace))
            parsed = await stt_chunking.parse_bounded_multipart(
                request,
                execution,
                workspace=workspace,
                cleanup=cleanup,
                deadline_at=deadline_at,
            )
            cleanup.add("multipart_form", parsed.close_form)
            fields, uploads = stt_chunking.upload_file_parts(parsed.form)
            if not uploads:
                return openai_error_response("No file part in the request.", status_code=400, param="file", code="missing_file")

            requested_model = model_override or str(parsed.form.get("model", "whisper-1"))
            model_resolution = resolve_model_for_operation(operation, requested_model)
            watcher = RequestDisconnectWatcher(request.receive)
            cleanup.add("disconnect_watcher", watcher.aclose)
            if cancellation is None:
                raise RuntimeError("STT cancellation registration was not acquired")
            waiters = (watcher.wait, cancellation.token.wait)
            if model_unpeeked:
                # The body has already been consumed. Hand off execution, not
                # parsing: the same owner keeps the form/workspace alive until
                # the final response (including a native stream) is finished.
                target_service = (model_resolution.alias.service if model_resolution.alias is not None else None) or execution.service_id
                service_changed = target_service != execution.service_id
                receipt.backend = target_service
                decision = _apply_selected_stt_policy(
                    receipt, auth_context, operation=operation,
                    model=model_resolution.alias.engine if model_resolution.alias is not None else None,
                    requested_model=requested_model)
                if decision is not None and decision.denied:
                    return _policy_denied_response(decision)
                if service_changed:
                    try:
                        target_execution = _stt_execution_snapshot(operation, target_service)
                    except stt_chunking.SttConfigurationError:
                        return _stt_error("The selected STT service has invalid execution limits.", status_code=503, code="stt_configuration_invalid")
                    if target_execution is None:
                        return _stt_error("The selected STT service is unavailable.", status_code=503, code="stt_backend_unavailable")
                    execution = target_execution
                # Upload time counts against both budgets; redispatch must not
                # grant a new deadline or bypass the target's multipart limits.
                deadline_at = min(deadline_at, started_at + execution.deadline_seconds)
                if len(uploads) > execution.max_files or len(fields) > execution.max_fields:
                    raise stt_chunking.MultiPartException("Too many multipart parts for the selected STT service.")
                if sum(upload.size or 0 for _name, upload in uploads) > execution.max_input_bytes:
                    raise stt_chunking.MultiPartException("Uploaded audio exceeds the configured STT limit.")
                if parsed.parser.max_parsed_field_bytes > execution.max_field_bytes:
                    raise stt_chunking.MultiPartException("Multipart field exceeds the configured STT limit.")
                if time.monotonic() >= deadline_at:
                    raise stt_chunking.SttDeadlineExceeded("STT request deadline exceeded")
                not_ready = await stt_chunking.await_with_cancellation(
                    _ensure_speech_service_ready(execution.service_id, label="STT engine"),
                    cancellation_waiters=waiters,
                    deadline_at=deadline_at,
                    on_cancel=signal_cancellation,
                )
                if not_ready is not None:
                    return not_ready
                unavailable = (await asyncio.to_thread(_service_availability_response, execution.service_id, service_label=execution.service_id))
                if unavailable is not None:
                    return unavailable
                if service_changed:
                    # Both gate operations are synchronous, so the transfer
                    # cannot interleave with another request's admission.
                    lease.release()
                    # Execution still uses the original workspace. Reserve the
                    # target budget on the disk that actually holds the files.
                    lease = stt_chunking.GLOBAL_STT_RESOURCE_GATE.acquire(
                        request_id=receipt.request_id, config=replace(execution, spool_dir=workspace.parent),
                    )
                    receipt.resource_decision = lease.decision.details.as_dict(lease.decision.status.value)
            effective_model = model_resolution.effective_model or execution.default_model or STT_BACKEND_MODEL
            if model_resolution.is_openai_alias and execution.default_model:
                effective_model = execution.default_model
            fields = stt_chunking.replace_model_field(fields, model=effective_model)
            engine_spec = (model_resolution.alias.engine_spec if model_resolution.alias is not None else None) or {}
            native_stream = bool_from_config(engine_spec.get("streaming"), False)
            wants_stream = any(name == "stream" and value.strip().lower() in {"true", "1"} for name, value in fields)
            if wants_stream:
                supported_formats = {"json", "verbose_json"}
                if native_stream:
                    supported_formats.add("diarized_json")
                if any(name == "response_format" and value.strip().lower() not in supported_formats for name, value in fields):
                    return openai_error_response(
                        "stream=true requires a JSON response_format.",
                        status_code=400,
                        param="response_format",
                        code="unsupported_stream_response_format",
                    )
            stream_model = str(engine_spec.get("stream_model") or "")
            if wants_stream and native_stream and stream_model:
                # One weight file served in two modes: offline answers fastest, streaming sends deltas.
                fields = stt_chunking.replace_model_field(fields, model=stream_model)
            wav16k_input = str(engine_spec.get("upload_format") or "") == "wav16k"
            multipart_fields: dict[str, str | list[str]] = {}
            for field_name, field_value in fields:
                if field_name == "stream" and wants_stream and not native_stream:
                    # Keep stream in fields so chunking stays ineligible; only
                    # omit it from the buffered engine's outgoing request.
                    continue
                previous = multipart_fields.get(field_name)
                multipart_fields[field_name] = field_value if previous is None else [*previous, field_value] if isinstance(previous, list) else [previous, field_value]
            _record_stt_input_shape(receipt, fields, uploads)

            headers = prepare_downstream_headers(request.headers, auth_context, execution.service_id, f"/v1/audio/{operation}", backend_config=execution.backend_config)
            pop_header(headers, "content-type")
            pop_header(headers, "content-length")
            url = f"{execution.host}/v1/audio/{operation}"
            client = httpx.AsyncClient(timeout=httpx.Timeout(execution.timeout_seconds, connect=min(10.0, execution.timeout_seconds)))
            cleanup.add("http_client", client.aclose)

            async def send_files(files: list[tuple[str, tuple[str, Any, str]]]) -> stt_chunking.UpstreamResponse:
                try:
                    outgoing = client.build_request("POST", url, headers=headers, data=multipart_fields, files=files)
                    upstream = await stt_chunking.await_with_cancellation(client.send(outgoing, stream=True), cancellation_waiters=waiters, deadline_at=deadline_at, on_cancel=signal_cancellation)
                    cleanup.add("upstream_response", upstream.aclose)
                    try:
                        body = await stt_chunking.read_bounded_response(upstream, max_bytes=execution.max_response_bytes, cancellation_waiters=waiters, deadline_at=deadline_at, on_cancel=signal_cancellation)
                    finally:
                        await cleanup.release("upstream_response", upstream.aclose)
                    return stt_chunking.UpstreamResponse(upstream.status_code, body, dict(upstream.headers))
                except httpx.TimeoutException as error:
                    raise stt_chunking.SttBackendTimeout("STT backend timed out") from error
                except httpx.ConnectError as error:
                    raise stt_chunking.SttBackendUnavailable("STT backend is unavailable") from error
                except httpx.TransportError as error:
                    # Reset/closed/protocol error after the connection was made: the engine died
                    # mid-request (typically a GPU out-of-memory kill). Another engine may serve it.
                    raise stt_chunking.SttBackendConnectionLost("STT backend dropped the connection") from error

            async def post_file(path: Path, filename: str, media_type: str) -> stt_chunking.UpstreamResponse:
                handle = path.open("rb")
                cleanup.add("chunk_upload_handle", handle.close)
                try:
                    return await send_files([("file", (filename, handle, media_type))])
                finally:
                    await cleanup.release("chunk_upload_handle", handle.close)

            async def prepared_wav(upload: Any) -> Path:
                """Decode the upload to 16 kHz mono WAV, the only input audio.cpp engines accept."""
                destination = workspace / "normalized-16k.wav"
                cleanup.add("normalized_wav", lambda: destination.unlink(missing_ok=True))
                try:
                    await stt_chunking.run_media_command(
                        [
                            "ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
                            "-i", os.fspath(stt_chunking.source_path(upload)),
                            "-vn", "-ac", "1", "-ar", "16000", "-acodec", "pcm_s16le",
                            os.fspath(destination),
                        ],
                        timeout_seconds=execution.timeout_seconds,
                        cancellation_waiters=waiters,
                        deadline_at=deadline_at,
                        on_cancel=signal_cancellation,
                        max_output_bytes=execution.max_media_output_bytes,
                    )
                except stt_chunking.SttMediaCommandFailed as error:
                    # ffmpeg ran and refused the file: the caller sent something that is not audio.
                    raise stt_chunking.SttInvalidAudio("STT input is not readable audio") from error
                size = destination.stat().st_size if destination.exists() else 0
                if size <= 44:
                    raise stt_chunking.SttInvalidAudio("STT input holds no decodable audio")
                if size > execution.max_decoded_bytes:
                    raise stt_chunking.SttResourceLimitExceeded("Decoded audio exceeds the configured STT limit")
                return destination

            async def open_stream(path: Path, filename: str) -> Response:
                """Relay an engine's SSE transcript while it is being produced."""
                nonlocal cleanup_deferred
                handle = path.open("rb")
                cleanup.add("stream_upload_handle", handle.close)
                outgoing = client.build_request(
                    "POST", url, headers=headers, data=multipart_fields,
                    files=[("file", (filename, handle, "audio/wav" if wav16k_input else "application/octet-stream"))],
                )
                try:
                    upstream = await stt_chunking.await_with_cancellation(
                        client.send(outgoing, stream=True),
                        cancellation_waiters=waiters, deadline_at=deadline_at, on_cancel=signal_cancellation,
                    )
                except httpx.TimeoutException as error:
                    raise stt_chunking.SttBackendTimeout("STT backend timed out") from error
                except httpx.ConnectError as error:
                    raise stt_chunking.SttBackendUnavailable("STT backend is unavailable") from error
                cleanup.add("upstream_response", upstream.aclose)
                if upstream.status_code != 200:
                    body = await stt_chunking.read_bounded_response(
                        upstream, max_bytes=execution.max_response_bytes,
                        cancellation_waiters=waiters, deadline_at=deadline_at, on_cancel=signal_cancellation,
                    )
                    return _stt_response_from_upstream(
                        stt_chunking.UpstreamResponse(upstream.status_code, body, dict(upstream.headers))
                    )
                cleanup_deferred = True

                async def relay():
                    try:
                        total = 0
                        iterator = upstream.aiter_raw().__aiter__()
                        while True:
                            try:
                                chunk = await stt_chunking.await_with_cancellation(
                                    iterator.__anext__(),
                                    cancellation_waiters=waiters,
                                    deadline_at=deadline_at,
                                    on_cancel=signal_cancellation,
                                )
                            except StopAsyncIteration:
                                break
                            total += len(chunk)
                            if total > execution.max_response_bytes:
                                raise stt_chunking.SttResponseLimitExceeded("STT backend response exceeds the configured limit")
                            yield chunk
                    except (ClientDisconnect, stt_chunking.SttCancelled) as error:
                        signal_cancellation()
                        raise asyncio.CancelledError from error
                    except (asyncio.CancelledError, GeneratorExit):
                        signal_cancellation()
                        raise
                    finally:
                        await cleanup.aclose()
                    if cleanup.failed:
                        raise stt_chunking.SttCleanupFailure("STT cleanup failed")
                    owner.report(status="succeeded", reason="completed")

                source = relay()
                owned_stream = owner.handoff_stream(source)

                async def response_body():
                    try:
                        async for chunk in owned_stream:
                            yield chunk
                    finally:
                        # Closing a suspended async-for does not close its
                        # source. Release the relay before terminal ownership.
                        try:
                            await source.aclose()
                        finally:
                            await owned_stream.aclose()

                return StreamingResponse(
                    response_body(),
                    media_type="text/event-stream",
                    headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
                )

            async def post_uploads() -> stt_chunking.UpstreamResponse:
                opened: list[tuple[str, Any, str, str]] = []
                try:
                    for index, (name, upload) in enumerate(uploads):
                        handle = stt_chunking.source_path(upload).open("rb")
                        opened.append((name, handle, upload.filename or "audio", upload.content_type or "application/octet-stream"))
                        cleanup.add(f"direct_upload_handle_{index}", handle.close)
                    return await send_files([(name, (filename, handle, media_type)) for name, handle, filename, media_type in opened])
                finally:
                    for index, (_name, handle, _filename, _media_type) in enumerate(opened):
                        await cleanup.release(f"direct_upload_handle_{index}", handle.close)

            prepared_source: Path | None = None
            if len(uploads) == 1:
                _name, upload = uploads[0]
                if wav16k_input:
                    prepared_source = await prepared_wav(upload)
                outcome = await stt_chunking.execute_chunking(
                    source_path=prepared_source or stt_chunking.source_path(upload),
                    source_stem=Path(upload.filename or "audio").stem or "audio",
                    fields=fields,
                    config=execution,
                    post_file=lambda path, filename: post_file(path, filename, "audio/wav"),
                    cancellation_waiters=waiters,
                    deadline_at=deadline_at,
                    on_cancel=signal_cancellation,
                    on_attempt_started=lambda count: receipt.metadata["stt"].update({"attempts_started": count}),
                    cleanup=cleanup,
                )
            else:
                outcome = stt_chunking.ChunkingOutcome("passthrough", 0, "multiple_files")
            receipt.metadata["stt"].update({"attempts_started": outcome.attempts_started, "chunked": outcome.mode == "chunked"})
            if outcome.fallback_reason:
                receipt.add_fallback_reason(outcome.fallback_reason)
            if outcome.mode == "chunked":
                receipt.metadata["status_code"] = 200
                return Response(content=json.dumps(outcome.merged_payload), status_code=200, media_type="application/json")
            if outcome.mode == "upstream_error" and outcome.upstream_response is not None:
                receipt.metadata["status_code"] = outcome.upstream_response.status_code
                return _stt_response_from_upstream(outcome.upstream_response)
            if wants_stream and native_stream and len(uploads) == 1:
                receipt.metadata["status_code"] = 200
                return await open_stream(
                    prepared_source or stt_chunking.source_path(uploads[0][1]),
                    "audio.wav" if prepared_source else (uploads[0][1].filename or "audio"),
                )
            if prepared_source is not None:
                direct = await post_file(prepared_source, "audio.wav", "audio/wav")
            else:
                direct = await post_uploads()
            receipt.metadata["status_code"] = direct.status_code
            response = _stt_response_from_upstream(direct)
            if wants_stream and not native_stream and direct.status_code == 200:
                try:
                    events = speech_stream.transcript_json_to_sse(json.loads(direct.body))
                except (ValueError, TypeError):
                    return _stt_error("STT backend returned an invalid JSON transcript for streaming.", status_code=502, code="invalid_stt_stream_response")
                return Response(
                    content=b"".join(events),
                    media_type="text/event-stream",
                    headers={"Cache-Control": "no-cache"},
                )
            return response
        finally:
            if not cleanup_deferred:
                await cleanup.aclose()
                if cleanup.failed and sys.exc_info()[0] is None:
                    raise stt_chunking.SttCleanupFailure("STT cleanup failed")

    async with owner:
        try:
            cancellation = cancellation_registry().register(receipt.request_id)
            cleanup.add("cancellation_handle", cancellation.release)
        except CancellationRegistryFull:
            owner.report(status="failed", reason="failed")
            return _stt_error("STT cancellation capacity is currently exhausted.", status_code=503, code="stt_cancellation_capacity")
        try:
            response = await execute()
        except ClientDisconnect:
            signal_cancellation()
            owner.report(status="cancelled", reason="cancelled")
            return Response(status_code=499)
        except stt_chunking.SttCancelled:
            signal_cancellation()
            owner.report(status="cancelled", reason="cancelled")
            return Response(status_code=499)
        except stt_chunking.SttDeadlineExceeded:
            owner.report(status="timed_out", reason="idle_timeout")
            return _stt_error("STT request deadline exceeded.", status_code=504, code="stt_request_deadline")
        except stt_chunking.SttResourceLimitExceeded as error:
            owner.report(status="failed", reason="failed")
            response = _stt_error(str(error), status_code=413, code="stt_resource_limit")
            if error.decision is not None:
                evidence = error.decision.details.as_dict(error.decision.status.value)
                evidence["wait_deadline"] = time.time() + 60
                receipt.resource_decision = evidence
                body = json.loads(response.body)
                projected = resource_decisions.project_decision(evidence)
                body["error"]["decision"] = projected
                if projected["reasons"]:
                    body["error"]["message"] = projected["reasons"][0]["message"]
                response = Response(content=json.dumps(body), status_code=413, media_type="application/json")
            return response
        except stt_chunking.MultiPartException as error:
            owner.report(status="failed", reason="failed")
            return _stt_error(str(error), status_code=413, code="stt_upload_limit")
        except ModelCompatibilityError as error:
            owner.report(status="failed", reason="failed")
            return model_compatibility_error(error)
        except stt_chunking.SttInvalidAudio:
            owner.report(status="failed", reason="failed")
            return openai_error_response(
                "Audio file might be corrupted or unsupported",
                status_code=400,
                param="file",
                code="invalid_value",
            )
        except stt_chunking.SttChunkResponseError:
            owner.report(status="failed", reason="failed")
            return _stt_error("STT backend returned a chunk response that cannot be merged.", status_code=502, code="invalid_stt_chunk_response")
        except stt_chunking.SttResponseLimitExceeded:
            owner.report(status="failed", reason="failed")
            return _stt_error("STT backend response exceeded the configured limit.", status_code=502, code="stt_response_limit")
        except stt_chunking.SttChunkAttemptError:
            owner.report(status="failed", reason="failed")
            return _stt_error("STT chunk request failed after chunk processing started.", status_code=502, code="stt_chunk_attempt_failed")
        except stt_chunking.SttSetupFailure:
            owner.report(status="failed", reason="failed")
            return _stt_error("STT media setup failed.", status_code=502, code="stt_media_setup_failed")
        except stt_chunking.SttBackendTimeout:
            owner.report(status="timed_out", reason="idle_timeout")
            return _stt_error("STT request timeout.", status_code=504, code="stt_request_timeout")
        except stt_chunking.SttBackendConnectionLost:
            owner.report(status="failed", reason="connect_error")
            return _stt_error("STT backend dropped the connection.", status_code=502, code="stt_backend_connection_lost")
        except stt_chunking.SttBackendUnavailable:
            owner.report(status="failed", reason="connect_error")
            return _stt_error("STT backend is unavailable.", status_code=502, code="stt_backend_unavailable")
        except stt_chunking.SttCleanupFailure:
            owner.report(status="failed", reason="failed")
            return _stt_error("STT request cleanup failed.", status_code=502, code="stt_cleanup_failed")
        except Exception:
            owner.report(status="failed", reason="failed")
            return _stt_error("STT proxy request failed.", status_code=502, code="stt_proxy_error")
        if not cleanup_deferred:
            succeeded = stt_chunking.upstream_response_succeeded(response.status_code)
            owner.report(status="succeeded" if succeeded else "failed", reason="completed" if succeeded else "failed")
        return response


# =============================================================================
# ComfyUI Backend (Image Generation)
# =============================================================================

_UI_WORKFLOW_CACHE: dict[str, Optional[dict]] = {}


def _load_ui_workflow(api_path: Path) -> Optional[dict]:
    """Load a UI-format workflow JSON sibling to the given API workflow.

    Looks for `<name>.ui.json` next to `<name>.json`. Returns the parsed dict
    if found, else None. Results are cached by absolute path. A twin is only a
    fallback for the derived workflow (see ``_build_comfy_submit_payload``).
    """
    api_path = Path(api_path).resolve()
    key = str(api_path)
    if key in _UI_WORKFLOW_CACHE:
        return _UI_WORKFLOW_CACHE[key]
    ui_path = api_path.with_name(api_path.stem + ".ui.json")
    if not ui_path.exists():
        # No twin is fine: the submit step derives the workflow from the graph.
        _UI_WORKFLOW_CACHE[key] = None
        return None
    try:
        with open(ui_path) as f:
            ui = json.load(f)
        _UI_WORKFLOW_CACHE[key] = ui
        return ui
    except Exception as e:
        print(f"[proxy] failed to read UI workflow {ui_path}: {e}", flush=True)
        _UI_WORKFLOW_CACHE[key] = None
        return None


def _build_comfy_submit_payload(workflow: dict, **extra: Any) -> dict:
    """Build the JSON body for POST /prompt, including extra_pnginfo when available.

    Pops the proxy-private `__ui_workflow__` key off `workflow` (added by the
    workflow loaders) and threads it into `extra_data.extra_pnginfo.workflow`.
    Without this, ComfyUI saves outputs without the UI-format graph in PNGInfo,
    so users can't drag the resulting mp4/PNG into ComfyUI's frontend to
    re-open the generation.
    """
    twin = workflow.pop("__ui_workflow__", None)
    # Derive from the graph actually submitted, so the embedded workflow shows
    # this request's prompt, seed and sizes. The hand-authored twin is a
    # fallback only: it carries the template's values, and several twins are
    # stale (widget values shifted by control_after_generate).
    ui = _derive_ui_workflow(workflow) or twin
    if not ui:
        print("[proxy] WARNING: submitting a ComfyUI prompt without an embedded workflow "
              "(derivation failed, no UI twin); dragging its output into ComfyUI will not "
              "reopen the generation", flush=True)
    payload = {"prompt": workflow}
    if ui:
        payload["extra_data"] = {"extra_pnginfo": {"workflow": ui}}
    payload.update(extra)
    return payload


def load_comfy_workflow(model_name: str) -> Optional[dict]:
    """Load a ComfyUI workflow template by model name.

    Attaches the UI-format twin (`<model>.ui.json`) under the private
    `__ui_workflow__` key when present, so submit sites can include it in
    `extra_data.extra_pnginfo.workflow`. The key survives deepcopy and is
    popped by `_build_comfy_submit_payload`.
    """
    workflow_path = COMFY_WORKFLOWS_DIR / f"{model_name}.json"
    if not workflow_path.exists():
        workflow_path = _comfy_workflow_artifact_path_for_model(model_name)
    if not workflow_path.exists():
        return None
    workflow = _load_comfy_workflow_file(workflow_path)
    if workflow is None:
        return None
    return workflow




def _comfy_object_info(class_type: str) -> Optional[dict]:
    """A node type's slot definitions from ComfyUI /object_info (cached), or None."""
    return comfy_object_info.lookup(COMFY_HOST, class_type)


def _derive_ui_workflow(api: Mapping[str, Any]) -> Optional[dict]:
    """Derive a UI-format ComfyUI graph from an API-format workflow.

    So generated media embed the 'workflow' chunk/tag (re-openable in the
    ComfyUI frontend). Uses /object_info for each node's slot ordering; see
    ``gateway.comfy_ui_graph``. Best-effort: None if ComfyUI is unreachable or
    any node type is unknown, in which case the caller falls back to a
    hand-authored twin or omits the chunk.
    """
    try:
        return comfy_ui_graph.derive_ui_workflow(api, _comfy_object_info)
    except Exception as exc:  # noqa: BLE001 - never fail a render over metadata
        print(f"[proxy] UI workflow derivation failed: {type(exc).__name__}: {exc}", flush=True)
        return None


def _load_comfy_workflow_file(workflow_path: Path) -> Optional[dict]:
    with open(workflow_path) as f:
        workflow = json.load(f)
    errors = validate_comfyui_workflow_graph(workflow)
    if errors:
        print(
            f"[proxy] invalid ComfyUI workflow {workflow_path}: {'; '.join(errors)}",
            flush=True,
        )
        return None
    # Hand-authored UI twin: fallback only. The submit step derives the workflow
    # from the final graph (see _build_comfy_submit_payload).
    ui = _load_ui_workflow(workflow_path)
    if ui is not None:
        workflow["__ui_workflow__"] = ui
    return workflow


def _comfy_workflow_artifact_path_for_model(model_name: str) -> Path:
    try:
        registry = GATEWAY_WORKFLOW_REGISTRY
    except NameError:
        return COMFY_WORKFLOWS_DIR / f"{model_name}.json"
    for record in registry.records():
        bindings = record.manifest.get("bindings")
        if not isinstance(bindings, Mapping):
            continue
        comfy = bindings.get("comfyui")
        if not isinstance(comfy, Mapping):
            continue
        artifact = comfy.get("workflow")
        if not isinstance(artifact, str) or not artifact:
            continue
        if Path(artifact.replace("package://", "")).stem != model_name:
            continue
        return _resolve_workflow_artifact_path(record, artifact)
    return COMFY_WORKFLOWS_DIR / f"{model_name}.json"


def _resolve_workflow_artifact_path(record: Any, artifact: str) -> Path:
    if artifact.startswith("package://"):
        artifact = artifact.removeprefix("package://").lstrip("/")
    path = Path(artifact)
    if path.is_absolute():
        return path

    project_relative = (Path(__file__).resolve().parent / path).resolve()
    if project_relative.exists():
        return project_relative

    source_path = Path(getattr(record, "source_path", "") or "")
    if str(source_path):
        base = source_path if source_path.is_dir() else source_path.parent
        return (base / path).resolve()
    return project_relative


async def check_comfy_health() -> bool:
    """Check if ComfyUI backend is healthy."""
    if not COMFY_ENABLED:
        return False
    return await check_service_health("comfyui")


def parse_size(size_str: str) -> tuple[int, int]:
    """Parse OpenAI size string like '1024x1024' to (width, height)."""
    if not size_str or "x" not in size_str:
        return 1024, 1024
    try:
        w, h = size_str.lower().split("x")
        return int(w), int(h)
    except:
        return 1024, 1024


def _image_size_adjustment_header(requested: Any, effective: str) -> str | None:
    requested_size = str(requested or "").strip()
    if not requested_size:
        return None
    if requested_size == effective:
        return None
    return f"{requested_size}->{effective}"


def _record_image_size_adjustment(
    receipt: RouteReceipt | None,
    *,
    requested: Any,
    effective: str,
) -> dict[str, str]:
    adjustment = _image_size_adjustment_header(requested, effective)
    if adjustment is None:
        return {}
    if receipt is not None:
        receipt.metadata["image_size_adjustment"] = {
            "requested": str(requested),
            "effective": effective,
        }
        receipt.add_warning(f"size_adjusted:{adjustment}")
    return {"X-Azizam-Size-Adjusted": adjustment}


# =============================================================================
# Image cache, signed URLs, and adaptive batching (Fix 1 + Fix 2)
# =============================================================================
# Single source of truth for everything in the image hot path that needs to
# survive restarts: VRAM-per-(workflow,size) measurements and on-disk PNG bytes.
# Implementation rules:
#   - No silent downgrades: clients that ask for `response_format=url` get URLs
#     they can dereference (signed, bearerless, and time-limited); clients that
#     ask for `n=4` get 4 images (or a 503 with Retry-After if VRAM can't fit
#     even one).
#   - VRAM probe is a *measurement*, not a guess: we read free VRAM from
#     ComfyUI's /system_stats before/after a single-image run and persist
#     the per-image cost to disk so subsequent restarts inherit the cache.

_vram_estimates_lock = threading.Lock()
# Schema v3 entry shape:
#   {
#     "peak_bytes": int,            # == marginal_bytes; kept for status-page compat
#     "marginal_bytes": int,        # comfy_used_peak - comfy_used_before (or - baseline)
#     "comfy_baseline_bytes": int,  # min ComfyUI per-process VRAM in the 2s pre-run window
#     "model_state": "warm" | "cold",
#     "samples_count": int,
#     "trusted": bool,
#     "measured_at": int (unix s),
#     "source": "probe" | "probe_unloaded" | "endpoint_diff",
#   }
#
# Schema v2 (legacy) stored `peak_bytes = vram_total - min(vram_free)` — i.e.
# whole-GPU peak occupancy during the run. That captured voxtral, desktop, and
# the resident ComfyUI baseline in addition to flux's actual contribution,
# yielding numbers ~4x too high. v2 entries are migrated to v3 on read but
# marked trusted=False so the batcher ignores them and re-measures.
#
# Schema v1 (older) was a flat dict {key: int_bytes} where the int was
# `free_before - free_after_round` — the residual, not the peak. Also migrated
# to v3 untrusted.
_VRAM_ESTIMATES_SCHEMA_VERSION = 3
_VRAM_LEGACY_TRUST_FLOOR = 64 * 1024 * 1024  # 64 MiB
# Sanity bounds for marginal measurements. Anything outside is rejected and
# logged loudly — it indicates a probe bug or extraordinary external pressure
# (concurrent allocation by another process race-conditioning the diff).
_VRAM_MARGINAL_MIN_BYTES = 100 * 1024 * 1024       # 100 MiB
_VRAM_MARGINAL_MAX_BYTES = 20 * 1024 * 1024 * 1024  # 20 GiB
# Cold-path detection threshold: if ComfyUI's per-process VRAM rose by more
# than this between the 2s pre-run baseline and the moment of submit, treat
# the run as a cold (first-load) measurement and use `peak - baseline` as the
# marginal cost instead of `peak - before`.
_VRAM_COLD_LOAD_THRESHOLD_BYTES = 3 * 1024 * 1024 * 1024  # 3 GiB
_vram_estimates_cache: dict[str, dict] = {}
_vram_estimates_loaded = False
_image_url_signing_secret: Optional[bytes] = None


def _normalize_vram_entry(value) -> Optional[dict]:
    """Coerce a raw cache value (legacy int, v2 dict, or v3 dict) into v3 shape.

    Legacy v1 ints (`free_before - free_after`) and v2 dicts (`total - min_free`,
    i.e. whole-GPU peak occupancy) record the wrong semantics for the batcher.
    Both are migrated forward with trusted=False so the cache surfaces them on
    the status page but the batcher re-measures on the next run.
    """
    if isinstance(value, (int, float)):
        peak = int(value)
        if peak < _VRAM_LEGACY_TRUST_FLOOR:
            peak = 0
        return {
            "peak_bytes": peak,
            "marginal_bytes": peak,
            "comfy_baseline_bytes": 0,
            "model_state": "unknown",
            "samples_count": 0,
            "trusted": False,
            "measured_at": 0,
            "source": "endpoint_diff_v1",
        }
    if isinstance(value, dict):
        try:
            peak = int(value.get("peak_bytes", 0))
        except (TypeError, ValueError):
            peak = 0
        # Detect schema version by the presence of v3-only fields.
        has_v3 = "marginal_bytes" in value and "model_state" in value
        if has_v3:
            try:
                marginal = int(value.get("marginal_bytes", 0))
            except (TypeError, ValueError):
                marginal = 0
            try:
                baseline = int(value.get("comfy_baseline_bytes", 0))
            except (TypeError, ValueError):
                baseline = 0
            try:
                samples = int(value.get("samples_count", 0))
            except (TypeError, ValueError):
                samples = 0
            state = str(value.get("model_state", "unknown"))
            trusted = bool(value.get("trusted", False))
            source = str(value.get("source", "unknown"))
        else:
            # v2 entry: peak_bytes was whole-GPU peak. Force untrusted so the
            # batcher won't plan against the old absolute semantics.
            marginal = peak
            baseline = 0
            samples = 0
            state = "unknown"
            trusted = False
            source = "v2_absolute"
        return {
            "peak_bytes": marginal if has_v3 else peak,
            "marginal_bytes": marginal,
            "comfy_baseline_bytes": baseline,
            "model_state": state,
            "samples_count": samples,
            "trusted": trusted,
            "measured_at": int(value.get("measured_at", 0) or 0),
            "source": source,
        }
    return None


def _load_vram_estimates() -> dict[str, dict]:
    """Lazy-load the on-disk VRAM-per-image estimates (schema v2)."""
    global _vram_estimates_loaded
    with _vram_estimates_lock:
        if _vram_estimates_loaded:
            return _vram_estimates_cache
        if VRAM_ESTIMATES_FILE.exists():
            try:
                raw = json.loads(VRAM_ESTIMATES_FILE.read_text())
                entries_blob = None
                if isinstance(raw, dict) and isinstance(raw.get("entries"), dict):
                    # v2 wrapped shape.
                    entries_blob = raw.get("entries")
                elif isinstance(raw, dict):
                    # v1 flat shape — migrate.
                    entries_blob = raw
                if isinstance(entries_blob, dict):
                    for k, v in entries_blob.items():
                        if not isinstance(k, str):
                            continue
                        entry = _normalize_vram_entry(v)
                        if entry is not None:
                            _vram_estimates_cache[k] = entry
            except Exception as e:
                print(f"[proxy] Could not load VRAM estimates ({VRAM_ESTIMATES_FILE}): {e}", flush=True)
        _vram_estimates_loaded = True
        return _vram_estimates_cache


def _persist_vram_estimates() -> None:
    with _vram_estimates_lock:
        try:
            VRAM_ESTIMATES_FILE.parent.mkdir(parents=True, exist_ok=True)
            payload = {
                "version": _VRAM_ESTIMATES_SCHEMA_VERSION,
                "entries": _vram_estimates_cache,
            }
            VRAM_ESTIMATES_FILE.write_text(json.dumps(payload, indent=2))
        except Exception as e:
            print(f"[proxy] Could not persist VRAM estimates: {e}", flush=True)


def _vram_cache_key(workflow_name: str, width: int, height: int) -> str:
    return f"{workflow_name}:{width}x{height}"


def get_vram_estimate(workflow_name: str, width: int, height: int) -> Optional[int]:
    """Return cached VRAM-per-image bytes for this (workflow, size), or None.

    Only returns trusted measurements. Untrusted (legacy or probe-fallback)
    entries cause the caller to re-measure on next run instead of planning
    capacity against bad data.
    """
    cache = _load_vram_estimates()
    entry = cache.get(_vram_cache_key(workflow_name, width, height))
    if not isinstance(entry, dict):
        return None
    if not entry.get("trusted"):
        return None
    peak = entry.get("peak_bytes")
    return int(peak) if isinstance(peak, int) and peak > 0 else None


def record_vram_estimate(
    workflow_name: str,
    width: int,
    height: int,
    bytes_per_image: int,
    *,
    trusted: bool = True,
    source: str = "probe",
    model_state: str = "unknown",
    comfy_baseline_bytes: int = 0,
    samples_count: int = 0,
) -> None:
    """Persist a measured VRAM-per-image cost so restarts inherit the calibration.

    ``bytes_per_image`` is flux's *marginal* per-image contribution (the
    per-image slice of ``comfy_used_peak - comfy_used_before`` or
    ``comfy_used_peak - comfy_baseline``), NOT whole-GPU peak occupancy. This
    is insensitive to concurrent voxtral / desktop / TTS activity because the
    sample stream is per-process (filtered to ComfyUI PID(s) on GPU0 via
    ``nvidia-smi --query-compute-apps``).

    We keep a lower-bound (the measured marginal), since under-estimating
    leads to OOM. Adopt a 10% safety margin baked into the stored value when
    trusted.

    Trusted measurements come from the in-run per-process probe. Untrusted
    measurements (probe failed, sanity bounds violated, fell back to endpoint
    diff) are persisted with trusted=False so the status page can surface
    them but the batcher won't plan against them.
    """
    if bytes_per_image <= 0:
        return
    # Hard sanity gate for trusted writes. Loud rejection — caller should see
    # this in journal and investigate. Untrusted writes bypass the bound check
    # (they're informational only).
    if trusted and (
        bytes_per_image < _VRAM_MARGINAL_MIN_BYTES
        or bytes_per_image > _VRAM_MARGINAL_MAX_BYTES
    ):
        print(
            f"[proxy] record_vram_estimate: REJECTING out-of-bounds marginal "
            f"for {workflow_name} {width}x{height}: "
            f"{bytes_per_image / (1024**2):.1f} MiB "
            f"(allowed range "
            f"{_VRAM_MARGINAL_MIN_BYTES / (1024**2):.0f} MiB .. "
            f"{_VRAM_MARGINAL_MAX_BYTES / (1024**3):.0f} GiB). "
            f"Recording untrusted.",
            flush=True,
        )
        trusted = False
        source = source + "_oob"
    safe_value = int(bytes_per_image * 1.1) if trusted else int(bytes_per_image)
    key = _vram_cache_key(workflow_name, width, height)
    cache = _load_vram_estimates()
    prior = cache.get(key) if isinstance(cache.get(key), dict) else None
    prior_peak = int(prior.get("peak_bytes", 0)) if prior else 0
    prior_trusted = bool(prior.get("trusted")) if prior else False
    # Only let a trusted measurement overwrite a prior trusted one. An
    # untrusted measurement never displaces a trusted one. When both are
    # trusted, keep the larger value — never under-estimate.
    if trusted:
        new_peak = max(safe_value, prior_peak) if prior_trusted else safe_value
        new_trusted = True
    else:
        if prior_trusted:
            return
        new_peak = safe_value
        new_trusted = False
    cache[key] = {
        "peak_bytes": new_peak,
        "marginal_bytes": new_peak,
        "comfy_baseline_bytes": int(comfy_baseline_bytes or 0),
        "model_state": str(model_state or "unknown"),
        "samples_count": int(samples_count or 0),
        "trusted": new_trusted,
        "measured_at": int(time.time()),
        "source": source,
    }
    _persist_vram_estimates()


async def comfy_vram_snapshot(
    client: httpx.AsyncClient,
) -> tuple[Optional[int], Optional[int]]:
    """Return (free, total) VRAM bytes on GPU0 from ComfyUI /system_stats."""
    try:
        resp = await client.get(f"{COMFY_HOST}/system_stats", timeout=HEALTH_CHECK_TIMEOUT)
        if resp.status_code != 200:
            return None, None
        payload = resp.json()
        devices = payload.get("devices") or []
        if not devices:
            return None, None
        # GPU0 is the inference card per the project's NAS+RTX layout.
        free = devices[0].get("vram_free")
        total = devices[0].get("vram_total")
        free_i = int(free) if isinstance(free, (int, float)) else None
        total_i = int(total) if isinstance(total, (int, float)) else None
        return free_i, total_i
    except Exception as e:
        print(f"[proxy] comfy_vram_snapshot: {e}", flush=True)
        return None, None


async def comfy_free_vram_bytes(client: httpx.AsyncClient) -> Optional[int]:
    """Backward-compatible: just the free-VRAM read."""
    free, _ = await comfy_vram_snapshot(client)
    return free


async def _free_comfy_models_if_idle(client: httpx.AsyncClient) -> bool:
    """Unload ComfyUI models only when its queue has no running execution."""
    try:
        response = await client.get(f"{COMFY_HOST}/queue", timeout=HEALTH_CHECK_TIMEOUT)
        if response.status_code != 200:
            return False
        queue = response.json()
        if not isinstance(queue, Mapping):
            return False
        running = queue.get("queue_running")
        pending = queue.get("queue_pending")
        if not isinstance(running, list) or not isinstance(pending, list) or running or pending:
            return False
        response = await client.post(
            f"{COMFY_HOST}/free",
            json={"unload_models": True, "free_memory": True},
            timeout=HEALTH_CHECK_TIMEOUT,
        )
        if response.status_code != 200:
            return False
        print("[proxy] ComfyUI idle models unloaded after VRAM exhaustion", flush=True)
        await asyncio.sleep(1.0)
        return True
    except (httpx.HTTPError, ValueError, TypeError) as exc:
        print(f"[proxy] ComfyUI model unload failed: {type(exc).__name__}", flush=True)
        return False


# Sample cadence for the in-run VRAM probe. Spec floor is 250ms; default 500ms.
_VRAM_PROBE_INTERVAL_S = 0.5
_VRAM_PROBE_INTERVAL_MIN_S = 0.25
# How long the "pre-run baseline" window stays open after probe start. Used to
# compute ``comfy_baseline_bytes`` = min of ComfyUI per-process VRAM in this
# window. With 500 ms cadence we get ~4 samples in 2 s.
_VRAM_BASELINE_WINDOW_S = 2.0

# GPU0 is the inference card (per the project's NAS+RTX layout). nvidia-smi
# exposes UUIDs in its ``--query-compute-apps`` output; we filter by GPU0's
# UUID so that any GPU1 (LLM card) allocations from the same process are
# correctly excluded.
_gpu0_uuid_cache: Optional[str] = None
_gpu0_uuid_lock = threading.Lock()


def _resolve_gpu0_uuid() -> Optional[str]:
    """Return the GPU0 UUID string from ``nvidia-smi``. Cached after first call."""
    global _gpu0_uuid_cache
    with _gpu0_uuid_lock:
        if _gpu0_uuid_cache is not None:
            return _gpu0_uuid_cache or None
        try:
            p = subprocess.run(
                [
                    "nvidia-smi",
                    "--query-gpu=index,uuid",
                    "--format=csv,noheader",
                ],
                capture_output=True,
                text=True,
                timeout=2.0,
            )
        except Exception as e:  # FileNotFoundError, TimeoutExpired, etc.
            print(f"[proxy] _resolve_gpu0_uuid: nvidia-smi failed: {e}", flush=True)
            _gpu0_uuid_cache = ""
            return None
        if p.returncode != 0:
            _gpu0_uuid_cache = ""
            return None
        for line in p.stdout.strip().splitlines():
            parts = [x.strip() for x in line.split(",", 1)]
            if len(parts) == 2 and parts[0] == "0":
                _gpu0_uuid_cache = parts[1]
                return parts[1]
        _gpu0_uuid_cache = ""
        return None


def _resolve_comfy_pids() -> set[int]:
    """Identify all ComfyUI processes by scanning /proc.

    A process is considered "ComfyUI" if its cmdline contains ``main.py`` AND
    its cwd resolves to a path containing ``ComfyUI``. Then we expand the set
    to include all descendant tasks via /proc/<pid>/task/*/children, because
    ComfyUI occasionally spawns short-lived worker subprocesses that hold
    their own VRAM allocations.

    Returns an empty set on any error (callers handle gracefully).
    """
    roots: set[int] = set()
    try:
        proc_entries = os.listdir("/proc")
    except Exception:
        return roots
    for name in proc_entries:
        if not name.isdigit():
            continue
        pid = int(name)
        try:
            with open(f"/proc/{pid}/cmdline", "rb") as f:
                cmdline = f.read().decode("utf-8", errors="replace").split("\x00")
            if not any("main.py" in part for part in cmdline if part):
                continue
            cwd = os.readlink(f"/proc/{pid}/cwd")
        except Exception:
            continue
        if "ComfyUI" in cwd:
            roots.add(pid)
    if not roots:
        return roots
    # Walk descendants. /proc/<pid>/task/<tid>/children lists immediate child
    # PIDs whitespace-separated. We BFS to catch grandchildren too.
    all_pids = set(roots)
    frontier = list(roots)
    while frontier:
        pid = frontier.pop()
        try:
            tasks = os.listdir(f"/proc/{pid}/task")
        except Exception:
            continue
        for tid in tasks:
            try:
                with open(f"/proc/{pid}/task/{tid}/children", "r") as f:
                    children_raw = f.read().split()
            except Exception:
                continue
            for child in children_raw:
                if not child.isdigit():
                    continue
                cpid = int(child)
                if cpid not in all_pids:
                    all_pids.add(cpid)
                    frontier.append(cpid)
    return all_pids


def _sample_comfy_vram_bytes(comfy_pids: set[int], gpu0_uuid: Optional[str]) -> Optional[int]:
    """Return ComfyUI's per-process VRAM occupancy on GPU0, in bytes.

    Sums ``used_memory`` rows from ``nvidia-smi --query-compute-apps`` where
    the PID is in ``comfy_pids`` and (if ``gpu0_uuid`` is known) the gpu_uuid
    matches GPU0. Returns None on nvidia-smi failure so the probe can flag
    the run as untrusted.
    """
    try:
        p = subprocess.run(
            [
                "nvidia-smi",
                "--query-compute-apps=pid,gpu_uuid,used_memory",
                "--format=csv,noheader,nounits",
            ],
            capture_output=True,
            text=True,
            timeout=2.0,
        )
    except Exception as e:
        print(f"[proxy] _sample_comfy_vram_bytes: nvidia-smi failed: {e}", flush=True)
        return None
    if p.returncode != 0:
        return None
    total_mb = 0
    matched = False
    for line in p.stdout.strip().splitlines():
        parts = [x.strip() for x in line.split(",")]
        if len(parts) < 3:
            continue
        try:
            pid = int(parts[0])
            used_mb = int(parts[2])
        except ValueError:
            continue
        if pid not in comfy_pids:
            continue
        if gpu0_uuid and parts[1] != gpu0_uuid:
            continue
        total_mb += used_mb
        matched = True
    if not matched:
        # ComfyUI is in our PID set but holds no compute context on GPU0 yet.
        # That's a legitimate 0 (model unloaded), not a failure.
        return 0
    return total_mb * 1024 * 1024


class _VramProbe:
    """Tracks ComfyUI's per-process VRAM contribution across a single round.

    Marginal cost semantics (replacing the older whole-GPU ``total - min_free``):

      - ``comfy_used_before``    = first sample, taken before the /prompt POST.
      - ``comfy_used_baseline``  = min comfy_used during the first ~2 s window.
      - ``comfy_used_peak``      = max comfy_used across all samples.

    Marginal = ``peak - before`` for a warm run. When the run is cold (the
    model loaded for the first time), ``before`` already includes the loaded
    weights, so the marginal underestimates the real round cost; we detect
    this via ``before - baseline > _VRAM_COLD_LOAD_THRESHOLD_BYTES`` and use
    ``peak - baseline`` instead.

    Per-process sampling makes the measurement insensitive to concurrent
    voxtral / desktop / TTS activity — those PIDs are filtered out of the
    ``nvidia-smi --query-compute-apps`` row stream. The legacy ``total -
    min_free`` figure is also retained (as ``system_peak_used_bytes``) so the
    status page can still report whole-GPU pressure.
    """

    def __init__(
        self,
        client: httpx.AsyncClient,
        interval: float = _VRAM_PROBE_INTERVAL_S,
    ) -> None:
        self._client = client
        self._interval = max(_VRAM_PROBE_INTERVAL_MIN_S, float(interval))
        self._stop = asyncio.Event()
        self._task: Optional[asyncio.Task] = None
        self._gpu0_uuid: Optional[str] = None
        self._comfy_pids: set[int] = set()
        self._t_start: float = 0.0
        self.samples = 0
        # Whole-GPU view (legacy): retained for "system pressure" reporting.
        self.min_free: Optional[int] = None
        self.total: Optional[int] = None
        # Per-ComfyUI-process view: the new source of truth for the batcher.
        self.comfy_before: Optional[int] = None
        self.comfy_baseline_min: Optional[int] = None  # min within baseline window
        self.comfy_peak: Optional[int] = None
        self.error: Optional[str] = None
        # Set to True if at least one per-process sample succeeded.
        self.have_per_process_data = False

    async def _record_sample(self) -> None:
        # Whole-GPU side: keep populating min_free / total via ComfyUI's
        # /system_stats. Cheap, async, and feeds the legacy "system pressure"
        # metric (NOT used by the batcher).
        free, total = await comfy_vram_snapshot(self._client)
        if isinstance(total, int) and self.total is None:
            self.total = total
        if isinstance(free, int):
            if self.min_free is None or free < self.min_free:
                self.min_free = free

        # Per-process side: poll nvidia-smi in a worker thread so we don't
        # block the event loop. ~5-15 ms per call on this box.
        try:
            comfy_used = await asyncio.to_thread(
                _sample_comfy_vram_bytes, self._comfy_pids, self._gpu0_uuid
            )
        except Exception as e:
            self.error = f"{type(e).__name__}: {e}"
            comfy_used = None

        if isinstance(comfy_used, int):
            self.have_per_process_data = True
            if self.comfy_before is None:
                self.comfy_before = comfy_used
            if self.comfy_peak is None or comfy_used > self.comfy_peak:
                self.comfy_peak = comfy_used
            # Baseline window: only the first ~2 s after probe start. We
            # specifically want the MIN here (model may already be in the
            # process of loading on the very first sample of a cold run).
            if (time.monotonic() - self._t_start) <= _VRAM_BASELINE_WINDOW_S:
                if self.comfy_baseline_min is None or comfy_used < self.comfy_baseline_min:
                    self.comfy_baseline_min = comfy_used

        self.samples += 1

    async def _run(self) -> None:
        try:
            # Resolve identifiers once. Cheap; both calls are short subprocess
            # invocations gated by 2s timeouts.
            self._gpu0_uuid = await asyncio.to_thread(_resolve_gpu0_uuid)
            self._comfy_pids = await asyncio.to_thread(_resolve_comfy_pids)
            if not self._comfy_pids:
                self.error = "no ComfyUI PIDs resolved"
                # Continue sampling anyway — at least the whole-GPU fields
                # will be populated for the legacy fallback path.

            # Capture an immediate "before" baseline so we have at least one
            # data point even on very short rounds. This sample becomes
            # ``comfy_before``.
            await self._record_sample()
            while not self._stop.is_set():
                try:
                    await asyncio.wait_for(self._stop.wait(), timeout=self._interval)
                    break  # stop signaled — exit loop, final sample below.
                except asyncio.TimeoutError:
                    await self._record_sample()
            # One final sample after stop to catch end-of-run state.
            await self._record_sample()
        except Exception as e:
            self.error = f"{type(e).__name__}: {e}"

    def start(self) -> None:
        if self._task is None:
            self._t_start = time.monotonic()
            self._task = asyncio.create_task(self._run())

    async def stop(self) -> None:
        self._stop.set()
        if self._task is not None:
            try:
                await self._task
            except Exception as e:
                self.error = f"{type(e).__name__}: {e}"

    # ----- whole-GPU view (legacy, for status "system pressure") -----------

    def system_peak_used_bytes(self) -> Optional[int]:
        """Legacy ``total - min_free``: whole-GPU peak occupancy during the run.

        Kept for the status page's system-pressure reporting. NOT used by the
        batcher — it conflates concurrent allocations from other processes.
        """
        if not isinstance(self.total, int) or not isinstance(self.min_free, int):
            return None
        peak = self.total - self.min_free
        return peak if peak > 0 else None

    # ----- per-process view (new, used by the batcher) ---------------------

    def marginal_and_state(self) -> tuple[Optional[int], str]:
        """Compute flux's marginal VRAM contribution and the model_state tag.

        Returns ``(marginal_bytes, model_state)``:
          - ``model_state="warm"``: ``before`` was already at steady state, so
            marginal = ``peak - before``.
          - ``model_state="cold"``: ``before`` jumped > 3 GiB above the 2s
            baseline minimum during the probe window, indicating a first-load
            run. Use ``peak - baseline_min`` so the recorded cost includes
            the model weights, otherwise we'd persist an unrealistically low
            value (steady-state activations only).
          - Returns ``(None, "unknown")`` if we lack the inputs.
        """
        if not self.have_per_process_data:
            return None, "unknown"
        if not isinstance(self.comfy_before, int) or not isinstance(self.comfy_peak, int):
            return None, "unknown"
        baseline = (
            self.comfy_baseline_min
            if isinstance(self.comfy_baseline_min, int)
            else self.comfy_before
        )
        cold = (self.comfy_before - baseline) > _VRAM_COLD_LOAD_THRESHOLD_BYTES
        if cold:
            marginal = self.comfy_peak - baseline
            state = "cold"
        else:
            marginal = self.comfy_peak - self.comfy_before
            state = "warm"
        if marginal <= 0:
            return None, state
        return marginal, state

    def trustworthy(self) -> bool:
        # Require at least two samples (otherwise we may have caught only the
        # idle baseline) AND a usable per-process marginal.
        if self.samples < 2:
            return False
        marginal, _ = self.marginal_and_state()
        return isinstance(marginal, int) and marginal > 0

    # ----- backward-compatibility shim ------------------------------------

    def peak_used_bytes(self) -> Optional[int]:
        """Deprecated: returns the per-process marginal (NOT whole-GPU peak).

        Old call sites referred to this as "peak"; the field name now means
        flux's marginal contribution to ComfyUI's allocation. Whole-GPU peak
        is available via :meth:`system_peak_used_bytes`.
        """
        marginal, _ = self.marginal_and_state()
        return marginal


def compute_max_batch(free_vram: Optional[int], per_image: Optional[int]) -> int:
    """Adaptive batch sizing under a free-VRAM budget.

    Returns 0 when the estimate says not even one image fits. That is advisory:
    the caller still submits batch=1 (after trying an idle-model free) and lets
    ComfyUI manage memory; only a real execution OOM fails the request.
    """
    if not isinstance(per_image, int) or per_image <= 0:
        # No estimate yet — be cautious: probe with batch_size=1.
        return 1
    if not isinstance(free_vram, int) or free_vram <= 0:
        return 1
    budget = max(0, free_vram - IMAGE_VRAM_RESERVE_BYTES)
    if budget < per_image:
        return 0  # caller surfaces 503 with Retry-After
    cap = max(1, budget // per_image)
    return min(int(cap), max(1, IMAGE_MAX_BATCH_SIZE))


def apply_batch_size(workflow: dict, meta: dict, batch_size: int) -> bool:
    """Set batch_size on the workflow's latent node. Returns True iff applied."""
    node_id = meta.get("batch_size_node")
    if not node_id or node_id not in workflow:
        return False
    inputs = workflow[node_id].get("inputs")
    if not isinstance(inputs, dict) or "batch_size" not in inputs:
        return False
    inputs["batch_size"] = max(1, int(batch_size))
    return True


@dataclass(frozen=True)
class ImageBackgroundRemovalDecision:
    remove_background: bool
    confidence: Optional[float] = None
    reason: str = ""
    source: str = "default"
    error: str = ""


def _background_removal_fallback(source: str, error: str = "") -> ImageBackgroundRemovalDecision:
    return ImageBackgroundRemovalDecision(
        remove_background=False,
        confidence=0.0,
        reason="background removal bypassed",
        source=source,
        error=str(error or "")[:200],
    )


def parse_image_background(value: Any) -> tuple[Optional[str], Optional[str]]:
    """Parse OpenAI's image `background` option.

    Returns (value, error). None and empty string mean OpenAI's default: auto.
    """
    if value is None or value == "":
        return "auto", None
    if not isinstance(value, str):
        return None, "background must be one of 'transparent', 'opaque', or 'auto'"
    normalized = value.strip().lower()
    if normalized in ("transparent", "opaque", "auto"):
        return normalized, None
    return None, "background must be one of 'transparent', 'opaque', or 'auto'"


def _parse_image_output_shape(
    receipt: RouteReceipt | None,
    *,
    output_format_raw: Any,
    output_compression_raw: Any,
    quality_raw: Any,
    background: str,
) -> tuple[str, Optional[int], str, Optional[Response]]:
    """Parse+validate output_format/output_compression/quality together.

    Returns ``(output_format, output_compression, quality, error_response)``.
    When ``error_response`` is not None the caller must return it immediately;
    the other three values are unused placeholders in that case.
    """
    output_format, fmt_err = parse_output_format(output_format_raw)
    if fmt_err:
        _record_image_input(receipt, "output_format", rejected_reason=fmt_err)
        return output_format, None, "auto", openai_error_response(
            fmt_err, param="output_format", code="invalid_value",
        )
    if output_format_raw not in (None, ""):
        _record_image_input(receipt, "output_format")

    conflict = background_format_conflict(background, output_format)
    if conflict:
        _record_image_input(receipt, "background", rejected_reason="conflicts_with_output_format")
        return output_format, None, "auto", openai_error_response(
            conflict, param="background", code="invalid_value",
        )

    output_compression, comp_err = parse_output_compression(output_compression_raw, output_format)
    if comp_err:
        _record_image_input(receipt, "output_compression", rejected_reason=comp_err)
        return output_format, None, "auto", openai_error_response(
            comp_err, param="output_compression", code="invalid_value",
        )
    if output_compression_raw not in (None, ""):
        _record_image_input(receipt, "output_compression")

    quality, quality_err = parse_quality(quality_raw)
    if quality_err:
        _record_image_input(receipt, "quality", rejected_reason=quality_err)
        return output_format, output_compression, quality, openai_error_response(
            quality_err, param="quality", code="invalid_value",
        )
    if quality_raw not in (None, ""):
        _record_image_input(receipt, "quality")

    return output_format, output_compression, quality, None


def _apply_quality_steps(
    manifest: Mapping[str, Any] | None,
    workflow: dict[str, Any],
    quality: str,
    receipt: RouteReceipt | None,
) -> dict[str, Any]:
    """Map `quality` to a per-workflow sampler-step count when the manifest
    declares a `quality_steps` table; otherwise record-only (no silent lie:
    the receipt shows quality was accepted but not applied to this workflow).
    """
    if quality == "auto":
        return workflow
    steps = quality_steps_from_manifest(manifest, quality)
    if steps is None:
        if receipt is not None:
            receipt.ignore_input(
                "quality",
                "resolved workflow has no quality_steps mapping; accepted but not applied",
            )
        return workflow
    return _apply_manifest_route_inputs(manifest, workflow, {"steps": steps})


def _ideogram4_is_grounded_json(prompt: str) -> bool:
    """True only if ``prompt`` is an Ideogram-4 caption with real grounding boxes.

    A prompt that merely parses as JSON is NOT enough: callers (e.g. an agent)
    routinely send ``{"high_level_description": "...prose..."}`` with no
    ``elements`` — Ideogram then gets a degenerate, ungrounded caption and
    renders worse text/layout (and trips the safety filter more often). Treat
    such payloads as plain text so they get structurized into real obj/text
    boxes. We accept elements at the top level (hand-authored shape) OR under
    ``compositional_deconstruction`` (the shape our structurizer emits).
    """
    try:
        data = json.loads(prompt)
    except (ValueError, TypeError):
        return False
    if not isinstance(data, dict):
        return False
    for container in (data, data.get("compositional_deconstruction")):
        if isinstance(container, dict):
            els = container.get("elements")
            if isinstance(els, list) and len(els) > 0:
                return True
    return False


def _ideogram4_brief_from_prompt(prompt: str) -> str:
    """Return a plain-text creative brief to feed the structurizer.

    Plain text passes through unchanged. JSON-wrapped prose (no grounding
    elements) gets its human-readable description fields pulled out so the
    structurizer converts the *intent*, not raw JSON syntax.
    """
    try:
        data = json.loads(prompt)
    except (ValueError, TypeError):
        return prompt
    if not isinstance(data, dict):
        return prompt
    parts = []
    for key in ("high_level_description", "prompt", "description", "scene"):
        val = data.get(key)
        if isinstance(val, str) and val.strip():
            parts.append(val.strip())
    style = data.get("style_description")
    if isinstance(style, dict):
        aes = style.get("aesthetics") or style.get("medium")
        if isinstance(aes, str) and aes.strip():
            parts.append(aes.strip())
    # Fall back to the raw string only if we found no usable prose.
    return "  ".join(parts) if parts else prompt


_IDEOGRAM4_STRUCTURIZE_USER_TEMPLATE = (
    "Convert this image description to an Ideogram 4 JSON caption. Output ONLY the JSON "
    "object, nothing before or after it, no markdown fences, no commentary.\n\n"
    "Input: {prompt}\n\n"
    "Schema (bbox = integers 0-1000 in order [y_min, x_min, y_max, x_max]).\n"
    "Element types: \"obj\" for visual objects, \"text\" for words rendered IN the image "
    "(labels, signs, captions, speech bubbles, annotations).\n"
    "Rules that make the model render reliably (follow ALL of them):\n"
    "1. DEPTH BANDS: always begin elements with full-width horizontal bands stacked back "
    "to front — a BACKGROUND band, a MID-GROUND band, and a GROUND band — even for simple "
    "scenes. Prefix each desc with its role in caps (e.g. \"BACKGROUND — ...\", \"GROUND — "
    "...\", \"PRIMARY SUBJECT — ...\"). These bands are what stop the model emitting a blank "
    "refusal image; never omit them.\n"
    "2. SUBJECT + PROPS: then a PRIMARY SUBJECT box, plus 1-3 secondary prop/scenery boxes "
    "spread across the canvas. Give each desc material + lighting detail, not just a noun.\n"
    "3. TEXT: for EVERY piece of visible text emit a SEPARATE \"text\" element with the exact "
    "words in its \"text\" field and a roomy own bbox. Never bury text inside an obj desc.\n"
    "4. Fill style_description.lighting and .photo with a full descriptive sentence each, not "
    "one word. Always give a concrete \"background\" string.\n"
    "5. ENGLISH ONLY: every \"text\" element value must be English using only Latin "
    "letters/numerals. Never emit Chinese, Japanese, Korean, or any non-English glyphs "
    "(the model injects them unprompted otherwise). Also append ', all rendered text in "
    "English only' to high_level_description.\n"
    'Example shape:\n'
    '{{"high_level_description":"one rich sentence describing the whole scene",'
    '"style_description":{{"aesthetics":"...","lighting":"full sentence on light source, direction, quality, color temperature",'
    '"photo":"full sentence on framing, composition, depth of field, lens","medium":"photograph"}},'
    '"compositional_deconstruction":{{"background":"concrete description of the backdrop",'
    '"elements":['
    '{{"type":"obj","bbox":[0,0,800,1000],"desc":"BACKGROUND — ... material/lighting"}},'
    '{{"type":"obj","bbox":[400,0,600,1000],"desc":"MID-GROUND — ... material/lighting"}},'
    '{{"type":"obj","bbox":[600,0,1000,1000],"desc":"GROUND — ... material/lighting"}},'
    '{{"type":"obj","bbox":[300,250,900,750],"desc":"PRIMARY SUBJECT — ... material/lighting"}},'
    '{{"type":"obj","bbox":[350,40,800,240],"desc":"PROP — a nearby object"}},'
    '{{"type":"text","bbox":[120,150,260,880],"text":"EXACT WORDS HERE","desc":"handwritten label"}}'
    ']}}}}'
)


def _ideogram4_minimal_grounded_json(brief: str) -> str:
    """Last-resort JSON wrapper for a plain-text brief.

    Returning raw plain text to Ideogram 4 almost always trips its safety
    classifier (grey 'Image blocked' output). When the LLM converter is
    unavailable or keeps producing invalid JSON, wrap the brief in a minimal
    but *grounded* JSON skeleton (subject + floor + backdrop boxes) — the
    r/StableDiffusion 'enough bboxes' fix — so we still hand the model the
    structured form it expects instead of guaranteed-blocked plain text.
    """
    safe = json.dumps(brief)[1:-1]  # escape quotes/newlines, drop outer quotes
    return (
        '{"high_level_description":"' + safe + '",'
        '"style_description":{"aesthetics":"as described","lighting":"flat",'
        '"photo":"illustration","medium":"illustration"},'
        '"compositional_deconstruction":{"background":"a plain backdrop",'
        '"elements":['
        '{"type":"obj","bbox":[250,300,750,800],"desc":"' + safe + '"},'
        '{"type":"obj","bbox":[0,800,1000,1000],"desc":"the ground"},'
        '{"type":"obj","bbox":[0,0,1000,280],"desc":"the backdrop behind the scene"}'
        ']}}'
    )


async def _ideogram4_structurize_prompt(plain_prompt: str) -> str:
    """Convert a plain-text prompt to Ideogram 4 JSON caption via local LLM.

    Retries the conversion a few times on parse failure, since Qwen3
    occasionally emits empty/garbled output. NEVER falls back to raw plain
    text (that reliably trips Ideogram's safety filter); on total failure it
    returns a minimal grounded JSON skeleton instead. Qwen3 in thinking mode
    uses ~1700 reasoning tokens before emitting visible output, so max_tokens
    must be >=2000.
    """
    # Truncate to ~600 chars — the converter only needs the creative brief, not
    # the full style/constraint boilerplate that callers often append.
    brief = plain_prompt[:600]
    user_msg = _IDEOGRAM4_STRUCTURIZE_USER_TEMPLATE.format(prompt=brief)
    for attempt in range(3):
        try:
            async with httpx.AsyncClient(timeout=httpx.Timeout(120, connect=5)) as client:
                resp = await client.post(
                    f"{KOBOLD_HOST}/v1/chat/completions",
                    json={
                        "messages": [{"role": "user", "content": user_msg}],
                        "max_tokens": 3000,
                        # Slightly vary temperature across retries so a stuck
                        # generation has a chance to produce different output.
                        "temperature": 0.1 + 0.2 * attempt,
                    },
                )
            if resp.status_code != 200:
                continue
            content = resp.json()["choices"][0]["message"]["content"].strip()
            # Drop any <think>...</think> block the model may leak despite thinking suppression.
            if "</think>" in content:
                content = content.split("</think>", 1)[1].strip()
            # Strip accidental markdown fences
            if content.startswith("```"):
                content = content.split("```")[1].lstrip("json").strip()
            # Some models add prose before/after the JSON — extract the outermost object.
            if not content.startswith("{") and "{" in content:
                content = content[content.index("{"): content.rindex("}") + 1]
            json.loads(content)  # validate — raises if not valid JSON
            return content
        except Exception:
            continue
    # All attempts failed — return grounded JSON, never raw plain text.
    return _ideogram4_minimal_grounded_json(brief)


async def resolve_image_background_decision(
    background: str,
    prompt: str,
    *,
    auth_context: AuthContext,
    force_bypass: bool = False,
    force_bypass_reason: str = "edit mask supplied",
) -> ImageBackgroundRemovalDecision:
    """Resolve OpenAI's background option into a workflow output selection."""
    if force_bypass:
        return _background_removal_fallback("forced_bypass", force_bypass_reason)
    if background == "transparent":
        return ImageBackgroundRemovalDecision(
            remove_background=True,
            confidence=1.0,
            reason="client requested transparent background",
            source="request",
        )
    if background == "opaque":
        return ImageBackgroundRemovalDecision(
            remove_background=False,
            confidence=1.0,
            reason="client requested opaque background",
            source="request",
        )
    return await decide_image_background_removal(prompt, auth_context=auth_context)


def _extract_json_object(text: str) -> Optional[dict]:
    """Best-effort JSON object extraction for backends that ignore json_object."""
    if not isinstance(text, str):
        return None
    stripped = text.strip()
    if not stripped:
        return None
    try:
        obj = json.loads(stripped)
        return obj if isinstance(obj, dict) else None
    except json.JSONDecodeError:
        pass
    start = stripped.find("{")
    end = stripped.rfind("}")
    if start < 0 or end <= start:
        return None
    try:
        obj = json.loads(stripped[start:end + 1])
    except json.JSONDecodeError:
        return None
    return obj if isinstance(obj, dict) else None


def parse_background_removal_decision(raw: Any, *, source: str = "llm") -> ImageBackgroundRemovalDecision:
    """Normalize the LLM's structured decision into the internal shape."""
    if isinstance(raw, str):
        raw = _extract_json_object(raw)
    if not isinstance(raw, dict):
        return _background_removal_fallback(source, "decision was not a JSON object")

    remove_background = raw.get("remove_background")
    if not isinstance(remove_background, bool):
        return _background_removal_fallback(source, "remove_background was not a boolean")

    confidence = raw.get("confidence")
    try:
        confidence_val = float(confidence) if confidence is not None else None
    except (TypeError, ValueError):
        confidence_val = None
    if confidence_val is not None:
        confidence_val = max(0.0, min(1.0, confidence_val))

    reason = raw.get("reason") or raw.get("rationale") or ""
    return ImageBackgroundRemovalDecision(
        remove_background=remove_background,
        confidence=confidence_val,
        reason=str(reason)[:200],
        source=source,
    )


async def decide_image_background_removal(
    prompt: str,
    *,
    auth_context: AuthContext,
    force_bypass: bool = False,
) -> ImageBackgroundRemovalDecision:
    """Ask the active LLM whether this image request should return transparency.

    Failure is intentionally non-fatal. The proxy can always produce the normal
    image, so unknown/invalid decisions default to bypass.
    """
    if force_bypass:
        return _background_removal_fallback("forced_bypass", "edit mask supplied")
    if not IMAGE_BACKGROUND_REMOVAL_ENABLED:
        return _background_removal_fallback("disabled")
    prompt = str(prompt or "").strip()
    if not prompt:
        return _background_removal_fallback("empty_prompt")

    active = await get_active_backend()
    # Generic: any local-swap LLM backend resolves its host from LLM_BACKEND_HOSTS.
    target_host = LLM_BACKEND_HOSTS.get(active) if active else None
    if active and _is_local_swap_backend(active) and target_host:
        service = active
    else:
        return _background_removal_fallback("llm_unavailable", "no active LLM backend")

    model_id = await effective_llm_model_for_host(target_host)
    if not model_id:
        model_id = default_model_for_operation("chat", "default")

    headers = configured_downstream_headers(auth_context, service)
    # enable_thinking=False suppresses thinking (engine-agnostic kwarg — the load-bearing mechanism).
    # No /no_think prompt-string injection: verified non-functional; kwarg-only is the contract.
    payload = {
        "model": model_id,
        "messages": [
            {
                "role": "system",
                "content": (
                    "Decide whether an image generation request should have its "
                    "background removed and returned as a transparent PNG. "
                    "Use the user's intent, not keyword matching. Return only JSON "
                    "with keys remove_background boolean, confidence number 0..1, "
                    "and reason string. Choose true for reusable assets such as "
                    "logos, stickers, product cutouts, icons, isolated objects for "
                    "commerce, or explicitly transparent-background intent. Choose "
                    "false for portraits, landscapes, scenes, paintings, context-rich "
                    "images, and ordinary photos where the environment is part of the result."
                ),
            },
            {"role": "user", "content": prompt},
        ],
        "temperature": 0,
        "max_tokens": 160,
        "response_format": {"type": "json_object"},
        "chat_template_kwargs": {_QWEN3_ENABLE_THINKING_KEY: False},
    }
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(IMAGE_BACKGROUND_REMOVAL_TIMEOUT, connect=5)) as client:
            resp = await client.post(f"{target_host}/v1/chat/completions", headers=headers, json=payload)
        if resp.status_code != 200:
            return _background_removal_fallback("llm_error", f"HTTP {resp.status_code}: {resp.text[:120]}")
        data = resp.json()
        content = (
            ((data.get("choices") or [{}])[0].get("message") or {}).get("content")
            if isinstance(data, dict)
            else ""
        )
        return parse_background_removal_decision(content, source="llm")
    except Exception as e:
        return _background_removal_fallback("llm_error", str(e))


def set_workflow_background_removal(workflow: dict, meta: dict, enabled: bool) -> bool:
    """Select the workflow-defined plain or transparent image path.

    Background-removal graph structure lives in the committed workflow JSON.
    The proxy only toggles the SaveImage input declared in `_meta`.
    """
    cfg = meta.get("background_removal")
    if not isinstance(cfg, dict):
        return False
    save_node_id = str(cfg.get("save_node") or "")
    selected_input = cfg.get("transparent_image" if enabled else "plain_image")

    save = workflow.get(save_node_id)
    if not isinstance(save, dict) or save.get("class_type") != "SaveImage":
        return False
    inputs = save.get("inputs")
    if not isinstance(inputs, dict):
        return False
    if not (
        isinstance(selected_input, list)
        and len(selected_input) == 2
        and isinstance(selected_input[0], str)
        and isinstance(selected_input[1], int)
        and selected_input[0] in workflow
    ):
        return False
    inputs["images"] = list(selected_input)
    return True


def _image_signing_secret() -> bytes:
    """Resolve (and lazily generate) the HMAC secret used for signed image URLs."""
    global _image_url_signing_secret
    if _image_url_signing_secret is not None:
        return _image_url_signing_secret
    if IMAGE_SIGNED_URL_SECRET_CFG:
        _image_url_signing_secret = IMAGE_SIGNED_URL_SECRET_CFG.encode("utf-8")
        return _image_url_signing_secret
    secret_path = IMAGE_CACHE_DIR / ".url_signing_secret"
    if secret_path.exists():
        try:
            data = secret_path.read_bytes().strip()
            if data:
                _image_url_signing_secret = data
                return _image_url_signing_secret
        except Exception:
            pass
    # Generate and persist.
    IMAGE_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    secret = secrets.token_urlsafe(48).encode("utf-8")
    try:
        secret_path.write_bytes(secret)
        os.chmod(secret_path, 0o600)
    except Exception as e:
        print(f"[proxy] Could not persist image URL signing secret: {e}", flush=True)
    _image_url_signing_secret = secret
    return secret


def _sign_image_token(image_id: str, expires: int) -> str:
    return _sign_asset_token(image_id, expires)


def _sign_asset_token(asset_id: str, expires: int, metadata_mode: str | None = None) -> str:
    # ``metadata_mode`` is part of the signed message so a client cannot flip a
    # ``none`` URL to ``full`` (the signature covers it).
    suffix = f":md={metadata_mode}" if metadata_mode else ""
    msg = f"{asset_id}:{expires}{suffix}".encode("utf-8")
    return hmac.new(_image_signing_secret(), msg, hashlib.sha256).hexdigest()


def verify_image_signature(image_id: str, expires: int, sig: str) -> bool:
    """Constant-time HMAC verification for signed image URLs."""
    return verify_asset_signature(image_id, expires, sig)


def verify_asset_signature(asset_id: str, expires: int, sig: str, metadata_mode: str | None = None) -> bool:
    """Constant-time HMAC verification for signed asset URLs."""
    if expires < int(time.time()):
        return False
    expected = _sign_asset_token(asset_id, expires, metadata_mode)
    return hmac.compare_digest(expected, str(sig or ""))


def _asset_owner_key(auth_context: AuthContext | None) -> str | None:
    from gateway.ownership import owner_key
    # A list route asks once per row; in a read request the answer is read once.
    # The entry holds the context itself, so its id cannot be reused by another object.
    return request_connections.memo(
        ("asset-owner-key", id(auth_context)),
        lambda: (auth_context, owner_key(auth_context, path=ADMIN_STORE.path)))[1]


def _asset_read_owner_keys(auth_context: AuthContext | None) -> tuple[str, ...]:
    from gateway.ownership import credential_owner_keys
    identity = getattr(auth_context, "identity", None)
    return request_connections.memo(
        ("asset-read-owner-keys", id(auth_context)),
        lambda: (auth_context, credential_owner_keys(
            _asset_owner_key(auth_context), path=ADMIN_STORE.path,
            current_key_hash=getattr(identity, "key_hash", None))))[1]


async def _warm_video_owner_keys(auth_context: AuthContext | None) -> None:
    """Resolve the caller's owner keys (SQLite) off the loop, once per request.

    `_video_job_access_allowed` reads them through the request memo, so the
    synchronous video checks that follow hit the memo instead of the database.
    """
    if auth_context is not None:
        await asyncio.to_thread(_asset_read_owner_keys, auth_context)


def _asset_metadata_path(asset_id: str) -> Path | None:
    parsed = _parse_asset_id(asset_id)
    if parsed is None:
        return None
    _, digest = parsed
    return IMAGE_CACHE_DIR / f"{digest}.meta.json"


def _read_asset_metadata(asset_id: str) -> dict[str, Any]:
    path = _asset_metadata_path(asset_id)
    if path is None or not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


def _write_asset_metadata(asset_id: str, metadata: Mapping[str, Any]) -> None:
    path = _asset_metadata_path(asset_id)
    if path is None:
        return
    IMAGE_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f"{path.name}.tmp")
    try:
        tmp.write_text(json.dumps(dict(metadata), sort_keys=True), encoding="utf-8")
        tmp.replace(path)
    except Exception as e:
        print(f"[proxy] Could not persist asset metadata for {asset_id}: {e}", flush=True)
        try:
            tmp.unlink(missing_ok=True)
        except Exception:
            pass


def _record_asset_owner(asset_id: str, owner_key_hash: str | None) -> None:
    from gateway.ownership import stored_owner_key
    owner_key_hash = stored_owner_key(owner_key_hash, path=ADMIN_STORE.path)
    if not owner_key_hash:
        return
    metadata = _read_asset_metadata(asset_id)
    owners_raw = metadata.get("owner_key_hashes") or []
    owners = [str(owner) for owner in owners_raw if isinstance(owner, str)]
    if owner_key_hash not in owners:
        owners.append(owner_key_hash)
    metadata["asset_id"] = asset_id
    metadata["owner_key_hashes"] = sorted(set(owners))
    metadata["updated_at"] = int(time.time())
    _write_asset_metadata(asset_id, metadata)


def _asset_access_allowed(asset_id: str, auth_context: AuthContext | None) -> bool:
    owners_raw = _read_asset_metadata(asset_id).get("owner_key_hashes") or []
    owners = {str(owner) for owner in owners_raw if isinstance(owner, str)}
    if not owners:
        # Fail closed for authenticated callers when metadata is absent. Auth-
        # disabled local runs have no identity and keep the old cache behavior.
        return _asset_owner_key(auth_context) is None
    return bool(owners.intersection(_asset_read_owner_keys(auth_context)))


_CURRENT_MAKER = object()


class MediaPublishCanceled(Exception):
    """A canceled make job tried to publish output."""


class _MakePublishGate:
    """Decides once, under one lock, whether a make job publishes or is canceled.

    Publication (``store_asset_bytes``, which also keeps the prompt) and
    cancel take the same lock, so a job never does both.

    Cancel also stops the job's work on its event loop: it ends the wait for
    a turn (``stop_waiting``). Running calls drain before cancellation settles;
    closing an HTTP call would not prove that the backend released its resources.
    """

    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.canceled = False
        self.published = False
        self.loop: asyncio.AbstractEventLoop | None = None
        self.stop_waiting: asyncio.Event | None = None

    def cancel(self) -> bool:
        """Cancel unless output is already published. Safe from any thread."""
        with self.lock:
            if self.published:
                return False
            self.canceled = True
            loop = self.loop
        if loop is not None:
            with contextlib.suppress(RuntimeError):  # A closed loop runs nothing.
                loop.call_soon_threadsafe(self._stop)
        return True

    def _stop(self) -> None:
        # On the job's loop, which also clears ``stop_waiting`` when the wait ends.
        if self.stop_waiting is not None:
            self.stop_waiting.set()



_MAKE_PUBLISH_GATE: contextvars.ContextVar[_MakePublishGate | None] = contextvars.ContextVar(
    "make_publish_gate", default=None,
)


def store_asset_bytes(content: bytes, **options: Any) -> str:
    """Store clean media; any retained prompt lives only in asset_prompts.

    Inside a canceled make job this publishes nothing and raises
    ``MediaPublishCanceled``.
    """
    gate = _MAKE_PUBLISH_GATE.get()
    if gate is None:
        return _store_asset_bytes(content, **options)
    with gate.lock:
        if gate.canceled:
            raise MediaPublishCanceled("the make job was canceled")
        asset_id = _store_asset_bytes(content, **options)
        gate.published = True
    return asset_id


def _store_asset_bytes(
    content: bytes,
    *,
    kind: str = "img",
    suffix: str = ".png",
    owner_key_hash: str | None = None,
    maker_person_id: str | None | object = _CURRENT_MAKER,
) -> str:
    """Store clean media; any retained prompt lives only in asset_prompts."""
    kind = str(kind).strip().lower()
    if kind not in {"img", "aud", "vid"}:
        raise ValueError("asset kind must be one of img, aud, vid")
    suffix = str(suffix or "").strip().lower()
    if not suffix.startswith("."):
        suffix = f".{suffix or 'bin'}"
    delivery = media_delivery.current()
    decision = getattr(delivery, "prompt_decision", None)
    text = getattr(delivery, "prompt_text", None)
    metadata: dict[str, str] = {}
    if decision is not None and decision.keep and text:
        try:
            metadata = {} if kind == "aud" and not getattr(delivery, "capture_embedded_prompt", True) else prompt_memory.capture_metadata(content, suffix)
        except Exception:
            # A metadata/storage failure never discards a finished generation.
            decision = prompt_memory.Decision(decision.person_id, False, "storage_failed")
            delivery.prompt_decision = decision
    content = media_metadata.strip_metadata(content, suffix, workdir=media_delivery.DEFAULT_WORKDIR)
    digest = hashlib.sha256(content).hexdigest()
    asset_id = f"{kind}_{digest}"
    IMAGE_CACHE_DIR.mkdir(parents=True, exist_ok=True)
    target = IMAGE_CACHE_DIR / f"{digest}{suffix}"
    with prompt_metadata_migration.CACHE_MUTATION_LOCK:
        if not target.exists():
            tmp = target.with_suffix(f"{suffix}.tmp")
            try:
                tmp.write_bytes(content)
                tmp.replace(target)
            finally:
                tmp.unlink(missing_ok=True)
        _record_asset_owner(asset_id, owner_key_hash)
        person_id = (getattr(delivery, "person_id", None) or getattr(decision, "person_id", None)) if maker_person_id is _CURRENT_MAKER else maker_person_id
        metadata_sidecar = _read_asset_metadata(asset_id)
        makers = set(metadata_sidecar.get("maker_person_ids") or [])
        if person_id:
            makers.add(person_id)
        if makers:
            metadata_sidecar["maker_person_ids"] = sorted(makers)
        _write_asset_metadata(asset_id, metadata_sidecar)
    if decision is not None and decision.keep and text:
        saved = prompt_memory.safe_put(
            asset_id, decision.person_id, text,
            kept_until=decision.kept_until, metadata=metadata,
            admin_path=ADMIN_STORE.path, created_at=decision.created_at,
        )
        if not saved:
            delivery.prompt_decision = prompt_memory.Decision(decision.person_id, False, "storage_failed")
    return asset_id


def store_image_bytes(content: bytes, *, owner_key_hash: str | None = None, suffix: str = ".png") -> str:
    """Write `content` to the content-addressed cache. Returns the image_id."""
    return store_asset_bytes(
        content,
        kind="img",
        suffix=suffix,
        owner_key_hash=owner_key_hash,
    )


_ASSET_SUFFIXES_BY_KIND = {
    "img": (".png", ".jpg", ".jpeg", ".webp", ".gif"),
    "aud": (".wav", ".mp3", ".flac", ".ogg", ".m4a", ".aac"),
    "vid": (".mp4", ".webm", ".mov", ".mkv"),
}

_ASSET_MEDIA_TYPES = {
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".jpeg": "image/jpeg",
    ".webp": "image/webp",
    ".gif": "image/gif",
    ".wav": "audio/wav",
    ".mp3": "audio/mpeg",
    ".flac": "audio/flac",
    ".ogg": "audio/ogg",
    ".m4a": "audio/mp4",
    ".aac": "audio/aac",
    ".mp4": "video/mp4",
    ".webm": "video/webm",
    ".mov": "video/quicktime",
    ".mkv": "video/x-matroska",
}

_ASSET_KIND_NAMES = {
    "img": "image",
    "aud": "audio",
    "vid": "video",
}


def _parse_asset_id(asset_id: str) -> tuple[str, str] | None:
    if not isinstance(asset_id, str) or "_" not in asset_id:
        return None
    kind, digest = asset_id.split("_", 1)
    if kind not in _ASSET_SUFFIXES_BY_KIND:
        return None
    if len(digest) != 64 or not all(c in "0123456789abcdef" for c in digest):
        return None
    return kind, digest


def asset_cache_path(asset_id: str) -> Optional[Path]:
    parsed = _parse_asset_id(asset_id)
    if parsed is None:
        return None
    kind, digest = parsed
    candidates = [IMAGE_CACHE_DIR / f"{digest}{suffix}" for suffix in _ASSET_SUFFIXES_BY_KIND[kind]]
    listed = directory_index.names(IMAGE_CACHE_DIR)  # one listing for every asset, not five probes each
    if listed is None:
        for candidate in candidates:
            if candidate.exists():
                return candidate
        try:
            listed = os.listdir(IMAGE_CACHE_DIR)
        except OSError:
            return candidates[0]
    found = next((candidate for candidate in candidates if candidate.name in listed), None)
    if found is not None:
        return found
    # The output kept its own suffix (a .gif or .webp from ComfyUI `gifs` or `images`).
    other = directory_index.stored_name(listed, digest)
    return IMAGE_CACHE_DIR / other if other else candidates[0]


def asset_media_type(asset_id: str, path: Path | None = None) -> str:
    path = path or asset_cache_path(asset_id)
    suffix = path.suffix.lower() if path is not None else ""
    return _ASSET_MEDIA_TYPES.get(suffix, "application/octet-stream")


def _gateway_asset_metadata_payload(
    asset_id: str,
    request: Request,
    *,
    cache_path: Path,
) -> dict[str, Any]:
    parsed = _parse_asset_id(asset_id)
    kind = parsed[0] if parsed else ""
    stat = cache_path.stat()
    metadata = _read_asset_metadata(asset_id)
    updated_at = metadata.get("updated_at")
    try:
        updated_at_value = int(updated_at)
    except (TypeError, ValueError):
        updated_at_value = int(stat.st_mtime)
    return {
        "object": "gateway.asset",
        "id": asset_id,
        "asset_id": asset_id,
        "kind": _ASSET_KIND_NAMES.get(kind, kind or "asset"),
        "media_type": asset_media_type(asset_id, cache_path),
        "size_bytes": int(stat.st_size),
        "created_at": int(stat.st_ctime),
        "updated_at": updated_at_value,
        "content_url": build_signed_asset_url(request, asset_id),
        "content_route": f"/v1/assets/{asset_id}/content",
        "expires_in": IMAGE_SIGNED_URL_TTL,
        "owner_scoped": bool(metadata.get("owner_key_hashes")),
    }


def image_cache_path(image_id: str) -> Optional[Path]:
    if not image_id.startswith("img_"):
        return None
    return asset_cache_path(image_id)


def build_signed_asset_url(request: Request, asset_id: str, metadata_mode: str | None = None) -> str:
    """Build a signed, hostname-aware URL for a generated asset.

    The URL carries ``md=full|none``. Its default is ``none`` because a
    transferable bearer URL cannot establish the maker's identity.
    """
    mode = metadata_mode or provenance.METADATA_NONE
    proto = (request.headers.get("x-forwarded-proto") or request.url.scheme or "http").split(",")[0].strip()
    host = request.headers.get("x-forwarded-host") or request.headers.get("host") or request.url.netloc
    if mode == thumbnails.THUMB_MODE:
        # The expiry steps once per TTL, so the URL is the same all window long
        # and the browser can keep the preview between visits.
        expires = (int(time.time()) // IMAGE_SIGNED_URL_TTL + 2) * IMAGE_SIGNED_URL_TTL
        sig = _sign_asset_token(asset_id, expires, mode)
        return f"{proto}://{host}/v1/assets/{asset_id}/thumbnail?expires={expires}&sig={sig}"
    expires = int(time.time()) + IMAGE_SIGNED_URL_TTL
    sig = _sign_asset_token(asset_id, expires, mode)
    return f"{proto}://{host}/v1/assets/{asset_id}/content?expires={expires}&md={mode}&sig={sig}"


def build_signed_image_url(request: Request, image_id: str, metadata_mode: str | None = None) -> str:
    """Build a signed, hostname-aware URL for an image stored in the cache.

    Honors `X-Forwarded-Proto` and the request's Host header so the URL works
    regardless of which Traefik route the client came in on.
    """
    mode = metadata_mode or provenance.METADATA_NONE
    expires = int(time.time()) + IMAGE_SIGNED_URL_TTL
    sig = _sign_asset_token(image_id, expires, mode)
    proto = (request.headers.get("x-forwarded-proto") or request.url.scheme or "http").split(",")[0].strip()
    host = request.headers.get("x-forwarded-host") or request.headers.get("host") or request.url.netloc
    return f"{proto}://{host}/v1/images/{image_id}/content?expires={expires}&md={mode}&sig={sig}"



def has_vision_content(messages) -> bool:
    """Return True iff any chat message carries an image content block.

    We check the OpenAI standard `image_url` block as well as the Anthropic-
    flavored `input_image` shape that some clients use against this proxy.
    """
    if not isinstance(messages, list):
        return False
    for msg in messages:
        if not isinstance(msg, dict):
            continue
        content = msg.get("content")
        if not isinstance(content, list):
            continue
        for block in content:
            if not isinstance(block, dict):
                continue
            btype = block.get("type")
            if btype in ("image_url", "input_image", "image"):
                return True
    return False


def _comfy_execution_error_message(job: Mapping[str, Any] | None) -> str | None:
    """Return a safe, short ComfyUI execution error summary if one is present."""
    status_block = (job or {}).get("status", {}) if isinstance(job, Mapping) else {}
    if not isinstance(status_block, Mapping):
        return None

    messages = status_block.get("messages", []) or []
    for msg in messages:
        if not (isinstance(msg, (list, tuple)) and msg and msg[0] == "execution_error"):
            continue
        payload = msg[1] if len(msg) > 1 and isinstance(msg[1], Mapping) else {}
        node_type = str(payload.get("node_type") or "").strip()
        node_id = str(payload.get("node_id") or "").strip()


        location = "ComfyUI execution error"
        if node_type and node_id:
            location = f"ComfyUI {node_type} node {node_id}"
        elif node_type:
            location = f"ComfyUI {node_type}"
        elif node_id:
            location = f"ComfyUI node {node_id}"

        return f"{location}: execution failed"[:500]

    status = str(status_block.get("status_str") or status_block.get("status") or "").lower()
    if status == "error":
        return "ComfyUI execution failed"
    return None


def _comfy_execution_error_node_id(job: Mapping[str, Any] | None) -> str | None:
    status_block = (job or {}).get("status", {}) if isinstance(job, Mapping) else {}
    for msg in (status_block.get("messages", []) or []) if isinstance(status_block, Mapping) else []:
        if isinstance(msg, (list, tuple)) and msg and msg[0] == "execution_error":
            payload = msg[1] if len(msg) > 1 and isinstance(msg[1], Mapping) else {}
            node_id = str(payload.get("node_id") or "").strip()
            return node_id or None
    return None


def _video_job_warnings(record: Mapping[str, Any] | None, job: Mapping[str, Any] | None) -> list[str]:
    """Warnings read from a finished job's outputs (character replace: how many
    people were tracked)."""
    subject = (record or {}).get("subject") if isinstance(record, Mapping) else None
    if not isinstance(subject, Mapping):
        return []
    count = video_subject.tracked_count((job or {}).get("outputs") if isinstance(job, Mapping) else None)
    return video_subject.warnings_for(
        count, explicit=bool(subject.get("explicit")), subject=str(subject.get("subject") or "person"))


def _chain_failure_error(record: Mapping[str, Any] | None, job: Mapping[str, Any] | None, message: str) -> dict[str, Any]:
    """Error object for a failed video job. A long-video chain adds which
    segment failed and how many finished. The job fails as a whole: no partial
    video is kept, so a truncated clip is never passed off as the result."""
    error: dict[str, Any] = {"code": "video_generation_failed", "message": message}
    chain = (record or {}).get("chain") if isinstance(record, Mapping) else None
    if not isinstance(chain, Mapping):
        return error
    index = video_extend.segment_of_node(chain.get("units") or [], _comfy_execution_error_node_id(job) or "")
    if index is None:
        return error
    total = int(chain.get("segments") or 0)
    frames = list(chain.get("segment_frames") or [])
    fps = float(chain.get("fps") or 24.0)
    done_frames = int(chain.get("source_frames") or 0) + sum(frames[:index])
    error.update({
        "message": (f"segment {index + 1} of {total} failed ({index} finished); no partial video is kept. "
                    f"{message}")[:600],
        "failed_segment": index + 1,
        "segments_completed": index,
        "segments_total": total,
        "completed_seconds": round(done_frames / fps, 3),
    })
    return error


def _comfy_prompt_queue_position_from_queue(queue: Mapping[str, Any], prompt_id: str) -> Optional[int]:
    """Return a 1-based pending queue position for a ComfyUI prompt, if known."""
    pending = queue.get("queue_pending")
    if not isinstance(pending, list):
        return None
    for index, entry in enumerate(pending, start=1):
        if isinstance(entry, (list, tuple)) and len(entry) >= 2 and entry[1] == prompt_id:
            return index
    return None


async def _comfy_prompt_queue_position(
    client: httpx.AsyncClient,
    prompt_id: str,
    headers: Mapping[str, str],
) -> Optional[int]:
    try:
        response = await client.get(f"{COMFY_HOST}/queue", headers=dict(headers), timeout=HEALTH_CHECK_TIMEOUT)
    except Exception:
        return None
    if response.status_code != 200:
        return None
    try:
        queue = response.json()
    except Exception:
        return None
    if not isinstance(queue, Mapping):
        return None
    return _comfy_prompt_queue_position_from_queue(queue, prompt_id)


async def _cancel_comfy_prompt(
    client: httpx.AsyncClient,
    prompt_id: str,
    headers: Mapping[str, str],
    *,
    reason: str,
) -> bool:
    try:
        response = await client.post(
            f"{COMFY_HOST}/api/jobs/{prompt_id}/cancel",
            headers=dict(headers),
            timeout=HEALTH_CHECK_TIMEOUT,
        )
    except Exception as e:
        print(f"[proxy] ComfyUI cancel failed for {prompt_id} after {reason}: {e}", flush=True)
        return False
    if response.status_code != 200:
        print(
            f"[proxy] ComfyUI cancel failed for {prompt_id} after {reason}: HTTP {response.status_code}",
            flush=True,
        )
        return False
    print(f"[proxy] ComfyUI prompt cancelled after {reason}: {prompt_id}", flush=True)
    return True


def _image_generation_timeout_response(queue_position: Optional[int]) -> Response:
    error: dict[str, Any] = {
        "message": "Image generation timed out before ComfyUI returned an image",
        "type": "api_error",
        "code": "image_generation_timeout",
    }
    if queue_position is not None:
        error["queue_position"] = queue_position
        error["message"] = (
            "Image generation timed out before ComfyUI returned an image "
            f"(queue_position={queue_position})"
        )
    return Response(
        content=json.dumps({"error": error}),
        status_code=504,
        media_type="application/json",
    )


def _image_client_disconnected_response(prompt_id: str) -> Response:
    return Response(
        content=json.dumps({
            "error": {
                "message": "Image generation cancelled because the client disconnected",
                "type": "api_error",
                "code": "image_client_disconnected",
                "prompt_id": prompt_id,
            }
        }),
        status_code=499,
        media_type="application/json",
    )


async def _request_is_disconnected(request: Request | None) -> bool:
    if request is None or not hasattr(request, "is_disconnected"):
        return False
    try:
        return bool(await request.is_disconnected())
    except Exception:
        return False


async def _comfy_run_round(
    client: httpx.AsyncClient,
    workflow: dict,
    headers: dict,
    label: str,
    *,
    vram_probe: Optional[_VramProbe] = None,
    request: Request | None = None,
    max_wait_s: int | None = None,
) -> tuple[Optional[Response], list[bytes]]:
    """Submit a single ComfyUI prompt and harvest the resulting image bytes.

    ``max_wait_s`` replaces COMFY_TIMEOUT as the wall-clock limit (queue wait included);
    async jobs pass a long value so a prompt queued behind a video render is not cancelled.

    Returns (error_response, image_bytes_list). On success error_response is None.
    Caller is responsible for any retry / batch-splitting strategy.

    If ``vram_probe`` is provided, it is started before the prompt is
    submitted and stopped after the round completes (including on error).
    The probe samples ComfyUI's per-process VRAM via nvidia-smi (filtered to
    the ComfyUI PID set on GPU0); callers read ``marginal_and_state()`` to
    get flux's marginal contribution and whether the run was warm or cold.
    """
    if vram_probe is not None:
        vram_probe.start()

    async def _finalize_probe() -> None:
        if vram_probe is not None:
            try:
                await vram_probe.stop()
            except Exception as e:
                print(f"[proxy] VRAM probe stop error: {e}", flush=True)

    prompt_id: Optional[str] = None
    try:
        try:
            resp = await client.post(
                f"{COMFY_HOST}/prompt",
                headers=headers,
                json=_build_comfy_submit_payload(workflow),
            )
        except httpx.TimeoutException:
            return Response(
                content=json.dumps({"error": {"message": "ComfyUI request timeout", "type": "api_error"}}),
                status_code=504,
                media_type="application/json",
            ), []
        except httpx.ConnectError:
            return Response(
                content=json.dumps({"error": {"message": f"ComfyUI unavailable at {COMFY_HOST}", "type": "api_error"}}),
                status_code=502,
                media_type="application/json",
            ), []
        except httpx.TransportError:
            # The peer dropped the connection mid-exchange (e.g. RemoteProtocolError).
            return Response(
                content=json.dumps({"error": {"message": f"Image backend connection dropped", "type": "api_error"}}),
                status_code=502,
                media_type="application/json",
            ), []

        if resp.status_code != 200:
            return Response(
                content=json.dumps({"error": {"message": f"ComfyUI error: {resp.text}", "type": "api_error"}}),
                status_code=502,
                media_type="application/json",
            ), []

        result = resp.json()
        prompt_id = result.get("prompt_id")
        if not prompt_id:
            return Response(
                content=json.dumps({"error": {"message": "No prompt_id returned", "type": "api_error"}}),
                status_code=502,
                media_type="application/json",
            ), []

        print(f"[proxy] ComfyUI {label} submitted: {prompt_id}", flush=True)

        # Keep the original total sleep budget; history request time was never
        # charged against it. Check immediately, then back off to the old cadence.
        remaining_wait_s = float(max_wait_s or COMFY_TIMEOUT)
        poll_delay_s = 0.0
        job = None
        while remaining_wait_s > 0:
            if await _request_is_disconnected(request):
                await _cancel_comfy_prompt(client, prompt_id, headers, reason="client disconnect")
                return _image_client_disconnected_response(prompt_id), []
            if poll_delay_s:
                await asyncio.sleep(poll_delay_s)
                remaining_wait_s -= poll_delay_s
            poll_delay_s = min(
                poll_delay_s * 2 if poll_delay_s else 0.05,
                0.5,
                remaining_wait_s,
            )
            try:
                history_resp = await client.get(f"{COMFY_HOST}/history/{prompt_id}", headers=headers)
            except httpx.TransportError:
                continue
            if history_resp.status_code != 200:
                continue
            history = history_resp.json()
            if prompt_id not in history:
                continue
            candidate = history[prompt_id]
            error_message = _comfy_execution_error_message(candidate)
            if error_message:
                return Response(
                    content=json.dumps({
                        "error": {
                            "message": error_message,
                            "type": "api_error",
                        }
                    }),
                    status_code=502,
                    media_type="application/json",
                ), []
            if candidate.get("status", {}).get("completed"):
                job = candidate
                break

        if job is None:
            queue_position = await _comfy_prompt_queue_position(client, prompt_id, headers)
            await _cancel_comfy_prompt(client, prompt_id, headers, reason="image timeout")
            return _image_generation_timeout_response(queue_position), []

        images: list[bytes] = []
        outputs = job.get("outputs", {})
        for _node_id, node_output in outputs.items():
            if "images" not in node_output:
                continue
            for img_info in node_output["images"]:
                filename = img_info.get("filename")
                subfolder = img_info.get("subfolder", "")
                img_type = img_info.get("type", "output")
                params = {"filename": filename, "type": img_type}
                if subfolder:
                    params["subfolder"] = subfolder
                try:
                    img_resp = await client.get(f"{COMFY_HOST}/view", headers=headers, params=params)
                except httpx.TransportError:
                    continue
                if img_resp.status_code == 200 and img_resp.content:
                    images.append(img_resp.content)
        return None, images
    except asyncio.CancelledError:
        if prompt_id:
            await _cancel_comfy_prompt(client, prompt_id, headers, reason="request cancellation")
        raise
    finally:
        await _finalize_probe()


def _build_image_response_payload(
    request: Request,
    images: list[bytes],
    response_format: str,
    warning_headers: dict,
    auth_context: AuthContext | None = None,
    *,
    output_format: str = "png",
    output_compression: Optional[int] = None,
    background: Optional[str] = None,
    quality: Optional[str] = None,
    size: Optional[str] = None,
) -> Response:
    """Shape `data[]` for either b64_json or url, honoring the client's choice.

    `output_format`/`output_compression` drive a real Pillow re-encode (not
    just an echoed label): every image in `images` is ComfyUI's native PNG
    bytes until this point. `background`/`quality`/`size` are echoed at the
    top level to match the gpt-image-1 response shape; pass the *resolved*
    background ("transparent"/"opaque", never "auto") since that is what
    OpenAI itself echoes back.
    """
    data: list[dict] = []
    owner_key_hash = _asset_owner_key(auth_context)
    suffix = f".{output_format}" if output_format != "jpeg" else ".jpg"
    delivery = media_delivery.current()
    mode = delivery.mode if delivery is not None else _media_metadata_bound(auth_context)
    for index, raw in enumerate(images):
        # Keep the in-memory response copy for the requester's profile mode.
        # store_asset_bytes strips the cache copy and writes the sole prompt row.
        record = _image_provenance_record(
            delivery, index, size=size, quality=quality, background=background,
            output_format=output_format, output_compression=output_compression,
        )
        raw = media_delivery.attach_provenance(raw, ".png", record)
        exif = (
            media_metadata.exif_bytes(media_delivery.image_exif_entries(raw, record))
            if output_format != "png" else None
        )
        encoded, mime_type = encode_image_bytes(
            raw, output_format, output_compression, exif=exif
        )
        image_id = store_image_bytes(encoded, owner_key_hash=owner_key_hash, suffix=suffix)
        item: dict[str, Any] = {
            "asset_id": image_id,
            "asset_url": build_signed_asset_url(request, image_id),
            "media_type": mime_type,
        }
        if response_format == "url":
            item["url"] = build_signed_image_url(request, image_id)
        else:
            # Delivered copy: the request/profile decides; the stored copy is untouched.
            delivered = media_delivery.deliver_bytes(encoded, suffix, mode)
            item["b64_json"] = base64.b64encode(delivered).decode("utf-8")
        data.append(item)
    if delivery is not None and delivery.receipt is not None:
        from gateway import media_ingestion
        media_ingestion.index_receipt_assets(delivery.receipt, data)
    headers = {"content-type": "application/json"}
    headers.update(warning_headers)
    payload: dict[str, Any] = {
        "created": int(time.time()),
        "data": data,
        "output_format": output_format,
    }
    if background is not None:
        payload["background"] = background
    # "auto" is a request-time convenience, never a value OpenAI's own
    # response schema accepts -- it always echoes back the resolved tier,
    # or omits the field. We have no way to know which concrete tier an
    # unspecified/"auto" request would have resolved to, so omit rather
    # than fabricate one.
    if quality is not None and quality != "auto":
        payload["quality"] = quality
    if size is not None:
        payload["size"] = size
    return Response(
        content=json.dumps(payload),
        status_code=200,
        media_type="application/json",
        headers=headers,
    )


def _image_provenance_record(
    delivery: "media_delivery.DeliveryContext | None",
    index: int,
    *,
    size: Optional[str],
    quality: Optional[str],
    background: Optional[str],
    output_format: str,
    output_compression: Optional[int],
) -> dict[str, Any]:
    """Provenance record for image ``index`` of this request (no secrets)."""
    parameters: dict[str, Any] = dict(delivery.parameters) if delivery is not None else {}
    parameters.update({
        k: v for k, v in (
            ("size", size), ("quality", quality), ("background", background),
            ("output_format", output_format), ("output_compression", output_compression),
        ) if v is not None
    })
    seeds = delivery.seeds if delivery is not None else []
    return provenance.build_provenance_record(
        receipt=delivery.receipt if delivery is not None else None,
        kind="image",
        model_alias=delivery.model_alias if delivery is not None else None,
        seed=seeds[index] if index < len(seeds) else None,
        parameters=parameters,
        index=index,
    )


def _default_image_response_format(requested_model: Any) -> str:
    model_id = normalize_model_id(str(requested_model or ""))
    if model_id.startswith("dall-e-"):
        return "url"
    return "b64_json"


async def _generate_images_with_adaptive_batching(
    request: Request,
    client: httpx.AsyncClient,
    base_workflow: dict,
    meta: dict,
    seed_node: Optional[str],
    seed_field: str,
    workflow_name: str,
    width: int,
    height: int,
    n_requested: int,
    response_format: str,
    headers: dict,
    background_removal_decision: Optional[ImageBackgroundRemovalDecision] = None,
    fallback_workflow: Optional[dict] = None,
    fallback_workflow_name: Optional[str] = None,
    image_transform: Optional[Callable[[bytes], bytes]] = None,
    image_response_headers: Optional[dict[str, str]] = None,
    fixed_seed: Optional[int] = None,
    auth_context: AuthContext | None = None,
    output_format: str = "png",
    output_compression: Optional[int] = None,
    output_background: Optional[str] = None,
    output_quality: Optional[str] = None,
    output_size: Optional[str] = None,
) -> Response:
    """Submit `ceil(n / max_batch)` rounds and aggregate `n_requested` images.

    On the first round (when no VRAM estimate exists), force batch_size=1 and
    measure the per-image VRAM cost so subsequent rounds (and subsequent
    requests) can scale up safely. Never exceeds free VRAM minus reserve.
    """
    estimate = get_vram_estimate(workflow_name, width, height)
    free_before = await comfy_free_vram_bytes(client)
    warnings: list[str] = []
    response_headers: dict[str, str] = {}
    models_freed = False

    images_collected: list[bytes] = []
    images_remaining = n_requested
    rounds_run = 0

    # Soft cap on rounds — each round produces at least 1 image, so worst case
    # we run n_requested rounds. Add a small extra buffer for retry-on-OOM.
    max_rounds = max(1, n_requested + 2)

    while images_remaining > 0 and rounds_run < max_rounds:
        rounds_run += 1
        free_now = await comfy_free_vram_bytes(client)

        # Sizing model:
        #   - Probe round (rounds_run==1, no estimate): batch_size=1 so we can
        #     measure incremental VRAM cost without risking OOM.
        #   - Subsequent rounds (or any round when we have an estimate):
        #     compute cap from free_now / estimate. If we have no estimate but
        #     are past round 1, assume the cost is small (model already
        #     resident) and trust IMAGE_MAX_BATCH_SIZE as the ceiling.
        if rounds_run == 1 and estimate is None:
            batch_target = 1
        elif estimate is not None:
            cap = compute_max_batch(free_now, estimate)
            if cap == 0 and IMAGE_FREE_VRAM_ON_EXHAUSTION and not models_freed:
                models_freed = await _free_comfy_models_if_idle(client)
                if models_freed:
                    free_now = await comfy_free_vram_bytes(client)
                    cap = compute_max_batch(free_now, estimate)
            # The estimate sizes batches > 1 only. It is measured as the
            # marginal ComfyUI VRAM of a probe run (cold model loads
            # included), so it over-states what one more image needs and
            # ComfyUI offloads within --reserve-vram anyway. A single image is
            # therefore never refused on the estimate: after the idle-model
            # free above, submit batch=1 and let a real execution OOM (one
            # unload + retry below) be the only failure.
            batch_target = min(max(cap, 1), images_remaining)
        else:
            # No estimate, but we already proved on round 1 that the model fits
            # and can produce images. Trust the configured ceiling — any
            # OOM here is data we'll capture on the next request via the
            # measurement code below.
            batch_target = min(IMAGE_MAX_BATCH_SIZE, images_remaining)

        # Build a per-round workflow copy. Re-seed each round so multiple rounds
        # produce different images instead of the same image repeated.
        round_workflow = copy.deepcopy(base_workflow)
        if seed_node and seed_node in round_workflow:
            round_seed = (
                (fixed_seed + len(images_collected))
                if fixed_seed is not None
                else random.randint(0, 2**32 - 1)
            )
            inputs = round_workflow[seed_node].get("inputs", {})
            inputs[seed_field] = round_seed

        applied = apply_batch_size(round_workflow, meta, batch_target)
        if not applied and batch_target > 1:
            # Workflow lacks a batch_size_node — can't scale up. Loop instead,
            # but warn the client so this isn't a silent slow path.
            warnings.append(
                f"workflow '{workflow_name}' has no batch_size_node; "
                f"falling back to {images_remaining} sequential rounds"
            )
            batch_target = 1

        # Only run the probe on rounds where we don't yet have a trusted
        # estimate (rounds_run == 1 is the typical case). Subsequent rounds
        # skip the probe overhead.
        probe: Optional[_VramProbe] = None
        if estimate is None:
            probe = _VramProbe(client)

        err, round_images = await _comfy_run_round(
            client,
            round_workflow,
            headers,
            label=f"image round {rounds_run}/{max_rounds} (target={batch_target})",
            vram_probe=probe,
            request=request,
        )
        if err is not None and not models_freed and IMAGE_FREE_VRAM_ON_EXHAUSTION:
            try:
                body = json.loads(err.body.decode("utf-8")) if getattr(err, "body", None) else {}
                error_text = str(((body.get("error") or {}).get("message") or "")).lower()
            except Exception:
                error_text = ""
            if any(marker in error_text for marker in ("cuda out of memory", "cuda oom", "out of memory", "oom")):
                models_freed = await _free_comfy_models_if_idle(client)
                if models_freed:
                    round_workflow = copy.deepcopy(base_workflow)
                    if seed_node and seed_node in round_workflow:
                        inputs = round_workflow[seed_node].get("inputs", {})
                        inputs[seed_field] = round_seed
                    apply_batch_size(round_workflow, meta, 1)
                    err, round_images = await _comfy_run_round(
                        client, round_workflow, headers,
                        label=f"image round {rounds_run}/{max_rounds} after model unload",
                        request=request,
                    )
        if models_freed:
            response_headers["X-ComfyUI-Models-Freed"] = "true"
        if err is None:
            _delivery = media_delivery.current()
            if _delivery is not None:
                _round_seed = (
                    round_workflow.get(seed_node, {}).get("inputs", {}).get(seed_field)
                    if seed_node
                    else None
                )
                _delivery.seeds.extend(
                    [_round_seed if isinstance(_round_seed, int) else None] * len(round_images)
                )
        if err is not None:
            if (
                background_removal_decision is not None
                and background_removal_decision.remove_background
                and fallback_workflow is not None
            ):
                try:
                    body = json.loads(err.body.decode("utf-8")) if getattr(err, "body", None) else {}
                    msg = ((body.get("error") or {}).get("message") or "") if isinstance(body, dict) else ""
                except Exception:
                    msg = ""
                msg = msg[:200] or f"HTTP {getattr(err, 'status_code', 'unknown')}"
                print(f"[proxy] background removal failed; retrying without RMBG: {msg}", flush=True)
                firehose_metrics.record_event(
                    "image_background_removal_fallback",
                    "RMBG failed; retried without background removal",
                    workflow=workflow_name,
                    reason=msg,
                )
                bypass_decision = ImageBackgroundRemovalDecision(
                    remove_background=False,
                    confidence=0.0,
                    reason="RMBG failed; retried without background removal",
                    source="rmbg_fallback",
                    error=msg,
                )
                return await _generate_images_with_adaptive_batching(
                    request=request,
                    client=client,
                    base_workflow=copy.deepcopy(fallback_workflow),
                    meta=meta,
                    seed_node=seed_node,
                    seed_field=seed_field,
                    workflow_name=fallback_workflow_name or workflow_name,
                    width=width,
                    height=height,
                    n_requested=n_requested,
                    response_format=response_format,
                    headers=headers,
                    background_removal_decision=bypass_decision,
                    image_transform=image_transform,
                    image_response_headers=image_response_headers,
                    fixed_seed=fixed_seed,
                    auth_context=auth_context,
                    output_format=output_format,
                    output_compression=output_compression,
                    # RMBG failed and we're retrying without it (bypass_decision
                    # above): the rendered image will be opaque, not
                    # transparent. Echoing the original (still "transparent")
                    # output_background here would claim a transparency the
                    # fallback render never produces.
                    output_background="opaque",
                    output_quality=output_quality,
                    output_size=output_size,
                )
            return err

        if not round_images:
            warnings.append(f"round {rounds_run} produced 0 images")
            # Avoid infinite loops if the backend silently returns nothing.
            if rounds_run >= 2 and not images_collected:
                return Response(
                    content=json.dumps({"error": {"message": "ComfyUI returned no images", "type": "api_error"}}),
                    status_code=502,
                    media_type="application/json",
                )
            continue

        images_collected.extend(round_images)
        images_remaining -= len(round_images)

        # VRAM measurement after the first successful round.
        # Preferred: in-run per-process probe measures flux's MARGINAL
        # contribution to ComfyUI's GPU0 allocation (peak_comfy_used -
        # before_comfy_used). Insensitive to concurrent voxtral / desktop /
        # TTS activity, unlike the old `total - min_free` approach which
        # captured whole-GPU pressure at peak.
        # Fallback: endpoint diff `free_before - free_after`, tagged as
        # untrusted so the batcher doesn't plan against it.
        if estimate is None and rounds_run == 1:
            per_image_cost = 0
            measurement_trusted = False
            source = "probe"
            model_state = "unknown"
            comfy_baseline = 0
            samples_count = probe.samples if probe is not None else 0
            free_after, _ = await comfy_vram_snapshot(client)

            if probe is not None and probe.trustworthy():
                marginal, model_state = probe.marginal_and_state()
                if isinstance(marginal, int) and marginal > 0:
                    # marginal is the per-batch-round delta; divide by
                    # batch_target to get per-image cost (cache key is
                    # per-image).
                    divisor = max(1, batch_target)
                    per_image_cost = marginal // divisor
                    measurement_trusted = True
                    source = "probe"
                comfy_baseline = (
                    probe.comfy_baseline_min
                    if isinstance(probe.comfy_baseline_min, int)
                    else 0
                )
            elif probe is not None and probe.error:
                print(
                    f"[proxy] VRAM probe error for {workflow_name} "
                    f"{width}x{height}: {probe.error}",
                    flush=True,
                )

            if per_image_cost <= 0:
                # Probe failed or returned nothing useful. Fall back to the
                # legacy endpoint diff so we at least persist *something*,
                # but mark it untrusted.
                if isinstance(free_after, int) and isinstance(free_before, int) and free_after < free_before:
                    per_image_cost = (free_before - free_after) // max(1, batch_target)
                if per_image_cost <= 0:
                    per_image_cost = 4 * 1024 * 1024  # synthetic floor: 4 MiB
                measurement_trusted = False
                source = "endpoint_diff"
                if model_state == "unknown":
                    model_state = "unknown"

            record_vram_estimate(
                workflow_name,
                width,
                height,
                per_image_cost,
                trusted=measurement_trusted,
                source=source,
                model_state=model_state,
                comfy_baseline_bytes=comfy_baseline,
                samples_count=samples_count,
            )
            # Re-read; will be None if measurement was untrusted (so we
            # don't make scheduling decisions off it).
            estimate = get_vram_estimate(workflow_name, width, height)
            sys_peak = probe.system_peak_used_bytes() if probe is not None else None
            sys_peak_str = (
                f"{sys_peak / (1024**3):.2f} GiB" if isinstance(sys_peak, int) else "n/a"
            )
            before_str = (
                f"{probe.comfy_before / (1024**3):.2f} GiB"
                if probe is not None and isinstance(probe.comfy_before, int)
                else "n/a"
            )
            peak_str = (
                f"{probe.comfy_peak / (1024**3):.2f} GiB"
                if probe is not None and isinstance(probe.comfy_peak, int)
                else "n/a"
            )
            print(
                f"[proxy] VRAM estimate for {workflow_name} {width}x{height}: "
                f"{per_image_cost / (1024**2):.1f} MiB/image marginal "
                f"(trusted={measurement_trusted}, source={source}, "
                f"model_state={model_state}, probe_samples={samples_count}, "
                f"comfy_before={before_str}, comfy_peak={peak_str}, "
                f"system_peak={sys_peak_str})",
                flush=True,
            )

    images_collected = images_collected[:n_requested]
    if not images_collected:
        return Response(
            content=json.dumps({"error": {"message": "No images generated", "type": "api_error"}}),
            status_code=500,
            media_type="application/json",
        )

    if len(images_collected) < n_requested:
        warnings.append(
            f"requested n={n_requested} but produced {len(images_collected)} after {rounds_run} round(s)"
        )

    if image_transform is not None:
        try:
            images_collected = [image_transform(raw) for raw in images_collected]
        except Exception as e:
            return Response(
                content=json.dumps({
                    "error": {
                        "message": f"Image post-processing failed: {e}",
                        "type": "api_error",
                    }
                }),
                status_code=502,
                media_type="application/json",
            )

    if warnings:
        # Single header, comma-joined per RFC 7234. Visible to the client.
        response_headers["X-Proxy-Warning"] = "; ".join(warnings)
    if image_response_headers:
        response_headers.update(image_response_headers)
    response_headers["X-Image-Rounds"] = str(rounds_run)
    response_headers["X-Image-Returned"] = str(len(images_collected))
    if background_removal_decision is not None:
        response_headers["X-Image-Background-Removal"] = (
            "true" if background_removal_decision.remove_background else "false"
        )
        if background_removal_decision.source:
            response_headers["X-Image-Background-Removal-Source"] = background_removal_decision.source

    print(
        f"[proxy] ComfyUI generated {len(images_collected)}/{n_requested} image(s) "
        f"across {rounds_run} round(s)",
        flush=True,
    )

    return await asyncio.to_thread(_build_image_response_payload,
        request,
        images_collected,
        response_format,
        response_headers,
        auth_context=auth_context,
        output_format=output_format,
        output_compression=output_compression,
        background=output_background,
        quality=output_quality,
        size=output_size,
    )


async def proxy_image_request(request, auth_context, receipt=None):
    """Dispatch image requests through their declared engine protocol."""
    response = await _try_protocol_request(request, auth_context, "images", receipt=receipt)
    if response is not None:
        return response
    return await proxy_comfy_request(request, auth_context, receipt=receipt)


async def proxy_comfy_request(
    request: Request,
    auth_context: AuthContext,
    receipt: RouteReceipt | None = None,
) -> Response:
    """Handle OpenAI-compatible image generation request via ComfyUI."""
    admission = _dispatch_admission_response(
        'image.generate', auth_context=auth_context, service_id="comfyui",
        service_available=COMFY_ENABLED, resource_class='image', queue_key=_MEDIA_JOB_QUEUE_KEY,
    )
    if admission is not None:
        return admission

    if not COMFY_ENABLED:
        if receipt is not None:
            receipt.add_fallback_reason("comfy_disabled")
        return Response(
            content=json.dumps({"error": {"message": "Image generation not enabled", "type": "service_unavailable"}}),
            status_code=503,
            media_type="application/json"
        )
    service_response = (await asyncio.to_thread(_service_availability_response, "comfyui",
        service_label="ComfyUI",))
    if service_response is not None:
        if receipt is not None:
            receipt.add_fallback_reason("comfy_operator_mode")
        return service_response

    try:
        body = await request.json()
    except:
        _record_image_input(receipt, "body", rejected_reason="invalid_json")
        return Response(
            content=json.dumps({"error": {"message": "Invalid JSON body", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    if not isinstance(body, dict):
        _record_image_input(receipt, "body", rejected_reason="invalid_json")
        return Response(
            content=json.dumps({"error": {"message": "Request body must be a JSON object", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    unknown_response = _record_unknown_image_fields(
        receipt,
        body,
        STANDARD_IMAGE_GENERATE_FIELDS,
    )
    if unknown_response is not None:
        return unknown_response
    metadata_error = _note_media_metadata_body(body)
    if metadata_error is not None:
        return metadata_error

    prompt = body.get("prompt", "")
    requested_model = body.get("model", COMFY_DEFAULT_MODEL)
    model = requested_model
    requested_size = body.get("size")
    size = requested_size or "1024x1024"
    if str(model).startswith("ideogram4") and prompt:
        # Only skip conversion when the prompt is ALREADY a grounded Ideogram-4
        # caption (has real obj/text elements). JSON that merely wraps a prose
        # description with no elements (a common agent mistake) must still be
        # structurized — otherwise Ideogram gets an ungrounded caption and the
        # text/layout quality collapses. See _ideogram4_is_grounded_json.
        if not _ideogram4_is_grounded_json(prompt):
            prompt = await _ideogram4_structurize_prompt(
                _ideogram4_brief_from_prompt(prompt)
            )
    if receipt is not None:
        receipt.requested_model = str(requested_model) if requested_model is not None else None
    _record_image_input(receipt, "model")
    _record_image_input(receipt, "size")
    background, background_err = parse_image_background(body.get("background"))
    if background_err:
        _record_image_input(receipt, "background", rejected_reason=background_err)
        return Response(
            content=json.dumps({"error": {
                "message": background_err,
                "type": "invalid_request_error",
                "param": "background",
                "code": "invalid_value",
            }}),
            status_code=400,
            media_type="application/json",
        )
    if "background" in body:
        _record_image_input(receipt, "background")
    output_format, output_compression, quality, output_shape_error = _parse_image_output_shape(
        receipt,
        output_format_raw=body.get("output_format"),
        output_compression_raw=body.get("output_compression"),
        quality_raw=body.get("quality"),
        background=background or "auto",
    )
    if output_shape_error is not None:
        return output_shape_error
    n = body.get("n", 1)
    if isinstance(n, bool) or not isinstance(n, int):
        _record_image_input(receipt, "n", rejected_reason="not_integer")
        return openai_error_response("n must be an integer", param="n")
    if n < 1 or n > 10:
        _record_image_input(receipt, "n", rejected_reason="out_of_range")
        return openai_error_response("n must be between 1 and 10", param="n")
    _record_image_input(receipt, "n")
    response_format = body.get(
        "response_format",
        _default_image_response_format(requested_model),
    )
    if response_format not in ("b64_json", "url"):
        _record_image_input(receipt, "response_format", rejected_reason="unsupported_value")
        return Response(
            content=json.dumps({"error": {"message": "response_format must be 'b64_json' or 'url'", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )
    _record_image_input(receipt, "response_format")
    headers = configured_downstream_headers(auth_context, "comfyui")
    try:
        model_resolution = resolve_model_for_operation("images", model)
    except ModelCompatibilityError as e:
        _record_image_input(receipt, "model", rejected_reason="model_incompatible")
        return model_compatibility_error(e)
    if model_resolution.is_openai_alias:
        print(f"[proxy] Model alias {model} -> {model_resolution.effective_model} for image generation", flush=True)
        model = model_resolution.effective_model

    if receipt is not None:
        receipt.resolved_model = str(model) if model is not None else None

    if not prompt:
        _record_image_input(receipt, "prompt", rejected_reason="missing")
        return Response(
            content=json.dumps({"error": {"message": "prompt is required", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    _record_image_input(receipt, "prompt")

    manifest = _find_image_manifest("image.generate", str(model))
    gateway_compose = _gateway_image_generate_compose(manifest)
    if gateway_compose == "offset_inpaint_tile":
        if background == "transparent":
            _record_image_input(
                receipt,
                "background",
                rejected_reason="unsupported_for_gateway_composition",
            )
            return Response(
                content=json.dumps({
                    "error": {
                        "message": "background=transparent is not supported for offset-inpaint tile generation",
                        "type": "invalid_request_error",
                        "param": "background",
                        "code": "unsupported_value",
                    }
                }),
                status_code=400,
                media_type="application/json",
            )
        return await _proxy_offset_inpaint_tile_request(
            request=request,
            body=body,
            auth_context=auth_context,
            receipt=receipt,
            manifest=manifest,
            prompt=prompt,
            model=str(model),
            size=str(size),
            n=n,
            response_format=response_format,
            headers=headers,
            output_format=output_format,
            output_compression=output_compression,
            quality=quality,
        )

    workflow = load_comfy_workflow(model)
    if not workflow:
        return model_compatibility_error(
            ModelCompatibilityError(
                f"Model '{model}' is not available for image generation.",
                code="model_not_found",
            )
        )

    workflow = copy.deepcopy(workflow)
    meta = workflow.pop("_meta", {})
    workflow_name = str(meta.get("name") or model)
    if receipt is not None:
        receipt.requested_workflow = str(model) if model is not None else None
        receipt.resolved_workflow = workflow_name
    if manifest is not None:
        identity = manifest_identity(manifest)
        if receipt is not None:
            receipt.attach_manifest(
                manifest_id=identity.id,
                manifest_version=identity.version,
                manifest_hash=identity.manifest_hash,
            )
    else:
        _attach_image_manifest_if_available(receipt, "image.generate", str(model))
    if receipt is not None:
        decision = _apply_image_route_policy(
            receipt,
            auth_context,
            model=str(model) if model is not None else None,
            workflow=_policy_workflow_for_receipt(receipt),
            manifest=manifest,
        )
        if decision.denied:
            return _policy_denied_response(decision)
    target_decision = _workflow_target_policy_decision(
        auth_context,
        requested=str(model) if model is not None else None,
        resolved=workflow_name,
        manifest=manifest,
        extra_ids=(
            [_policy_workflow_for_receipt(receipt)]
            if _policy_workflow_for_receipt(receipt)
            else ()
        ),
    )
    if target_decision is not None and target_decision.denied:
        return _policy_denied_response(target_decision)
    background_decision = await resolve_image_background_decision(
        background or "auto",
        prompt,
        auth_context=auth_context,
        # jpeg has no alpha channel: "auto" background must never select
        # removal for a jpeg request, or the response would advertise a
        # transparency the encoded bytes can't actually carry.
        force_bypass=(output_format == "jpeg"),
        force_bypass_reason="output_format=jpeg has no alpha channel",
    )

    prompt_node = meta.get("prompt_node")
    size_node = meta.get("size_node")
    seed_node = meta.get("seed_node")

    if prompt_node and prompt_node in workflow:
        workflow[prompt_node]["inputs"]["text"] = prompt

    width, height = parse_size(size)
    effective_size = f"{width}x{height}"
    for _sn in ([size_node] if isinstance(size_node, str) else (size_node or [])):
        if _sn and _sn in workflow:
            workflow[_sn]["inputs"]["width"] = width
            workflow[_sn]["inputs"]["height"] = height
    workflow = _apply_manifest_route_inputs(
        manifest,
        workflow,
        {"prompt": prompt, "width": width, "height": height},
    )
    workflow = _apply_quality_steps(manifest, workflow, quality, receipt)

    workflow, extension_response = await _apply_workflow_extensions_to_image_request(
        request_body=body,
        manifest=manifest,
        backend_request=workflow,
        standard_fields=STANDARD_IMAGE_GENERATE_FIELDS,
        receipt=receipt,
        auth_context=auth_context,
    )
    if extension_response is not None:
        return extension_response
    fixed_seed = _workflow_extension_integer(body, "seed")

    fallback_workflow = copy.deepcopy(workflow)
    set_workflow_background_removal(fallback_workflow, meta, False)

    if background_decision.remove_background:
        if set_workflow_background_removal(workflow, meta, True):
            print(
                f"[proxy] Image background removal enabled for {workflow_name} "
                f"(confidence={background_decision.confidence})",
                flush=True,
            )
            firehose_metrics.record_event(
                "image_background_removal",
                "background removal enabled",
                workflow=workflow_name,
                confidence=background_decision.confidence,
                source=background_decision.source,
            )
            workflow_name_for_batching = f"{workflow_name}+rmbg"
        else:
            print(f"[proxy] background removal requested but workflow {workflow_name} has no background_removal wiring", flush=True)
            firehose_metrics.record_event(
                "image_background_removal_fallback",
                "workflow has no RMBG wiring",
                workflow=workflow_name,
            )
            background_decision = ImageBackgroundRemovalDecision(
                remove_background=False,
                confidence=0.0,
                reason="workflow has no RMBG wiring",
                source="workflow_unsupported",
            )
            workflow_name_for_batching = workflow_name
    else:
        set_workflow_background_removal(workflow, meta, False)
        workflow_name_for_batching = workflow_name

    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(COMFY_TIMEOUT, connect=10)) as client:
            admission = _dispatch_admission_response(
                "image.generate", auth_context=auth_context, service_id="comfyui",
                service_available=COMFY_ENABLED, resource_class="image", queue_key=_MEDIA_JOB_QUEUE_KEY,
            )
            if admission is not None:
                return admission
            return await _generate_images_with_adaptive_batching(
                request=request,
                client=client,
                base_workflow=workflow,
                meta=meta,
                seed_node=seed_node,
                seed_field="seed",
                workflow_name=workflow_name_for_batching,
                width=width,
                height=height,
                n_requested=n,
                response_format=response_format,
                headers=headers,
                image_response_headers=_record_image_size_adjustment(
                    receipt,
                    requested=requested_size,
                    effective=effective_size,
                ),
                background_removal_decision=background_decision,
                fallback_workflow=fallback_workflow,
                fallback_workflow_name=workflow_name,
                fixed_seed=fixed_seed,
                auth_context=auth_context,
                output_format=output_format,
                output_compression=output_compression,
                output_background="transparent" if background_decision.remove_background else "opaque",
                output_quality=quality,
                output_size=effective_size,
            )
    except httpx.TimeoutException:
        return Response(
            content=json.dumps({"error": {"message": "ComfyUI request timeout", "type": "api_error"}}),
            status_code=504,
            media_type="application/json"
        )
    except httpx.ConnectError:
        return Response(
            content=json.dumps({"error": {"message": f"ComfyUI unavailable at {COMFY_HOST}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )
    except Exception as e:
        return Response(
            content=json.dumps({"error": {"message": f"ComfyUI proxy error: {str(e)}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )


# Multipart field names OpenAI clients use for edit reference image(s). The
# gpt-image-1 multi-image edit shape repeats "image[]" once per file (up to
# 16); legacy dall-e-2 edits send a single "image" part. "images" is kept as
# a defensive allow-listed alias (not an OpenAI SDK field) so a non-SDK
# client using the plural, unbracketed name still works instead of being
# silently ignored.
_EDIT_IMAGE_FIELD_NAMES = ("image[]", "image", "images")


def _collect_edit_image_uploads(form: Any) -> list[Any]:
    """Return every uploaded file across the edit image field names, in order.

    Starlette's ``FormData`` (and the test stubs mirroring it) expose
    ``multi_items()`` with every repeated key preserved; ``form.get()`` only
    ever returns the first. Using ``multi_items()`` here is what actually
    fixes the multi-reference-image drop bug: every ``image[]`` part a
    client uploads is now read, not just the first.
    """
    uploads: list[Any] = []
    for key, value in form.multi_items():
        if key in _EDIT_IMAGE_FIELD_NAMES and hasattr(value, "read"):
            uploads.append(value)
    return uploads


def _image_edit_node_slots(meta: Mapping[str, Any]) -> list[str]:
    """Return the ordered ComfyUI node ids that accept an uploaded edit image.

    Workflows declare image capacity via ``_meta.image_nodes`` (a list, for
    workflows built to accept multiple reference images) or the legacy
    singular ``_meta.image_node`` (capacity 1 — true of every shipped
    workflow today). Order determines which uploaded file, in submission
    order, binds to which node.
    """
    nodes = meta.get("image_nodes")
    if isinstance(nodes, list) and nodes:
        return [str(n) for n in nodes if n]
    single = meta.get("image_node")
    return [str(single)] if single else []



async def _identity_edit_alias(
    request: Request,
    auth_context: AuthContext,
    form: Any,
    form_dict: Mapping[str, Any],
    image_files: list[Any],
    prompt: str,
    response_format: str,
) -> Response:
    """``POST /v1/images/edits`` with ``model=image-identity``.

    The reference photos are the ``image[]`` parts. Options (people, attempts,
    seed, ...) travel in ``extensions["com.azizam.workflow"]``. The response is
    the usual image payload plus ``likeness``, ``attempts`` and ``people``.
    """
    options = ((form_dict.get("extensions") or {}).get(WORKFLOW_EXTENSION_NAMESPACE) or {})
    if not isinstance(options, Mapping):
        return identity_api.error(400, "invalid_extensions", "the workflow extension must be an object", param="extensions")
    try:
        photos = [await item.read() for item in image_files]
        if not photos or len(photos) > identity_api.MAX_PHOTOS or not all(photos):
            raise identity_scene.IdentityError(f"send 1 to {identity_api.MAX_PHOTOS} reference photos", param="image")
        unknown = set(options) - identity_api.SCENE_OPTION_NAMES
        if unknown:
            raise identity_scene.IdentityError(f"unknown identity option: {sorted(unknown)[0]}", param="extensions")
        req = identity_api.build_scene_request(options, photos, prompt)
        # The OpenAI-shaped edit route stays synchronous unless the client asks for a job.
        if identity_api.wants_async(options, req, default="sync"):
            return await app.state.identity_submit(request, auth_context, req, response_format)
        return await app.state.identity_run_scene(request, auth_context, req, response_format)
    except (identity_scene.IdentityError, likeness_module.LikenessError) as exc:
        return identity_api.error(400, getattr(exc, "code", "invalid_request"), str(exc), param=getattr(exc, "param", None), faces=getattr(exc, "faces", None))
    except (TypeError, ValueError) as exc:
        return identity_api.error(400, "invalid_option", f"invalid identity option: {exc}", param="extensions")
    except (httpx.HTTPError, RuntimeError) as exc:
        return identity_api.error(502, "identity_backend_error", f"identity workflow failed: {str(exc) or type(exc).__name__}")


async def proxy_comfy_edit_request(
    request: Request,
    auth_context: AuthContext,
    receipt: RouteReceipt | None = None,
) -> Response:
    """Handle OpenAI-compatible image edit request via ComfyUI."""
    admission = _dispatch_admission_response(
        'image.edit', auth_context=auth_context, service_id="comfyui",
        service_available=COMFY_ENABLED, resource_class='image', queue_key=_MEDIA_JOB_QUEUE_KEY,
    )
    if admission is not None:
        return admission

    if not COMFY_ENABLED:
        if receipt is not None:
            receipt.add_fallback_reason("comfy_disabled")
        return Response(
            content=json.dumps({"error": {"message": "Image generation not enabled", "type": "service_unavailable"}}),
            status_code=503,
            media_type="application/json"
        )
    service_response = (await asyncio.to_thread(_service_availability_response, "comfyui",
        service_label="ComfyUI",))
    if service_response is not None:
        if receipt is not None:
            receipt.add_fallback_reason("comfy_operator_mode")
        return service_response

    form_dict: dict[str, Any] = {}
    try:
        form = await request.form()
    except Exception as e:
        _record_image_input(receipt, "body", rejected_reason="invalid_form")
        return Response(
            content=json.dumps({"error": {"message": f"Invalid form data: {e}", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    for key, value in form.multi_items():
        if key in form_dict:
            continue
        if _merge_multipart_extension_bracket_field(form_dict, str(key), value):
            continue
        form_dict[str(key)] = value
    extensions_raw = form.get("extensions")
    if isinstance(extensions_raw, str):
        try:
            parsed_extensions = json.loads(extensions_raw)
            if "extensions" in form_dict and isinstance(form_dict["extensions"], dict) and isinstance(parsed_extensions, dict):
                form_dict["extensions"] = {
                    **parsed_extensions,
                    **form_dict["extensions"],
                }
            else:
                form_dict["extensions"] = parsed_extensions
        except json.JSONDecodeError:
            _record_image_input(receipt, "extensions", rejected_reason="invalid_json")
            return Response(
                content=json.dumps({"error": {
                    "message": "extensions must be a JSON object string",
                    "type": "invalid_request_error",
                    "param": "extensions",
                    "code": "invalid_json",
                }}),
                status_code=400,
                media_type="application/json",
            )
    unknown_response = _record_unknown_image_fields(
        receipt,
        form_dict,
        STANDARD_IMAGE_EDIT_FIELDS,
        extra_allowed_fields=set(_extension_asset_field_references(form_dict).values()),
    )
    if unknown_response is not None:
        return unknown_response
    metadata_error = _note_media_metadata_body(form_dict)
    if metadata_error is not None:
        return metadata_error

    image_files = _collect_edit_image_uploads(form)
    image_file = image_files[0] if image_files else None
    mask_file = form.get("mask")
    prompt = form.get("prompt", "")
    requested_model = form.get("model", IMAGE_EDIT_DEFAULT_MODEL)
    model = requested_model
    requested_size = form.get("size")
    size = requested_size
    requested_dimensions: tuple[int, int] | None = None
    if size is not None and size != "auto":
        try:
            # Accept the spellings that worked before strict validation: "512X768", "512 x 768".
            normalized = re.sub(r"\s*[xX]\s*", "x", size.strip()) if isinstance(size, str) else None
            if normalized is None or not re.fullmatch(r"[0-9]+x[0-9]+", normalized):
                raise ValueError
            width, height = (int(part) for part in normalized.split("x"))
            if width <= 0 or height <= 0:
                raise ValueError
            requested_dimensions = (width, height)
        except (TypeError, ValueError, OverflowError):
            _record_image_input(receipt, "size", rejected_reason="invalid_dimensions")
            return openai_error_response(
                "size must be 'auto' or WIDTHxHEIGHT with positive integers", param="size",
            )
    if receipt is not None:
        receipt.requested_model = str(requested_model) if requested_model is not None else None
    _record_image_input(receipt, "model")
    if size:
        _record_image_input(receipt, "size")
    background, background_err = parse_image_background(form.get("background"))
    if background_err:
        _record_image_input(receipt, "background", rejected_reason=background_err)
        return Response(
            content=json.dumps({
                "error": {
                    "message": background_err,
                    "type": "invalid_request_error",
                    "param": "background",
                    "code": "invalid_value",
                }
            }),
            status_code=400,
            media_type="application/json",
        )
    if form.get("background") is not None:
        _record_image_input(receipt, "background")
    output_format, output_compression, quality, output_shape_error = _parse_image_output_shape(
        receipt,
        output_format_raw=form.get("output_format"),
        output_compression_raw=form.get("output_compression"),
        quality_raw=form.get("quality"),
        background=background or "auto",
    )
    if output_shape_error is not None:
        return output_shape_error
    try:
        n = int(form.get("n", 1))
    except (TypeError, ValueError):
        _record_image_input(receipt, "n", rejected_reason="not_integer")
        return Response(
            content=json.dumps({"error": {"message": "n must be an integer", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )
    if n < 1 or n > 10:
        _record_image_input(receipt, "n", rejected_reason="out_of_range")
        return Response(
            content=json.dumps({"error": {"message": "n must be between 1 and 10", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )
    _record_image_input(receipt, "n")
    response_format = str(form.get("response_format", "b64_json"))
    if response_format not in ("b64_json", "url"):
        _record_image_input(receipt, "response_format", rejected_reason="unsupported_value")
        return Response(
            content=json.dumps({"error": {"message": "response_format must be 'b64_json' or 'url'", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )
    _record_image_input(receipt, "response_format")
    headers = configured_downstream_headers(auth_context, "comfyui")
    try:
        model_resolution = resolve_model_for_operation("image_edits", model)
    except ModelCompatibilityError as e:
        _record_image_input(receipt, "model", rejected_reason="model_incompatible")
        return model_compatibility_error(e)
    if model_resolution.is_openai_alias:
        print(f"[proxy] Model alias {model} -> {model_resolution.effective_model} for image edit", flush=True)
        model = model_resolution.effective_model

    if not image_file:
        _record_image_input(receipt, "image", rejected_reason="missing")
        return Response(
            content=json.dumps({"error": {"message": "image is required", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    _record_image_input(receipt, "image[]" if form.get("image[]") else "image")

    model = _select_edit_workflow(
        str(model),
        image_count=len(image_files),
        has_mask=bool(mask_file),
    )

    if receipt is not None:
        receipt.resolved_model = str(model) if model is not None else None

    if str(model) == IDENTITY_MODEL_ID:
        return await _identity_edit_alias(
            request, auth_context, form, form_dict, image_files, str(prompt or ""), response_format,
        )

    workflow = load_comfy_workflow(model)
    if not workflow:
        return model_compatibility_error(
            ModelCompatibilityError(
                f"Model '{model}' is not available for image editing.",
                code="model_not_found",
            )
        )
    manifest = _find_image_manifest("image.edit", str(model))
    if requested_dimensions is not None and manifest is not None:
        for field, value in zip(("width", "height"), requested_dimensions):
            spec = (manifest.get("inputs") or {}).get(field) or {}
            if (("minimum" in spec and value < spec["minimum"])
                    or ("maximum" in spec and value > spec["maximum"])):
                _record_image_input(receipt, "size", rejected_reason="out_of_range")
                return openai_error_response(
                    f"size {field} is outside the workflow dimension limits", param="size",
                )

    prompt_ignored_by_workflow = _manifest_ignores_prompt(manifest)
    if not prompt and not prompt_ignored_by_workflow:
        _record_image_input(receipt, "prompt", rejected_reason="missing")
        return Response(
            content=json.dumps({"error": {"message": "prompt is required", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    if prompt:
        _record_image_input(receipt, "prompt")
    elif prompt_ignored_by_workflow:
        _record_image_input(
            receipt,
            "prompt",
            ignored_reason="workflow does not use prompt",
        )
    required_route_bound_inputs = _manifest_required_route_bound_inputs(manifest, "comfyui")
    minimum_image_count = 1 + len(required_route_bound_inputs)
    if len(image_files) < minimum_image_count:
        _record_image_input(receipt, "image[]", rejected_reason="missing_required_image")
        return Response(
            content=json.dumps({
                "error": {
                    "message": (
                        f"workflow {model} requires at least {minimum_image_count} "
                        f"input image(s); {len(image_files)} were provided"
                    ),
                    "type": "invalid_request_error",
                    "param": "image[]",
                    "code": "missing_required_image",
                }
            }),
            status_code=400,
            media_type="application/json",
        )

    workflow = copy.deepcopy(workflow)
    meta = workflow.pop("_meta", {})
    workflow_name = str(meta.get("name") or model)
    if receipt is not None:
        receipt.requested_workflow = str(model) if model is not None else None
        receipt.resolved_workflow = workflow_name
    image_slots = _image_edit_node_slots(meta)
    if len(image_files) > len(image_slots):
        _record_image_input(receipt, "image[]", rejected_reason="too_many_images")
        return openai_error_response(
            f"workflow {workflow_name} accepts at most {len(image_slots)} "
            f"input image(s); {len(image_files)} were provided",
            param="image[]", code="too_many_images",
        )
    if manifest is not None:
        identity = manifest_identity(manifest)
        if receipt is not None:
            receipt.attach_manifest(
                manifest_id=identity.id,
                manifest_version=identity.version,
                manifest_hash=identity.manifest_hash,
            )
    else:
        _attach_image_manifest_if_available(receipt, "image.edit", str(model))
    required_mask_input = _manifest_required_route_mask_input(manifest)
    if not mask_file and required_mask_input:
        _record_image_input(receipt, "mask", rejected_reason="missing")
        return openai_error_response(
            f"mask is required for workflow input {required_mask_input}",
            param="mask", code="missing_required_parameter",
        )

    # Authorize the resolved workflow before anything is sent to the backend.
    if receipt is not None:
        decision = _apply_image_route_policy(
            receipt,
            auth_context,
            model=str(model) if model is not None else None,
            workflow=_policy_workflow_for_receipt(receipt),
            manifest=manifest,
        )
        if decision.denied:
            return _policy_denied_response(decision)
    target_decision = _workflow_target_policy_decision(
        auth_context,
        requested=str(model) if model is not None else None,
        resolved=workflow_name,
        manifest=manifest,
        extra_ids=(
            [_policy_workflow_for_receipt(receipt)]
            if _policy_workflow_for_receipt(receipt)
            else ()
        ),
    )
    if target_decision is not None and target_decision.denied:
        return _policy_denied_response(target_decision)
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(COMFY_TIMEOUT, connect=10)) as client:
            image_content = await image_file.read()
            mask_content = await mask_file.read() if mask_file else None
            mask_context: ImageEditMaskContext | None = None
            if mask_content is not None:
                mask_context, mask_error = _prepare_image_edit_mask_context(
                    source_image_content=image_content,
                    mask_content=mask_content,
                )
                if mask_error is not None:
                    _record_image_input(receipt, "mask", rejected_reason="invalid_mask")
                    return mask_error
                _record_image_input(receipt, "mask")

            if mask_context is not None and _manifest_uses_source_alpha_mask(manifest):
                image_content = _apply_edit_mask_as_source_alpha(mask_context)

            files = {"image": (image_file.filename or "input.png", image_content, "image/png")}
            upload_resp = await client.post(f"{COMFY_HOST}/upload/image", headers=headers, files=files)

            if upload_resp.status_code != 200:
                return Response(
                    content=json.dumps({"error": {"message": f"Image upload failed: {upload_resp.text}", "type": "api_error"}}),
                    status_code=502,
                    media_type="application/json"
                )

            upload_result = upload_resp.json()
            uploaded_filename = upload_result.get("name")
            if not uploaded_filename:
                return Response(
                    content=json.dumps({"error": {"message": "No filename returned from upload", "type": "api_error"}}),
                    status_code=502,
                    media_type="application/json"
                )

            print(f"[proxy] Uploaded image: {uploaded_filename}", flush=True)

            try:
                from PIL import Image
                import io
                img = Image.open(io.BytesIO(image_content))
                img_width, img_height = img.size
                print(f"[proxy] Detected image size: {img_width}x{img_height}", flush=True)
            except Exception as e:
                print(f"[proxy] Could not detect image size: {e}, using default 1024x1024", flush=True)
                img_width, img_height = 1024, 1024

            if requested_dimensions is not None:
                img_width, img_height = requested_dimensions
            effective_size = f"{img_width}x{img_height}"

            extension_asset_fields, asset_error_response = _allowed_image_extension_asset_fields(
                request_body=form_dict,
                manifest=manifest,
                receipt=receipt,
            )
            if asset_error_response is not None:
                return asset_error_response
            background_decision = await resolve_image_background_decision(
                background or "auto",
                prompt,
                auth_context=auth_context,
                # jpeg has no alpha channel: "auto" background must never
                # select removal for a jpeg request (see the generate route's
                # identical guard for the full rationale).
                force_bypass=bool(mask_file) or output_format == "jpeg",
                force_bypass_reason=(
                    "edit mask supplied" if mask_file
                    else "output_format=jpeg has no alpha channel"
                ),
            )

            prompt_node = meta.get("prompt_node")
            seed_node = meta.get("seed_node")
            size_node = meta.get("size_node")

            if prompt_node and prompt_node in workflow:
                workflow[prompt_node]["inputs"]["text"] = prompt

            # Upload any reference images beyond the first (already uploaded
            # above as `uploaded_filename`) and bind every uploaded filename,
            # in submission order, to the workflow's declared image slots.
            image_filenames = [uploaded_filename]
            for extra_file in image_files[1:]:
                extra_content = await extra_file.read()
                extra_upload_resp = await client.post(
                    f"{COMFY_HOST}/upload/image",
                    headers=headers,
                    files={"image": (extra_file.filename or "input.png", extra_content, "image/png")},
                )
                if extra_upload_resp.status_code != 200:
                    return Response(
                        content=json.dumps({"error": {"message": f"Image upload failed: {extra_upload_resp.text}", "type": "api_error"}}),
                        status_code=502,
                        media_type="application/json"
                    )
                extra_upload_result = extra_upload_resp.json()
                extra_filename = extra_upload_result.get("name")
                if not extra_filename:
                    return Response(
                        content=json.dumps({"error": {"message": "No filename returned from upload", "type": "api_error"}}),
                        status_code=502,
                        media_type="application/json"
                    )
                print(f"[proxy] Uploaded additional reference image: {extra_filename}", flush=True)
                image_filenames.append(extra_filename)

            for slot_node, filename in zip(image_slots, image_filenames):
                if slot_node in workflow:
                    workflow[slot_node]["inputs"]["image"] = filename

            mask_input_name = _manifest_route_managed_mask_input(manifest)
            mask_uses_workflow = bool(
                mask_context is not None
                and _manifest_uses_source_alpha_mask(manifest)
            )
            if mask_context is not None and mask_input_name and mask_content is not None:
                mask_files = {"image": ("normalized-mask.png", mask_context.edit_mask, "image/png")}
                mask_upload_resp = await client.post(
                    f"{COMFY_HOST}/upload/image",
                    headers=headers,
                    files=mask_files,
                )
                if mask_upload_resp.status_code != 200:
                    return Response(
                        content=json.dumps({"error": {"message": f"Mask upload failed: {mask_upload_resp.text}", "type": "api_error"}}),
                        status_code=502,
                        media_type="application/json"
                    )
                mask_upload_result = mask_upload_resp.json()
                uploaded_mask_filename = mask_upload_result.get("name")
                if not uploaded_mask_filename:
                    return Response(
                        content=json.dumps({"error": {"message": "No mask filename returned from upload", "type": "api_error"}}),
                        status_code=502,
                        media_type="application/json"
                    )
                workflow = bind_backend_request(
                    manifest,
                    "comfyui",
                    workflow,
                    {mask_input_name: uploaded_mask_filename},
                ).request
                mask_uses_workflow = True

            # Set size on Flux2Scheduler and EmptyFlux2LatentImage nodes.
            # V2 workflows use node 48 for scheduler and 47 for empty latent.
            for node_id in ["47", "48", size_node]:
                if node_id and node_id in workflow:
                    if "width" in workflow[node_id]["inputs"]:
                        workflow[node_id]["inputs"]["width"] = img_width
                    if "height" in workflow[node_id]["inputs"]:
                        workflow[node_id]["inputs"]["height"] = img_height
            workflow = _apply_manifest_route_inputs(
                manifest,
                workflow,
                {"width": img_width, "height": img_height},
            )
            workflow = _apply_quality_steps(manifest, workflow, quality, receipt)

            workflow, extension_response = await _apply_workflow_extensions_to_image_request(
                request_body=form_dict,
                manifest=manifest,
                backend_request=workflow,
                standard_fields=STANDARD_IMAGE_EDIT_FIELDS,
                receipt=receipt,
                form=form,
                client=client,
                headers=headers,
                extension_asset_fields=extension_asset_fields,
                auth_context=auth_context,
            )
            if extension_response is not None:
                return extension_response

            image_transform: Optional[Callable[[bytes], bytes]] = None
            image_response_headers: dict[str, str] = _record_image_size_adjustment(
                receipt,
                requested=requested_size,
                effective=effective_size,
            )
            if mask_context is not None:
                if mask_uses_workflow:
                    image_response_headers["X-Image-Mask"] = "workflow"
                    image_response_headers["X-Image-Mask-Source"] = mask_context.mask_mode
                else:
                    image_transform = lambda raw: _apply_image_edit_mask_composite(mask_context, raw)
                    image_response_headers["X-Image-Mask"] = "post-composite"
                    image_response_headers["X-Image-Mask-Source"] = mask_context.mask_mode
                    if receipt is not None:
                        receipt.add_warning("mask_mode:post_composite")

            fallback_workflow = copy.deepcopy(workflow)
            set_workflow_background_removal(fallback_workflow, meta, False)
            if background_decision.remove_background:
                if set_workflow_background_removal(workflow, meta, True):
                    print(
                        f"[proxy] Image edit background removal enabled for {workflow_name} "
                        f"(confidence={background_decision.confidence})",
                        flush=True,
                    )
                    firehose_metrics.record_event(
                        "image_background_removal",
                        "edit background removal enabled",
                        workflow=workflow_name,
                        confidence=background_decision.confidence,
                        source=background_decision.source,
                    )
                    workflow_name_for_batching = f"{workflow_name}+rmbg"
                else:
                    print(f"[proxy] background removal requested but edit workflow {workflow_name} has no background_removal wiring", flush=True)
                    firehose_metrics.record_event(
                        "image_background_removal_fallback",
                        "edit workflow has no RMBG wiring",
                        workflow=workflow_name,
                    )
                    background_decision = ImageBackgroundRemovalDecision(
                        remove_background=False,
                        confidence=0.0,
                        reason="workflow has no RMBG wiring",
                        source="workflow_unsupported",
                    )
                    workflow_name_for_batching = workflow_name
            else:
                set_workflow_background_removal(workflow, meta, False)
                workflow_name_for_batching = workflow_name

            # V2 uses RandomNoise with noise_seed, V1 used KSampler with seed.
            seed_field = "seed"
            if seed_node and seed_node in workflow:
                inputs = workflow[seed_node].get("inputs", {})
                if "noise_seed" in inputs:
                    seed_field = "noise_seed"

            admission = _dispatch_admission_response(
                "image.edit", auth_context=auth_context, service_id="comfyui",
                service_available=COMFY_ENABLED, resource_class="image", queue_key=_MEDIA_JOB_QUEUE_KEY,
            )
            if admission is not None:
                return admission
            return await _generate_images_with_adaptive_batching(
                request=request,
                client=client,
                base_workflow=workflow,
                meta=meta,
                seed_node=seed_node,
                seed_field=seed_field,
                workflow_name=workflow_name_for_batching,
                width=img_width,
                height=img_height,
                n_requested=n,
                response_format=response_format,
                headers=headers,
                background_removal_decision=background_decision,
                fallback_workflow=fallback_workflow,
                fallback_workflow_name=workflow_name,
                image_transform=image_transform,
                image_response_headers=image_response_headers,
                auth_context=auth_context,
                output_format=output_format,
                output_compression=output_compression,
                output_background="transparent" if background_decision.remove_background else "opaque",
                output_quality=quality,
                output_size=effective_size,
                fixed_seed=_workflow_extension_integer(form_dict, "seed"),
            )

    except httpx.TimeoutException:
        return Response(
            content=json.dumps({"error": {"message": "ComfyUI request timeout", "type": "api_error"}}),
            status_code=504,
            media_type="application/json"
        )
    except httpx.ConnectError:
        return Response(
            content=json.dumps({"error": {"message": f"ComfyUI unavailable at {COMFY_HOST}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )
    except Exception as e:
        return Response(
            content=json.dumps({"error": {"message": f"ComfyUI edit error: {str(e)}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )


# OpenAI's variations request has no prompt (unlike edits); there is no local
# "true" variations model, so the gateway routes through an edit-capable
# workflow with this fixed generic prompt instead of asking the client for one
# it isn't allowed to send.
IMAGE_VARIATIONS_PROMPT = (
    "Create a creative variation of this image: keep the same subject, "
    "composition, and overall style, but vary fine detail and texture."
)


class _OverlayFormRequest:
    """Request-shim that overrides/injects specific multipart fields.

    Delegates every attribute except ``form()`` to the real request (so
    ``request.url``/``request.headers`` used downstream for signed URLs keep
    working), and returns a ``FormData`` with ``overlay`` fields added/
    replaced over the already-parsed base form. Used to route
    ``/v1/images/variations`` through the edit route's upload/inject pipeline
    without duplicating it: a variations request has no ``prompt``, so this
    injects the fixed prompt above (and the configured workflow as `model`)
    on top of the client's real ``image`` upload(s).
    """

    def __init__(self, request: Request, base_form: FormData, overlay: Mapping[str, str]) -> None:
        self._request = request
        items = [(k, v) for k, v in base_form.multi_items() if k not in overlay]
        items.extend(overlay.items())
        self._form = FormData(items)

    def __getattr__(self, name: str) -> Any:
        return getattr(self._request, name)

    async def form(self) -> FormData:
        return self._form


async def proxy_comfy_variations_request(
    request: Request,
    auth_context: AuthContext,
    receipt: RouteReceipt | None = None,
) -> Response:
    """Handle OpenAI-compatible /v1/images/variations.

    There is no local model dedicated to "variations" (an unprompted
    creative re-render). Instead this validates the narrower variations
    field set, then delegates to `proxy_comfy_edit_request` via
    `_OverlayFormRequest` with a fixed generic prompt and the configured
    edit-capable workflow (`images.variations.default_workflow`,
    `proxy_config.yml`), reusing its entire upload/inject/adaptive-batching
    pipeline rather than duplicating it.
    """
    admission = _dispatch_admission_response(
        'image.variation', auth_context=auth_context, service_id="comfyui",
        service_available=COMFY_ENABLED, resource_class='image', queue_key=_MEDIA_JOB_QUEUE_KEY,
    )
    if admission is not None:
        return admission

    if not COMFY_ENABLED:
        if receipt is not None:
            receipt.add_fallback_reason("comfy_disabled")
        return Response(
            content=json.dumps({"error": {"message": "Image generation not enabled", "type": "service_unavailable"}}),
            status_code=503,
            media_type="application/json"
        )
    service_response = (await asyncio.to_thread(_service_availability_response, "comfyui",
        service_label="ComfyUI",))
    if service_response is not None:
        if receipt is not None:
            receipt.add_fallback_reason("comfy_operator_mode")
        return service_response

    try:
        form = await request.form()
    except Exception as e:
        _record_image_input(receipt, "body", rejected_reason="invalid_form")
        return Response(
            content=json.dumps({"error": {"message": f"Invalid form data: {e}", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )

    form_dict: dict[str, Any] = {}
    for key, value in form.multi_items():
        if key in form_dict:
            continue
        form_dict[str(key)] = value
    # Variations take no workflow controls except the gateway-level metadata
    # control. Read it, then drop it before the strict unknown-field check.
    metadata_field = f"extensions[{WORKFLOW_EXTENSION_NAMESPACE}][{provenance.METADATA_CONTROL}]"
    metadata_value = form_dict.pop(metadata_field, None)
    if metadata_value is not None:
        metadata_error = _note_media_metadata_body({
            "extensions": {WORKFLOW_EXTENSION_NAMESPACE: {
                provenance.METADATA_CONTROL: metadata_value}}
        })
        if metadata_error is not None:
            return metadata_error
    unknown_response = _record_unknown_image_fields(
        receipt,
        form_dict,
        STANDARD_IMAGE_VARIATIONS_FIELDS,
    )
    if unknown_response is not None:
        return unknown_response

    image_files = _collect_edit_image_uploads(form)
    if not image_files:
        _record_image_input(receipt, "image", rejected_reason="missing")
        return Response(
            content=json.dumps({"error": {"message": "image is required", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    if len(image_files) > 1:
        # OpenAI's variations endpoint takes exactly one input image. Reject
        # clearly rather than silently using only the first (the same
        # silent-drop bug class this media-refresh fixes for edits).
        _record_image_input(receipt, "image", rejected_reason="too_many_images")
        return Response(
            content=json.dumps({
                "error": {
                    "message": (
                        f"/v1/images/variations accepts exactly one input image; "
                        f"{len(image_files)} were provided"
                    ),
                    "type": "invalid_request_error",
                    "param": "image",
                    "code": "too_many_images",
                }
            }),
            status_code=400,
            media_type="application/json",
        )
    _record_image_input(receipt, "image")

    requested_model_raw = form.get("model")
    requested_model = str(requested_model_raw) if requested_model_raw else ""
    if requested_model:
        # An OpenAI-named model (dall-e-2, dall-e-3, gpt-image-1, ...) is a
        # request for "whatever the gateway's variations default is", same as
        # omitting `model` entirely -- these public names carry no local
        # workflow identity of their own. A name that doesn't resolve as an
        # OpenAI alias is a concrete local workflow id and is honored as-is.
        try:
            model_resolution = resolve_model_for_operation("image_edits", requested_model)
        except ModelCompatibilityError as e:
            _record_image_input(receipt, "model", rejected_reason="model_incompatible")
            return model_compatibility_error(e)
        model = IMAGE_VARIATIONS_DEFAULT_WORKFLOW if model_resolution.is_openai_alias else requested_model
    else:
        model = IMAGE_VARIATIONS_DEFAULT_WORKFLOW
    if not (model.endswith("-edit") or model.endswith("-inpaint")):
        model = f"{model}-edit"
    if receipt is not None:
        receipt.requested_model = requested_model or None
    _record_image_input(receipt, "model")

    overlay: dict[str, str] = {
        "prompt": IMAGE_VARIATIONS_PROMPT,
        "model": model,
    }
    manifest = _find_image_manifest("image.edit", model)
    if manifest is not None and "denoise" in (manifest.get("inputs") or {}):
        # Only inject the denoise extension when the resolved workflow's
        # manifest actually declares it -- an unsupported extension input
        # would otherwise be rejected with a 400 by the edit route itself.
        overlay["extensions"] = json.dumps({
            WORKFLOW_EXTENSION_NAMESPACE: {"denoise": IMAGE_VARIATIONS_DENOISE}
        })

    overlay_request = _OverlayFormRequest(request, form, overlay)
    client_requested_model = requested_model or None
    response = await proxy_comfy_edit_request(
        overlay_request,  # type: ignore[arg-type]
        auth_context,
        receipt=receipt,
    )
    if receipt is not None:
        # proxy_comfy_edit_request just overwrote receipt.requested_model with
        # the *injected* overlay model (what the edit backend was asked to
        # run) -- from its own point of view that's correct, but here it
        # clobbers what the client actually sent (e.g. "dall-e-2"). Restore
        # the client's requested_model and keep the delegated workflow (which
        # receipt.resolved_model already reflects) as separate, clearly-named
        # metadata rather than conflating the two.
        receipt.metadata["variations_delegated_workflow"] = model
        receipt.requested_model = client_requested_model
    return response


# =============================================================================
# ComfyUI Backend (Video Generation — Sora-shaped async API)
# =============================================================================
#
# Endpoints (mirror Sora 2):
#   POST /v1/videos                     -> {video_id, status: "queued", ...}
#   GET  /v1/videos/{video_id}          -> {video_id, status, progress, ...}
#   GET  /v1/videos/{video_id}/content  -> binary mp4 (Content-Type: video/mp4)
#
# `video_id` is `video_<comfy_prompt_id>`. We round-trip ComfyUI's prompt id and
# look it up via /history/{prompt_id} on poll. The proxy is stateless across
# restarts — clients are expected to keep the id and re-poll. ComfyUI persists
# history for the life of its process.

VIDEO_ID_PREFIX = "video_"


# =============================================================================
# ComfyUI websocket listener for real-time progress
# =============================================================================
#
# A single long-lived websocket subscription per proxy process. ComfyUI emits
# events keyed by `prompt_id`; we cache the latest progress so /v1/videos/{id}
# can return real step/total/percent without polling /history every time.
#
# Phase heuristic: encoding ~0-5%, sampling 5-90%, decoding 90-100%. The
# sampler is the long-running phase, so its step/total drives most of the bar.
# When the listener is down, callers fall back to /history polling.

# Stable client_id used for both the websocket connection and the /prompt POST
# body. ComfyUI routes events for a submission to the matching client_id.
COMFY_CLIENT_ID = uuid.uuid4().hex

# prompt_id -> {status, percent, step, total, node, phase, error, updated_at}
_video_progress: dict[str, dict] = {}
_video_progress_lock = asyncio.Lock()

# Garbage-collect entries older than this many seconds (default 6h).
_VIDEO_PROGRESS_TTL = 6 * 3600

# Heuristic sampler-node class identifiers. We treat anything containing
# "Sampler" or "KSampler" in the node class as the sampling phase.
_SAMPLER_HINT_SUBSTRINGS = ("sampler", "ksampler")
# VAE decode / save / output nodes => post-sampling.
_DECODE_HINT_SUBSTRINGS = ("vaedecode", "savevideo", "videocombine", "save_video", "save")


def _node_class_from_workflow(workflow: dict | None, node_id: str | None) -> str:
    if not workflow or not node_id:
        return ""
    node = workflow.get(node_id) if isinstance(workflow, dict) else None
    if isinstance(node, dict):
        return str(node.get("class_type") or "").lower()
    return ""


# prompt_id -> workflow dict (kept alongside progress state to classify nodes
# into phases without re-fetching /history).
_video_workflows: dict[str, dict] = {}
# Long-video chains: prompt_id -> per-segment [{"sample": node_id, "decode": node_id}].
# Lets progress span all segments instead of restarting at each sampler.
_video_chain_units: dict[str, list[dict[str, str]]] = {}

# prompt_id -> {model, size, seconds, actual_seconds, created_at, completed_at,
#               owner_key_hash, deleted_at}
# Safe (prompt-free) submit-time metadata the OpenAI list/retrieve shapes need
# but ComfyUI's own /history doesn't carry (no model/size/seconds/created_at
# fields, and no concept of "which of these history entries are ours" since
# /history is shared across every image/video/audio job type). Same
# process-lifetime-only statefulness as _video_progress/_video_workflows: a
# restart loses it, same as the comment at the top of this section documents
# for /v1/videos/{id} polling.
#
# This dict is also the single source of truth for "does this video_id exist
# and is it mine" across GET (status), GET (content), GET (list), and DELETE:
# `owner_key_hash` scopes every one of those to the principal that created
# the job (mirrors `_asset_owner_key`'s existing image/audio asset model; see
# `_video_job_access_allowed`), and `deleted_at` is the DELETE tombstone --
# once set, every read route treats the job as not-found, regardless of
# whether ComfyUI's own /history still has the entry (its retention is
# independent of ours and outside our control).
_video_job_records: dict[str, dict] = {}


def _video_job_access_allowed(prompt_id: str, auth_context: AuthContext | None) -> bool:
    """Mirror `_asset_access_allowed`'s ownership semantics for video jobs.

    No owner recorded (e.g. the job predates this field, or auth was
    disabled at submit time) fails closed for an authenticated caller but
    keeps the old unscoped behavior for an auth-disabled deployment, exactly
    like `_asset_access_allowed`.
    """
    record = _video_job_records.get(prompt_id)
    owner = record.get("owner_key_hash") if record is not None else None
    if not owner:
        return _asset_owner_key(auth_context) is None
    return owner in _asset_read_owner_keys(auth_context)


def _video_job_visible(prompt_id: str, auth_context: AuthContext | None) -> bool:
    """True iff the job is known, not deleted, and owned by the caller."""
    record = _video_job_records.get(prompt_id)
    if record is None or record.get("deleted_at") is not None:
        return False
    return _video_job_access_allowed(prompt_id, auth_context)


# Record ids loaded from the store at startup (not created by this process).
_video_records_restored: set[str] = set()


def _video_job_blocked(prompt_id: str, auth_context: AuthContext | None) -> bool:
    """True when the caller must get 404 for this video id.

    A tracked job is blocked unless it is visible (owned, not deleted). An id
    with no record is blocked too whenever auth is enabled: it is either
    unknown or was created before ownership was recorded, and ComfyUI's shared
    /history must not become a way to read another key's video. With auth
    disabled (`_asset_owner_key` is None) nothing is owned, so an untracked id
    still falls through to the ComfyUI history lookup. `videos.allow_untracked_ids`
    (default false) restores that fall-through for authenticated callers, for the
    deploy that first starts recording ids: videos made before it have no record.
    """
    if prompt_id in _video_job_records:
        return not _video_job_visible(prompt_id, auth_context)
    if VIDEO_ALLOW_UNTRACKED_IDS:
        return False
    return _asset_owner_key(auth_context) is not None


# Persisted records are kept this long. ComfyUI's /history is the bytes' source
# of truth; this only needs to outlive typical client use of a video id.


def _persist_video_record(prompt_id: str) -> None:
    """Write one record through to the media-jobs SQLite. Best effort: a store
    failure must not fail a render, so it is logged and swallowed."""
    record = _video_job_records.get(prompt_id)
    if record is None:
        return
    try:
        video_job_records.save(prompt_id, record, path=media_jobs.DB_PATH)
    except Exception as exc:  # noqa: BLE001
        print(f"[proxy] video record persist failed for {prompt_id}: {type(exc).__name__}: {exc}", flush=True)


def _forget_video_record_row(prompt_id: str) -> None:
    try:
        video_job_records.remove(prompt_id, path=media_jobs.DB_PATH)
    except Exception as exc:  # noqa: BLE001
        print(f"[proxy] video record delete failed for {prompt_id}: {type(exc).__name__}: {exc}", flush=True)


def _hydrate_video_job_records() -> int:
    """Load persisted records into `_video_job_records` (startup)."""
    try:
        loaded = video_job_records.load_all(path=media_jobs.DB_PATH)
    except Exception as exc:  # noqa: BLE001
        print(f"[proxy] video record hydrate failed: {type(exc).__name__}: {exc}", flush=True)
        return 0
    for pid, rec in loaded.items():
        if pid not in _video_job_records:
            _video_job_records[pid] = rec
            _video_records_restored.add(pid)
    return len(loaded)


def _classify_phase(node_class: str) -> str:
    nc = (node_class or "").lower()
    if any(s in nc for s in _SAMPLER_HINT_SUBSTRINGS):
        return "sampling"
    if any(s in nc for s in _DECODE_HINT_SUBSTRINGS):
        return "decoding"
    return "encoding"


def _phase_percent(phase: str, sampler_frac: float) -> int:
    """Map (phase, sampler progress 0..1) to overall percent.

    encoding => 0..5, sampling => 5..90, decoding => 90..99 (100 reserved for
    terminal success). Conservative because LTX I/O after sampling is fast.
    """
    sampler_frac = max(0.0, min(1.0, sampler_frac))
    if phase == "encoding":
        return 5
    if phase == "sampling":
        return int(round(5 + sampler_frac * 85))
    if phase == "decoding":
        return 92
    return 5


def _video_percent(prompt_id: str, node_id: str | None, phase: str, frac: float) -> int:
    """Overall percent for a node event. A chain job spreads 5..92 over its segments."""
    units = _video_chain_units.get(prompt_id)
    index = video_extend.segment_of_node(units, str(node_id or ""), progress_only=True) if units else None
    if index is None:
        return _phase_percent(phase, frac)
    frac = max(0.0, min(1.0, frac))
    done = index + (frac if phase == "sampling" else 0.97 if phase == "decoding" else 0.0)
    return int(round(5 + 87 * done / len(units)))


def _openai_video_status(status: str) -> str:
    return _OPENAI_VIDEO_STATUS_BY_INTERNAL.get(str(status), str(status))


def _video_progress_percent(value: Any, *, floor: int = 0, ceiling: int = 100) -> int:
    try:
        progress = int(value)
    except (TypeError, ValueError):
        progress = floor
    return max(floor, min(progress, ceiling))


def _tracked_video_fields(prompt_id: str, auth_context: AuthContext | None = None) -> dict[str, Any]:
    record = _video_job_records.get(prompt_id) or {}
    fields = {
        key: record.get(key)
        for key in (
            "model", "size", "seconds", "actual_seconds", "created_at", "completed_at",
            "expires_at", "error", "remixed_from_video_id",
            "extended_from_video_id", "total_seconds",
        )
        if record.get(key) is not None
    }
    if record.get("resolved_model") is not None:
        fields["azizam_resolved_model"] = record["resolved_model"]
    person_id = _auth_person_id(auth_context)
    if person_id != record.get("person_id"):
        person_id = None
    prompt_asset_id = str(record.get("asset_id") or f"video_{prompt_id}")
    saved = prompt_memory.get(prompt_asset_id, person_id) if person_id else None
    fields["prompt"] = saved["prompt_text"] if saved else None
    return fields


def _hold_video_progress(prompt_id: str, payload: dict[str, Any]) -> dict[str, Any]:
    """Never report lower progress than an earlier poll did for the same job.

    Multi-stage graphs (LTX upscale, Bernini high+low) restart the sampler bar
    in each stage, and a queue-only poll reports a flat 25. OpenAI's `progress`
    only moves forward, so keep a high-water mark per job. Terminal states
    report 100 and are left alone.
    """
    status = payload.get("azizam_status")
    entry = _video_progress.setdefault(prompt_id, {})
    if status in ("succeeded", "failed"):
        entry["status"] = status
        entry["updated_at"] = payload.get("updated_at") or int(time.time())
        return payload
    if status not in ("queued", "running"):
        return payload
    high = max(int(entry.get("reported_progress", 0)), int(payload.get("progress") or 0))
    if high > int(entry.get("reported_progress", 0)):
        entry["updated_at"] = payload.get("updated_at") or int(time.time())
    entry["reported_progress"] = high
    entry["status"] = status
    payload["progress"] = high
    return payload


def _openai_video_payload(
    *,
    video_id: str,
    prompt_id: str,
    status: str,
    progress: int,
    auth_context: AuthContext | None = None,
    updated_at: int | None = None,
    **extra: Any,
) -> dict[str, Any]:
    tracked = _tracked_video_fields(prompt_id, auth_context)
    payload: dict[str, Any] = {
        "id": video_id,
        "object": "video",
        "azizam_object": "video.generation",
        "status": _openai_video_status(status),
        "azizam_status": status,
        "progress": _video_progress_percent(progress),
        "completed_at": None,
        "expires_at": None,
        "prompt": None,
        "remixed_from_video_id": None,
        "error": None,
    }
    payload.update(tracked)
    if updated_at is not None:
        payload["updated_at"] = updated_at
    if status == "succeeded" and payload.get("completed_at") is None:
        payload["completed_at"] = updated_at or int(time.time())
    payload.update({key: value for key, value in extra.items() if value is not None})
    chain = (_video_job_records.get(prompt_id) or {}).get("chain")
    if isinstance(chain, Mapping):
        total = int(chain.get("segments") or 0)
        if status == "succeeded":
            done = total
        else:
            node = (_video_progress.get(prompt_id) or {}).get("unit_node")
            index = video_extend.segment_of_node(chain.get("units") or [], str(node or ""), progress_only=True)
            done = index if index is not None else 0
        payload["segments_total"] = total
        payload["segments_completed"] = done
    return payload


async def _record_event(event: dict) -> None:
    etype = event.get("type")
    data = event.get("data") or {}
    prompt_id = data.get("prompt_id")
    if not prompt_id:
        return

    async with _video_progress_lock:
        entry = _video_progress.setdefault(prompt_id, {
            "status": "running",
            "percent": 0,
            "step": 0,
            "total": 0,
            "node": None,
            "node_class": None,
            "phase": "encoding",
            "error": None,
            "updated_at": time.time(),
        })

        wf = _video_workflows.get(prompt_id)
        units = _video_chain_units.get(prompt_id)
        event_node = data.get("node") if etype == "executing" else data.get("node") or data.get("node_id")
        if units and event_node is not None and video_extend.segment_of_node(units, str(event_node), progress_only=True) is not None:
            entry["unit_node"] = str(event_node)

        if etype == "executing":
            node_id = data.get("node")
            if node_id is None:
                # null node => execution complete for this prompt (legacy signal).
                pass
            else:
                node_class = _node_class_from_workflow(wf, str(node_id))
                phase = _classify_phase(node_class)
                entry["node"] = str(node_id)
                entry["node_class"] = node_class or None
                entry["phase"] = phase
                # When entering a new node we don't yet know its step/total;
                # keep prior step/total but recompute phase percent.
                if phase != "sampling":
                    entry["step"] = 0
                    entry["total"] = 0
                    entry["percent"] = max(entry["percent"], _video_percent(prompt_id, node_id, phase, 0.0))
        elif etype == "progress":
            value = int(data.get("value") or 0)
            maxv = int(data.get("max") or 0)
            node_id = str(data.get("node") or entry.get("node") or "")
            node_class = _node_class_from_workflow(wf, node_id) or entry.get("node_class") or ""
            phase = _classify_phase(node_class) if node_class else entry.get("phase", "sampling")
            entry["node"] = node_id or entry.get("node")
            entry["node_class"] = node_class or entry.get("node_class")
            entry["phase"] = phase
            entry["step"] = value
            entry["total"] = maxv
            frac = (value / maxv) if maxv > 0 else 0.0
            entry["percent"] = _video_percent(prompt_id, node_id, phase, frac)
        elif etype == "progress_state":
            # Modern ComfyUI per-node progress map. Pick the running node with
            # the highest fractional progress as the representative step/total.
            nodes = data.get("nodes") or {}
            best = None  # (frac, value, max, node_id, node_class)
            for node_id, ns in nodes.items():
                state = (ns or {}).get("state")
                if state != "running":
                    continue
                v = float(ns.get("value") or 0)
                m = float(ns.get("max") or 0)
                frac = (v / m) if m > 0 else 0.0
                node_class = _node_class_from_workflow(wf, str(node_id))
                # Prefer sampler nodes when present; else keep best by frac.
                weight = (1 if any(s in node_class for s in _SAMPLER_HINT_SUBSTRINGS) else 0)
                key = (weight, frac)
                if best is None or key > best[0]:
                    best = (key, int(v), int(m), str(node_id), node_class)
            if best is not None:
                _, v_i, m_i, node_id, node_class = best
                phase = _classify_phase(node_class)
                entry["node"] = node_id
                entry["node_class"] = node_class or None
                entry["phase"] = phase
                entry["step"] = v_i
                entry["total"] = m_i
                frac = (v_i / m_i) if m_i > 0 else 0.0
                entry["percent"] = _video_percent(prompt_id, node_id, phase, frac)
        elif etype == "execution_success":
            entry["status"] = "succeeded"
            entry["percent"] = 100
            entry["phase"] = "done"
            entry["ended_at"] = time.time()
        elif etype == "execution_error":
            entry["status"] = "failed"
            entry["error"] = _comfy_execution_error_message({"status": {"messages": [["execution_error", data]]}})
            entry["ended_at"] = time.time()

        entry["updated_at"] = time.time()


# How long a tombstoned (DELETE'd) _video_job_records entry is kept around
# before being forgotten entirely. Matches _VIDEO_RECONCILE_RETAIN (the
# existing terminal-entry retention window) -- long enough that a client
# polling right after DELETE reliably sees 404, short enough not to leak.
_VIDEO_JOB_RECORD_DELETED_RETAIN = 5 * 60


def _gc_video_job_records_locked(now: float) -> None:
    """Forget explicitly deleted video records after the polling grace period.

    Caller must hold `_video_progress_lock`. Other records have no expiry.
    """
    drop: list[str] = []
    for pid, rec in _video_job_records.items():
        deleted_at = rec.get("deleted_at")
        if deleted_at is not None:
            if now - deleted_at > _VIDEO_JOB_RECORD_DELETED_RETAIN:
                drop.append(pid)
            continue
    for pid in drop:
        _video_job_records.pop(pid, None)
        _forget_video_record_row(pid)
        prompt_memory.delete_asset(f"video_{pid}")


async def _gc_video_progress() -> None:
    now = time.time()
    cutoff = now - _VIDEO_PROGRESS_TTL
    async with _video_progress_lock:
        stale = [pid for pid, e in _video_progress.items() if e.get("updated_at", 0) < cutoff]
        for pid in stale:
            _video_progress.pop(pid, None)
            _video_workflows.pop(pid, None)
            _video_chain_units.pop(pid, None)
        _gc_video_job_records_locked(now)


# How often the reconciliation loop polls ComfyUI for authoritative state.
_VIDEO_RECONCILE_INTERVAL = 15
# How long to keep entries with a terminal status after ended_at before GC.
_VIDEO_RECONCILE_RETAIN = 5 * 60
# How many recent /history items to consider when reconciling.
_VIDEO_RECONCILE_HISTORY_LIMIT = 200


def _extract_prompt_ids(queue_block: list) -> set[str]:
    """ComfyUI /queue entries are tuple-like lists: [priority, prompt_id, ...]."""
    out: set[str] = set()
    if not isinstance(queue_block, list):
        return out
    for entry in queue_block:
        if isinstance(entry, (list, tuple)) and len(entry) >= 2:
            pid = entry[1]
            if isinstance(pid, str) and pid:
                out.add(pid)
    return out


def _history_terminal_state(job: dict) -> tuple[str, Optional[str]]:
    """Return (terminal_status, error_text) for a /history entry.

    terminal_status is 'succeeded', 'failed', or 'running' (not yet terminal).
    """
    error_message = _comfy_execution_error_message(job)
    if error_message:
        return ("failed", error_message)

    status_block = (job or {}).get("status", {}) or {}
    if not status_block.get("completed"):
        return ("running", None)
    return ("succeeded", None)


async def _fetch_comfy_state() -> tuple[Optional[set[str]], Optional[dict]]:
    """Fetch ComfyUI authoritative state: (active_prompt_ids, history_map).

    Returns (None, None) on any error. Uses 2s timeouts per the spec.
    """
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(2.0, connect=2.0), verify=tls_context()) as client:
            q_resp = await client.get(f"{COMFY_HOST}/queue")
            h_resp = await client.get(f"{COMFY_HOST}/history?max_items={_VIDEO_RECONCILE_HISTORY_LIMIT}")
    except Exception as e:
        print(f"[proxy] video reconcile: ComfyUI fetch failed ({e})", flush=True)
        return (None, None)
    if q_resp.status_code != 200 or h_resp.status_code != 200:
        return (None, None)
    # A body that is not the expected JSON object says nothing about the
    # queue: an empty answer here would read as "ComfyUI forgot every prompt"
    # and orphan live jobs, so it counts as unavailable.
    try:
        q_data = q_resp.json()
        h_data = h_resp.json()
    except Exception:
        return (None, None)
    if not isinstance(q_data, dict) or not isinstance(h_data, dict):
        return (None, None)
    active: set[str] = set()
    active |= _extract_prompt_ids(q_data.get("queue_running") or [])
    active |= _extract_prompt_ids(q_data.get("queue_pending") or [])
    return (active, h_data)


async def _reconcile_video_progress() -> None:
    """Reconcile _video_progress against ComfyUI's /queue and /history.

    - In /queue (running or pending): leave as-is.
    - In /history: mark succeeded/failed with terminal info.
    - In neither: mark failed/orphaned (ComfyUI does not know the prompt_id).
    - Entries with ended_at older than _VIDEO_RECONCILE_RETAIN: garbage-collect.
    """
    active, history = await _fetch_comfy_state()
    now = time.time()

    async with _video_progress_lock:
        if not _video_progress:
            return

        if active is None or history is None:
            # ComfyUI unreachable: only run the time-based GC, do not mutate
            # statuses (could be a transient blip).
            _gc_video_progress_terminal_locked(now)
            return

        for prompt_id in list(_video_progress.keys()):
            entry = _video_progress.get(prompt_id)
            if not isinstance(entry, dict):
                continue
            current_status = entry.get("status")

            if prompt_id in active:
                # Real job in flight; touch updated_at so it doesn't look stale
                # but otherwise let the ws listener drive it.
                continue

            if prompt_id in history:
                job = history.get(prompt_id) or {}
                terminal, err_text = _history_terminal_state(job)
                if terminal == "succeeded" and current_status != "succeeded":
                    entry["status"] = "succeeded"
                    entry["percent"] = 100
                    entry["phase"] = "done"
                    entry.setdefault("ended_at", now)
                    entry["updated_at"] = now
                elif terminal == "failed" and current_status != "failed":
                    entry["status"] = "failed"
                    if err_text and not entry.get("error"):
                        entry["error"] = err_text
                    entry.setdefault("ended_at", now)
                    entry["updated_at"] = now
                continue

            # Not in queue, not in history => orphaned. Only mark non-terminal
            # entries; leave existing succeeded/failed alone (they may already
            # have been GC'd from /history but already terminal locally).
            if current_status in ("queued", "running", None):
                entry["status"] = "failed"
                entry["error"] = "orphaned: ComfyUI does not report this prompt_id"
                entry.setdefault("ended_at", now)
                entry["updated_at"] = now

        _gc_video_progress_terminal_locked(now)


def _gc_video_progress_terminal_locked(now: float) -> None:
    """Drop terminal entries whose ended_at is older than retain window.

    Caller must hold _video_progress_lock.
    """
    cutoff = now - _VIDEO_RECONCILE_RETAIN
    drop: list[str] = []
    for pid, e in _video_progress.items():
        if not isinstance(e, dict):
            drop.append(pid)
            continue
        if e.get("status") in ("succeeded", "failed"):
            ended = e.get("ended_at")
            # If terminal but no ended_at (legacy entry), seed it so it has
            # a fair retention window starting now instead of being dropped.
            if not ended:
                e["ended_at"] = now
                continue
            if ended < cutoff:
                drop.append(pid)
    for pid in drop:
        _video_progress.pop(pid, None)
        _video_workflows.pop(pid, None)
        _video_chain_units.pop(pid, None)
    # _video_job_records has its own independent retention -- see
    # _gc_video_job_records_locked's docstring for why it must not piggyback
    # on this (much shorter) terminal-entry sweep.
    _gc_video_job_records_locked(now)


async def _reconcile_video_progress_loop(stop_event: asyncio.Event) -> None:
    """Long-running reconciliation loop. Never crashes on transient errors."""
    while not stop_event.is_set():
        try:
            await _reconcile_video_progress()
        except Exception as e:  # noqa: BLE001
            print(f"[proxy] video reconcile loop error: {e}", flush=True)
        try:
            await asyncio.wait_for(stop_event.wait(), timeout=_VIDEO_RECONCILE_INTERVAL)
        except asyncio.TimeoutError:
            continue


# Listener state (so handlers can tell whether the ws is up).
_comfy_ws_connected = False


async def _comfy_ws_listener(stop_event: asyncio.Event) -> None:
    """Long-lived websocket subscription to ComfyUI with reconnect+backoff."""
    global _comfy_ws_connected
    try:
        from websockets.asyncio.client import connect as ws_connect
    except Exception as e:
        print(f"[proxy] ComfyUI ws listener disabled (websockets import failed: {e})", flush=True)
        return

    # ComfyUI ws lives at the same host/port as the REST API.
    ws_url = COMFY_HOST.replace("http://", "ws://").replace("https://", "wss://")
    ws_url = f"{ws_url}/ws?clientId={COMFY_CLIENT_ID}"
    backoff = 1.0
    last_gc = time.time()

    while not stop_event.is_set():
        try:
            async with ws_connect(ws_url, max_size=8 * 1024 * 1024, ping_interval=20, ping_timeout=20) as ws:
                _comfy_ws_connected = True
                backoff = 1.0
                print(f"[proxy] ComfyUI ws connected: {ws_url}", flush=True)
                async for raw in ws:
                    if stop_event.is_set():
                        break
                    if isinstance(raw, (bytes, bytearray)):
                        # Binary frames (preview images). Ignore.
                        continue
                    try:
                        evt = json.loads(raw)
                    except Exception:
                        continue
                    try:
                        await _record_event(evt)
                    except Exception as e:
                        print(f"[proxy] ws event handler error: {e}", flush=True)
                    if time.time() - last_gc > 600:
                        await _gc_video_progress()
                        last_gc = time.time()
        except asyncio.CancelledError:
            raise
        except Exception as e:
            _comfy_ws_connected = False
            print(f"[proxy] ComfyUI ws disconnected ({e}); reconnect in {backoff:.0f}s", flush=True)
            try:
                await asyncio.wait_for(stop_event.wait(), timeout=backoff)
            except asyncio.TimeoutError:
                pass
            backoff = min(backoff * 2, 30.0)
        else:
            _comfy_ws_connected = False
    _comfy_ws_connected = False


def _video_progress_snapshot(prompt_id: str) -> Optional[dict]:
    # Synchronous read; the dict is mutated under lock by the listener but a
    # plain copy here is acceptable (we only read scalars).
    entry = _video_progress.get(prompt_id)
    if entry is None:
        return None
    return dict(entry)


def _resolve_video_workflow(model: str) -> tuple[Optional[str], Optional[dict]]:
    """Map a client-supplied `model` to (workflow_name, workflow_cfg).

    Resolution order:
      1. Explicit workflow name match in `videos.workflows`.
      2. Alias match in `videos.aliases`.
      3. Empty -> default workflow.
    Returns (None, None) if the resolved name doesn't exist.
    """
    candidate = (model or "").strip()
    if not candidate:
        candidate = VIDEO_DEFAULT_WORKFLOW

    # 1) direct workflow name
    if candidate in VIDEO_WORKFLOWS:
        return candidate, VIDEO_WORKFLOWS[candidate]

    # 2) alias
    alias_target = VIDEO_ALIASES.get(candidate.lower())
    if alias_target and alias_target in VIDEO_WORKFLOWS:
        return alias_target, VIDEO_WORKFLOWS[alias_target]

    return None, None


def _load_video_workflow_file(workflow_cfg: dict) -> Optional[dict]:
    """Load the JSON for a configured video workflow.

    Attaches the UI-format twin under `__ui_workflow__` so the submit site can
    embed it via `extra_data.extra_pnginfo.workflow` for mp4 PNGInfo metadata.
    """
    file_path = workflow_cfg.get("file")
    if not file_path:
        return None
    p = Path(file_path)
    if not p.is_absolute():
        # Resolve relative paths against the proxy's directory.
        p = Path(__file__).parent / p
    if not p.exists():
        return None
    with open(p) as f:
        workflow = json.load(f)
    errors = validate_comfyui_workflow_graph(workflow)
    if errors:
        print(
            f"[proxy] invalid video ComfyUI workflow {p}: {'; '.join(errors)}",
            flush=True,
        )
        return None
    ui = _load_ui_workflow(p)
    if ui is not None:
        workflow["__ui_workflow__"] = ui
    return workflow


def _find_video_manifest(workflow_name: str, workflow_cfg: dict) -> Optional[dict]:
    manifest_path = workflow_cfg.get("manifest")
    candidates = []
    if manifest_path:
        candidates.append(Path(manifest_path))
    candidates.append(Path("manifests") / "workflows" / f"{workflow_name}.yml")

    for candidate in candidates:
        p = candidate
        if not p.is_absolute():
            p = Path(__file__).parent / p
        if not p.exists():
            continue
        try:
            return load_workflow_manifest(p)
        except ManifestError:
            raise
        except Exception as e:
            raise ManifestError(f"failed to load video workflow manifest {p}: {e}") from e
    return None


def _parse_size_clamped(size_str: str, max_size_str: str, multiple: int = 32) -> tuple[int, int]:
    """Parse 'WxH', clamp to per-workflow max_size, floor to a multiple.

    `multiple` is 32 for most workflows; LTX-2.5 needs 64 (its first
    stage runs at half size, which must itself be a multiple of 32). Sizes are
    floored (not rejected) so any OpenAI-style size string stays usable; the
    created job reports the size actually used.
    """
    width, height = parse_size(size_str or "1280x720")
    if max_size_str:
        try:
            mw, mh = parse_size(max_size_str)
            if mw and mh:
                width = min(width, mw)
                height = min(height, mh)
        except Exception:
            pass
    multiple = max(1, int(multiple))
    width = max(64, (width // multiple) * multiple)
    height = max(64, (height // multiple) * multiple)
    return width, height


def _seconds_to_length(seconds: float, frame_rate: float, *, step: int = 8, offset: int = 1) -> int:
    """Translate request `seconds` to a latent `length` of the form step*k+offset.

    Defaults are the LTX rule (8k+1). MiniMax H3 uses step=17, offset=5.

    Rounds to the *nearest* representable 8k+1 length (vs flooring). For
    fps=24 this gives ~0.333s granularity, so a request like seconds=3
    produces length=73 (3.0417s actual, +0.0417s drift) instead of the
    old length=65 (2.7083s, -0.2917s drift). Callers should compare
    `length / frame_rate` against `seconds` to decide whether to surface
    `X-Duration-Adjusted`.
    """
    frames = max(1, int(round(seconds * frame_rate)))
    # LTX latent length convention: lengths of form 8k+1 (1, 9, 17, ...)
    # Round to nearest k, not floor.
    k = max(1, int(round((frames - offset) / float(step))))
    return k * step + offset


def _video_id_from_prompt_id(prompt_id: str) -> str:
    return f"{VIDEO_ID_PREFIX}{prompt_id}"


def _prompt_id_from_video_id(video_id: str) -> Optional[str]:
    if not video_id or not video_id.startswith(VIDEO_ID_PREFIX):
        return None
    pid = video_id[len(VIDEO_ID_PREFIX):]
    return pid or None


async def _comfy_history(client: httpx.AsyncClient, prompt_id: str, headers: dict) -> Optional[dict]:
    try:
        resp = await client.get(f"{COMFY_HOST}/history/{prompt_id}", headers=headers, timeout=15)
        if resp.status_code != 200:
            return None
        data = resp.json()
        return data.get(prompt_id) if isinstance(data, dict) else None
    except Exception:
        return None


async def _comfy_queue_status(client: httpx.AsyncClient, prompt_id: str, headers: dict) -> str:
    """Return one of: queued, running, unknown.

    ComfyUI's `/queue` returns {queue_running: [...], queue_pending: [...]}, where
    each entry is a tuple-like list `[priority, prompt_id, ...]`.
    """
    try:
        resp = await client.get(f"{COMFY_HOST}/queue", headers=headers, timeout=10)
        if resp.status_code != 200:
            return "unknown"
        data = resp.json() or {}
        for entry in data.get("queue_running", []) or []:
            if isinstance(entry, (list, tuple)) and len(entry) >= 2 and entry[1] == prompt_id:
                return "running"
        for entry in data.get("queue_pending", []) or []:
            if isinstance(entry, (list, tuple)) and len(entry) >= 2 and entry[1] == prompt_id:
                return "queued"
    except Exception:
        return "unknown"
    return "unknown"


def _job_status_from_history(job: dict) -> tuple[str, int]:
    """Translate a ComfyUI history entry to (sora_status, progress_0_to_100)."""
    if _comfy_execution_error_message(job):
        return "failed", 100

    status_block = (job or {}).get("status", {}) or {}
    if status_block.get("completed"):
        return "succeeded", 100
    # If history has the entry but not yet completed, treat as running.
    return "running", 50


def _extract_video_output(job: dict) -> Optional[dict]:
    """Find the first video file produced by the workflow.

    ComfyUI's SaveVideo node writes to outputs[node_id]['videos'] = [{filename, subfolder, type}].
    Some older workflows surface the file under 'gifs' or 'images' (frame sequences) instead.
    """
    outputs = (job or {}).get("outputs", {}) or {}
    # ComfyUI's LoadVideo node can echo the uploaded source under ``images``.
    # Prefer the output directory marker; history object order is not stable.
    fallback = None
    for node_id, node_output in outputs.items():
        for key in ("videos", "gifs", "images"):
            entries = node_output.get(key) or []
            for entry in entries:
                filename = entry.get("filename") or ""
                if filename.lower().endswith((".mp4", ".webm", ".mov", ".mkv")):
                    candidate = {
                        "filename": filename,
                        "subfolder": entry.get("subfolder", ""),
                        "type": entry.get("type", "output"),
                    }
                    if candidate["type"] == "output":
                        return candidate
                    if fallback is None:
                        fallback = candidate
    return fallback


class _InputReferenceError(ValueError):
    """Raised when an input_reference value can't be parsed/fetched."""


_DATA_URI_PREFIX = "data:"


async def _resolve_gateway_media_url(
    url: str,
    auth_context: AuthContext | None,
    request: Request | None = None,
) -> media_fetch.FetchedMedia | None:
    """Resolve our own content URLs with signatures and caller ownership."""
    await _warm_video_owner_keys(auth_context)
    parsed = urlsplit(url)
    public_urls = [
        str(get_env("AZIZAM_PUBLIC_URL") or ""),
        str((config.get("proxy") or {}).get("public_url") or ""),
        str(instance_settings(ADMIN_DB_PATH, _instance_presentation_defaults()).get("base_url") or ""),
    ]
    hosts = {urlsplit(base).hostname for base in public_urls if base}
    if request is not None:
        # Signed URLs are minted from these same request hosts. Recognizing a
        # host permits only internal owned-media resolution, never network I/O.
        hosts.update(
            urlsplit(f"//{value.split(',')[0].strip()}").hostname
            for value in (
                request.headers.get("host"), request.headers.get("x-forwarded-host"),
            ) if value
        )
    if parsed.hostname not in hosts:
        return None
    match = re.fullmatch(r"/(?:openai/|gateway/)?v1/(images|assets|videos)/([^/]+)/content", parsed.path)
    if match is None:
        # A known gateway host is never a network fetch escape hatch.
        raise media_fetch.MediaFetchError("gateway media URL must reference a content asset")
    route, asset_id = match.groups()
    if route == "videos" and asset_id.startswith(VIDEO_ID_PREFIX):
        prompt_id = _prompt_id_from_video_id(asset_id)
        if not prompt_id or not _video_job_access_allowed(prompt_id, auth_context):
            raise media_fetch.MediaFetchError("video is not accessible for this API key")
        data, filename = await _load_completed_video_bytes(asset_id, auth_context)
        return media_fetch.FetchedMedia(data, filename, "video/mp4")
    cache_path = image_cache_path(asset_id) if route == "images" else asset_cache_path(asset_id)
    if cache_path is not None and cache_path.exists() and cache_path.stat().st_size > media_fetch.max_bytes():
        raise media_fetch.MediaFetchError("media exceeds the download byte limit")
    content_request = Request({
        "type": "http", "method": "GET", "path": parsed.path,
        "query_string": parsed.query.encode("ascii"), "headers": [],
    })
    response = _signed_asset_content_response(
        asset_id, content_request, invalid_message="invalid media asset",
        missing_message="media asset not found", image_only=route == "images",
        auth_context=auth_context,
    )
    if response.status_code != 200:
        message = json.loads(response.body)["error"]["message"]
        raise media_fetch.MediaFetchError(message)
    filename = f"{asset_id}{cache_path.suffix}" if cache_path else asset_id
    return media_fetch.FetchedMedia(response.body, filename, response.headers.get("content-type", "application/octet-stream"))


async def _fetch_media_url(
    url: str, auth_context: AuthContext | None, *, request: Request | None = None,
) -> media_fetch.FetchedMedia:
    return await media_fetch.safe_fetch_media(
        url, internal_resolver=lambda value: _resolve_gateway_media_url(value, auth_context, request)
    )


def _resolve_cached_image_asset(
    asset_id: str,
    auth_context: AuthContext | None = None,
) -> tuple[bytes, str]:
    parsed = _parse_asset_id(asset_id)
    if parsed is None or parsed[0] != "img":
        raise _InputReferenceError("asset_id must reference a cached image asset")
    path = asset_cache_path(asset_id)
    if path is None or not path.exists():
        raise _InputReferenceError("asset_id not found (may have been evicted)")
    if not _asset_access_allowed(asset_id, auth_context):
        raise _InputReferenceError("asset_id is not accessible for this API key")
    return media_delivery.deliver_bytes(path.read_bytes(), path.suffix, "none"), f"{asset_id}{path.suffix or '.png'}"


async def _resolve_input_reference(
    value,
    auth_context: AuthContext | None = None,
    *,
    request: Request | None = None,
) -> tuple[bytes, str]:
    """Resolve an OpenAI-shaped input_reference into (bytes, filename).

    Accepts (in priority order):
      * dict {"type": "input_image", "image_url": {...}} or {"image_url": "..."}
        (OpenAI vision-style — pull image_url out and recurse)
      * ownership-checked cached image asset id
      * http:// or https:// URL (downloaded with network and byte limits)
      * data: URI ("data:image/png;base64,...")
      * raw base64 string (fallback when the above don't match)

    Returns the raw bytes plus a filename suitable for /upload/image.
    """
    if value is None:
        raise _InputReferenceError("input_reference is empty")

    # Unwrap OpenAI vision-style content blocks. We don't need full schema
    # support — pull out a string we can resolve.
    if isinstance(value, dict):
        asset_id = value.get("asset_id")
        if isinstance(asset_id, str):
            return _resolve_cached_image_asset(asset_id.strip(), auth_context)
        for key in ("image_url", "url", "input_image"):
            inner = value.get(key)
            if isinstance(inner, dict):
                inner = inner.get("url") or inner.get("image_url")
            if isinstance(inner, str):
                return await _resolve_input_reference(inner, auth_context, request=request)
        raise _InputReferenceError(
            "input_reference dict missing a recognizable image_url/url field"
        )

    if not isinstance(value, str):
        raise _InputReferenceError(f"input_reference must be a string, got {type(value).__name__}")

    s = value.strip()
    if not s:
        raise _InputReferenceError("input_reference is empty")

    if s.startswith("asset:"):
        return _resolve_cached_image_asset(s[len("asset:"):].strip(), auth_context)
    if s.startswith("img_"):
        return _resolve_cached_image_asset(s, auth_context)

    # HTTP(S) URL.
    if s.startswith(("http://", "https://")):
        try:
            fetched = await _fetch_media_url(s, auth_context, request=request)
            fname = fetched.filename
            if "." not in fname:
                fname += ".png"
            return fetched.data, fname
        except Exception as e:
            raise _InputReferenceError(f"failed to download input_reference: {e}") from e

    # data: URI.
    if s.startswith(_DATA_URI_PREFIX):
        try:
            header, _, b64 = s.partition(",")
            data = base64.b64decode(b64, validate=False)
            ext = "png"
            # data:image/jpeg;base64,...
            if "image/" in header:
                mime = header.split("image/", 1)[1].split(";", 1)[0].strip().lower()
                if mime in ("jpeg", "jpg", "png", "webp", "gif"):
                    ext = "jpg" if mime == "jpeg" else mime
            return data, f"input_reference.{ext}"
        except Exception as e:
            raise _InputReferenceError(f"failed to decode data: URI: {e}") from e

    # Raw base64 fallback. Only accept if it decodes to non-trivial bytes.
    try:
        data = base64.b64decode(s, validate=True)
        if len(data) >= 64:  # Heuristic: any image is bigger than 64 bytes.
            return data, "input_reference.png"
    except Exception:
        pass

    # Check after base64: JPEG base64 commonly starts with '/'. No branch
    # treats a public string as a local filename or opens the supplied path.
    if s.startswith(("/", "\\", "file:", "./", "../", "~/")) or re.match(r"^[A-Za-z]:[\\/]", s):
        raise _InputReferenceError(
            "Filesystem paths are not accepted; send the bytes as a multipart upload "
            "or a data:image/...;base64 URI"
        )

    raise _InputReferenceError(
        "input_reference must be an asset id, http(s) URL, data: URI, or base64 string"
    )


class _VideoFormParseError(Exception):
    """Raised when an incoming multipart /v1/videos request can't be normalized."""


_VIDEO_FORM_FILE_FIELDS = frozenset({"input_reference"})


async def _read_video_create_form_body(request: Request) -> dict[str, Any]:
    """Normalize an openai-python multipart /v1/videos request into a JSON body.

    The OpenAI Python SDK always submits videos.create as multipart/form-data so
    that `input_reference` can be uploaded as a file. The rest of the video
    handler is written against a JSON-shaped dict (prompt/model/size/seconds/...
    as scalars, input_reference as asset id / URL / data: URI / base64). Here we
    flatten the form back into that shape so the downstream pipeline is unchanged.

    File uploads for `input_reference` are converted to a data: URI so the
    existing input_reference resolver can decode them without any new branch.
    """
    try:
        form = await request.form(max_part_size=video_inputs.MAX_FORM_PART_BYTES)
    except Exception as exc:
        raise _VideoFormParseError(f"Invalid multipart body: {exc}") from exc

    try:
        items: list[tuple[str, Any]] = []
        for name, value in form.multi_items():
            if name in _VIDEO_FORM_FILE_FIELDS and hasattr(value, "read") and hasattr(value, "filename"):
                try:
                    raw = await value.read()
                except Exception as exc:
                    raise _VideoFormParseError(
                        f"failed to read uploaded {name}: {exc}"
                    ) from exc
                mime = getattr(value, "content_type", None) or "application/octet-stream"
                items.append((name, "data:" + mime + ";base64," + base64.b64encode(raw).decode("ascii")))
                continue
            # Plain scalar form field. OpenAI's SDK sends everything else as text;
            # callers may send numeric/bool-looking strings, which the existing JSON
            # path also accepts as strings (it coerces seconds/seed via float()/int()).
            items.append((name, value if not hasattr(value, "read") else str(value)))
        try:
            # The SDK flattens extra_body={"extensions": {...}} into
            # extensions[ns][name] fields; rebuild the nested mapping.
            return video_inputs.parse_bracket_form(items)
        except ValueError as exc:
            raise _VideoFormParseError(str(exc)) from exc
    finally:
        await form.close()


class _VideoAssetError(Exception):
    """A video-workflow asset input could not be resolved."""

    def __init__(self, message: str, *, param: str, status: int = 400, code: str | None = None):
        super().__init__(message)
        self.param = param
        self.status = status
        self.code = code


def _video_asset_error_response(exc: "_VideoAssetError") -> Response:
    error: dict[str, Any] = {
        "message": str(exc),
        "type": "invalid_request_error" if exc.status < 500 else "api_error",
        "param": exc.param,
    }
    if exc.code:
        error["code"] = exc.code
    return Response(content=json.dumps({"error": error}), status_code=exc.status, media_type="application/json")


async def _load_completed_video_bytes(
    video_id: str,
    auth_context: AuthContext | None,
) -> tuple[bytes, str]:
    """Return (mp4 bytes, filename) of a completed gateway video the caller owns.

    Mirrors proxy_comfy_video_content's ownership gate: a tracked job must be
    visible to the caller; an untracked id (gateway restarted since submit)
    falls through to ComfyUI's history, as the status route does.
    """
    await _warm_video_owner_keys(auth_context)
    param = "video"
    prompt_id = _prompt_id_from_video_id(video_id)
    if not prompt_id:
        raise _VideoAssetError("invalid video_id", param=param)
    if _video_job_blocked(prompt_id, auth_context):
        raise _VideoAssetError("video_id not found", param=param, status=404)
    headers = configured_downstream_headers(auth_context, "comfyui")
    async with httpx.AsyncClient(timeout=httpx.Timeout(120, connect=10)) as client:
        job = await _comfy_history(client, prompt_id, headers)
        if job is None:
            raise _VideoAssetError("video_id not found", param=param, status=404)
        status, _ = _job_status_from_history(job)
        if status != "succeeded":
            raise _VideoAssetError(
                f"Source video is not completed (status={_openai_video_status(status)})",
                param=param, code="video_not_ready",
            )
        file_info = _extract_video_output(job)
        if not file_info:
            raise _VideoAssetError("Source video has no output", param=param, status=404)
        params = {"filename": file_info["filename"], "type": file_info["type"]}
        if file_info["subfolder"]:
            params["subfolder"] = file_info["subfolder"]
        async with client.stream(
            "GET", f"{COMFY_HOST}/view",
            headers={**headers, "accept-encoding": "identity"}, params=params,
        ) as view:
            if view.status_code != 200:
                raise _VideoAssetError(f"ComfyUI /view error: {view.status_code}", param=param, status=502)
            try:
                data = await media_fetch.read_bounded_media_response(view)
            except media_fetch.MediaFetchError as exc:
                raise _VideoAssetError(str(exc), param=param) from exc
            return data, Path(file_info["filename"]).name


def _asset_reference_video_id(value: Any) -> str | None:
    if isinstance(value, Mapping):
        candidate = value.get("video_id") or value.get("id")
        return candidate.strip() if isinstance(candidate, str) and candidate.strip() else None
    if isinstance(value, str) and value.strip().startswith(VIDEO_ID_PREFIX):
        return value.strip()
    return None


async def _resolve_video_workflow_asset(
    value: Any,
    *,
    kind: str,
    param: str,
    auth_context: AuthContext | None,
    request: Request | None = None,
) -> tuple[bytes, str, str]:
    """Resolve one workflow asset to (bytes, filename, content_type).

    Accepted values: a gateway video id (`video_...` or `{"video_id": ...}`,
    video inputs only), an `asset_id` (images only), an http(s) URL, a data:
    URI, or a base64 string.
    """
    if kind == "video":
        video_id = _asset_reference_video_id(value)
        if video_id:
            try:
                data, name = await _load_completed_video_bytes(video_id, auth_context)
            except _VideoAssetError as exc:
                raise _VideoAssetError(str(exc), param=param, status=exc.status, code=exc.code) from exc
            return data, name, "video/mp4"
        if isinstance(value, Mapping):
            value = value.get("url") or value.get("data")
        if isinstance(value, str) and value.startswith(_DATA_URI_PREFIX):
            header, _, b64 = value.partition(",")
            mime = header[len(_DATA_URI_PREFIX):].split(";", 1)[0].strip().lower()
            if not mime.startswith("video/"):
                raise _VideoAssetError(f"{param} data URI must be video/*, got {mime or 'no type'}", param=param)
            try:
                data = base64.b64decode(b64, validate=False)
            except Exception as exc:
                raise _VideoAssetError(f"{param} is not valid base64: {exc}", param=param) from exc
            return data, f"source{video_inputs.suffix_for_video(None, mime)}", mime
        if not isinstance(value, str) or not value.strip().startswith(("http://", "https://")):
            raise _VideoAssetError(
                f"{param} must be a video id, an http(s) URL, or a video/* data URI",
                param=param,
            )
        try:
            fetched = await _fetch_media_url(value.strip(), auth_context, request=request)
        except Exception as exc:
            raise _VideoAssetError(f"failed to download {param}: {exc}", param=param) from exc
        mime = fetched.content_type if fetched.content_type != "application/octet-stream" else "video/mp4"
        return fetched.data, f"source{video_inputs.suffix_for_video(fetched.filename, mime)}", mime
    try:
        data, name = await _resolve_input_reference(value, auth_context, request=request)
    except _InputReferenceError as exc:
        raise _VideoAssetError(f"{param}: {exc}", param=param) from exc
    suffix = Path(name).suffix.lower()
    mime = {".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp", ".gif": "image/gif"}.get(suffix, "image/png")
    return data, name, mime


async def _resolve_video_workflow_assets(
    body: Mapping[str, Any],
    manifest: Mapping[str, Any],
    workflow_cfg: Mapping[str, Any],
    auth_context: AuthContext | None,
    *,
    request: Request | None = None,
) -> tuple[dict[str, tuple[bytes, str, str]], "video_inputs.VideoProbe | None"]:
    """Resolve every asset extension input a request supplied, and probe the source video.

    Nothing is uploaded to ComfyUI here, so a request that fails validation
    later leaves no files behind in ComfyUI's input directory.
    """
    block = (body.get("extensions") or {}).get(WORKFLOW_EXTENSION_NAMESPACE) or {}
    if not isinstance(block, Mapping):
        raise _VideoAssetError("extensions must be a mapping", param="extensions")
    specs = manifest.get("inputs") or {}
    binding_map = (((manifest.get("bindings") or {}).get("comfyui") or {}).get("map")) or {}
    source_input = workflow_cfg.get("source_video_input")
    ext_param = f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}"
    if source_input and source_input not in block:
        raise _VideoAssetError(
            f"{source_input} is required for this model: pass a video id, URL or data URI",
            param=f"{ext_param}.{source_input}",
        )
    for name, spec in specs.items():
        if (
            isinstance(spec, Mapping)
            and spec.get("type") == "asset"
            and spec.get("required")
            and name in binding_map
            and name not in block
        ):
            raise _VideoAssetError(
                f"{name} is required for this model", param=f"{ext_param}.{name}"
            )
    assets: dict[str, tuple[bytes, str, str]] = {}
    for name, value in block.items():
        spec = specs.get(name)
        if not isinstance(spec, Mapping) or spec.get("type") != "asset" or name not in binding_map:
            continue
        kind = "video" if name == source_input else "image"
        data, filename, mime = await _resolve_video_workflow_asset(
            value, kind=kind, param=f"{ext_param}.{name}", auth_context=auth_context, request=request,
        )
        if not data:
            raise _VideoAssetError(f"{name} is empty", param=f"{ext_param}.{name}")
        if len(data) > video_inputs.MAX_SOURCE_VIDEO_BYTES:
            raise _VideoAssetError(f"{name} is larger than the {video_inputs.MAX_SOURCE_VIDEO_BYTES >> 20} MB limit", param=f"{ext_param}.{name}")
        assets[name] = (data, filename, mime)
    probe = None
    if source_input and source_input in assets:
        data, filename, mime = assets[source_input]
        probe = await asyncio.to_thread(
            video_inputs.probe_video,
            data,
            video_inputs.suffix_for_video(filename, mime),
            workdir=Path(__file__).parent / "cache" / "video_inputs",
        )
        if probe is None and shutil.which("ffprobe") is not None:
            raise _VideoAssetError(
                f"{source_input} is not a readable video", param=f"{ext_param}.{source_input}"
            )
    return assets, probe


async def _upload_video_workflow_assets(
    body: Mapping[str, Any],
    assets: Mapping[str, tuple[bytes, str, str]],
    auth_context: AuthContext | None,
) -> tuple[dict[str, Any], Response | None]:
    """Upload resolved assets to ComfyUI's input dir; return the body with filenames."""
    updated = dict(body)
    extensions = dict(updated.get("extensions") or {})
    block = dict(extensions.get(WORKFLOW_EXTENSION_NAMESPACE) or {})
    headers = configured_downstream_headers(auth_context, "comfyui")
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(120, connect=10)) as client:
            for name, (data, filename, mime) in assets.items():
                resp = await client.post(
                    f"{COMFY_HOST}/upload/image",
                    headers=headers,
                    files={"image": (filename, data, mime)},
                )
                uploaded = resp.json().get("name") if resp.status_code == 200 else None
                if not uploaded:
                    return updated, Response(
                        content=json.dumps({"error": {
                            "message": f"ComfyUI upload failed for {name}: {resp.text[:200]}",
                            "type": "api_error",
                        }}),
                        status_code=502,
                        media_type="application/json",
                    )
                block[name] = str(uploaded)
    except httpx.HTTPError as exc:
        return updated, Response(
            content=json.dumps({"error": {"message": f"Asset upload failed: {exc}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json",
        )
    extensions[WORKFLOW_EXTENSION_NAMESPACE] = block
    updated["extensions"] = extensions
    return updated, None


async def _submit_video_graph(
    *,
    workflow: dict[str, Any],
    auth_context: AuthContext,
    workflow_name: str,
    requested_model: Any,
    public_model: str,
    prompt: str,
    width: int,
    height: int,
    length: int,
    seed_val: int,
    seconds_val: float,
    actual_seconds: float,
    remixed_from_video_id: str | None,
    duration_adjustment_reason: str | None,
    record_extra: Mapping[str, Any] | None = None,
    payload_extra: Mapping[str, Any] | None = None,
    progress_units: list[dict[str, str]] | None = None,
) -> Response:
    """Queue `workflow` on ComfyUI, record the job, and return the video resource.

    Shared by POST /v1/videos (template workflows) and the long-video chain
    (extensions, storyboards, long `seconds`). `record_extra` and `payload_extra`
    add fields to the stored record and to the response. `progress_units` names
    the per-segment sampler/decode nodes so progress spans the whole chain.
    """
    headers = configured_downstream_headers(auth_context, "comfyui")
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(30, connect=10)) as client:
            admission = _dispatch_admission_response(
                "video.generate", auth_context=auth_context, service_id="comfyui",
                service_available=COMFY_ENABLED, resource_class="video", queue_key=_MEDIA_JOB_QUEUE_KEY,
            )
            if admission is not None:
                return admission
            # client_id routes ws events for this submission to our listener.
            resp = await client.post(
                f"{COMFY_HOST}/prompt",
                headers=headers,
                json=_build_comfy_submit_payload(workflow, client_id=COMFY_CLIENT_ID),
            )
            if resp.status_code != 200:
                # Do NOT record _video_progress here: no prompt_id means there
                # is nothing to reconcile against, and a partial entry would
                # leak as a stale "running" job. Surface the error instead.
                return Response(
                    content=json.dumps({"error": {"message": f"ComfyUI error: {resp.text[:500]}", "type": "api_error"}}),
                    status_code=502,
                    media_type="application/json"
                )
            try:
                result = resp.json()
            except Exception:
                result = {}
            prompt_id = result.get("prompt_id") if isinstance(result, dict) else None
            if not prompt_id or not isinstance(prompt_id, str):
                # Same rationale: never seed _video_progress without a valid
                # prompt_id from ComfyUI, otherwise the entry can never be
                # reconciled and will show forever as a phantom job.
                return Response(
                    content=json.dumps({"error": {"message": "No prompt_id returned", "type": "api_error"}}),
                    status_code=502,
                    media_type="application/json"
                )

            # Seed progress state so /v1/videos/{id} can phase-classify nodes
            # by class type before any ws events arrive.
            try:
                async with _video_progress_lock:
                    _video_workflows[prompt_id] = workflow
                    if progress_units:
                        _video_chain_units[prompt_id] = progress_units
                    _video_progress.setdefault(prompt_id, {
                        "status": "queued",
                        "percent": 0,
                        "step": 0,
                        "total": 0,
                        "node": None,
                        "node_class": None,
                        "phase": "encoding",
                        "error": None,
                        "updated_at": time.time(),
                    })
            except Exception:
                pass

            video_id = _video_id_from_prompt_id(prompt_id)
            print(
                f"[proxy] Video job submitted: workflow={workflow_name} id={video_id} "
                f"size={width}x{height} length={length} seed={seed_val}",
                flush=True,
            )

            # Firehose: capture submit metadata (alias, size, seconds, key) for
            # the live-video-job panel and the activity timeline.
            try:
                key_name_for_event = (
                    auth_context.identity.name
                    if auth_context and getattr(auth_context, "identity", None)
                    else None
                )
                firehose_metrics.capture_video_submit(
                    prompt_id,
                    alias=requested_model,
                    workflow=workflow_name,
                    size=f"{width}x{height}",
                    seconds=seconds_val,
                    key_name=key_name_for_event,
                )
                firehose_metrics.record_event(
                    "video_submit",
                    f"{requested_model} · {width}x{height} · {seconds_val:g}s",
                    prompt_id=prompt_id,
                    alias=requested_model,
                    workflow=workflow_name,
                    size=f"{width}x{height}",
                    seconds=seconds_val,
                    key=key_name_for_event,
                )
            except Exception:
                pass

            now = int(time.time())
            response_headers = {}
            if duration_adjustment_reason is not None:
                response_headers["X-Duration-Adjusted"] = (
                    f"requested={seconds_val:g} actual={actual_seconds:.4f} "
                    f"reason={duration_adjustment_reason}"
                )
            # `object` and `seconds` are typed against the OpenAI Python SDK's
            # `Video` model (object: Literal["video"], seconds: Union[str, ...]).
            # Sending a string keeps the SDK's loose-construct parser happy
            # across SDK versions; the precise float lives in `actual_seconds`.
            seconds_str = str(int(seconds_val)) if float(seconds_val).is_integer() else str(seconds_val)
            # Submit-time metadata for GET /v1/videos (list) and DELETE
            # /v1/videos/{id} -- see _video_job_records' own docstring for why
            # this can't just be read back from ComfyUI's /history.
            try:
                async with _video_progress_lock:
                    _video_job_records[prompt_id] = {
                        "model": public_model,
                        "resolved_model": workflow_name,
                        "size": f"{width}x{height}",
                        "seconds": seconds_str,
                        "actual_seconds": round(actual_seconds, 4),
                        "created_at": now,
                        "completed_at": None,
                        "expires_at": now + 86400,
                        "error": None,
                        "remixed_from_video_id": remixed_from_video_id,
                        # Delivery control from the submit request (None = use profile default).
                        "metadata_mode": (media_delivery.current().requested_mode if media_delivery.current() else None),
                        "provenance": provenance.build_provenance_record(
                            kind="video",
                            requested_model=public_model,
                            resolved_model=workflow_name,
                            workflow_id=f"video.generate.{workflow_name}",
                            backend="comfyui",
                            seed=seed_val,
                            parameters={
                                **(media_delivery.current().parameters if media_delivery.current() else {}),
                                "size": f"{width}x{height}",
                                "seconds": seconds_str,
                                "actual_seconds": round(actual_seconds, 4),
                                "length_frames": length,
                            },
                            request_id=video_id,
                            created_at=now,
                        ),
                        **(record_extra or {}),
                        # Owner scoping for GET/list/DELETE/content -- mirrors
                        # _asset_owner_key's existing image/audio asset model.
                        "app_profile": plan_ref(auth_context.identity),
                        "app_id": auth_context.identity.app_id if auth_context.identity else None,
                        "person_id": _auth_person_id(auth_context),
                        "api_key_name": auth_context.identity.name if auth_context.identity else None,
                        "owner_key_hash": _asset_owner_key(auth_context),
                        "deleted_at": None,
                    }
                _persist_video_record(prompt_id)
                context = media_delivery.current()
                memory = context.prompt_decision if context is not None else None
                if memory is not None and memory.keep and context.prompt_text:
                    saved = await asyncio.to_thread(prompt_memory.safe_put,
                        f"video_{prompt_id}", memory.person_id, context.prompt_text,
                        kept_until=memory.kept_until, admin_path=ADMIN_STORE.path,
                        created_at=memory.created_at,
                    )
                    if not saved:
                        context.prompt_decision = prompt_memory.Decision(memory.person_id, False, "storage_failed")
            except Exception:
                pass
            immediate_prompt = _tracked_video_fields(prompt_id, auth_context).get("prompt")
            context = media_delivery.current()
            memory = context.prompt_decision if context is not None else None
            if (_auth_person_id(auth_context) is None and (memory is None or memory.reason == "no_person")
                    and not prompt_memory.household_settings(admin_path=ADMIN_STORE.path)["never_keep"]):
                # Echo this caller's input only in the create response. It is
                # never retained in the job record or exposed by later reads.
                immediate_prompt = prompt
            payload = {
                "id": video_id,
                "object": "video",
                "model": public_model,
                "azizam_resolved_model": workflow_name,
                "status": "queued",
                "progress": 0,
                "created_at": now,
                "completed_at": None,
                "expires_at": now + 86400,
                "prompt": immediate_prompt,
                "remixed_from_video_id": remixed_from_video_id,
                "error": None,
                "size": f"{width}x{height}",
                "seconds": seconds_str,
                "actual_seconds": round(actual_seconds, 4),
                **(payload_extra or {}),
            }
            return Response(
                content=json.dumps(payload),
                status_code=200,
                media_type="application/json",
                headers=response_headers,
            )

    except httpx.ConnectError:
        return Response(
            content=json.dumps({"error": {"message": f"ComfyUI unavailable at {COMFY_HOST}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )
    except Exception as e:
        return Response(
            content=json.dumps({"error": {"message": f"Video submit error: {str(e)}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )


async def proxy_comfy_video_create(
    request: Request,
    auth_context: AuthContext,
    *,
    body_override: Mapping[str, Any] | None = None,
    remixed_from_video_id: str | None = None,
) -> Response:
    """POST /v1/videos — submit a job and return {video_id, status: queued}.

    `body_override` and `remixed_from_video_id` let the remix routes reuse this
    pipeline with an already-parsed body.
    """
    admission = _dispatch_admission_response(
        'video.generate', auth_context=auth_context, service_id="comfyui",
        service_available=COMFY_ENABLED, resource_class='video', queue_key=_MEDIA_JOB_QUEUE_KEY,
    )
    if admission is not None:
        return admission

    if not COMFY_ENABLED:
        return Response(
            content=json.dumps({"error": {"message": "Video generation not enabled", "type": "service_unavailable"}}),
            status_code=503,
            media_type="application/json"
        )
    service_response = (await asyncio.to_thread(_service_availability_response, "comfyui",
        service_label="ComfyUI",))
    if service_response is not None:
        return service_response

    content_type = request.headers.get("content-type", "")
    if body_override is not None:
        body = dict(body_override)
    elif "multipart/form-data" in content_type or "application/x-www-form-urlencoded" in content_type:
        # openai-python's videos.create always uploads as multipart/form-data so
        # that input_reference can be a binary upload. Normalize the form into
        # the JSON body shape the rest of this handler expects.
        try:
            body = await _read_video_create_form_body(request)
        except _VideoFormParseError as exc:
            return Response(
                content=json.dumps({"error": {
                    "message": str(exc),
                    "type": "invalid_request_error",
                }}),
                status_code=400,
                media_type="application/json",
            )
    else:
        try:
            body = await request.json()
        except Exception:
            return Response(
                content=json.dumps({"error": {"message": "Invalid JSON body", "type": "invalid_request_error"}}),
                status_code=400,
                media_type="application/json"
            )
    unknown_video_fields = detect_unknown_top_level_fields(
        body,
        STANDARD_VIDEO_CREATE_FIELDS,
    )
    if unknown_video_fields:
        first_name, first_reason = next(iter(unknown_video_fields.items()))
        return Response(
            content=json.dumps({"error": {
                "message": first_reason,
                "type": "invalid_request_error",
                "param": first_name,
                "code": "unknown_parameter",
            }}),
            status_code=400,
            media_type="application/json",
        )
    _begin_media_delivery(auth_context)
    metadata_error = _note_media_metadata_body(body)
    if metadata_error is not None:
        return metadata_error

    raw_prompt = body.get("prompt")
    if raw_prompt is not None and not isinstance(raw_prompt, str):
        return Response(
            content=json.dumps({"error": {
                "message": "prompt must be a string",
                "type": "invalid_request_error",
                "param": "prompt",
            }}),
            status_code=400,
            media_type="application/json",
        )
    prompt = (raw_prompt or "").strip()
    requested_model = body.get("model") or VIDEO_DEFAULT_WORKFLOW
    public_model = str(requested_model)
    size_from_body = body.get("size")
    seconds = body.get("seconds")
    seed = body.get("seed")
    input_reference = body.get("input_reference")  # optional path / URL / data-URI / raw b64 (I2V)
    image_strength = body.get("image_strength")  # optional float 0..1, default 1.0 when input_reference present

    if not prompt and body.get("shots") is None:
        return Response(
            content=json.dumps({"error": {"message": "prompt is required", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )

    # OpenAI-compat: rewrite sora-* aliases to the local default before workflow lookup.
    try:
        model_resolution = resolve_model_for_operation("videos", requested_model)
    except ModelCompatibilityError as e:
        return model_compatibility_error(e)
    if model_resolution.is_openai_alias:
        print(
            f"[proxy] Video model alias {requested_model} -> {model_resolution.effective_model}",
            flush=True,
        )
        requested_model = model_resolution.effective_model

    workflow_name, workflow_cfg = _resolve_video_workflow(requested_model)
    if not workflow_cfg:
        return model_compatibility_error(
            ModelCompatibilityError(
                f"Model '{requested_model}' is not available for video generation.",
                code="model_not_found",
            )
        )
    # Some models ship separate text-to-video and image-to-video graphs (LTX-2.5,
    # MiniMax H3). `i2v_workflow` on the t2v entry names the image variant; it
    # is selected when the request carries input_reference.
    i2v_workflow_name = workflow_cfg.get("i2v_workflow")
    if input_reference and i2v_workflow_name:
        i2v_cfg = VIDEO_WORKFLOWS.get(i2v_workflow_name)
        if i2v_cfg:
            workflow_name, workflow_cfg = i2v_workflow_name, i2v_cfg
    if workflow_cfg.get("requires_input_reference") and not input_reference:
        return Response(
            content=json.dumps({"error": {
                "message": f"Model {workflow_name} is image-to-video and requires input_reference",
                "type": "invalid_request_error",
                "param": "input_reference",
            }}),
            status_code=400,
            media_type="application/json",
        )
    # Long video: `shots`, or `seconds` past the model's native length when the
    # model names a chain workflow, or a chain workflow itself (video-long).
    chain_name = chain_cfg = None
    if video_extend.engine_for(workflow_cfg.get("builder")):
        chain_name, chain_cfg = workflow_name, workflow_cfg
    else:
        try:
            beyond_native = seconds is not None and float(seconds) > float(workflow_cfg.get("max_seconds", 8))
        except (TypeError, ValueError):
            beyond_native = False
        if body.get("shots") is not None or (beyond_native and workflow_cfg.get("chain_workflow")):
            chain_name, chain_cfg = _chain_workflow_for(requested_model)
            if chain_cfg is None:
                return _json_error(
                    400, f"Model {workflow_name} cannot render shots or clips longer than "
                    f"{workflow_cfg.get('max_seconds', 8):g} s; use video-long, ltx-2.5-long or minimax-h3",
                    param="shots" if body.get("shots") is not None else "seconds",
                    code="long_video_not_supported")
    if chain_cfg is not None:
        return await _submit_video_chain(
            request, auth_context, body=body, workflow_name=str(chain_name),
            requested_model=requested_model, public_model=public_model)
    policy_decision = evaluate_and_apply(
        auth_context.identity,
        make_policy_request(
            protocol="openai.video",
            intent=INTENT_VIDEO_GENERATE,
            model=str(requested_model) if requested_model is not None else None,
            workflow=f"video.generate.{workflow_name}",
            backend="comfyui",
            capability_exposure="default",
            capability_trust_tier="stable",
            capability_resource_tier="expensive",
        ),
    )
    if policy_decision.denied:
        return _policy_denied_response(policy_decision)
    target_decision = _workflow_target_policy_decision(
        auth_context,
        requested=str(requested_model) if requested_model is not None else None,
        resolved=str(workflow_name),
        extra_ids=(f"video.generate.{workflow_name}",),
    )
    if target_decision is not None and target_decision.denied:
        return _policy_denied_response(target_decision)

    workflow_template = _load_video_workflow_file(workflow_cfg)
    if workflow_template is None:
        return Response(
            content=json.dumps({"error": {"message": f"Workflow file missing for {workflow_name}", "type": "api_error"}}),
            status_code=500,
            media_type="application/json"
        )

    # Video-conditioned workflows (remix, character replace) take a source video
    # as an extension input. Resolve and probe it now: its frame rate and length
    # decide the frame count below. Upload happens later, after validation.
    staged_assets: dict[str, tuple[bytes, str, str]] = {}
    source_probe = None
    video_manifest = None
    if workflow_cfg.get("requires_extensions"):
        try:
            video_manifest = _find_video_manifest(str(workflow_name), workflow_cfg)
        except ManifestError as e:
            return Response(
                content=json.dumps({"error": {"message": str(e), "type": "api_error"}}),
                status_code=500,
                media_type="application/json",
            )
        if video_manifest is None:
            return Response(
                content=json.dumps({"error": {
                    "message": f"Workflow {workflow_name} does not have a video workflow manifest",
                    "type": "api_error",
                    "code": "workflow_manifest_missing",
                }}),
                status_code=500,
                media_type="application/json",
            )
        try:
            body = merge_workflow_inputs(body)
            ext_block = (body.get("extensions") or {}).get(WORKFLOW_EXTENSION_NAMESPACE)
            if isinstance(ext_block, Mapping):
                body["extensions"] = {
                    **body["extensions"],
                    WORKFLOW_EXTENSION_NAMESPACE: video_inputs.coerce_form_scalars(
                        ext_block, video_manifest.get("inputs") or {}
                    ),
                }
            staged_assets, source_probe = await _resolve_video_workflow_assets(
                body, video_manifest, workflow_cfg, auth_context, request=request,
            )
        except ExtensionError as e:
            return Response(
                content=json.dumps({"error": {
                    "message": str(e),
                    "type": "invalid_request_error",
                    "code": "invalid_workflow_extension",
                }}),
                status_code=400,
                media_type="application/json",
            )
        except _VideoAssetError as e:
            return _video_asset_error_response(e)

    # Validate / clamp request inputs.
    max_seconds = float(workflow_cfg.get("max_seconds", 8))
    min_seconds = float(workflow_cfg.get("min_seconds", 1))
    source_fps = source_probe.fps if source_probe is not None else None
    source_seconds = (
        source_probe.frames / source_probe.fps if source_probe is not None else None
    )
    try:
        if seconds is not None:
            seconds_val = float(seconds)
        elif source_seconds is not None:
            # No seconds given: keep the source's length, up to the workflow default.
            seconds_val = min(
                float(workflow_cfg.get("default_seconds", max_seconds)),
                max_seconds,
                source_seconds,
            )
        else:
            seconds_val = min(5.0, max_seconds)
    except (TypeError, ValueError):
        return Response(
            content=json.dumps({"error": {"message": "seconds must be a number", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    if seconds_val < min_seconds or seconds_val > max_seconds:
        return Response(
            content=json.dumps({
                "error": {
                    "message": (
                        f"seconds must be between {min_seconds} and {max_seconds} for model {workflow_name}"
                    ),
                    "type": "invalid_request_error",
                }
            }),
            status_code=400,
            media_type="application/json"
        )

    if source_seconds is not None and seconds_val > source_seconds + 0.05:
        return Response(
            content=json.dumps({
                "error": {
                    "message": (
                        f"seconds ({seconds_val:g}) is longer than the source video "
                        f"({source_seconds:.2f} s)"
                    ),
                    "type": "invalid_request_error",
                    "param": "seconds",
                }
            }),
            status_code=400,
            media_type="application/json",
        )

    size = size_from_body or workflow_cfg.get("default_size") or "1280x720"
    width, height = _parse_size_clamped(
        size,
        workflow_cfg.get("max_size", "1280x720"),
        int(workflow_cfg.get("size_multiple", 32)),
    )
    # The output keeps the source clip's frame rate for video-conditioned workflows.
    frame_rate = float(source_fps or workflow_cfg.get("frame_rate", 25))
    # Frame count must be step*k+offset (LTX: 8k+1; MiniMax H3: 17k+5; Wan: 4k+1).
    length_step = int(workflow_cfg.get("length_step", 8))
    length = _seconds_to_length(
        seconds_val,
        frame_rate,
        step=length_step,
        offset=int(workflow_cfg.get("length_offset", 1)),
    )
    if source_probe is not None or workflow_cfg.get("max_length"):
        # Never ask for more frames than the source has, or than the model was tested at.
        cap = int(workflow_cfg["max_length"]) if workflow_cfg.get("max_length") else None
        length = video_inputs.snap_length_down(
            length,
            step=length_step,
            offset=int(workflow_cfg.get("length_offset", 1)),
            available=min(
                [v for v in (cap, source_probe.frames if source_probe is not None else None) if v]
                or [length]
            ),
        )
    # `actual_seconds` is what the rendered mp4 will actually contain (within
    # codec/container rounding). It starts as the LTX 8N+1-snapped duration for
    # short workflows; long-form overrides this further down.
    actual_seconds = length / frame_rate
    duration_adjustment_reason = None

    # Inject parameters into a deep copy of the workflow.
    workflow = copy.deepcopy(workflow_template)
    meta = workflow.pop("_meta", {})

    prompt_node = meta.get("prompt_node")
    neg_node = meta.get("negative_prompt_node")
    size_node = meta.get("size_node")
    # length_node must be explicit. Falling back to size_node is unsafe because
    # source-of-truth Primitive width/height nodes use the same `value` key as a
    # PrimitiveInt length node, so the size value would be overwritten by length.
    # Workflows that don't drive length per-request (e.g. long-form chunked loops
    # that compute it from chunk_seconds) should leave length_node unset.
    length_node = meta.get("length_node")
    seed_node = meta.get("seed_node")
    fr_node = meta.get("frame_rate_node")

    if prompt_node and prompt_node in workflow:
        # `prompt_field` names the text input when it is not CLIPTextEncode's `text`
        # (MiniMax H3's conditioning node takes `prompt`).
        workflow[prompt_node]["inputs"][meta.get("prompt_field", "text")] = prompt

    # negative prompt left at template default unless body overrides
    negative_prompt = body.get("negative_prompt")
    if negative_prompt and neg_node and neg_node in workflow:
        workflow[neg_node]["inputs"]["text"] = negative_prompt

    # Helpers to accept either a single node id or a list of node ids in _meta.
    # Some workflows have a single source-of-truth Primitive node feeding many
    # consumers; others spread the field across consumer nodes directly. Accept
    # both so workflow JSONs can stay close to ComfyUI's native format.
    def _as_list(v):
        if v is None:
            return []
        return list(v) if isinstance(v, (list, tuple)) else [v]

    def _set_field(node_id, candidate_keys, value):
        if not node_id or node_id not in workflow:
            return False
        inputs = workflow[node_id].get("inputs", {})
        for k in candidate_keys:
            if k in inputs:
                inputs[k] = value
                return True
        return False

    # size_node forms supported:
    #   "7"                   -> single node with both width/height keys (e.g. EmptyLatentImage)
    #   ["W_NID", "H_NID"]    -> two separate INTConstant/PrimitiveInt source nodes; index 0 is
    #                            width, index 1 is height. Each takes a single `value` key.
    #   width_node/height_node in _meta override the list/single behavior.
    width_node = meta.get("width_node")
    height_node = meta.get("height_node")
    size_list = _as_list(size_node)
    if width_node is None and isinstance(size_node, (list, tuple)) and len(size_list) >= 2:
        width_node = size_list[0]
        height_node = size_list[1]
    if width_node is not None or height_node is not None:
        if width_node:
            _set_field(width_node, ["width", "value"], width)
        if height_node:
            _set_field(height_node, ["height", "value"], height)
    else:
        for nid in size_list:
            _set_field(nid, ["width"], width)
            _set_field(nid, ["height"], height)

    # length_node: also accept "value" (PrimitiveInt source-of-truth pattern)
    # and "frames_number" (LTXVEmptyLatentAudio variant). length_nodes (plural)
    # in _meta is honored too for fan-out when multiple consumers need the same
    # length without a Primitive node.
    length_targets = _as_list(meta.get("length_nodes")) or _as_list(length_node)
    for nid in length_targets:
        _set_field(nid, ["length", "value", "frames_number"], length)
    if length_targets and abs(actual_seconds - seconds_val) > 0.05:
        # 8N+1 LTX latent stride => ~0.333s granularity at fps=24. Surface it.
        duration_adjustment_reason = (
            "ltx_latent_8np1_stride" if length_step == 8 else "frame_count_stride"
        )

    # Remix workflows slice the source clip; keep half a frame of slack past `length`.
    for nid in _as_list(meta.get("duration_node")):
        _set_field(nid, ["duration"], round((length + 0.5) / frame_rate, 4))

    fr_targets = _as_list(meta.get("frame_rate_nodes")) or _as_list(fr_node)
    for nid in fr_targets:
        _set_field(nid, ["frame_rate", "value"], frame_rate)

    try:
        seed_val = int(seed) if seed is not None else random.randint(0, 2**32 - 1)
    except (TypeError, ValueError):
        seed_val = random.randint(0, 2**32 - 1)
    seed_targets = _as_list(meta.get("seed_nodes")) or _as_list(seed_node)
    for nid in seed_targets:
        # `value` covers INTConstant nodes used as a shared seed source that
        # downstream RandomNoise/Math nodes derive from. Without `value` the seed silently
        # never reaches the graph and ComfyUI's full-graph cache returns
        # byte-identical mp4s for repeat prompts.
        _set_field(nid, ["noise_seed", "seed", "value"], seed_val)

    # I2V: when input_reference is supplied, resolve to bytes, upload to ComfyUI,
    # and wire it into the workflow via the keys exposed in _meta.
    #
    # Workflow contract (uniform across aliases — Option A: one workflow per alias
    # handles both T2V and I2V):
    #   * `image_node`: LoadImage node id whose `image` field gets set to the
    #     uploaded filename. Fields: ["image"].
    #   * `image_strength_node` (LTX): PrimitiveFloat node id whose `value`
    #     field gates conditioning strength. 0.0 = pure T2V passthrough,
    #     1.0 = first frame pinned to the image. Fields: ["value"].
    #   * `image_target_node` + `image_target_field` (Wan): conditional wiring
    #     mode. The proxy sets `inputs[<field>] = [image_node, 0]` to enable
    #     I2V; absent for T2V (lets the I2V latent node fall through its
    #     start_image=None T2V branch). No strength knob on Wan.
    #
    # T2V path: leave image_strength_node at 0.0 (LTX) / leave start_image
    # unwired (Wan). The placeholder image stays in the LoadImage field —
    # harmless because the LTX inplace node operates at strength=0 (mask=1.0,
    # full noise) and the Wan LoadImage is orphaned (executor skips it).
    if input_reference:
        # image_node alone is enough: first-frame-only workflows (MiniMax H3) wire the
        # LoadImage output in the graph and have no strength knob.
        if not meta.get("image_node"):
            return Response(
                content=json.dumps({
                    "error": {
                        "message": (
                            f"Workflow {workflow_name} does not support I2V "
                            "(missing _meta.image_node)."
                        ),
                        "type": "invalid_request_error",
                    }
                }),
                status_code=400,
                media_type="application/json"
            )

        try:
            image_bytes, image_filename = await _resolve_input_reference(
                input_reference,
                auth_context,
                request=request,
            )
        except _InputReferenceError as e:
            return Response(
                content=json.dumps({
                    "error": {"message": str(e), "type": "invalid_request_error"}
                }),
                status_code=400,
                media_type="application/json"
            )

        # Upload to ComfyUI's input cache (same endpoint /upload/image used by image-edit).
        upload_headers = configured_downstream_headers(auth_context, "comfyui")
        try:
            async with httpx.AsyncClient(timeout=httpx.Timeout(60, connect=10)) as upload_client:
                files = {"image": (image_filename, image_bytes, "image/png")}
                upload_resp = await upload_client.post(
                    f"{COMFY_HOST}/upload/image",
                    headers=upload_headers,
                    files=files,
                )
        except Exception as e:
            return Response(
                content=json.dumps({
                    "error": {"message": f"Image upload failed: {e}", "type": "api_error"}
                }),
                status_code=502,
                media_type="application/json"
            )
        if upload_resp.status_code != 200:
            return Response(
                content=json.dumps({
                    "error": {
                        "message": f"ComfyUI image upload failed: {upload_resp.text[:300]}",
                        "type": "api_error",
                    }
                }),
                status_code=502,
                media_type="application/json"
            )
        try:
            uploaded_filename = upload_resp.json().get("name")
        except Exception:
            uploaded_filename = None
        if not uploaded_filename:
            return Response(
                content=json.dumps({
                    "error": {"message": "ComfyUI did not return uploaded filename", "type": "api_error"}
                }),
                status_code=502,
                media_type="application/json"
            )
        print(f"[proxy] Video I2V uploaded image: {uploaded_filename}", flush=True)

        # Wire the uploaded filename into the LoadImage node.
        image_node = meta["image_node"]
        if not _set_field(image_node, ["image"], uploaded_filename):
            return Response(
                content=json.dumps({
                    "error": {
                        "message": f"Workflow {workflow_name} image_node {image_node} missing or has no `image` input",
                        "type": "api_error",
                    }
                }),
                status_code=500,
                media_type="application/json"
            )

        # Strength: clamp to [0,1]. Default 1.0 when an image is provided.
        try:
            strength_val = float(
                image_strength if image_strength is not None else meta.get("image_strength_default", 1.0)
            )
        except (TypeError, ValueError):
            strength_val = 1.0
        strength_val = max(0.0, min(1.0, strength_val))

        strength_node = meta.get("image_strength_node")
        if strength_node:
            # LTX: set the PrimitiveFloat that feeds LTXVImgToVideoInplaceKJ.strength_*.
            _set_field(strength_node, ["value"], strength_val)

        target_node = meta.get("image_target_node")
        target_field = meta.get("image_target_field")
        if target_node and target_field:
            # Wan: connect start_image link from image_node into the I2V latent node.
            if target_node in workflow:
                workflow[target_node].setdefault("inputs", {})[target_field] = [image_node, 0]

    if staged_assets:
        body, upload_error = await _upload_video_workflow_assets(body, staged_assets, auth_context)
        if upload_error is not None:
            return upload_error
    _workflow_block = (
        (body.get("extensions") or {}).get(WORKFLOW_EXTENSION_NAMESPACE)
        if isinstance(body.get("extensions"), Mapping)
        else body.get("extensions")
    )
    if isinstance(_workflow_block, Mapping):
        # Gateway-level controls (metadata) are not workflow inputs.
        _workflow_block = {
            k: v for k, v in _workflow_block.items() if k not in provenance.RESERVED_GATEWAY_CONTROLS
        }
    has_workflow_extensions = (
        bool(workflow_cfg.get("requires_extensions")) or bool(body.get("inputs")) or bool(_workflow_block)
    )
    if has_workflow_extensions:
        try:
            manifest = video_manifest or _find_video_manifest(str(workflow_name), workflow_cfg)
            if manifest is None:
                return Response(
                    content=json.dumps({"error": {
                        "message": f"Workflow {workflow_name} does not have a video workflow manifest",
                        "type": "invalid_request_error",
                        "code": "workflow_manifest_missing",
                    }}),
                    status_code=400,
                    media_type="application/json",
                )
            extension_binding = bind_video_workflow_extensions(
                body,
                manifest,
                workflow,
            )
        except (ExtensionError, ManifestError) as e:
            return Response(
                content=json.dumps({"error": {
                    "message": str(e),
                    "type": "invalid_request_error",
                    "code": "invalid_workflow_extension",
                }}),
                status_code=400,
                media_type="application/json",
            )
        if not extension_binding.ok:
            rejected = dict(extension_binding.validation.rejected)
            rejected.update(extension_binding.unknown_top_level)
            first_name, first_reason = next(iter(rejected.items()))
            return Response(
                content=json.dumps({"error": {
                    "message": first_reason,
                    "type": "invalid_request_error",
                    "param": first_name,
                    "code": "invalid_workflow_extension",
                }}),
                status_code=400,
                media_type="application/json",
            )
        workflow = extension_binding.request

    subject_record: dict[str, Any] | None = None
    if workflow_cfg.get("subject_select"):
        # Character replace: pick which person is replaced, and remember how to
        # read how many were tracked once the job is done.
        block = ((body.get("extensions") or {}).get(WORKFLOW_EXTENSION_NAMESPACE) or {})
        try:
            index_text = str(block.get("subject_index", "0")).strip()
            if not re.fullmatch(r"\d+(,\d+)*", index_text):
                raise video_subject.SubjectError(
                    "subject_index must be a number like 0 or a list like 0,2", "subject_index")
            video_subject.apply_point(workflow, block, width, height)
            if block.get("reference_fit", True) not in (False, "false", "False", 0):
                video_subject.add_reference_fit(workflow)
        except video_subject.SubjectError as exc:
            return _json_error(400, str(exc), param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{exc.param}",
                               code="invalid_workflow_extension")
        subject_record = {
            "probe_node": video_subject.PROBE_NODE,
            "explicit": video_subject.explicit_selection(block),
            "subject": str(block.get("source_subject") or "person"),
        }

    return await _submit_video_graph(
        record_extra={"subject": subject_record} if subject_record else None,
        workflow=workflow,
        auth_context=auth_context,
        workflow_name=workflow_name,
        requested_model=requested_model,
        public_model=public_model,
        prompt=prompt,
        width=width,
        height=height,
        length=length,
        seed_val=seed_val,
        seconds_val=seconds_val,
        actual_seconds=actual_seconds,
        remixed_from_video_id=remixed_from_video_id,
        duration_adjustment_reason=duration_adjustment_reason,
    )



# =============================================================================
# Long video: extensions, storyboards, long `seconds`
# =============================================================================
#
# One request makes one ComfyUI prompt (gateway/video_extend.py builds it). The
# video id is that prompt's id, so status, content, list, delete, ownership and
# the persisted record work as for any other video. A failure fails the whole
# job; the error names the segment that failed and how many were finished.

_CHAIN_MAX_SHOTS = 12
_CHAIN_MAX_TEXT = 8000


def _chain_workflow_for(requested_model: Any) -> tuple[str | None, dict | None]:
    """Return (name, cfg) of the chain workflow a model name leads to, if any.

    A chain workflow has a `builder` that names a continuity engine
    (`video_extend.ENGINES`: `ltx25_chain`, `h3_chain`). A template workflow can
    name one with `chain_workflow` (LTX-2.5 and MiniMax H3 t2v/i2v do: past their
    native length they become a chain).
    """
    name, cfg = _resolve_video_workflow(str(requested_model or ""))
    if not cfg:
        return None, None
    if video_extend.engine_for(cfg.get("builder")):
        return name, cfg
    target = cfg.get("chain_workflow")
    if target and target in VIDEO_WORKFLOWS and video_extend.engine_for(VIDEO_WORKFLOWS[target].get("builder")):
        return str(target), VIDEO_WORKFLOWS[target]
    return None, None


def _chain_policy_denial(auth_context: AuthContext, requested_model: Any, workflow_name: str) -> Response | None:
    decision = evaluate_and_apply(
        auth_context.identity,
        make_policy_request(
            protocol="openai.video",
            intent=INTENT_VIDEO_GENERATE,
            model=str(requested_model) if requested_model is not None else None,
            workflow=f"video.generate.{workflow_name}",
            backend="comfyui",
            capability_exposure="default",
            capability_trust_tier="stable",
            capability_resource_tier="expensive",
        ),
    )
    if decision.denied:
        return _policy_denied_response(decision)
    target = _workflow_target_policy_decision(
        auth_context,
        requested=str(requested_model) if requested_model is not None else None,
        resolved=str(workflow_name),
        extra_ids=(f"video.generate.{workflow_name}",),
    )
    if target is not None and target.denied:
        return _policy_denied_response(target)
    return None


def _chain_number(value: Any, *, param: str, minimum: float, maximum: float | None = None) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        raise video_extend.PlanError(f"{param} must be a number", code="invalid_value", param=param) from None
    if number != number or number < minimum or (maximum is not None and number > maximum):
        bound = f"between {minimum:g} and {maximum:g}" if maximum is not None else f"at least {minimum:g}"
        raise video_extend.PlanError(f"{param} must be {bound}", code="invalid_value", param=param)
    return number


def _parse_chain_options(body: Mapping[str, Any], engine: video_extend.ChainEngine) -> dict[str, Any]:
    """Read the gateway options: ledger text, context window and strength.

    Which options exist depends on the engine (`engine.option_keys`)."""
    merged = merge_workflow_inputs(body)
    block = (merged.get("extensions") or {}).get(WORKFLOW_EXTENSION_NAMESPACE) or {}
    if not isinstance(block, Mapping):
        raise video_extend.PlanError("extensions must be a mapping", code="invalid_workflow_extension", param="extensions")
    unknown = [
        k for k in block
        if k not in engine.option_keys and k not in provenance.RESERVED_GATEWAY_CONTROLS
    ]
    if unknown:
        raise video_extend.PlanError(
            f"unsupported long-video option {unknown[0]!r}; supported: {', '.join(engine.option_keys)}",
            code="invalid_workflow_extension",
            param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{unknown[0]}",
        )
    options: dict[str, Any] = {}
    ledger = block.get("state_ledger")
    if ledger is not None:
        if not isinstance(ledger, str) or len(ledger) > _CHAIN_MAX_TEXT:
            raise video_extend.PlanError(
                f"state_ledger must be text of at most {_CHAIN_MAX_TEXT} characters",
                code="invalid_value", param="state_ledger",
            )
        options["state_ledger"] = ledger
    context = body.get("context_seconds", block.get("context_seconds"))
    if context is not None:
        options["context_seconds"] = _chain_number(context, param="context_seconds", minimum=0.34, maximum=4.0)
    strength = block.get("context_strength")
    if strength is not None:
        options["context_strength"] = _chain_number(strength, param="context_strength", minimum=0.0, maximum=1.0)
    return options


def _parse_chain_shots(body: Mapping[str, Any], *, default_seconds: float, min_seconds: float) -> list[tuple[str, float]]:
    """Return [(prompt, seconds)] from `shots`, or from `prompt` + `seconds`."""
    shots = body.get("shots")
    if isinstance(shots, str):
        # multipart clients can send the list as a JSON string
        try:
            shots = json.loads(shots)
        except ValueError:
            raise video_extend.PlanError("shots must be a JSON list of {prompt, seconds} objects",
                                         code="invalid_shots", param="shots") from None
    if shots is None:
        prompt = body.get("prompt")
        if not isinstance(prompt, str) or not prompt.strip():
            raise video_extend.PlanError("prompt is required", code="invalid_value", param="prompt")
        seconds = body.get("seconds")
        value = default_seconds if seconds is None else _chain_number(
            seconds, param="seconds", minimum=min_seconds)
        return [(prompt.strip(), value)]
    if not isinstance(shots, list) or not shots or len(shots) > _CHAIN_MAX_SHOTS:
        raise video_extend.PlanError(
            f"shots must be a list of 1 to {_CHAIN_MAX_SHOTS} {{prompt, seconds}} objects",
            code="invalid_shots", param="shots")
    out: list[tuple[str, float]] = []
    for index, shot in enumerate(shots):
        label = f"shots[{index}]"
        if not isinstance(shot, Mapping):
            raise video_extend.PlanError(f"{label} must be an object", code="invalid_shots", param=label)
        prompt = shot.get("prompt")
        if not isinstance(prompt, str) or not prompt.strip():
            raise video_extend.PlanError(f"{label}.prompt is required", code="invalid_shots", param=f"{label}.prompt")
        seconds = _chain_number(
            shot.get("seconds"), param=f"{label}.seconds", minimum=min_seconds)
        out.append((prompt.strip(), seconds))
    given = body.get("seconds")
    if given is not None:
        total = sum(s for _, s in out)
        if abs(_chain_number(given, param="seconds", minimum=0.0) - total) > 0.5:
            raise video_extend.PlanError(
                f"seconds ({given}) does not match the sum of shots[].seconds ({total:g}); "
                "omit seconds when you send shots",
                code="shots_seconds_mismatch", param="seconds")
    return out


async def _upload_comfy_input(data: bytes, filename: str, mime: str, auth_context: AuthContext) -> str:
    """Upload bytes to ComfyUI's input dir. Return the stored file name."""
    headers = configured_downstream_headers(auth_context, "comfyui")
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(120, connect=10)) as client:
            resp = await client.post(f"{COMFY_HOST}/upload/image", headers=headers,
                                     files={"image": (filename, data, mime)})
    except httpx.HTTPError as exc:
        raise _VideoAssetError(f"ComfyUI upload failed: {exc}", status=502) from exc
    name = resp.json().get("name") if resp.status_code == 200 else None
    if not name:
        raise _VideoAssetError(f"ComfyUI upload failed: {resp.text[:200]}", status=502)
    return str(name)


async def _submit_video_chain(
    request: Request,
    auth_context: AuthContext,
    *,
    body: Mapping[str, Any],
    workflow_name: str,
    requested_model: Any,
    public_model: str,
    source: Any = None,
    source_video_id: str | None = None,
) -> Response:
    """Plan, build and queue a long-video chain (create with shots or long
    seconds, or an extension of `source`)."""
    extending = source is not None
    workflow_cfg = VIDEO_WORKFLOWS.get(workflow_name) or {}
    engine = video_extend.engine_for(workflow_cfg.get("builder"))
    try:
        options = _parse_chain_options(body, engine)
        shots = _parse_chain_shots(body, default_seconds=8.0, min_seconds=engine.min_shot_seconds)
        if body.get("inputs"):
            raise video_extend.PlanError(
                "inputs is not supported for long video; use extensions.com.azizam.workflow",
                code="invalid_workflow_extension", param="inputs")
    except video_extend.PlanError as exc:
        return _json_error(400, str(exc), code=exc.code, param=exc.param)
    if extending and body.get("input_reference"):
        return _json_error(400, "input_reference is not supported on extensions; the source video is the context",
                           param="input_reference", code="unsupported_parameter")

    denial = _chain_policy_denial(auth_context, requested_model, workflow_name)
    if denial is not None:
        return denial

    # Source video: resolve, probe, then upload to ComfyUI only after validation.
    probe = None
    source_bytes = None
    source_name = None
    if extending:
        try:
            source_bytes, source_name, _mime = await _resolve_video_workflow_asset(
                source, kind="video", param="video", auth_context=auth_context, request=request)
        except _VideoAssetError as exc:
            return _video_asset_error_response(exc)
        if not source_bytes or len(source_bytes) > video_inputs.MAX_SOURCE_VIDEO_BYTES:
            return _json_error(400, "video is empty or larger than the size limit", param="video")
        probe = await asyncio.to_thread(
            video_inputs.probe_video, source_bytes, video_inputs.suffix_for_video(source_name, _mime),
            workdir=Path(__file__).parent / "cache" / "video_inputs")
        if probe is None:
            return _json_error(400, "video is not a readable video", param="video")

    fps = float(probe.fps) if probe is not None else float(workflow_cfg.get("frame_rate", 24))
    if probe is not None:
        try:
            engine.check_source(fps)
        except video_extend.PlanError as exc:
            return _json_error(400, str(exc), code=exc.code, param=exc.param)
    context_seconds = options.get("context_seconds", video_extend.DEFAULT_CONTEXT_SECONDS)
    tail_frames = engine.tail_frames(context_seconds, fps)
    if probe is not None and probe.frames < tail_frames:
        return _json_error(
            400, f"the source video has {probe.frames} frames; extending needs at least {tail_frames} "
            f"for context_seconds={context_seconds:g}", param="video", code="video_too_short")

    try:
        segments = engine.plan_segments(
            shots, fps=fps, has_source=extending,
            max_segment_seconds=float(workflow_cfg.get("chain_segment_seconds", VIDEO_CHAIN_SEGMENT_SECONDS)),
            state_ledger=options.get("state_ledger"))
    except video_extend.PlanError as exc:
        return _json_error(400, str(exc), code=exc.code, param=exc.param)
    source_frames = probe.frames if probe is not None else 0
    total_seconds = video_extend.total_seconds(segments, fps, source_frames)
    if total_seconds > VIDEO_MAX_TOTAL_SECONDS + 0.05:
        return _json_error(
            400,
            f"total video length would be {total_seconds:.1f} s"
            + (f" ({source_frames / fps:.1f} s source + {total_seconds - source_frames / fps:.1f} s new)" if extending else "")
            + f", over the {VIDEO_MAX_TOTAL_SECONDS:g} s limit (videos.max_total_seconds). "
            "Quality drops with each added segment; finish this video or start a new one.",
            code="video_total_length_exceeded", param="seconds")

    # Size: requested, else the source's, else the workflow default.
    size = body.get("size")
    if not size and probe is not None:
        size = f"{probe.width}x{probe.height}"
    width, height = _parse_size_clamped(
        str(size or workflow_cfg.get("default_size") or "960x512"),
        workflow_cfg.get("max_size", "1280x720"), int(workflow_cfg.get("size_multiple", 32)))

    try:
        seed_val = int(body["seed"]) if body.get("seed") is not None else random.randint(0, 2**32 - 1)
    except (TypeError, ValueError):
        return _json_error(400, "seed must be an integer", param="seed")

    first_frame_image = None
    first_frame_strength = 1.0
    try:
        if source_bytes is not None:
            uploaded = await _upload_comfy_input(
                source_bytes, source_name or "source.mp4", "video/mp4", auth_context)
        if body.get("input_reference"):
            try:
                image_bytes, image_name = await _resolve_input_reference(body["input_reference"], auth_context, request=request)
            except _InputReferenceError as exc:
                return _json_error(400, str(exc), param="input_reference")
            first_frame_image = await _upload_comfy_input(image_bytes, image_name, "image/png", auth_context)
            if body.get("image_strength") is not None:
                try:
                    first_frame_strength = max(0.0, min(1.0, float(body["image_strength"])))
                except (TypeError, ValueError):
                    return _json_error(400, "image_strength must be a number", param="image_strength")
    except _VideoAssetError as exc:
        return _video_asset_error_response(exc)

    spec = video_extend.ChainSpec(
        segments=segments, width=width, height=height, fps=fps, seed=seed_val,
        negative=str(body.get("negative_prompt") or engine.default_negative),
        context_frames=tail_frames,
        context_strength=options.get("context_strength", video_extend.DEFAULT_CONTEXT_STRENGTH),
        source=(video_extend.SourceVideo(uploaded, probe.frames, fps, probe.width, probe.height, probe.has_audio)
                if probe is not None else None),
        first_frame_image=first_frame_image, first_frame_strength=first_frame_strength)
    built = engine.build(spec)
    total_seconds = built.total_frames / fps

    prompt_text = "\n".join(p for p, _ in shots)
    chain_info = {
        "segments": len(segments),
        "segment_frames": [s.frames for s in segments],
        "shots": len(shots),
        "units": built.units,
        "total_frames": built.total_frames,
        "fps": fps,
        "context_seconds": context_seconds,
        "source_frames": source_frames,
    }
    seconds_requested = sum(s for _, s in shots) + source_frames / fps
    reason = engine.stride_reason if abs(total_seconds - seconds_requested) > 0.05 else None
    return await _submit_video_graph(
        workflow=built.graph,
        auth_context=auth_context,
        workflow_name=workflow_name,
        requested_model=requested_model,
        public_model=public_model,
        prompt=prompt_text,
        width=width,
        height=height,
        length=built.total_frames,
        seed_val=seed_val,
        seconds_val=seconds_requested,
        actual_seconds=total_seconds,
        remixed_from_video_id=source_video_id,
        duration_adjustment_reason=reason,
        record_extra={"chain": chain_info, "extended_from_video_id": source_video_id,
                      "seconds": _seconds_text(total_seconds), "total_seconds": round(total_seconds, 3)},
        payload_extra={"extended_from_video_id": source_video_id, "total_seconds": round(total_seconds, 3),
                       "segments": len(segments), "seconds": _seconds_text(total_seconds)},
        progress_units=built.units,
    )


def _seconds_text(value: float) -> str:
    return str(int(value)) if float(value).is_integer() else f"{value:.3f}".rstrip("0").rstrip(".")


async def proxy_comfy_video_extend(request: Request, auth_context: AuthContext) -> Response:
    """POST /v1/videos/extensions -- Sora's extend shape: `{"video": {"id"}, "prompt", "seconds"}`.

    The result is a new video: the source followed by `seconds` of new footage.
    `seconds` on the result is the stitched total. Gateway fields: `context_seconds`
    (overlap window, default 1), `model`, `seed`, `size`, `negative_prompt`, and
    `extensions.com.azizam.workflow.{state_ledger,context_strength}`.
    """
    await _warm_video_owner_keys(auth_context)
    admission = _dispatch_admission_response(
        'video.extend', auth_context=auth_context, service_id="comfyui",
        service_available=COMFY_ENABLED, resource_class='video', queue_key=_MEDIA_JOB_QUEUE_KEY,
    )
    if admission is not None:
        return admission

    if not COMFY_ENABLED:
        return _json_error(503, "Video generation not enabled", kind="service_unavailable")
    service_response = (await asyncio.to_thread(_service_availability_response, "comfyui", service_label="ComfyUI"))
    if service_response is not None:
        return service_response
    if not VIDEO_EXTEND_WORKFLOW:
        return _json_error(
            501, "Video extension is not configured on this gateway. Set videos.extend_workflow "
            "in proxy_config.yml to enable it.", code="video_extend_not_configured")
    try:
        body = await _read_video_request_body(request, id_reference_fields=("video",))
    except _VideoFormParseError as exc:
        return _json_error(400, str(exc))
    _begin_media_delivery(auth_context)
    memory_error = _note_media_metadata_body(body)
    if memory_error is not None:
        return memory_error
    video = body.pop("video", None)
    if video is None:
        return _json_error(400, "video is required: pass {\"id\": \"video_...\"} or upload a file", param="video")
    unknown = detect_unknown_top_level_fields(body, STANDARD_VIDEO_EXTEND_FIELDS)
    if unknown:
        name, reason = next(iter(unknown.items()))
        return _json_error(400, reason, param=name, code="unknown_parameter")
    if body.get("shots") is not None:
        return _json_error(400, "shots is not supported on extensions; call extensions once per shot, "
                           "or send shots to POST /v1/videos", param="shots", code="unsupported_parameter")
    source_id = _asset_reference_video_id(video)
    if source_id:
        prompt_id = _prompt_id_from_video_id(source_id)
        if not prompt_id:
            return _json_error(400, "invalid video id", param="video")
        async with _video_progress_lock:
            if _video_job_blocked(prompt_id, auth_context):
                return _json_error(404, "video_id not found", kind="not_found")
    # Without `model`, a video is extended by the model that made it (when that
    # model can extend), else by the configured default.
    source_model = (
        (_video_job_records.get(_prompt_id_from_video_id(source_id) or "") or {}).get("model")
        if source_id else None)
    requested = body.get("model")
    if not requested:
        requested = source_model if source_model and _chain_workflow_for(source_model)[1] else VIDEO_EXTEND_WORKFLOW
    workflow_name, cfg = _chain_workflow_for(requested)
    if not cfg:
        return _json_error(400, f"model {requested!r} cannot extend videos; use video-long, ltx-2.5-long or minimax-h3",
                           param="model", code="video_extend_not_supported")
    public_model = str(body.get("model") or source_model or "video-long")
    return await _submit_video_chain(
        request, auth_context, body=body, workflow_name=workflow_name,
        requested_model=requested, public_model=public_model,
        source=video, source_video_id=source_id)



async def proxy_comfy_video_status(video_id: str, auth_context: AuthContext) -> Response:
    """GET /v1/videos/{video_id} — poll status."""
    await _warm_video_owner_keys(auth_context)
    if not COMFY_ENABLED:
        return Response(
            content=json.dumps({"error": {"message": "Video generation not enabled", "type": "service_unavailable"}}),
            status_code=503,
            media_type="application/json"
        )
    prompt_id = _prompt_id_from_video_id(video_id)
    if not prompt_id:
        return Response(
            content=json.dumps({"error": {"message": "invalid video_id", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    # Ownership + tombstone gate. Only enforced when we actually have a
    # tracked record for this id -- an id with no record at all (never
    # tracked, or evicted past _video_job_records' own retention) has no
    # owner to check against, so it falls through to the legacy ComfyUI-
    # history lookup below unscoped, same as before this field existed.
    if _video_job_blocked(prompt_id, auth_context):
        return Response(
            content=json.dumps({"error": {"message": "video_id not found", "type": "not_found"}}),
            status_code=404,
            media_type="application/json"
        )

    headers = configured_downstream_headers(auth_context, "comfyui")
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(30, connect=10)) as client:
            job = await _comfy_history(client, prompt_id, headers)
            if job is None:
                # Not in history yet — prefer live ws state, fall back to /queue.
                live = _video_progress_snapshot(prompt_id)
                if live and live.get("status") in ("queued", "running"):
                    internal_status = "running" if live.get("percent", 0) > 0 or live.get("node") else live.get("status", "running")
                    payload = _openai_video_payload(
                        video_id=video_id,
                        prompt_id=prompt_id,
                        auth_context=auth_context,
                        status=internal_status,
                        progress=_video_progress_percent(live.get("percent"), ceiling=99),
                        updated_at=int(live.get("updated_at") or time.time()),
                        step=int(live.get("step") or 0),
                        total=int(live.get("total") or 0),
                        node=live.get("node"),
                        phase=live.get("phase"),
                    )
                    _hold_video_progress(prompt_id, payload)
                    return Response(
                        content=json.dumps(payload),
                        status_code=200,
                        media_type="application/json",
                    )
                queue_status = await _comfy_queue_status(client, prompt_id, headers)
                if queue_status == "unknown":
                    return Response(
                        content=json.dumps({"error": {"message": "video_id not found", "type": "not_found"}}),
                        status_code=404,
                        media_type="application/json"
                    )
                return Response(
                    content=json.dumps(_hold_video_progress(prompt_id, _openai_video_payload(
                        video_id=video_id,
                        prompt_id=prompt_id,
                        auth_context=auth_context,
                        status=queue_status,
                        progress=25 if queue_status == "running" else 0,
                        updated_at=int(time.time()),
                    ))),
                    status_code=200,
                    media_type="application/json"
                )

            sora_status, progress = _job_status_from_history(job)
            await _record_video_job_terminal_timestamp(prompt_id, sora_status)
            # Enrich with last-known live progress if available (e.g. step/total
            # captured during the run). For terminal states, the history wins.
            live = _video_progress_snapshot(prompt_id) or {}
            payload = _openai_video_payload(
                video_id=video_id,
                prompt_id=prompt_id,
                auth_context=auth_context,
                status=sora_status,
                progress=progress,
                updated_at=int(time.time()),
            )
            if sora_status == "running" and live:
                payload["progress"] = max(
                    _video_progress_percent(progress, ceiling=99),
                    _video_progress_percent(live.get("percent"), ceiling=99),
                )
                payload["step"] = int(live.get("step") or 0)
                payload["total"] = int(live.get("total") or 0)
                payload["node"] = live.get("node")
                payload["phase"] = live.get("phase")
            _hold_video_progress(prompt_id, payload)
            if sora_status == "succeeded":
                warnings = _video_job_warnings(_video_job_records.get(prompt_id), job)
                if warnings:
                    payload["azizam_warnings"] = warnings
            if sora_status == "failed":
                payload["error"] = _chain_failure_error(
                    _video_job_records.get(prompt_id), job,
                    _comfy_execution_error_message(job) or "ComfyUI execution_error",
                )
            return Response(
                content=json.dumps(payload),
                status_code=200,
                media_type="application/json"
            )
    except httpx.ConnectError:
        return Response(
            content=json.dumps({"error": {"message": f"ComfyUI unavailable at {COMFY_HOST}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )
    except Exception as e:
        return Response(
            content=json.dumps({"error": {"message": f"Video status error: {str(e)}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )


async def proxy_comfy_video_content(
    video_id: str,
    auth_context: AuthContext,
    *,
    metadata_mode: str = provenance.METADATA_FULL,
    index_library: bool = True,
) -> Response:
    """GET /v1/videos/{video_id}/content — return mp4 bytes.

    Full delivery requires a retained maker prompt record. Cached asset bytes
    are stripped before storage.
    """
    await _warm_video_owner_keys(auth_context)
    if not COMFY_ENABLED:
        return Response(
            content=json.dumps({"error": {"message": "Video generation not enabled", "type": "service_unavailable"}}),
            status_code=503,
            media_type="application/json"
        )
    prompt_id = _prompt_id_from_video_id(video_id)
    if not prompt_id:
        return Response(
            content=json.dumps({"error": {"message": "invalid video_id", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    # Same ownership + tombstone gate as proxy_comfy_video_status.
    if _video_job_blocked(prompt_id, auth_context):
        return Response(
            content=json.dumps({"error": {"message": "video_id not found", "type": "not_found"}}),
            status_code=404,
            media_type="application/json"
        )

    headers = configured_downstream_headers(auth_context, "comfyui")
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(60, connect=10)) as client:
            job = await _comfy_history(client, prompt_id, headers)
            if job is None:
                live = _video_progress_snapshot(prompt_id)
                queue_status = await _comfy_queue_status(client, prompt_id, headers)
                if live or queue_status in {"queued", "running"}:
                    internal_status = (
                        str(live.get("status"))
                        if live and live.get("status") in {"queued", "running"}
                        else queue_status
                    )
                    return Response(
                        content=json.dumps({
                            "error": {
                                "message": (
                                    f"Video content is not ready yet "
                                    f"(status={_openai_video_status(internal_status)})"
                                ),
                                "type": "invalid_request_error",
                                "code": "video_not_ready",
                            }
                        }),
                        status_code=404,
                        media_type="application/json",
                    )
                return Response(
                    content=json.dumps({"error": {"message": "video_id not found", "type": "not_found"}}),
                    status_code=404,
                    media_type="application/json"
                )
            sora_status, _ = _job_status_from_history(job)
            if sora_status != "succeeded":
                return Response(
                    content=json.dumps({
                        "error": {
                            "message": f"Video content is not ready yet (status={_openai_video_status(sora_status)})",
                            "type": "invalid_request_error",
                            "code": "video_not_ready",
                        }
                    }),
                    status_code=404,
                    media_type="application/json"
                )

            file_info = _extract_video_output(job)
            if not file_info:
                return Response(
                    content=json.dumps({"error": {"message": "No video output found in job", "type": "api_error"}}),
                    status_code=500,
                    media_type="application/json"
                )

            params = {"filename": file_info["filename"], "type": file_info["type"]}
            if file_info["subfolder"]:
                params["subfolder"] = file_info["subfolder"]
            view_resp = await client.get(f"{COMFY_HOST}/view", headers=headers, params=params)
            if view_resp.status_code != 200:
                return Response(
                    content=json.dumps({"error": {"message": f"ComfyUI /view error: {view_resp.status_code}", "type": "api_error"}}),
                    status_code=502,
                    media_type="application/json"
                )

            ext = Path(file_info["filename"]).suffix.lower()
            content_type = {
                ".mp4": "video/mp4",
                ".webm": "video/webm",
                ".mov": "video/quicktime",
                ".mkv": "video/x-matroska",
            }.get(ext, "application/octet-stream")

            video_bytes = view_resp.content
            record = _video_job_records.get(prompt_id) or {}
            person_id = record.get("person_id")
            saved_prompt_id = str(record.get("asset_id") or f"video_{prompt_id}")
            saved_prompt = await asyncio.to_thread(prompt_memory.get, saved_prompt_id, person_id) if person_id else None
            household = await asyncio.to_thread(prompt_memory.household_settings, admin_path=ADMIN_STORE.path)
            if metadata_mode == provenance.METADATA_FULL and (
                person_id != _auth_person_id(auth_context) or saved_prompt is None
                or household["never_keep"]
            ):
                return JSONResponse({"error": {"code": "prompt_not_accessible", "message": "Full metadata is available only to the maker while their prompt is kept."}}, status_code=403)
            try:
                # Internal asynchronous delivery strips the bytes before the
                # runner stores them. Capture the original workflow into its
                # retained maker row first, even when Library indexing waits.
                workflow_metadata = {}
                if saved_prompt:
                    workflow_metadata = await asyncio.to_thread(prompt_memory.capture_metadata, video_bytes, ext)
                    workflow_metadata = {**saved_prompt.get("metadata", {}), **workflow_metadata}
                    await asyncio.to_thread(
                        prompt_memory.safe_put, saved_prompt_id, person_id, saved_prompt["prompt_text"],
                        kept_until=saved_prompt["kept_until"], created_at=saved_prompt["created_at"],
                        metadata=workflow_metadata, admin_path=ADMIN_STORE.path,
                    )
                stored_video_bytes = await asyncio.to_thread(
                    media_delivery.attach_provenance, video_bytes, ext, record.get("provenance")
                )
                if index_library:
                    asset_id = await asyncio.to_thread(
                        store_asset_bytes,
                        stored_video_bytes,
                        kind="vid",
                        suffix=ext,
                        owner_key_hash=record.get("owner_key_hash") if isinstance(record.get("owner_key_hash"), str) else None,
                        maker_person_id=person_id,
                    )
                    if person_id:
                        await asyncio.to_thread(prompt_memory.move, f"video_{prompt_id}", asset_id, person_id,
                                                metadata=workflow_metadata, admin_path=ADMIN_STORE.path)
                    record["asset_id"] = asset_id
                    _persist_video_record(prompt_id)
                    from gateway import media_ingestion
                    await asyncio.to_thread(
                        media_ingestion.index_video_delivery,
                        video_id=video_id,
                        asset_id=asset_id,
                        filename=file_info["filename"],
                        media_type=content_type,
                        record=record,
                    )
                if metadata_mode == provenance.METADATA_NONE:
                    video_bytes = await asyncio.to_thread(
                        media_delivery.deliver_bytes, stored_video_bytes, ext, metadata_mode
                    )
                else:
                    video_bytes = stored_video_bytes
            except media_metadata.MediaMetadataError as exc:
                print(f"[proxy] video metadata rewrite failed: {exc}", flush=True)
                return Response(
                    content=json.dumps({"error": {"message": "Could not prepare video for delivery", "type": "api_error"}}),
                    status_code=502,
                    media_type="application/json",
                )

            return Response(
                content=video_bytes,
                status_code=200,
                media_type=content_type,
                headers={
                    "Content-Disposition": f'inline; filename="{file_info["filename"]}"',
                },
            )
    except httpx.ConnectError:
        return Response(
            content=json.dumps({"error": {"message": f"ComfyUI unavailable at {COMFY_HOST}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )
    except Exception as e:
        return Response(
            content=json.dumps({"error": {"message": f"Video content error: {str(e)}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )


async def _record_video_job_terminal_timestamp(prompt_id: str, status: str) -> None:
    """Stamp `completed_at` on a tracked video job the first time any route
    observes a terminal status for it. Called from both the list endpoint and
    the single-job status endpoint, so whichever one notices the transition
    first records it -- a client that never calls GET /v1/videos (list) still
    gets a correct completed_at if one later does, and vice versa."""
    if status not in ("succeeded", "failed"):
        return
    if status == "failed":
        await asyncio.to_thread(prompt_memory.delete_asset, f"video_{prompt_id}")
    async with _video_progress_lock:
        record = _video_job_records.get(prompt_id)
        if record is not None and record.get("completed_at") is None:
            record["completed_at"] = int(time.time())
            _persist_video_record(prompt_id)


_VIDEO_LIST_DEFAULT_LIMIT = 20
_VIDEO_LIST_MAX_LIMIT = 100


async def proxy_comfy_video_list(request: Request, auth_context: AuthContext) -> Response:
    """GET /v1/videos — list video jobs submitted via this route.

    Scope, matching the rest of /v1/videos' existing stateless design (see
    this file's own comment at the top of the video section): this lists
    jobs known to *this process* since its last restart, tracked in
    `_video_job_records`. It does not reach into ComfyUI's full history (which
    is shared across every image/video/audio job type, with no way to tell
    which entries came from this route) and it does not see jobs created
    through the separate `/gateway/v1/media/jobs` durable job store.
    """
    await _warm_video_owner_keys(auth_context)
    if not COMFY_ENABLED:
        return Response(
            content=json.dumps({"error": {"message": "Video generation not enabled", "type": "service_unavailable"}}),
            status_code=503,
            media_type="application/json"
        )
    service_response = (await asyncio.to_thread(_service_availability_response, "comfyui", service_label="ComfyUI"))
    if service_response is not None:
        return service_response

    query = request.query_params
    limit_raw = query.get("limit", str(_VIDEO_LIST_DEFAULT_LIMIT))
    try:
        limit = int(limit_raw)
    except (TypeError, ValueError):
        return Response(
            content=json.dumps({"error": {"message": "limit must be an integer", "type": "invalid_request_error", "param": "limit"}}),
            status_code=400,
            media_type="application/json",
        )
    if limit < 1 or limit > _VIDEO_LIST_MAX_LIMIT:
        return Response(
            content=json.dumps({"error": {
                "message": f"limit must be between 1 and {_VIDEO_LIST_MAX_LIMIT}",
                "type": "invalid_request_error",
                "param": "limit",
            }}),
            status_code=400,
            media_type="application/json",
        )

    order = query.get("order", "desc")
    if order not in ("asc", "desc"):
        return Response(
            content=json.dumps({"error": {"message": "order must be 'asc' or 'desc'", "type": "invalid_request_error", "param": "order"}}),
            status_code=400,
            media_type="application/json",
        )

    after = query.get("after")
    after_prompt_id = _prompt_id_from_video_id(after) if after else None
    if after and after_prompt_id is None:
        return Response(
            content=json.dumps({"error": {"message": "invalid after cursor", "type": "invalid_request_error", "param": "after"}}),
            status_code=400,
            media_type="application/json",
        )

    async with _video_progress_lock:
        records = [
            (pid, dict(rec))
            for pid, rec in _video_job_records.items()
            if _video_job_visible(pid, auth_context)
        ]
    records.sort(key=lambda item: item[1].get("created_at") or 0, reverse=(order == "desc"))

    if after_prompt_id is not None:
        ids_in_order = [pid for pid, _ in records]
        if after_prompt_id in ids_in_order:
            records = records[ids_in_order.index(after_prompt_id) + 1:]
        else:
            # The cursor doesn't resolve against this caller's current page
            # set -- it was evicted (past _video_job_records' own retention),
            # deleted, or never existed for this owner. Silently restarting
            # from page one here would look like forward progress to a
            # paginating client while actually re-serving the first page
            # forever; an explicit error is the honest response when we
            # cannot determine where in the ordering to resume.
            return Response(
                content=json.dumps({"error": {
                    "message": (
                        "after cursor does not reference a currently known "
                        "video job (it may have been deleted or evicted)"
                    ),
                    "type": "invalid_request_error",
                    "param": "after",
                    "code": "cursor_not_found",
                }}),
                status_code=400,
                media_type="application/json",
            )

    page = records[:limit]
    has_more = len(records) > len(page)

    headers = configured_downstream_headers(auth_context, "comfyui")
    data: list[dict[str, Any]] = []
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(30, connect=10)) as client:
            for prompt_id, record in page:
                video_id = _video_id_from_prompt_id(prompt_id)
                job = await _comfy_history(client, prompt_id, headers)
                entry: dict[str, Any] = {
                    "id": video_id,
                    "object": "video",
                    "model": record.get("model"),
                    "size": record.get("size"),
                    "seconds": record.get("seconds"),
                    "created_at": record.get("created_at"),
                    "completed_at": record.get("completed_at"),
                    "prompt": _tracked_video_fields(prompt_id, auth_context).get("prompt"),
                }
                if job is not None:
                    status, progress = _job_status_from_history(job)
                    await _record_video_job_terminal_timestamp(prompt_id, status)
                    if status in ("succeeded", "failed"):
                        async with _video_progress_lock:
                            fresh = _video_job_records.get(prompt_id)
                            if fresh is not None:
                                entry["completed_at"] = fresh.get("completed_at")
                    if status == "failed":
                        entry["error"] = _comfy_execution_error_message(job) or "ComfyUI execution_error"
                else:
                    live = _video_progress_snapshot(prompt_id)
                    if live and live.get("status") in ("queued", "running"):
                        status = "running" if live.get("percent", 0) > 0 or live.get("node") else live.get("status", "running")
                        progress = int(live.get("percent") or 0)
                    else:
                        queue_status = await _comfy_queue_status(client, prompt_id, headers)
                        status = queue_status if queue_status != "unknown" else "queued"
                        progress = 25 if status == "running" else 0
                entry["status"] = status
                entry["progress"] = progress
                data.append(entry)
    except httpx.ConnectError:
        return Response(
            content=json.dumps({"error": {"message": f"ComfyUI unavailable at {COMFY_HOST}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )

    return Response(
        content=json.dumps({
            "object": "list",
            "data": data,
            "first_id": data[0]["id"] if data else None,
            "last_id": data[-1]["id"] if data else None,
            "has_more": has_more,
        }),
        status_code=200,
        media_type="application/json",
    )


async def proxy_comfy_video_delete(video_id: str, auth_context: AuthContext) -> Response:
    """DELETE /v1/videos/{video_id}.

    A queued/running job is actively cancelled (ComfyUI's
    `/api/jobs/{id}/cancel` -- interrupts a running prompt, dequeues a
    pending one, atomically and idempotently) before being tombstoned; a
    job that's already terminal (succeeded/failed) is tombstoned directly.
    If cancellation can't be verified (ComfyUI unreachable, or it reports
    the cancel didn't take), this returns 409 instead of claiming
    `deleted: true` for a job that may keep rendering to completion.

    The tombstone (`_video_job_records[...]["deleted_at"]`, not an outright
    pop) is what makes "GET returns 404 and content is no longer served"
    actually hold: this gateway's own tracking (not ComfyUI's /history,
    which has no entry at all for a still-queued job -- that is not the
    same as "unknown id", and whose retention we don't control) is the
    source of truth for every read route.
    """
    await _warm_video_owner_keys(auth_context)
    if not COMFY_ENABLED:
        return Response(
            content=json.dumps({"error": {"message": "Video generation not enabled", "type": "service_unavailable"}}),
            status_code=503,
            media_type="application/json"
        )
    service_response = (await asyncio.to_thread(_service_availability_response, "comfyui", service_label="ComfyUI"))
    if service_response is not None:
        return service_response

    prompt_id = _prompt_id_from_video_id(video_id)
    if not prompt_id:
        return Response(
            content=json.dumps({"error": {"message": "invalid video_id", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )

    async with _video_progress_lock:
        if prompt_id in _video_job_records:
            known = _video_job_visible(prompt_id, auth_context)
        else:
            # No ownership metadata exists for a job we're only tracking via
            # the legacy _video_progress dict (shouldn't happen in practice
            # since both are written together, but kept as a defensive
            # fallback) -- nothing to scope against, so fall back to the
            # pre-ownership "is it known at all" check.
            known = prompt_id in _video_progress
    if not known:
        return Response(
            content=json.dumps({"error": {"message": "video_id not found", "type": "not_found"}}),
            status_code=404,
            media_type="application/json"
        )

    headers = configured_downstream_headers(auth_context, "comfyui")
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(30, connect=10)) as client:
            job = await _comfy_history(client, prompt_id, headers)
            if job is not None:
                current_status, _ = _job_status_from_history(job)
            else:
                live = _video_progress_snapshot(prompt_id)
                if live and live.get("status") in ("queued", "running"):
                    current_status = "running"
                else:
                    queue_status = await _comfy_queue_status(client, prompt_id, headers)
                    current_status = queue_status if queue_status != "unknown" else "succeeded"
                    # "unknown" here means ComfyUI has no record of this
                    # prompt_id at all (not in /history, not in /queue) --
                    # there is nothing left to cancel, so treat it as already
                    # terminal rather than attempting (and failing) a cancel.

            if current_status in ("queued", "running"):
                try:
                    cancel_resp = await client.post(
                        f"{COMFY_HOST}/api/jobs/{prompt_id}/cancel",
                        headers=headers,
                    )
                except Exception as e:
                    return Response(
                        content=json.dumps({"error": {
                            "message": f"Could not cancel in-progress video job: {e}",
                            "type": "api_error",
                            "code": "video_cancel_failed",
                        }}),
                        status_code=409,
                        media_type="application/json",
                    )
                if cancel_resp.status_code != 200:
                    return Response(
                        content=json.dumps({"error": {
                            "message": f"ComfyUI cancel request failed: HTTP {cancel_resp.status_code}",
                            "type": "api_error",
                            "code": "video_cancel_failed",
                        }}),
                        status_code=409,
                        media_type="application/json",
                    )
                # A {"cancelled": false} body means ComfyUI found nothing to
                # cancel (e.g. the job finished in the race between our
                # status check above and this call) -- that's fine, it's
                # terminal now; fall through to the tombstone below rather
                # than treating a no-op as a failure.

            # Best-effort: drop the ComfyUI history entry too, so a
            # succeeded/failed job's mp4 stops being reachable via /view
            # even if our own tombstone below were somehow bypassed. A job
            # we just cancelled while still queued has no history entry to
            # drop; the delete call is simply a no-op for it.
            try:
                await client.post(f"{COMFY_HOST}/history", headers=headers, json={"delete": [prompt_id]})
            except Exception:
                pass
    except httpx.ConnectError:
        return Response(
            content=json.dumps({"error": {"message": f"ComfyUI unavailable at {COMFY_HOST}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )
    except Exception as e:
        return Response(
            content=json.dumps({"error": {"message": f"Video delete error: {str(e)}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json"
        )

    now = int(time.time())
    async with _video_progress_lock:
        record = _video_job_records.get(prompt_id)
        if record is not None:
            record["deleted_at"] = now
            if record.get("completed_at") is None:
                record["completed_at"] = now
            _persist_video_record(prompt_id)
        _video_progress.pop(prompt_id, None)
        _video_workflows.pop(prompt_id, None)
        _video_chain_units.pop(prompt_id, None)

    await asyncio.to_thread(prompt_memory.delete_asset, f"video_{prompt_id}")
    if record and record.get("asset_id"):
        await asyncio.to_thread(prompt_memory.delete_asset, str(record["asset_id"]))
    return Response(
        content=json.dumps({"id": video_id, "object": "video", "deleted": True}),
        status_code=200,
        media_type="application/json",
    )


VIDEO_REMIX_PUBLIC_MODEL = "video-remix"


async def _read_video_request_body(
    request: Request, *, id_reference_fields: tuple[str, ...] = ()
) -> dict[str, Any]:
    """Read a JSON or multipart body for the remix/edit routes into a dict.

    ``id_reference_fields`` names file fields that may carry a video id instead of bytes: a
    zero-byte upload whose filename is ``<video id>`` or ``<video id>.<ext>`` becomes that id.
    openai-python's ``videos.extend`` sends ``video`` as a file part only (its ``{"id": ...}``
    form fails client-side), so this is the one way an SDK caller can extend by id.

    Raises _VideoFormParseError on a body that is not an object.
    """
    content_type = request.headers.get("content-type", "")
    if "multipart/form-data" in content_type or "application/x-www-form-urlencoded" in content_type:
        try:
            form = await request.form(max_part_size=video_inputs.MAX_FORM_PART_BYTES)
        except Exception as exc:
            raise _VideoFormParseError(f"Invalid multipart body: {exc}") from exc
        try:
            items: list[tuple[str, Any]] = []
            for name, value in form.multi_items():
                if hasattr(value, "read") and hasattr(value, "filename"):
                    raw = await value.read()
                    stem = Path(value.filename or "").stem
                    if not raw and name in id_reference_fields and stem.startswith(VIDEO_ID_PREFIX):
                        items.append((name, stem))
                        continue
                    mime = getattr(value, "content_type", None) or "application/octet-stream"
                    items.append((name, "data:" + mime + ";base64," + base64.b64encode(raw).decode("ascii")))
                else:
                    items.append((name, value))
            try:
                return video_inputs.parse_bracket_form(items)
            except ValueError as exc:
                raise _VideoFormParseError(str(exc)) from exc
        finally:
            await form.close()
    try:
        body = await request.json()
    except Exception as exc:
        raise _VideoFormParseError("Invalid JSON body") from exc
    if not isinstance(body, dict):
        raise _VideoFormParseError("Request body must be a JSON object")
    return body


def _json_error(status: int, message: str, *, code: str | None = None, param: str | None = None,
                kind: str = "invalid_request_error") -> Response:
    error: dict[str, Any] = {"message": message, "type": kind}
    if param:
        error["param"] = param
    if code:
        error["code"] = code
    return Response(content=json.dumps({"error": error}), status_code=status, media_type="application/json")


async def _submit_video_remix(
    request: Request,
    auth_context: AuthContext,
    *,
    body: dict[str, Any],
    source: Any,
    remixed_from_video_id: str | None,
) -> Response:
    """Create a remix job: the standard video create pipeline with `source_video` bound."""
    if not VIDEO_REMIX_WORKFLOW:
        return _json_error(
            501,
            "Video remix is not configured on this gateway. Set "
            "videos.remix_workflow in proxy_config.yml to enable it.",
            code="video_remix_not_configured",
        )
    block = (merge_workflow_inputs(body).get("extensions") or {}).get(WORKFLOW_EXTENSION_NAMESPACE) or {}
    if isinstance(block, Mapping) and "source_video" in block:
        return _json_error(
            400,
            "source_video is set by the remix route; do not pass it as a workflow extension",
            param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.source_video",
            code="invalid_workflow_extension",
        )
    create_body = merge_workflow_inputs(body)
    create_body.setdefault("model", VIDEO_REMIX_PUBLIC_MODEL)
    extensions = dict(create_body.get("extensions") or {})
    extensions[WORKFLOW_EXTENSION_NAMESPACE] = {
        **dict(extensions.get(WORKFLOW_EXTENSION_NAMESPACE) or {}),
        "source_video": source,
    }
    create_body["extensions"] = extensions
    return await proxy_comfy_video_create(
        request,
        auth_context,
        body_override=create_body,
        remixed_from_video_id=remixed_from_video_id,
    )


async def proxy_comfy_video_remix(
    video_id: str,
    auth_context: AuthContext,
    request: Request | None = None,
) -> Response:
    """POST /v1/videos/{video_id}/remix -- re-render a completed video with a new prompt.

    Same contract as OpenAI's remix: JSON `{"prompt": ...}`, a new video job
    back, `remixed_from_video_id` set to the source. The gateway runs
    `videos.remix_workflow` (Bernini-R). `model` is optional; when absent the
    resource reports `video-remix`. Gateway extras (`seed`, `seconds`, `size`,
    `negative_prompt`) are accepted as top-level fields.
    """
    await _warm_video_owner_keys(auth_context)
    admission = _dispatch_admission_response(
        'video.remix', auth_context=auth_context, service_id="comfyui",
        service_available=COMFY_ENABLED, resource_class='video', queue_key=_MEDIA_JOB_QUEUE_KEY,
    )
    if admission is not None:
        return admission

    if not COMFY_ENABLED:
        return Response(
            content=json.dumps({"error": {"message": "Video generation not enabled", "type": "service_unavailable"}}),
            status_code=503,
            media_type="application/json"
        )
    service_response = (await asyncio.to_thread(_service_availability_response, "comfyui", service_label="ComfyUI"))
    if service_response is not None:
        return service_response

    prompt_id = _prompt_id_from_video_id(video_id)
    if not prompt_id:
        return Response(
            content=json.dumps({"error": {"message": "invalid video_id", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json"
        )
    async with _video_progress_lock:
        if _video_job_blocked(prompt_id, auth_context):
            return _json_error(404, "video_id not found", kind="not_found")
    if not VIDEO_REMIX_WORKFLOW:
        return _json_error(
            501,
            "Video remix is not configured on this gateway. Set "
            "videos.remix_workflow in proxy_config.yml to enable it.",
            code="video_remix_not_configured",
        )
    if request is None:
        return _json_error(400, "remix needs a request body", param="prompt")
    try:
        body = await _read_video_request_body(request)
    except _VideoFormParseError as exc:
        return _json_error(400, str(exc))
    if not isinstance(body.get("prompt"), str) or not body["prompt"].strip():
        return _json_error(400, "prompt is required", param="prompt")
    return await _submit_video_remix(
        request,
        auth_context,
        body=body,
        source={"video_id": video_id},
        remixed_from_video_id=video_id,
    )


async def proxy_comfy_video_edit(request: Request, auth_context: AuthContext) -> Response:
    """POST /v1/videos/edits -- OpenAI's video edit: prompt plus a source video.

    `video` is either an uploaded file (multipart) or a reference to a
    completed gateway video (`{"id": ...}` as JSON, or `video[id]` in a form).
    An uploaded clip gives `remixed_from_video_id: null`.
    """
    await _warm_video_owner_keys(auth_context)
    admission = _dispatch_admission_response(
        'video.edit', auth_context=auth_context, service_id="comfyui",
        service_available=COMFY_ENABLED, resource_class='video', queue_key=_MEDIA_JOB_QUEUE_KEY,
    )
    if admission is not None:
        return admission

    if not COMFY_ENABLED:
        return _json_error(503, "Video generation not enabled", kind="service_unavailable")
    service_response = (await asyncio.to_thread(_service_availability_response, "comfyui", service_label="ComfyUI"))
    if service_response is not None:
        return service_response
    try:
        body = await _read_video_request_body(request)
    except _VideoFormParseError as exc:
        return _json_error(400, str(exc))
    if not isinstance(body.get("prompt"), str) or not body["prompt"].strip():
        return _json_error(400, "prompt is required", param="prompt")
    video = body.pop("video", None)
    if video is None:
        return _json_error(400, "video is required: upload a file or pass {\"id\": \"video_...\"}", param="video")
    source_id = _asset_reference_video_id(video)
    if source_id:
        prompt_id = _prompt_id_from_video_id(source_id)
        if not prompt_id:
            return _json_error(400, "invalid video id", param="video")
        async with _video_progress_lock:
            if _video_job_blocked(prompt_id, auth_context):
                return _json_error(404, "video_id not found", kind="not_found")
        source: Any = {"video_id": source_id}
    else:
        source = video
    return await _submit_video_remix(
        request,
        auth_context,
        body=body,
        source=source,
        remixed_from_video_id=source_id,
    )


