_DRIFT_CACHE_PATH = Path(__file__).parent / "cache" / "drift_status.json"
_DRIFT_SCRIPT_PATH = Path(__file__).parent / "scripts" / "check_workflow_drift.py"
# Match status_endpoint._DRIFT_REPORT_PATH so the renderer reads the same file.
_DRIFT_REPORT_PATH = Path(__file__).parent / "cache" / "drift_status.json"


async def _run_workflow_drift_once() -> dict:
    """Run check_workflow_drift.py once with a hard timeout. Returns a status
    dict suitable for serialising into ``cache/drift_status.json``.

    Uses the proxy's own venv interpreter so playwright is reachable. If the
    script isn't present, ComfyUI is offline, or playwright errors out, the
    failure is recorded as ``{"status": "error", "reason": ...}`` and the
    proxy keeps running."""
    if not _DRIFT_SCRIPT_PATH.is_file():
        return {
            "status": "error",
            "reason": f"drift script missing: {_DRIFT_SCRIPT_PATH}",
            "checked_at": int(time.time()),
        }
    interpreter = sys.executable or "python3"
    try:
        proc = await asyncio.create_subprocess_exec(
            interpreter, str(_DRIFT_SCRIPT_PATH), "--verbose",
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
            cwd=str(Path(__file__).parent),
        )
        try:
            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=120)
        except asyncio.TimeoutError:
            with contextlib.suppress(ProcessLookupError):
                proc.kill()
            return {
                "status": "error",
                "reason": "drift script timed out after 120s",
                "checked_at": int(time.time()),
            }
        rc = proc.returncode
        out = (stdout or b"").decode("utf-8", errors="replace")
        err = (stderr or b"").decode("utf-8", errors="replace")
        return {
            "status": "ok" if rc == 0 else "drift" if rc == 1 else "error",
            "exit_code": rc,
            "checked_at": int(time.time()),
            "stdout_tail": out[-2000:],
            "stderr_tail": err[-2000:],
        }
    except FileNotFoundError as e:
        return {
            "status": "error",
            "reason": f"interpreter not found: {e}",
            "checked_at": int(time.time()),
        }
    except Exception as e:  # noqa: BLE001
        return {
            "status": "error",
            "reason": f"{type(e).__name__}: {str(e)[:200]}",
            "checked_at": int(time.time()),
        }


async def _workflow_drift_loop(stop_event: asyncio.Event) -> None:
    """Refresh the drift cache every 6h. First run after a 30s grace period
    so we don't compete with backend warm-up."""
    try:
        await asyncio.wait_for(stop_event.wait(), timeout=30)
        return
    except asyncio.TimeoutError:
        pass
    while not stop_event.is_set():
        result = await _run_workflow_drift_once()
        try:
            _DRIFT_CACHE_PATH.parent.mkdir(parents=True, exist_ok=True)
            _DRIFT_CACHE_PATH.write_text(
                json.dumps(result, indent=2), encoding="utf-8"
            )
            print(
                f"[proxy] drift cache refreshed: status={result.get('status')} "
                f"exit_code={result.get('exit_code')}",
                flush=True,
            )
        except Exception as e:  # noqa: BLE001
            print(f"[proxy] drift cache write failed: {e}", flush=True)
        try:
            await asyncio.wait_for(stop_event.wait(), timeout=6 * 3600)
            return
        except asyncio.TimeoutError:
            continue


def _adopt_bootstrap_signin_lists() -> None:
    """First start after schema 9: the config file's old allow-lists become sign-in rules, once."""
    try:
        if signin_rules_migration.adopt_bootstrap_lists(ADMIN_STORE.path, _bootstrap_admin_oidc_cfg(), os.environ):
            print("[proxy] Sign-in rules were made from the old lists in the config file. "
                  "Check them in Settings > Sign-in.", flush=True)
    except Exception as exc:  # noqa: BLE001 - a start must not fail over a convenience
        print(f"[proxy] WARNING: could not read the old sign-in lists from the config: {exc}", flush=True)


async def _initialize_stores() -> None:
    """Initialize the independent store files side by side on worker threads.

    Startup waits for the slowest store, and the event loop stays free. Provider
    spend recovery writes through the stores, so it starts only after all of them
    are ready: a store that fails aborts startup before it runs.
    """
    await asyncio.gather(
        asyncio.to_thread(ADMIN_STORE.init_db),
        asyncio.to_thread(responses_store.init_db),
        asyncio.to_thread(receipt_store.init_db),
        asyncio.to_thread(media_jobs.init_db),
    )
    await asyncio.to_thread(providers.recover_provider_spend, path=ADMIN_DB_PATH.parent / "provider_spend.db")


def _migrate_host_command_permission() -> None:
    """Decision D13: installs that already declare command lifecycles keep them working."""
    registry = service_registry.load_service_registry(path=ADMIN_DB_PATH)
    services = (registry or {}).get("services") or {}
    host_commands.migrate_legacy_command_lifecycles(
        ADMIN_DB_PATH, services or config.get("backends") or {}
    )


@asynccontextmanager
async def lifespan(app: FastAPI):
    """App lifespan manager."""
    # Ownership and history stores must be ready before any worker can write.
    # In particular, do not run cleanup beside an unfinished quarantine.
    await _initialize_stores()
    await asyncio.to_thread(_adopt_bootstrap_signin_lists)
    await asyncio.to_thread(_migrate_host_command_permission)
    from gateway.lifecycle_drivers import _process_driver
    await asyncio.to_thread(_process_driver.recover, config.get("backends") or {})
    print(f"[proxy] Azizam starting on port {PROXY_PORT}", flush=True)
    print(f"[proxy] TTS backend: {TTS_HOST} (enabled: {TTS_ENABLED})", flush=True)
    print(f"[proxy] STT backend: {STT_HOST} (enabled: {STT_ENABLED})", flush=True)
    print(f"[proxy] ComfyUI backend: {COMFY_HOST} (enabled: {COMFY_ENABLED})", flush=True)
    print(f"[proxy] Model compatibility: {'enabled' if MODEL_COMPAT_ENABLED else 'disabled'}", flush=True)
    # Keep the last good ComfyUI node definitions on disk, so embedding a workflow
    # in generated media survives a ComfyUI that is restarting at submit time.
    comfy_object_info.DISK_CACHE_DIR = Path(__file__).resolve().parent / "cache" / "comfy_object_info"

    # Replay persisted firehose metrics so per-key counters and the recent-event
    # timeline survive proxy restarts. The window stays bounded at 24h; older
    # records are filtered out at replay time.
    try:
        replay_stats = await asyncio.to_thread(firehose_metrics.replay_persisted)
        print(
            f"[proxy] firehose replay: requests={replay_stats.get('requests_replayed')} "
            f"events={replay_stats.get('events_replayed')} skipped={replay_stats.get('skipped')}",
            flush=True,
        )
    except Exception as e:  # noqa: BLE001
        print(f"[proxy] firehose replay failed: {e}", flush=True)

    # Engines are reached lazily. A declared process driver may start one on
    # the first request when the owner has enabled host command execution.

    # Log the loop thread's stack whenever the event loop stops answering.
    watchdog = loop_watchdog.start(float(get_env("AZIZAM_LOOP_WATCHDOG_THRESHOLD_S", "1.0")))


    # ComfyUI websocket listener for real-time video progress. Optional —
    # /v1/videos/{id} falls back to /history polling if this can't connect.
    comfy_ws_stop = asyncio.Event()
    comfy_ws_task = None
    video_reconcile_stop = asyncio.Event()
    video_reconcile_task = None
    if COMFY_ENABLED:
        comfy_ws_task = asyncio.create_task(_comfy_ws_listener(comfy_ws_stop))
        print(f"[proxy] ComfyUI ws listener started (client_id={COMFY_CLIENT_ID})", flush=True)

        # Startup reconciliation: safety net for any persisted/hydrated
        # _video_progress (currently in-memory only, so this is usually a
        # no-op, but the hook is wired for future persistence).
        if _video_progress:
            try:
                await _reconcile_video_progress()
                print(
                    f"[proxy] video progress startup reconcile complete "
                    f"({len(_video_progress)} entries remain)",
                    flush=True,
                )
            except Exception as e:  # noqa: BLE001
                print(f"[proxy] video progress startup reconcile failed: {e}", flush=True)

        video_reconcile_task = asyncio.create_task(
            _reconcile_video_progress_loop(video_reconcile_stop)
        )
        print(
            f"[proxy] video progress reconciliation started "
            f"(every {_VIDEO_RECONCILE_INTERVAL}s, retain terminal {_VIDEO_RECONCILE_RETAIN}s)",
            flush=True,
        )

    # Workflow drift cache: run scripts/check_workflow_drift.py every 6h and
    # write the structured outcome to cache/drift_status.json. The script
    # depends on Playwright + a live ComfyUI; failures are recorded into the
    # cache (status=error, reason=...) instead of crashing.
    drift_stop = asyncio.Event()
    drift_task = asyncio.create_task(_workflow_drift_loop(drift_stop))
    print("[proxy] Workflow drift periodic task started (every 6h)", flush=True)

    # Metrics persistence: SQLite-backed time-series for the status page.
    # The sampler writes; readers (status_endpoint, firehose_render) open
    # short-lived connections via metrics_store.reader().
    metrics_task = None
    try:
        metrics_writer = metrics_sampler.start_writer()
        await asyncio.to_thread(metrics_writer.wait_ready)
        # The full integrity scan takes seconds on a large file; keep it off the startup path.
        asyncio.get_running_loop().run_in_executor(None, metrics_store.verify_integrity, metrics_store.DB_PATH)
        metrics_task = asyncio.create_task(metrics_sampler.sampler_loop(lambda: config))
        print(f"[proxy] Metrics sampler started (db={metrics_store.DB_PATH})", flush=True)
    except Exception as e:  # noqa: BLE001
        print(f"[proxy] Metrics sampler failed to start: {e}", flush=True)

    # Saved /v1/responses conversations survive until explicit deletion.
    print(f"[proxy] Responses store initialized (db={responses_store.DB_PATH})", flush=True)

    receipts_maintenance_stop = asyncio.Event()
    receipts_maintenance_task = None
    try:
        pruned = await asyncio.to_thread(receipt_store.maintain, ADMIN_STORE.path)
        receipts_maintenance_task = asyncio.create_task(
            _receipts_maintenance_loop(receipts_maintenance_stop)
        )
        print(
            f"[proxy] Receipt store initialized (db={receipt_store.DB_PATH}, pruned={pruned})",
            flush=True,
        )
    except Exception as e:  # noqa: BLE001
        print(f"[proxy] Receipt store failed to start: {e}", flush=True)

    try:
        _fail_orphaned_identity_jobs()
        print(f"[proxy] Hydrated {_hydrate_video_job_records()} persisted video job record(s)", flush=True)
        print(
            f"[proxy] Media job store initialized (db={media_jobs.DB_PATH})",
            flush=True,
        )
        _recover_media_jobs()
    except Exception as e:  # noqa: BLE001
        print(f"[proxy] Media job store failed to start: {e}", flush=True)

    try:
        print(f"[proxy] Admin store initialized (db={ADMIN_DB_PATH})", flush=True)
        app_key_count = active_app_credential_count()
        print(
            f"[proxy] Runtime App credentials: {app_key_count} active",
            flush=True,
        )
        if not app_key_count:
            print(
                "[proxy] WARNING: No active App credentials in admin.db; "
                "proxied requests will be rejected",
                flush=True,
            )
        provisioned = _provision_existing_user_personal_apps()
        if provisioned:
            print(
                f"[proxy] Provisioned {provisioned} self-service personal app(s)",
                flush=True,
            )
    except Exception as e:  # noqa: BLE001
        print(f"[proxy] Admin store failed to start: {e}", flush=True)

    prompt_memory_stop = asyncio.Event()
    prompt_memory_task = asyncio.create_task(_prompt_memory_maintenance_loop(prompt_memory_stop))
    metadata_migration_task = asyncio.create_task(prompt_metadata_migration.background_migration(
        IMAGE_CACHE_DIR, _prompt_migration_state_path(),
    ))

    yield

    prompt_memory_stop.set()
    prompt_memory_task.cancel()
    metadata_migration_task.cancel()
    await asyncio.gather(prompt_memory_task, metadata_migration_task, return_exceptions=True)
    state.shutdown_requested = True
    if watchdog is not None:
        watchdog.stop()
    # Every worker registry is owned by the gateway: cancel and join them all
    # before returning, not only the image workers.
    owned_job_tasks = [
        task
        for registry in (
            _image_media_job_tasks, _audio_media_job_tasks,
            _video_media_job_tasks, _identity_job_tasks,
        )
        for task in registry
    ]
    for task in owned_job_tasks:
        task.cancel()
    if owned_job_tasks:
        await asyncio.gather(*owned_job_tasks, return_exceptions=True)
    if comfy_ws_task is not None:
        comfy_ws_stop.set()
        comfy_ws_task.cancel()
        try:
            await comfy_ws_task
        except asyncio.CancelledError:
            pass
        except Exception:
            pass
    if video_reconcile_task is not None:
        video_reconcile_stop.set()
        video_reconcile_task.cancel()
        try:
            await video_reconcile_task
        except asyncio.CancelledError:
            pass
        except Exception:
            pass
    drift_stop.set()
    drift_task.cancel()
    try:
        await drift_task
    except asyncio.CancelledError:
        pass
    except Exception:
        pass
    if metrics_task is not None:
        metrics_task.cancel()
        try:
            await metrics_task
        except asyncio.CancelledError:
            pass
        except Exception:
            pass
    try:
        await asyncio.to_thread(metrics_sampler.close_writer)
    except Exception:
        pass
    if receipts_maintenance_task is not None:
        receipts_maintenance_stop.set()
        receipts_maintenance_task.cancel()
        try:
            await receipts_maintenance_task
        except asyncio.CancelledError:
            pass
    from gateway.lifecycle_drivers import _process_driver
    await asyncio.to_thread(_process_driver.shutdown)


# Build the shared TLS context now, at import, so no request builds it on the event loop.
tls_context()

app = FastAPI(lifespan=lifespan, docs_url=None, redoc_url=None)


