_HTML_CONTENT_TYPES = ("text/html",)
_BROWSER_UI_PREFIXES = ("/admin", "/setup", "/login", "/logout", "/me", "/auth")

_SECURITY_HEADERS = {
    "X-Content-Type-Options": "nosniff",
    "X-Frame-Options": "SAMEORIGIN",
    "Referrer-Policy": "strict-origin-when-cross-origin",
    # Inline styles/scripts are used in the admin UI, so unsafe-inline is
    # required. eval is not used. This is a hardening baseline, not a full
    # CSP lockdown; see docs/REVERSE_PROXY.md for tightening guidance.
    "Content-Security-Policy": (
        "default-src 'self'; "
        "script-src 'self' 'unsafe-inline'; "
        "style-src 'self' 'unsafe-inline'; "
        "img-src 'self' data: blob:; "
        "media-src 'self' blob: data:; "
        "frame-ancestors 'none'"
    ),
}


# Browser sign-in and sign-out responses carry session cookies, one-time keys
# or provider state: never cache them, never leak their URL as a referrer.
_BROWSER_AUTH_PATHS = frozenset({
    "/login", "/logout", "/auth/logout-confirm", "/admin/oidc/callback",
    "/setup/claim", "/setup/local-owner", "/setup/local-login", "/setup/first-app",
})


def _mark_browser_auth_response(response: Response) -> None:
    response.headers["cache-control"] = "no-store"
    response.headers["referrer-policy"] = "no-referrer"


@app.middleware("http")
async def _security_headers_middleware(request: Request, call_next):
    """Inject browser security headers on HTML/admin/portal responses."""
    response = await call_next(request)
    ct = response.headers.get("content-type", "")
    path = request.url.path
    if path in _BROWSER_AUTH_PATHS:
        _mark_browser_auth_response(response)
    is_html = any(ct.startswith(t) for t in _HTML_CONTENT_TYPES)
    is_ui_path = any(path == p or path.startswith(p + "/") or path.startswith(p + "?")
                     for p in _BROWSER_UI_PREFIXES)
    if is_html or is_ui_path:
        for name, value in _SECURITY_HEADERS.items():
            response.headers.setdefault(name, value)
    return response


@app.middleware("http")
async def _gateway_auth_middleware(request: Request, call_next):
    """Gate gateway-native discovery/receipt APIs, and the per-engine native lane, behind the proxy key layer."""
    if request.url.path.startswith(("/gateway/v1", "/native/")):
        refusal = await _authenticate_mounted_route(request)
        if refusal is not None:
            return refusal
    return await call_next(request)


async def _authenticate_mounted_route(request: Request) -> Response | None:
    """Put the caller's identity in the request scope, or return the refusal (401 without a key).

    The middleware above runs it for the gateway and native prefixes. The frontend mount runs it
    before every operation that does not check the caller itself, so a row on any other prefix gets
    the same check. A caller the middleware has already identified is not looked up twice.
    """
    if isinstance(request.scope.get("auth_context"), AuthContext):
        return None
    auth_context = await asyncio.to_thread(authenticate_request, request, request.url.path)
    if isinstance(auth_context, Response):
        return auth_context
    request.scope["auth_context"] = auth_context
    request.scope["gateway_audience"] = _gateway_audience_resolver(request)
    return None


async def _gateway_resource_lister(*, audience: str) -> list:
    try:
        reg = ADMIN_STORE.get_service_registry()
    except Exception:  # noqa: BLE001
        return []
    services = reg.get("services") if isinstance(reg, Mapping) else {}
    service_ids = [
        str(service_id)
        for service_id, service in (services or {}).items()
        if isinstance(service, Mapping)
        and service_registry.bool_from_config(service.get("enabled"), True)
    ]
    facts_list = await asyncio.gather(
        *[_service_resource_runtime_fact(service_id) for service_id in service_ids],
        return_exceptions=True,
    )
    runtime_facts: dict[str, Mapping[str, Any]] = {}
    for service_id, fact in zip(service_ids, facts_list):
        if isinstance(fact, Mapping):
            runtime_facts[service_id] = fact
        else:
            runtime_facts[service_id] = {"status": "unknown"}
    return service_registry.list_resource_summaries(
        reg,
        audience=audience,
        runtime_facts=runtime_facts,
    )


def _gateway_aliases_provider(operation: str | None = None) -> dict[str, Any]:
    out: dict[str, Any] = {}
    for op in ([operation] if operation else stable_aliases.OPERATIONS):
        out.update(
            stable_aliases.describe_aliases(
                config.get("model_aliases"),
                engine_available=_alias_engine_available_for(op),
                operation=op,
            )
        )
    return out


def _gateway_alias_resolver(operation: str, model: str) -> dict[str, Any]:
    if operation not in stable_aliases.OPERATIONS and operation not in {"completions", "translations"}:
        return {"alias": False, "resolved": False, "error": f"unknown operation: {operation}"}
    try:
        res = resolve_stable_alias(operation, model)
    except stable_aliases.AliasUnavailableError as exc:
        return {"alias": True, "resolved": False, "requested": model, "operation": operation, "error": str(exc), "code": exc.code}
    if res is None:
        return {"alias": False, "resolved": True, "requested": model, "operation": operation, "resolves_to": model}
    return {"alias": True, "resolved": True, **res.to_dict()}


def _stable_alias_model_entries() -> list[dict[str, Any]]:
    """One /v1/models entry per stable alias id, aggregated across operations."""
    entries: dict[str, dict[str, Any]] = {}
    for op, view in _gateway_aliases_provider().items():
        for row in view.get("stable", []):
            entry = entries.setdefault(row["alias"], {
                "id": row["alias"],
                "object": "model",
                "owned_by": "azizam",
                "azizam_alias": True,
                "azizam_resolves_to": {},
            })
            entry["azizam_resolves_to"][op] = row.get("resolves_to")
            if row.get("candidates"):
                entry.setdefault("azizam_engine_candidates", {})[op] = row["candidates"]
            if row.get("error"):
                entry.setdefault("azizam_alias_errors", {})[op] = row["error"]
    return list(entries.values())


