IDENTITY_CFG = config.get("identity", {}) or {}
IDENTITY_MODEL_ID = "image-identity"
IDENTITY_MANIFEST_ID = "image.edit.image-identity"
_IDENTITY_ROUTE_POLICY = {"protocol": "openai.images", "intent": "image.edit", "backend": "comfyui"}
_identity_template_cache: tuple[dict[str, Any], dict[str, Any]] | None = None


def _identity_face_cfg() -> Mapping[str, Any]:
    cfg = IDENTITY_CFG.get("face_service")
    return cfg if isinstance(cfg, Mapping) else {}


def _identity_face_client() -> identity_api.FaceServiceClient:
    bcfg = _identity_face_cfg()
    return identity_api.FaceServiceClient(
        f"http://{bcfg.get('host', '127.0.0.1')}:{bcfg.get('port', 8021)}",
        timeout=float(bcfg.get("timeout", 120)),
    )


async def _identity_ensure_face_service() -> Response | None:
    """Start the face sidecar through its lifecycle driver (config data, not the service registry)."""
    from gateway.lifecycle_drivers import driver_for_service

    bcfg = dict(_identity_face_cfg())
    if not bcfg:
        return Response(
            content=json.dumps({"error": {"message": "The face service is not configured.", "type": "service_unavailable"}}),
            status_code=503, media_type="application/json",
        )
    driver = driver_for_service("faces", {"faces": bcfg})
    if await driver.ensure_ready(bcfg, timeout_s=HEALTH_CHECK_TIMEOUT):
        return None
    return Response(
        content=json.dumps({"error": {
            "message": "The face service could not be started.", "type": "service_unavailable",
            "code": "backend_unavailable", "service": "faces",
        }}),
        status_code=503, media_type="application/json", headers={"Retry-After": "5"},
    )


def _identity_template() -> tuple[dict[str, Any], dict[str, Any]]:
    """The identity ComfyUI graph and its node bindings, both read from the manifest."""
    global _identity_template_cache
    if _identity_template_cache is None:
        record = GATEWAY_WORKFLOW_REGISTRY.get(IDENTITY_MANIFEST_ID)
        binding = ((record.manifest.get("bindings") or {}).get("gateway") or {}) if record else {}
        artifact = binding.get("workflow")
        if not isinstance(artifact, str):
            raise RuntimeError("identity workflow manifest is missing")
        graph = json.loads((Path(__file__).parent / artifact).read_text(encoding="utf-8"))
        _identity_template_cache = (graph, dict(binding))
    return _identity_template_cache


async def _identity_run_workflow(auth_context: AuthContext, graph: dict[str, Any], uploads: dict[str, bytes]) -> bytes:
    if not COMFY_ENABLED:
        raise RuntimeError("ComfyUI media backend is disabled")
    headers = configured_downstream_headers(auth_context, "comfyui")
    async with httpx.AsyncClient(timeout=httpx.Timeout(COMFY_TIMEOUT, connect=10)) as client:
        for node_id, content in uploads.items():
            name, upload_error = await _upload_comfy_image_bytes(
                client, headers, content, filename=f"identity-{uuid.uuid4().hex}.png"
            )
            if upload_error is not None:
                raise RuntimeError("ComfyUI image upload failed")
            graph[node_id]["inputs"]["image"] = name
        admission = _dispatch_admission_response(
            "image.edit", auth_context=auth_context, service_id="comfyui",
            service_available=COMFY_ENABLED, resource_class="image", queue_key=_MEDIA_JOB_QUEUE_KEY,
        )
        if admission is not None:
            raise identity_api.IdentityUnavailable(admission)
        error, images = await _comfy_run_round(
            client, graph, dict(headers), "identity scene",
            max_wait_s=int(IDENTITY_CFG.get("max_wait_s", 3600)),
        )
    if error is not None:
        try:
            message = json.loads(error.body.decode("utf-8"))["error"]["message"]
        except Exception:  # noqa: BLE001
            message = "ComfyUI returned an error"
        raise RuntimeError(str(message)[:300])
    if not images:
        raise RuntimeError("ComfyUI returned no image")
    return images[0]


def _identity_note_delivery(auth_context: Any, form_fields: Mapping[str, Any]) -> Response | None:
    """Open the delivery context for the native identity route (flat form fields)."""
    _begin_media_delivery(auth_context)
    try:
        # Parse the JSON container first, regardless of multipart field order.
        # SDK bracket fields then extend it rather than replacing its controls.
        controls = multipart_extensions(form_fields.get("extensions"))
        nested = video_inputs.parse_bracket_form([
            ("extensions", controls),
            *((name, value) for name, value in form_fields.items()
              if name != "extensions" and not hasattr(value, "read")),
        ])
    except ValueError as exc:
        return _media_metadata_error(exc)
    return _note_media_metadata_body(nested)


def _identity_store_image(request: Request, auth_context: AuthContext, content: bytes, response_format: str) -> dict[str, Any]:
    delivery = media_delivery.current() or _begin_media_delivery(auth_context)
    mode = delivery.mode
    record = provenance.build_provenance_record(
        receipt=delivery.receipt,
        kind="image",
        workflow_id=IDENTITY_MANIFEST_ID,
        resolved_model=IDENTITY_MODEL_ID,
        backend="comfyui",
        parameters=delivery.parameters or None,
    )
    content = media_delivery.attach_provenance(content, ".png", record)
    encoded, mime_type = encode_image_bytes(content, "png", None)
    image_id = store_image_bytes(encoded, owner_key_hash=_asset_owner_key(auth_context), suffix=".png")
    item: dict[str, Any] = {
        "asset_id": image_id,
        "asset_url": build_signed_asset_url(request, image_id),
        "media_type": mime_type,
    }
    if response_format == "url":
        item["url"] = build_signed_image_url(request, image_id)
    else:
        delivered = media_delivery.deliver_bytes(encoded, ".png", mode)
        item["b64_json"] = base64.b64encode(delivered).decode("utf-8")
    return item



_IDENTITY_JOB_INTENT = "image.identity"
_identity_job_semaphore = asyncio.Semaphore(1)
_identity_job_tasks: set[asyncio.Task] = set()


def _identity_request_shim(request: Request) -> Any:
    """A Request-shaped object that outlives the HTTP request (host headers for signed URLs)."""
    return _JsonBodyRequestShim(
        body={},
        headers=_safe_image_job_headers(request),
        scheme=request.url.scheme or "http",
        netloc=getattr(request.url, "netloc", "") or request.headers.get("host", "127.0.0.1"),
        scope=getattr(request, "scope", {}),
    )


async def _identity_submit_job(
    request: Request, auth_context: AuthContext, req: identity_scene.SceneRequest, response_format: str,
) -> Response:
    """Queue an identity scene as a media job: poll /gateway/v1/media/jobs/{id}, fetch .../content."""
    admission = _media_job_admission_response(
        "image.generate", auth_context=auth_context,
        path=getattr(request.url, "path", identity_api.IDENTITY_PATH),
    )
    if admission is not None:
        return admission
    job = media_jobs.MediaJob(
        intent=_IDENTITY_JOB_INTENT,
        workflow=IDENTITY_MANIFEST_ID,
        backend="comfyui",
        request_id=f"identity-{uuid.uuid4().hex}",
        app_profile=plan_ref(auth_context.identity),
        api_key_name=auth_context.identity.name if auth_context.identity else None,
        metadata={"mode": "async_identity", "attempts": req.attempts, "photos": len(req.photos)},
    )
    job.owner_key_hash = auth_context.identity.key_hash if auth_context.identity else None
    job.app_id = auth_context.identity.app_id if auth_context.identity else None
    media_jobs.create(job, path=media_jobs.DB_PATH)
    shim = _identity_request_shim(request)
    task = asyncio.create_task(_run_identity_job(job.job_id, shim, auth_context, req, response_format))
    _identity_job_tasks.add(task)
    task.add_done_callback(_identity_job_tasks.discard)
    return _image_media_job_response(
        media_jobs.get(job.job_id, audience="internal", path=media_jobs.DB_PATH) or job.to_dict("internal"),
        request,
        status_code=202,
    )


def _identity_job_progress(job_id: str) -> Callable[[str, float, dict[str, Any]], None]:
    def report(phase: str, fraction: float, detail: dict[str, Any]) -> None:
        percent = int(min(99, max(1, fraction * 100)))
        patch = {"phase": phase, **{k: v for k, v in detail.items() if isinstance(v, (str, int, float, bool))}}
        try:
            media_jobs.update_status(
                job_id, media_jobs.STATUS_RUNNING, progress=percent, metadata_patch=patch, path=media_jobs.DB_PATH
            )
            media_jobs.append_event(
                job_id, "progress", {"phase": phase, "status": media_jobs.STATUS_RUNNING, "progress": percent, **patch},
                path=media_jobs.DB_PATH,
            )
        except ValueError:
            pass  # the job was cancelled or finished; a late callback is not an error

    return report


async def _run_identity_job(
    job_id: str, shim: Any, auth_context: AuthContext, req: identity_scene.SceneRequest, response_format: str,
) -> None:
    async with _identity_job_semaphore:
        admission = _media_job_admission_response(
            "image.edit", count_queue=False, auth_context=auth_context,
        )
        if admission is not None:
            _identity_job_failed(job_id, _admission_refusal_message(admission))
            return
        try:
            media_jobs.update_status(
                job_id, media_jobs.STATUS_RUNNING, progress=1,
                metadata_patch={"started_at": int(time.time()), "phase": "queued"}, path=media_jobs.DB_PATH,
            )
        except ValueError:
            return
        req.on_progress = _identity_job_progress(job_id)
        try:
            worker_token = _ADMISSION_WORKER.set(True)
            try:
                result = await app.state.identity_execute(auth_context, req)
            finally:
                _ADMISSION_WORKER.reset(worker_token)
            item = await asyncio.to_thread(_identity_store_image, shim, auth_context, result.image, response_format)
            asset = {k: item[k] for k in ("asset_id", "asset_url", "media_type", "url") if k in item}
            asset.update(identity_api.scene_extras(result))
            media_jobs.update_status(
                job_id, media_jobs.STATUS_SUCCEEDED, progress=100, add_assets=[asset],
                metadata_patch={"completed_at": int(time.time())}, path=media_jobs.DB_PATH,
            )
            media_jobs.append_event(
                job_id, "succeeded", {"phase": "complete", "status": media_jobs.STATUS_SUCCEEDED, "progress": 100},
                path=media_jobs.DB_PATH,
            )
        except identity_api.IdentityUnavailable:
            _identity_job_failed(job_id, "The face service could not be started.")
        except (identity_scene.IdentityError, likeness_module.LikenessError) as exc:
            _identity_job_failed(job_id, str(exc))
        except asyncio.CancelledError:
            _identity_job_failed(job_id, "The gateway stopped before the job finished.")
            raise
        except Exception as exc:  # noqa: BLE001
            _identity_job_failed(job_id, f"identity workflow failed: {type(exc).__name__}")


def _identity_job_failed(job_id: str, message: str) -> None:
    try:
        media_jobs.update_status(
            job_id, media_jobs.STATUS_FAILED, error=message[:500],
            metadata_patch={"completed_at": int(time.time())}, path=media_jobs.DB_PATH,
        )
    except ValueError:
        pass


def _fail_orphaned_identity_jobs() -> int:
    """Identity jobs run in memory only: after a restart a queued or running one cannot continue."""
    failed = 0
    for status_value in (media_jobs.STATUS_RUNNING, media_jobs.STATUS_QUEUED):
        try:
            rows = media_jobs.recent(limit=200, audience="internal", status=status_value, path=media_jobs.DB_PATH)
        except Exception:  # noqa: BLE001
            continue
        for job in rows:
            if job.get("intent") == _IDENTITY_JOB_INTENT:
                _identity_job_failed(str(job.get("job_id")), "The gateway restarted before the job finished; submit it again.")
                failed += 1
    return failed


def _identity_payload_from_media_job(job: Mapping[str, Any]) -> dict[str, Any]:
    payload = _openai_image_payload_from_media_job(job)
    assets = [a for a in (job.get("assets") or []) if isinstance(a, Mapping)]
    if assets:
        extras = {k: assets[0][k] for k in identity_api.EXTRA_KEYS if k in assets[0]}
        payload.update(extras)
    return payload


def _identity_admission(auth: AuthContext, path: str) -> Response | None:
    denied = _enforce_runtime_route_policy(auth, path, policy=_IDENTITY_ROUTE_POLICY)
    if denied is not None:
        return denied
    return _dispatch_admission_response(
        "image.edit", auth_context=auth, service_id="comfyui",
        service_available=COMFY_ENABLED, resource_class="image", queue_key=_MEDIA_JOB_QUEUE_KEY,
    )


identity_api.register_identity_routes(
    app,
    identity_api.IdentityApiDeps(
        authenticate=lambda request, path: _gateway_auth_context(request, path),
        enforce_policy=_identity_admission,
        ensure_face_service=lambda: _identity_ensure_face_service(),
        face_client=lambda: _identity_face_client(),
        run_workflow=lambda auth, graph, uploads: _identity_run_workflow(auth, graph, uploads),
        template=lambda: _identity_template(),
        store_image=lambda request, auth, content, fmt: _identity_store_image(request, auth, content, fmt),
        note_delivery=lambda auth, fields: _identity_note_delivery(auth, fields),
        submit_job=lambda request, auth, req, fmt: _identity_submit_job(request, auth, req, fmt),
    ),
)


ADMIN_STORE.on_credential_revoked = _purge_voices_for_credential


def _resolved_admin_oidc_config() -> tuple[Any, Mapping[str, Any]]:
    """Return the parsed runtime config and the DB state it accepted.

    A rejected DB document must not influence provenance. Keeping the accepted
    document beside the parsed result gives callers one truthful state rather
    than separately re-reading untrusted persisted input.
    """
    try:
        db_value = ADMIN_STORE.get_oidc_config_setting_raw()
    except Exception as exc:  # noqa: BLE001
        print(f"[proxy] admin OIDC db read failed: {exc}", flush=True)
        db_value = None
    if not db_value:
        return ADMIN_OIDC_CONFIG, {}
    try:
        validate_oidc_stored_override(db_value)
        merged = _merged_admin_oidc_config_candidate(db_value)
    except OIDCConfigError as exc:
        print(f"[proxy] WARNING: admin OIDC db config invalid: {exc}", flush=True)
        return ADMIN_OIDC_CONFIG, {}
    if not merged.get("signing_key") and not merged.get("signing_key_env"):
        if ADMIN_SESSION_SIGNING_KEY:
            merged["signing_key"] = ADMIN_SESSION_SIGNING_KEY
    try:
        cfg = load_oidc_config(merged, env=os.environ)
    except OIDCConfigError as exc:
        print(f"[proxy] WARNING: admin OIDC db config invalid: {exc}", flush=True)
        return ADMIN_OIDC_CONFIG, {}
    # Preserve the established signing key/cookie so admin sessions survive
    # DB-driven provider changes.
    return (
        replace(
            cfg,
            signing_key=ADMIN_SESSION_SIGNING_KEY or cfg.signing_key,
            cookie=ADMIN_OIDC_CONFIG.cookie,
        ),
        dict(db_value),
    )


def _effective_admin_oidc_config():
    """Return OIDC configuration with the owner's sign-in choice applied."""
    cfg = _resolved_admin_oidc_config()[0]
    setting = admin_store.get_operator_setting("sign_in", path=ADMIN_STORE.path)
    if setting and setting["value"].get("mode") == "built-in":
        return replace(cfg, enabled=False)
    return cfg


def _merged_admin_oidc_config_candidate(db_value: Mapping[str, Any] | None) -> dict[str, Any]:
    """Merge bootstrap and DB overrides using canonical explicit clears."""
    merged = dict(_bootstrap_admin_oidc_cfg())
    for key, value in (db_value or {}).items():
        # Empty string (scalar) and empty list (list) are deliberate DB
        # overrides. Omission is the only preserve operation.
        merged[key] = value
    if not merged.get("signing_key") and not merged.get("signing_key_env") and ADMIN_SESSION_SIGNING_KEY:
        merged["signing_key"] = ADMIN_SESSION_SIGNING_KEY
    return merged


def _validate_admin_oidc_db_candidate(db_value: Mapping[str, Any]) -> bool:
    """Reject a write unless the live runtime parser accepts its merge."""
    validate_oidc_stored_override(db_value)
    return load_oidc_config(_merged_admin_oidc_config_candidate(db_value), env=os.environ).enabled


async def _admin_oidc_config_with_discovery():
    cfg = _effective_admin_oidc_config()
    if not cfg.enabled:
        return cfg
    if cfg.authorization_endpoint and cfg.token_endpoint and cfg.jwks_uri:
        return cfg
    discovery_url = f"{cfg.issuer.rstrip('/')}/.well-known/openid-configuration"
    async with httpx.AsyncClient(timeout=10) as client:
        response = await client.get(discovery_url)
        response.raise_for_status()
        metadata = response.json()
    return replace(
        cfg,
        authorization_endpoint=cfg.authorization_endpoint
        or str(metadata.get("authorization_endpoint", "")),
        token_endpoint=cfg.token_endpoint or str(metadata.get("token_endpoint", "")),
        jwks_uri=cfg.jwks_uri or str(metadata.get("jwks_uri", "")),
    )


async def _oidc_exchange_code(code: str, *, config, pkce: PKCEPair) -> dict[str, Any]:
    async with httpx.AsyncClient(timeout=20) as client:
        response = await client.post(
            config.token_endpoint,
            data={
                "grant_type": "authorization_code",
                "code": code,
                "redirect_uri": config.redirect_uri,
                "client_id": config.client_id,
                "client_secret": config.client_secret,
                "code_verifier": pkce.verifier,
            },
            headers={"accept": "application/json"},
        )
        response.raise_for_status()
        payload = response.json()
    if not isinstance(payload, dict):
        raise ValueError("OIDC token endpoint returned non-object JSON")
    return payload


async def _oidc_verify_id_token(id_token: str, *, config) -> Mapping[str, Any]:
    return await ADMIN_OIDC_JWKS_CACHE.verify(
        id_token, uri=config.jwks_uri, leeway=config.clock_skew_seconds,
    )


def _existing_admin_grants(*, include_revoked: bool = False) -> dict[str, str]:
    """Presence-only bootstrap guard; email is never an identity key."""
    return {str(row["id"]): str(row["role"])
            for row in admin_store.list_admin_roles(include_revoked=include_revoked, path=ADMIN_STORE.path)}


def _end_provider_access_after_refusal(issuer: str, claims: Mapping[str, Any]) -> None:
    """Revoke what the identity provider gave a person whose sign-in was refused.

    Removing someone from the admin group makes their next sign-in fail the
    sign-in rules, and that check runs before roles are reconciled. Without
    this, their grant and their sessions would last until they expire. Grants
    the owner gave by hand stay; the provider's grants, every session and every
    MCP connection end, and their personal keys pause until a sign-in succeeds.
    The person is found by (issuer, subject) and is never created here.
    """
    user = admin_store.find_oidc_user(issuer, str(claims.get("sub") or ""), path=ADMIN_STORE.path)
    if user is None:
        return
    _end_provider_access(str(user["id"]))


def _end_provider_access(person_id: str) -> None:
    """End what the rules gave a person who is now kept out (see the refusal above).

    The owner is never cut off here: the provider gives the owner nothing, and a
    provider that misbehaves must not be able to lock the owner out.
    """
    if "owner" in admin_store.effective_admin_roles("user", person_id, path=ADMIN_STORE.path):
        return
    # First, so a failure in any later step cannot leave the refusal unrecorded.
    # Their personal keys pause until a sign-in succeeds (reversible).
    accounts.record_signin_refusal(person_id, path=ADMIN_STORE.path)
    admin_store.reconcile_oidc_admin_roles(person_id, set(), path=ADMIN_STORE.path)
    accounts.revoke_person_sessions(person_id, path=ADMIN_STORE.path)
    # Connections made through MCP sign-in can refresh for up to 90 days.
    MCP_OAUTH.deps.store.revoke_person_grants(person_id, "sign_in_refused")


def _end_provider_access_in(tx: admin_store.Transaction, person_id: str) -> None:
    """:func:`_end_provider_access` for a Sign-in save: its steps join the save's transaction.

    The save is all or nothing, so no step here is written first for safety; what a
    rollback cannot undo (the person's MCP connections) runs after the commit.
    """
    if "owner" in admin_store.effective_admin_roles("user", person_id, path=ADMIN_STORE.path):
        return
    accounts.record_signin_refusal_in(tx.conn, person_id)
    admin_store.reconcile_oidc_admin_roles_in(tx.conn, person_id, set())
    accounts.revoke_person_sessions_in(tx.conn, person_id)
    tx.after_commit(lambda: MCP_OAUTH.deps.store.revoke_person_grants(person_id, "sign_in_refused"))


def _safe_admin_return_to(value: str | None, *, default: str = "/") -> str:
    return safe_browser_return_to(value, default=default)


def _login_url(*, return_to: str) -> str:
    safe_return_to = _safe_admin_return_to(return_to, default="/")
    return f"/login?return_to={quote(safe_return_to, safe='')}"


def _path_with_query(request: Request) -> str:
    query = f"?{request.url.query}" if request.url.query else ""
    return f"{request.url.path}{query}"


def _admin_auth_failure_response(
    request: Request,
    exc: AdminAuthError,
    *,
    return_to: str,
) -> Response:
    # A browser should never see a raw JSON 401/403 dead end on admin pages.
    # Only genuine API callers presenting a Bearer token get the JSON error.
    is_browser = not request.headers.get("authorization")
    if is_browser and exc.status_code == 401:
        return RedirectResponse(
            _login_url(return_to=return_to), status_code=302
        )
    if is_browser and exc.status_code == 403:
        return RedirectResponse("/", status_code=302)
    return Response(
        content=json.dumps({
            "error": {
                "code": exc.code,
                "message": exc.message,
            }
        }),
        status_code=exc.status_code,
        media_type="application/json",
        headers={"WWW-Authenticate": "Bearer"},
    )


def _browser_admin_session_signing_key() -> bytes | None:
    return ADMIN_AUTH.signing_key or ADMIN_SESSION_SIGNING_KEY


def _browser_admin_cookie_config():
    return ADMIN_AUTH.cookie or ADMIN_OIDC_CONFIG.cookie


def _oidc_session_from_request(request: Request):
    signing_key = _browser_admin_session_signing_key()
    if not signing_key:
        return None
    cookie = _browser_admin_cookie_config()
    raw = request.cookies.get(cookie.name)
    if not raw:
        return None
    try:
        session = decode_session_cookie(
            raw,
            signing_key=signing_key,
        )
        if not accounts.session_allowed(session.subject, session.session_id, path=ADMIN_STORE.path):
            return None
        return session
    except SessionError:
        return None


def _csrf_token_for_oidc_session(session) -> str:
    signing_key = ADMIN_AUTH.signing_key or ADMIN_SESSION_SIGNING_KEY
    if not signing_key:
        return ""
    try:
        return csrf_token_for_session(
            session,
            signing_key=signing_key,
        )
    except SessionError:
        return ""


def _require_user_session(request: Request):
    session = _oidc_session_from_request(request)
    if session is None:
        raise UserPortalError(
            "login_required",
            "Sign in before managing account keys",
            status_code=401,
        )
    return session


def _user_action_response_error(exc: UserPortalError) -> JSONResponse:
    return JSONResponse(
        status_code=exc.status_code,
        content={"error": {"code": exc.code, "message": exc.message}},
    )


def _require_user_action_header(request: Request, session) -> JSONResponse | None:
    if request.headers.get("x-azizam-user-action") == "1":
        expected = _csrf_token_for_oidc_session(session)
        supplied = request.headers.get("x-azizam-csrf") or ""
        if expected and hmac.compare_digest(supplied, expected):
            return None
        return JSONResponse(
            status_code=403,
            content={
                "error": {
                    "code": "user_csrf_required",
                    "message": "valid x-azizam-csrf header required",
                }
            },
        )
    return JSONResponse(
        status_code=403,
        content={
            "error": {
                "code": "user_action_header_required",
                "message": "x-azizam-user-action header required",
            }
        },
    )


def _app_access(app_id: str) -> EffectiveAccess | None:
    """The plans an App runs under right now (admin Check access)."""
    with admin_store.runtime_auth_connection(ADMIN_STORE.path) as conn:
        row = admin_store.runtime_access_row(conn, app_id=app_id)
    if row is None:
        return None
    return identity_from_access_row(row, key_hash="", name="", person_id=None).access


def _app_identity(app_id: str | None) -> tuple[str | None, str | None]:
    """The ``(app_id, person_id)`` a request from this App carries, for Check access.

    A request carries its App. It carries a person only when the App is a
    personal App and its owner made the key (``person_for_app_credential``);
    the owner's own key is the one Check access shows. Category rules that
    govern a person or an App by name read these two ids.
    """
    if not app_id:
        return None, None
    with admin_store.runtime_auth_connection(ADMIN_STORE.path) as conn:
        row = admin_store.runtime_access_row(conn, app_id=app_id)
    if row is None:
        return None, None
    owner = row.get("owner_user_id")
    person_id = person_for_app_credential({"kind": row.get("app_kind"), "owner_user_id": owner},
                                          {"created_by": owner})
    return str(row["app_id"]), person_id


async def _access_preview(access: EffectiveAccess, *, full_detail: bool = True,
                          app_id: str | None = None) -> dict[str, Any]:
    """Every Models page entry with what ``access`` can and cannot use (admin Check access).

    Decided by the discovery policy view (``_capability_for_access``), so the
    preview cannot drift from what the Models page and requests enforce. That
    view runs ``evaluate`` and the category gate, the code a request runs.
    ``full_detail`` is the owner's view; an administrator is not told the name
    of a restricted category (only the owner may open Categories). For an App
    the identity carries the App's id and person, as its requests do, so a
    category rule that governs them by name judges the preview as it judges a
    request. A plan alone has no person or App.
    """
    from gateway.access_preview import build_access_preview

    plans = (access.person_plan, access.app_plan)

    def assemble() -> dict[str, Any]:
        who_app, who_person = _app_identity(app_id)
        auth_context = AuthContext(identity=AuthIdentity(
            name="access-preview", key_hash="", access=access, app_id=who_app, person_id=who_person))
        viewed = _viewed_gateway_capabilities(auth_context)
        permitted = [cap for cap in viewed if cap.policy_available is not False]
        denied = [cap for cap in viewed if cap.policy_available is False]
        # A decision always records why it denied. A denial with no reason is the
        # gateway alias projection (never served; the catalog rebuilds aliases
        # from their targets), so nothing offers it and a plan cannot be blocked from it.
        offered = [replace(cap, policy_available=True, policy_reasons=(), policy_rule=None)
                   for cap in viewed if cap.policy_available is not False or cap.policy_reasons]
        service_records = _workflow_availability_services(ADMIN_STORE.get_service_registry())
        return build_access_preview(
            offered=_models_catalog_from([offered], service_records=service_records),
            permitted=_models_catalog_from([permitted], service_records=service_records),
            denied=denied,
            allowed=permitted,
            plan_names={plan.id: plan.name for plan in plans if plan is not None},
            category_names=category_enforcement.category_labels(),
            detail="full" if full_detail else "limited",
        )

    return await asyncio.to_thread(assemble)


class _LiveLiteLLMKeyClient:
    """Admin key client that re-resolves the runtime config on every call.

    The registry (and thus the sidecar base_url / master key) can change while
    the gateway runs. Rather than freeze a client at boot, this thin facade
    builds a fresh :class:`LiteLLMKeyAdminClient` from the live
    ``_litellm_runtime_config()`` for each operation, so the admin key panel
    always reflects the current substrate. It exposes the duck-typed surface
    ``gateway.admin_api`` expects (``enabled`` + the async ops). The referenced
    globals resolve at call time (request time), so defining this above
    ``_litellm_runtime_config`` in source order is fine.
    """

    @property
    def enabled(self) -> bool:
        return LiteLLMKeyAdminClient(_litellm_runtime_config()).enabled

    async def list_keys(self, **kwargs):
        return await LiteLLMKeyAdminClient((await asyncio.to_thread(_litellm_runtime_config))).list_keys(**kwargs)

    async def generate_key(self, spec):
        return await LiteLLMKeyAdminClient((await asyncio.to_thread(_litellm_runtime_config))).generate_key(spec)

    async def key_info(self, key):
        return await LiteLLMKeyAdminClient((await asyncio.to_thread(_litellm_runtime_config))).key_info(key)

    async def delete_keys(self, **kwargs):
        return await LiteLLMKeyAdminClient((await asyncio.to_thread(_litellm_runtime_config))).delete_keys(**kwargs)


