# Owner-defined categories and plans (design v3). Active rules tighten the
# runtime decision in runtime_auth.evaluate_and_apply (category_enforcement).
def _category_service_catalog() -> list[dict[str, Any]]:
    """Configured policy targets, independent of the rules being edited.

    Reuse the routing catalogs without health probes or caller-policy filtering.
    Stable chat aliases are rewritten before policy, so publish their targets.
    """
    registry = ADMIN_STORE.get_service_registry()
    entries: dict[str, dict[str, Any]] = {}

    def add(stem: str, label: str | None, kind: str, intent: str) -> None:
        if not stem:
            return
        entry = entries.setdefault(stem, {
            "stem": stem, "label": label or stem, "kind": kind, "capabilities": [],
        })
        if intent not in entry["capabilities"]:
            entry["capabilities"].append(intent)

    for record in GATEWAY_WORKFLOW_REGISTRY.records():
        if record.supported_backends:
            add(record.id, record.manifest.get("display_name"), "workflow", record.intent)

    backends = service_registry.runtime_backends(registry)
    # Use the execution catalog's public names, including provider prefixes,
    # and its enabled-model filtering before deriving protocol capabilities.
    for model, (service, record) in litellm_public_model_records(registry).items():
        routed = {**service, "config": {**service["config"], "models": [{"id": model}]}}
        intents = {capability.intent for capability in registered_model_capabilities(
            {"services": {service["id"]: routed}})}
        # A declared OpenAI chat protocol is sufficient for an executable route;
        # older service records need not repeat it in capability metadata.
        if not intents:
            intents.add("chat.completions")
        label = record.get("display_name") or record.get("title") or model
        for intent in sorted(intents):
            add(model, label, "model", intent)
    capabilities = build_local_capabilities(
        config, backends=backends,
        enabled_flags={"images": False, "videos": False, "audio": False},
    )
    for capability in capabilities:
        if not capability.model or capability.workflow:
            continue
        if capability.backend not in backends or not backends[capability.backend].get("enabled", True):
            continue
        add(capability.model, capability.title, "model", capability.intent)
        # The role catalog advertises both forms; chat accepts the bare name.
        if capability.model.startswith("role:"):
            add(capability.model.removeprefix("role:"), capability.title, "model", capability.intent)

    for capability in build_alias_capabilities(_gateway_aliases_provider()):
        # Media aliases reach policy as a manifest workflow, listed above.
        if capability.intent not in {"chat.completions", "text.embeddings"}:
            continue
        operation = "embeddings" if capability.intent == "text.embeddings" else "chat"
        alias = resolve_stable_alias(operation, capability.model)
        if alias is not None:
            target = _provider_alias_model(alias.target, alias.service, alias.engine_spec or {})
            add(target, capability.title, "model", capability.intent)

    # Speech and transcription requests are judged on the engine their model name
    # resolves to, so those engines are what an owner files or grants.
    name_views = _gateway_aliases_provider()
    for operation, intents in (("speech", (INTENT_SPEECH,)),
                               ("transcriptions", (INTENT_TRANSCRIPTIONS, INTENT_TRANSLATIONS))):
        for engine in name_views.get(operation, {}).get("engines") or ():
            for intent in intents:
                add(str(engine["engine"]), engine.get("display_name") or str(engine["engine"]), "model", intent)

    for capability in DECISION_RUNTIME.capabilities():
        # Like chat aliases, decision names are judged on the engine slot they
        # reach, so the slot is what an owner files or grants.
        slot = next((tag.removeprefix("resolves_to:") for tag in capability.tags
                     if tag.startswith("resolves_to:")), capability.model)
        add(slot, capability.title, "model", capability.intent)
    decision_providers = decision_provider_execution.systemone_providers(registry)
    openai_decisions = decision_provider_execution.openai_decisions_provider(registry)
    if openai_decisions is not None:
        decision_providers.append(openai_decisions)
    for provider in decision_providers:
        for model in decision_provider_execution.catalog_models(provider):
            capability = decision_provider_execution.capability_for(provider, model)
            add(model, capability.title, "model", capability.intent)

    for entry in entries.values():
        entry["capabilities"].sort()
    return [entries[stem] for stem in sorted(entries)]


