def _admin_oidc_config_snapshot() -> Mapping[str, Any] | None:
    bootstrap = _bootstrap_admin_oidc_cfg()
    cfg, accepted_db_setting = _resolved_admin_oidc_config()
    if not accepted_db_setting and not (
        cfg.enabled
        or cfg.display_name
        or cfg.issuer
        or cfg.client_id
        or cfg.redirect_uri
        or cfg.authorization_endpoint
        or cfg.token_endpoint
        or cfg.jwks_uri
    ):
        return None
    field_sources: dict[str, str] = {}
    for field_name in OIDC_PROVIDER_FIELDS:
        if field_name in accepted_db_setting:
            field_sources[field_name] = "database"
        elif field_name in bootstrap or (
            field_name == "client_secret" and bootstrap.get("client_secret_env")
        ):
            field_sources[field_name] = "bootstrap"
        else:
            field_sources[field_name] = "runtime_default"
    configured_sources = set(field_sources.values()) - {"runtime_default"}
    source = "merged" if len(configured_sources) > 1 else (
        next(iter(configured_sources), "runtime_default")
    )
    return {
        "source": source,
        "apply_mode": "live",
        "provenance": {"summary": source, "fields": field_sources},
        "enabled": cfg.enabled,
        "issuer": cfg.issuer,
        "client_id": cfg.client_id,
        "client_secret": "<redacted>" if cfg.client_secret else "",
        "client_secret_set": bool(cfg.client_secret),
        "display_name": cfg.display_name,
        "redirect_uri": cfg.redirect_uri,
        "scopes": list(cfg.scopes),
        "authorization_endpoint": cfg.authorization_endpoint,
        "token_endpoint": cfg.token_endpoint,
        "jwks_uri": cfg.jwks_uri,
        "clock_skew_seconds": cfg.clock_skew_seconds,
        "groups_claim": cfg.groups_claim,
        "updated_at": (
            (ADMIN_STORE.get_oidc_config_setting() or {}).get("updated_at")
            if accepted_db_setting else None
        ),
    }


def _operator_override_docs() -> dict[str, Any]:
    try:
        overrides = ADMIN_STORE.operator_overrides()
    except Exception as exc:  # noqa: BLE001
        print(f"[proxy] admin operator override read failed: {exc}", flush=True)
        return {"service_availability": {}, "media_job_admission": {}}
    if not isinstance(overrides, Mapping):
        return {"service_availability": {}, "media_job_admission": {}}
    return {
        "service_availability": (
            overrides.get("service_availability")
            if isinstance(overrides.get("service_availability"), Mapping)
            else {}
        ),
        "media_job_admission": (
            overrides.get("media_job_admission")
            if isinstance(overrides.get("media_job_admission"), Mapping)
            else {}
        ),
    }


def _operator_service_availability_overrides() -> dict[str, dict[str, Any]]:
    raw = _operator_override_docs().get("service_availability")
    if not isinstance(raw, Mapping):
        return {}
    out: dict[str, dict[str, Any]] = {}
    for key, value in raw.items():
        if isinstance(value, Mapping):
            out[str(key)] = dict(value)
    return out


def _service_availability_response(
    service_id: str,
    *,
    service_label: str | None = None,
) -> Response | None:
    override = _operator_service_availability_overrides().get(service_id, {})
    if not isinstance(override, Mapping):
        return None
    state = str(override.get("state") or "available").strip().lower()
    if state not in {"disabled", "maintenance", "draining"}:
        return None

    label = service_label or service_id
    message = str(override.get("reason") or "").strip() or f"{label} is {state}."
    retry_after = _optional_int_config(override, "retry_after_seconds") or 10
    return Response(
        content=json.dumps({
            "error": {
                "message": message,
                "type": "service_unavailable",
                "code": "backend_unavailable",
                "service": service_id,
                "state": state,
            }
        }),
        status_code=503,
        media_type="application/json",
        headers={"Retry-After": str(retry_after)},
    )


def _operator_media_job_admission_overrides() -> dict[str, Any]:
    raw = _operator_override_docs().get("media_job_admission")
    return dict(raw) if isinstance(raw, Mapping) else {}


def _effective_media_job_admission_cfg() -> dict[str, Any]:
    cfg = dict(MEDIA_JOB_ADMISSION_CFG) if isinstance(MEDIA_JOB_ADMISSION_CFG, Mapping) else {}
    overrides = _operator_media_job_admission_overrides()
    for key in (
        "disabled_intents",
        "disabled_resource_classes",
        "reserved_tokens",
        "max_queue_depth",
        "max_app_concurrency",
        "retry_after_seconds",
        "queue_retry_after_seconds",
        "scan_limit",
    ):
        if key in overrides:
            cfg[key] = overrides[key]
    return cfg


async def _start_browser_login(request: Request, *, default_return_to: str) -> Response:
    if not _effective_admin_oidc_config().enabled:
        # OIDC is not configured. Browser users who land on /login should go
        # to /setup, where local-owner sign-in or first-run creation lives.
        # API callers keep the explicit machine-readable 501 below.
        if not request.headers.get("authorization"):
            if not _owner_or_admin_exists():
                return RedirectResponse("/setup/", status_code=302)
            target = _safe_admin_return_to(request.query_params.get("return_to"), default=default_return_to)
            return RedirectResponse(f"/sign-in/?return_to={quote(target, safe='')}", status_code=302)
        return Response(
            content=(
                "OIDC browser login is not configured on this gateway yet. "
                "Open /setup/ to see what to configure. "
                "(`python proxy.py generate-admin-key <name>` is supported "
                "for recovery and headless automation, not normal first-run "
                "setup.)"
            ),
            status_code=501,
            media_type="text/plain; charset=utf-8",
        )
    try:
        client_ip = resolve_real_client_ip(request)
        if client_ip is None:
            raise accounts.AccountError("invalid_client_ip", "Cannot verify the sign-in client address.", 400)
        accounts.throttle_oidc(str(client_ip), path=ADMIN_STORE.path)
        cfg = oidc_config_for_public_base(
            await _admin_oidc_config_with_discovery(),
            instance_settings(ADMIN_STORE.path, _instance_presentation_defaults())["base_url"],
        )
        return_to = _safe_admin_return_to(
            request.query_params.get("return_to"),
            default=default_return_to,
        )
        callback = urlsplit(cfg.redirect_uri)
        # ASGI sees HTTP behind TLS ingress; only compare the host and port.
        if not callback_host_matches(request, cfg.redirect_uri):
            return RedirectResponse(
                f"{callback.scheme}://{callback.netloc}/login?return_to={quote(return_to, safe='')}",
                status_code=302, headers={"cache-control": "no-store"},
            )
        return begin_browser_login(cfg, ADMIN_OIDC_STATES, return_to=return_to)
    except accounts.AccountError as exc:
        return JSONResponse({"error": {"code": exc.code, "message": exc.message}}, status_code=exc.status,
                            headers={"retry-after": "60"} if exc.status == 429 else {})
    except Exception as e:  # noqa: BLE001
        return _browser_signin_failure(
            request, return_to=request.query_params.get("return_to"),
        ) or Response(
            content=f"OIDC login failed to start: {str(e)[:200]}",
            status_code=500,
            media_type="text/plain; charset=utf-8",
        )


def _owner_or_admin_exists() -> bool:
    """True if any non-revoked owner or admin role is assigned.

    Covers both OIDC user roles and service-account admin keys, since either
    is enough to manage the gateway.
    """
    return bool(_existing_admin_grants())


def _admin_credential_active(record: Mapping[str, Any]) -> bool:
    if record.get("revoked_at"):
        return False
    expires_at = record.get("expires_at")
    return expires_at is None or int(expires_at) > int(time.time())


def _setup_admin_counts() -> tuple[int, int]:
    apps = admin_store.list_apps(path=ADMIN_STORE.path)
    credentials = admin_store.list_credentials(path=ADMIN_STORE.path)
    active_runtime_keys = sum(
        1
        for credential in credentials
        if credential.get("subject_kind") == "app"
        and _admin_credential_active(credential)
    )
    return len([app for app in apps if not app.get("disabled_at")]), active_runtime_keys


def _setup_personal_app_for_session(session) -> Mapping[str, Any] | None:
    if session is None:
        return None
    subject_kind, subject_id = session_admin_role_subject(
        str(getattr(session, "subject", "") or "")
    )
    if subject_kind != "user":
        return None
    for app in admin_store.list_apps_for_user(
        subject_id,
        path=ADMIN_STORE.path,
    ):
        if app.get("kind") == "personal" and not app.get("disabled_at"):
            return app
    return None


def _setup_active_key_count_for_app(app_id: str | None) -> int:
    if not app_id:
        return 0
    return len(
        admin_store.list_active_credentials(
            subject_kind="app",
            app_id=str(app_id),
            path=ADMIN_STORE.path,
        )
    )


def _setup_doctor_items(
    *,
    signed_in_admin: bool,
    app_count: int,
    active_key_count: int,
    status_payload: Mapping[str, Any] | None,
) -> list[dict[str, str]]:
    items: list[dict[str, str]] = [
        {
            "label": "Owner/Admin",
            "state": "ok" if _owner_or_admin_exists() else "bad",
            "detail": "Control-plane owner or admin exists.",
        },
        {
            "label": "Browser session",
            "state": "ok" if signed_in_admin else "warn",
            "detail": (
                "This browser can administer the gateway."
                if signed_in_admin
                else "Sign in or claim with an oak_ admin key."
            ),
        },
        {
            "label": "Runtime App key",
            "state": "ok" if active_key_count else "warn",
            "detail": (
                f"{active_key_count} active runtime key(s) across {app_count} App(s)."
                if active_key_count
                else "Create a first App key before connecting SDKs or clients."
            ),
        },
        _setup_config_source_item(),
    ]
    if not status_payload:
        items.append(
            {
                "label": "Gateway health",
                "state": "warn",
                "detail": "Status cache was unavailable; use /status/raw for operator detail.",
            }
        )
        return items
    health_state = "ok" if not status_payload.get("error") else "warn"
    items.append(
        {
            "label": "Gateway health",
            "state": health_state,
            "detail": "Health/status cache loaded." if health_state == "ok" else "Status cache reported an error.",
        }
    )
    backends = status_payload.get("backends") if isinstance(status_payload, Mapping) else []
    if isinstance(backends, list) and backends:
        up = sum(1 for row in backends if isinstance(row, Mapping) and row.get("status") == "up")
        degraded = sum(
            1
            for row in backends
            if isinstance(row, Mapping) and row.get("status") == "degraded"
        )
        down = sum(1 for row in backends if isinstance(row, Mapping) and row.get("status") == "down")
        state = "ok" if down == 0 and degraded == 0 else ("warn" if up else "bad")
        items.append(
            {
                "label": "Backends",
                "state": state,
                "detail": f"{up} up, {degraded} degraded, {down} down.",
            }
        )
    return items


def _setup_config_source_item() -> dict[str, str]:
    return {
        "label": "Config source of truth",
        "state": "ok",
        "detail": "Apps, keys, access plans and people are admin.db-backed.",
    }


def _setup_admin_context(request: Request) -> AdminContext | None:
    try:
        actor = ADMIN_AUTH(request)
    except AdminAuthError:
        return None
    return actor if actor.is_admin else None


async def _setup_page_response(
    request: Request,
    *,
    claim_error: str | None = None,
    app_error: str | None = None,
    create_error: str | None = None,
    create_email: str | None = None,
    login_error: str | None = None,
    login_email: str | None = None,
    one_time_key: Mapping[str, Any] | None = None,
    status_code: int = 200,
) -> Response:
    session = (await asyncio.to_thread(_oidc_session_from_request, request))
    is_admin_signed_in = False
    actor_label: str | None = None
    if session is not None and session.role in {"owner", "admin", "superadmin"}:
        is_admin_signed_in = True
        actor_label = session.email or session.subject or None
    app_count, active_key_count = _setup_admin_counts()
    personal_app = _setup_personal_app_for_session(session) if is_admin_signed_in else None
    personal_app_name = (
        str(personal_app.get("name") or "") if personal_app is not None else None
    )
    personal_active_key_count = _setup_active_key_count_for_app(
        str(personal_app.get("id") or "") if personal_app is not None else None
    )
    status_payload: Mapping[str, Any] | None = None
    if is_admin_signed_in:
        try:
            status_payload = await status_endpoint.get_cached_status(config)
        except Exception as e:  # noqa: BLE001
            print(f"[proxy] setup status enrichment failed: {e}", flush=True)
            status_payload = None
    brand_label, brand_wordmark = _brand_settings()
    body = render_setup_page(
        brand=brand_label,
        wordmark=brand_wordmark,
        owner_or_admin_exists=_owner_or_admin_exists(),
        oidc_enabled=_effective_admin_oidc_config().enabled,
        login_url=_login_url(return_to="/setup/"),
        is_admin_signed_in=is_admin_signed_in,
        actor_label=actor_label,
        logout_url="/auth/logout-confirm" if is_admin_signed_in else None,
        claim_error=claim_error,
        can_claim_with_admin_key=bool(_browser_admin_session_signing_key()),
        create_error=create_error,
        create_email=create_email,
        login_error=login_error,
        login_email=login_email,
        csrf_token=_csrf_token_for_oidc_session(session) if session else "",
        public_base_url=_public_base_url(request) or "http://127.0.0.1:5000",
        app_count=app_count,
        active_key_count=active_key_count,
        personal_app_name=personal_app_name,
        personal_active_key_count=personal_active_key_count,
        app_error=app_error,
        one_time_key=one_time_key,
        doctor_items=_setup_doctor_items(
            signed_in_admin=is_admin_signed_in,
            app_count=app_count,
            active_key_count=active_key_count,
            status_payload=status_payload,
        )
        if is_admin_signed_in
        else [],
    )
    return Response(
        content=body,
        status_code=status_code,
        media_type="text/html; charset=utf-8",
        headers={"cache-control": "no-store"},
    )


@app.get("/setup/console", include_in_schema=False)
async def setup_console(request: Request):
    """Server-rendered setup console for headless and recovery use.

    The setup page is the web app's /setup/. This console keeps the tools the
    web page does not have (mint a key from the console, gateway doctor).
    """
    return await _setup_page_response(request)


async def _setup_form_values(request: Request) -> dict[str, str]:
    content_type = request.headers.get("content-type", "")
    if content_type.startswith("application/json"):
        try:
            body = await request.json()
        except Exception:
            body = {}
        if not isinstance(body, Mapping):
            return {}
        return {str(key): str(value).strip() for key, value in body.items()}
    raw = (await request.body()).decode("utf-8", errors="replace")
    parsed = parse_qs(raw, keep_blank_values=True)
    return {key: str((values or [""])[0]).strip() for key, values in parsed.items()}


async def _setup_claim_admin_key_value(request: Request) -> str:
    return (await _setup_form_values(request)).get("admin_key", "")


@app.post("/setup/claim", include_in_schema=False)
async def setup_claim_admin_key(request: Request):
    signing_key = _browser_admin_session_signing_key()
    if not signing_key:
        return await _setup_page_response(
            request,
            claim_error=(
                "Browser admin sessions are unavailable: this gateway "
                "cannot read or write its session signing key file."
            ),
            status_code=500,
        )
    admin_key = await _setup_claim_admin_key_value(request)
    if admin_key.startswith("opk_"):
        return await _setup_page_response(
            request,
            claim_error=(
                "That looks like a runtime App key (opk_). Setup needs an "
                "admin key (oak_) from generate-admin-key."
            ),
            status_code=400,
        )
    if not admin_key.startswith("oak_"):
        return await _setup_page_response(
            request,
            claim_error="Paste the oak_ admin key printed by generate-admin-key.",
            status_code=400,
        )
    credential = admin_store.find_credential_by_hash(
        hash_api_key(admin_key),
        path=ADMIN_STORE.path,
    )
    if credential is None or not _admin_credential_active(credential):
        return await _setup_page_response(
            request,
            claim_error="That admin key was not found, expired, or has been revoked.",
            status_code=400,
        )
    subject_kind = str(credential.get("subject_kind") or "")
    subject_id = str(credential.get("subject_id") or "")
    if subject_kind not in {"user", "service_account"} or not subject_id:
        return await _setup_page_response(
            request,
            claim_error="That key is not an admin key.",
            status_code=400,
        )
    role_names = admin_store.effective_admin_roles(
        subject_kind, subject_id, path=ADMIN_STORE.path,
    )
    if "owner" in role_names:
        role = "owner"
    elif "admin" in role_names or "superadmin" in role_names:
        role = "admin"
    else:
        return await _setup_page_response(
            request,
            claim_error="That admin key does not have owner or admin permission.",
            status_code=403,
        )
    session_subject = (
        service_account_session_subject(subject_id)
        if subject_kind == "service_account"
        else subject_id
    )
    session_email = (
        str(credential.get("display_name") or "admin key")
        if subject_kind == "service_account"
        else "local-admin"
    )
    admin_store.record_audit(
        "setup.claim",
        actor_kind=subject_kind,
        actor_id=subject_id,
        actor_label=session_email,
        target_kind=subject_kind,
        target_id=subject_id,
        metadata={"role": role, "credential_prefix": credential.get("prefix")},
        path=ADMIN_STORE.path,
    )
    session = session_from_claims(
        {"sub": session_subject, "email": session_email},
        role=role,
        cookie=_browser_admin_cookie_config(),
    )
    response = RedirectResponse("/", status_code=303)
    cookie = _browser_admin_cookie_config()
    response.set_cookie(
        cookie.name,
        encode_session_cookie(session, signing_key=signing_key),
        max_age=cookie.max_age_seconds,
        secure=cookie.secure,
        httponly=cookie.http_only,
        samesite=cookie.same_site,
        path=cookie.path,
        domain=cookie.domain,
    )
    return response


# ---------------------------------------------------------------------------
# Local owner: web-first claim + sign-in
# ---------------------------------------------------------------------------


_LOCAL_OWNER_ISSUER = "local"


def _normalize_local_email(value: str) -> str:
    return (value or "").strip().lower()


def _issue_browser_admin_session(
    *,
    user_id: str,
    email: str,
    role: str,
    signing_key: bytes,
    redirect_to: str = "/setup/",
) -> Response:
    cookie = _browser_admin_cookie_config()
    session = session_from_claims(
        {"sub": user_id, "email": email},
        role=role,
        cookie=cookie,
    )
    accounts.initialize(ADMIN_STORE.path)
    accounts.register_session(user_id, session.session_id, int(session.expires_at), path=ADMIN_STORE.path)
    response = RedirectResponse(redirect_to, status_code=303)
    response.set_cookie(
        cookie.name,
        encode_session_cookie(session, signing_key=signing_key),
        max_age=cookie.max_age_seconds,
        secure=cookie.secure,
        httponly=cookie.http_only,
        samesite=cookie.same_site,
        path=cookie.path,
        domain=cookie.domain,
    )
    return response


def _origin_header_allowed_for_request(request: Request) -> bool:
    # A same-origin attacker hostname can rebind to a private address. Setup
    # accepts literal host addresses, localhost, or the configured public host.
    public_base = instance_settings(ADMIN_STORE.path, _instance_presentation_defaults()).get("base_url")
    try:
        public = urlsplit(public_base) if public_base else None
        host = request.url.hostname
    except ValueError:
        return False
    try:
        literal_host = _normalize_ip(host) if host and host != "localhost" else None
    except ValueError:
        literal_host = None
    allowed_host = host == "localhost" or literal_host is not None or bool(
        public and public.scheme in {"http", "https"} and host == public.hostname
    )
    if not allowed_host:
        return False
    supplied = request.headers.get("origin") or request.headers.get("referer")
    if not supplied:
        return True
    try:
        parsed = urlsplit(supplied)
    except ValueError:
        return False
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return False

    # The socket can be HTTP behind a TLS terminator. Cookie security is
    # configured separately; forwarding headers do not widen this host set.
    allowed = {f"{scheme}://{request.url.netloc}" for scheme in ("http", "https")}

    # Saved presentation data can name the public origin; forwarded Host
    # headers must not expand the origins allowed to submit a setup form.
    if public_base:
        try:
            public = urlsplit(public_base)
        except ValueError:
            public = None
        if public and public.scheme in {"http", "https"} and public.netloc:
            public_origin = f"{public.scheme}://{public.netloc}"
            allowed.add(public_origin)
            for scheme in ("http", "https"):
                allowed.add(f"{scheme}://{public.netloc}")

    supplied_origin = f"{parsed.scheme}://{parsed.netloc}"
    return supplied_origin in allowed


@app.post("/setup/local-owner", include_in_schema=False)
async def setup_create_local_owner(request: Request):
    """Create the first local owner account from the browser.

    Only honored when no owner/admin role exists yet. After the account is
    created it gets the ``owner`` role and the browser receives a signed
    admin session; further calls land in the ``owner_or_admin_exists``
    branch of /setup.
    """
    signing_key = _browser_admin_session_signing_key()
    if not signing_key:
        return await _setup_page_response(
            request,
            create_error=(
                "Browser admin sessions are unavailable: this gateway "
                "cannot read or write its session signing key file."
            ),
            status_code=500,
        )
    if _owner_or_admin_exists():
        # First-run is over. Redirect through /setup so the operator sees the
        # signed-in landing card and can sign in if needed.
        return RedirectResponse("/setup/", status_code=303)
    if not _client_may_claim_first_owner(request):
        return await _setup_page_response(
            request,
            create_error=(
                "Create the first owner from the gateway host or a configured "
                "LAN client."
            ),
            status_code=403,
        )
    if not _origin_header_allowed_for_request(request):
        return await _setup_page_response(
            request,
            create_error="Use the setup page on this gateway to create the owner.",
            status_code=403,
        )

    values = await _setup_form_values(request)
    email = _normalize_local_email(values.get("email", ""))
    password = values.get("password", "")
    confirm = values.get("password_confirm", "")

    if not email:
        return await _setup_page_response(
            request,
            create_error="Enter an email or username for the owner account.",
            create_email=email or None,
            status_code=400,
        )
    if not password:
        return await _setup_page_response(
            request,
            create_error="Enter a password for the owner account.",
            create_email=email,
            status_code=400,
        )
    if password != confirm:
        return await _setup_page_response(
            request,
            create_error="The two passwords did not match.",
            create_email=email,
            status_code=400,
        )

    try:
        verifier = local_hash_password(password)
    except ValueError as exc:
        return await _setup_page_response(
            request,
            create_error=f"Could not store that password: {exc}",
            create_email=email,
            status_code=400,
        )

    user = admin_store.claim_first_local_owner(
        issuer=_LOCAL_OWNER_ISSUER,
        subject=email,
        email=email,
        display_name=email,
        verifier=verifier,
        granted_by="setup-local-owner",
        path=ADMIN_STORE.path,
    )
    if user is None:
        return RedirectResponse("/setup/", status_code=303)
    # A fresh gateway has no built-in default plan, so the first owner gets one
    # ordinary starting plan; without it they would be refused on their own gateway.
    admin_store.seed_first_owner_plan(str(user["id"]), path=ADMIN_STORE.path)
    # Parity with OIDC login: give the new owner a personal App up front so the
    # portal can hand them a working key without a separate "create App" step.
    _ensure_personal_app_for_owner(user, role="owner")
    # Setup is done — hand the new owner to the portal, where their key is
    # auto-minted and revealed once. Landing back on /setup would greet them
    # with the operator "this gateway has an owner" recovery card (third-person,
    # plus a redundant second key-mint flow). The portal is the real home.
    return _issue_browser_admin_session(
        user_id=str(user["id"]),
        email=email,
        role="owner",
        signing_key=signing_key,
        redirect_to="/",
    )


@app.post("/setup/local-login", include_in_schema=False)
async def setup_local_login(request: Request):
    """Sign an existing local owner / admin back in from /setup."""
    signing_key = _browser_admin_session_signing_key()
    if not signing_key:
        return await _setup_page_response(
            request,
            login_error=(
                "Browser admin sessions are unavailable: this gateway "
                "cannot read or write its session signing key file."
            ),
            status_code=500,
        )

    values = await _setup_form_values(request)
    email = _normalize_local_email(values.get("email", ""))
    password = values.get("password", "")
    generic_error = (
        "Sign-in name or password did not match a local owner account."
    )

    if not email or not password:
        return await _setup_page_response(
            request,
            login_error=generic_error,
            login_email=email or None,
            status_code=400,
        )

    from gateway.accounts_api import signin_options
    built_in = signin_options(ADMIN_STORE.path, {"enabled": _resolved_admin_oidc_config()[0].enabled})["built_in"]
    try:
        accounts.initialize(ADMIN_STORE.path)
        client_ip = resolve_real_client_ip(request)
        if client_ip is None:
            raise accounts.AccountError("invalid_client_ip", "Cannot verify the sign-in client address.", 400)
        accounts.throttle(str(client_ip), email, path=ADMIN_STORE.path)
    except accounts.AccountError as exc:
        return JSONResponse({"error": {"code": exc.code, "message": exc.message}}, status_code=exc.status)
    user = admin_store.find_user_by_email(
        email, issuer=_LOCAL_OWNER_ISSUER, path=ADMIN_STORE.path
    ) or admin_store.find_password_user_by_email(email, path=ADMIN_STORE.path)
    if user is None:
        return await _setup_page_response(
            request,
            login_error=generic_error,
            login_email=email,
            status_code=401,
        )
    verifier_row = admin_store.get_local_password_verifier(
        str(user["id"]), path=ADMIN_STORE.path
    )
    if verifier_row is None or not accounts.verify_password(
        password, str(verifier_row.get("verifier") or "")
    ):
        return await _setup_page_response(
            request,
            login_error=generic_error,
            login_email=email,
            status_code=401,
        )
    role_names = admin_store.effective_admin_roles(
        "user", str(user["id"]), path=ADMIN_STORE.path,
    )
    if not built_in and "owner" not in role_names:
        # Only the owner's password works while built-in sign-in is off.
        return JSONResponse({"error": {"code": "builtin_disabled", "message": "Use the identity provider to sign in."}}, status_code=403)
    if "owner" in role_names:
        role = "owner"
    elif "admin" in role_names or "superadmin" in role_names:
        role = "admin"
    else:
        return await _setup_page_response(
            request,
            login_error=(
                "That account no longer has owner or admin permission. "
                "Ask another admin to restore your role."
            ),
            login_email=email,
            status_code=403,
        )
    accounts.clear_signin_refusal(str(user["id"]), path=ADMIN_STORE.path)
    admin_store.record_audit(
        "setup.local_owner_login",
        actor_kind="user",
        actor_id=str(user["id"]),
        actor_label=str(user.get("display_name") or user.get("email") or user["id"]),
        target_kind="user",
        target_id=str(user["id"]),
        metadata={"email": email, "via": "setup_page"},
        path=ADMIN_STORE.path,
    )
    # A returning owner/admin signing in from /setup lands on the portal, their
    # home — not back on the operator setup console.
    return _issue_browser_admin_session(
        user_id=str(user["id"]),
        email=email,
        role=role,
        signing_key=signing_key,
        redirect_to=_safe_admin_return_to(values.get("return_to") or request.query_params.get("return_to")),
    )


@app.post("/setup/first-app", include_in_schema=False)
async def setup_create_first_app(request: Request):
    actor = _setup_admin_context(request)
    session = (await asyncio.to_thread(_oidc_session_from_request, request))
    if actor is None or actor.auth_method != "session":
        return await _setup_page_response(
            request,
            claim_error="Sign in or claim an admin browser session before creating an App.",
            status_code=401,
        )
    values = await _setup_form_values(request)
    expected = actor.csrf_token or ""
    supplied = values.get("csrf_token") or request.headers.get("x-azizam-csrf") or ""
    if expected and not hmac.compare_digest(supplied, expected):
        return await _setup_page_response(
            request,
            app_error="The setup form expired. Reload /setup and try again.",
            status_code=403,
        )
    app_name = (values.get("app_name") or "first-app").strip()
    key_label = (values.get("key_label") or "Setup key").strip()
    if not app_name:
        return await _setup_page_response(
            request,
            app_error="App name is required.",
            status_code=400,
        )
    try:
        session_subject_kind, _session_subject_id = session_admin_role_subject(
            str(getattr(session, "subject", "") or "")
        ) if session is not None else ("", "")
        if (
            session is not None
            and session_subject_kind == "user"
        ):
            app_record = _setup_personal_app_for_session(session)
            if app_record is None:
                payload = request_user_access(
                    session,
                    path=ADMIN_STORE.path,
                )
                app_record = payload["app"]
            credential = mint_user_app_key(
                session,
                str(app_record["id"]),
                label=key_label,
                path=ADMIN_STORE.path,
            )
            admin_store.record_audit(
                "setup.first_app_key",
                actor_kind="user",
                actor_id=str(getattr(session, "subject", "") or ""),
                actor_label=str(getattr(session, "email", "") or getattr(session, "subject", "") or "Unknown user"),
                target_kind="credential",
                target_id=str(credential.get("id") or ""),
                metadata={
                    "via": "setup_page",
                    "app_id": app_record.get("id"),
                    "prefix": credential.get("prefix"),
                },
                path=ADMIN_STORE.path,
            )
        else:
            app_record = ADMIN_STORE.create_app(
                data={"name": app_name, "kind": "service", "access_plan": "person"},
                actor=actor,
            )
            credential = ADMIN_STORE.create_credential(
                app_id=str(app_record["id"]),
                data={"label": key_label},
                actor=actor,
            )
            admin_store.record_audit(
                "setup.first_app_key",
                actor_kind=actor.actor_kind,
                actor_id=actor.audit_actor_id,
                actor_label=actor.actor_label,
                target_kind="credential",
                target_id=str(credential.get("id") or ""),
                metadata={
                    "via": "setup_page",
                    "app_id": app_record.get("id"),
                    "prefix": credential.get("prefix"),
                },
                path=ADMIN_STORE.path,
            )
    except UserPortalError as e:
        return await _setup_page_response(
            request,
            app_error=e.message,
            status_code=e.status_code,
        )
    except Exception as e:  # noqa: BLE001
        return await _setup_page_response(
            request,
            app_error=f"Could not create the App key: {str(e)[:180]}",
            status_code=400,
        )
    return await _setup_page_response(
        request,
        one_time_key={
            "api_key": credential.get("api_key"),
            "app_name": app_record.get("name") or app_name,
            "credential_prefix": credential.get("prefix"),
        },
        status_code=201,
    )


@app.get("/login", include_in_schema=False)
async def browser_login(request: Request):
    return await _start_browser_login(request, default_return_to="/")


def _browser_signin_failure(request: Request, *, return_to: str | None = None):
    """Give browser navigations a safe retry page; never forward provider detail."""
    if "text/html" not in request.headers.get("accept", ""):
        return None
    target = _safe_admin_return_to(return_to)
    return RedirectResponse(
        f"/sign-in/?error=provider&return_to={quote(target, safe='')}",
        status_code=303,
        headers={"cache-control": "no-store", "referrer-policy": "no-referrer"},
    )


@app.get("/admin/oidc/callback", include_in_schema=False)
async def admin_oidc_callback(request: Request):
    error = request.query_params.get("error")
    code = request.query_params.get("code")
    state_value = request.query_params.get("state")
    pending = ADMIN_OIDC_STATES.get(state_value or "")
    # A test from Settings runs before the provider is turned on.
    if not (pending and pending.test_id) and not _effective_admin_oidc_config().enabled:
        return Response(status_code=404)
    if not state_value or not (code or error):
        return _browser_signin_failure(request) or Response(
            content="OIDC callback missing code or state",
            status_code=400,
            media_type="text/plain; charset=utf-8",
        )
    state = None
    try:
        state = consume_browser_state(request, ADMIN_OIDC_STATES, state_value)
        if state.test_id:
            session = await asyncio.to_thread(_oidc_session_from_request, request)
            page = await SIGNIN_API.finish_test(
                state,
                session_user_id=session.subject if session else None,
                code=code, error=error, error_description=request.query_params.get("error_description"),
                exchange_code=_oidc_exchange_code, verify_id_token=_oidc_verify_id_token,
            )
            return clear_browser_binding(page, state)
        if error:
            raise ValueError("identity provider declined sign-in")
        cfg = await _admin_oidc_config_with_discovery()
        if state.redirect_uri:
            cfg = replace(cfg, redirect_uri=state.redirect_uri)
        tokens = await _oidc_exchange_code(
            code,
            config=cfg,
            pkce=PKCEPair(
                verifier=state.pkce_verifier,
                challenge="already-sent",
            ),
        )
        id_token = tokens.get("id_token")
        if not isinstance(id_token, str) or not id_token:
            raise ValueError("token endpoint did not return id_token")
        claims = await _oidc_verify_id_token(id_token, config=cfg)
        try:
            validate_id_token_claims(claims, config=cfg, expected_nonce=state.nonce)
            decision, bootstrap_owner = await _decide_oidc_signin(cfg, claims)
            if not decision.outcome.admitted:
                raise SignInRefused("sign-in rules do not let this person in")
        except SignInRefused:
            # A refused person keeps nothing the identity provider gave them.
            await asyncio.to_thread(_end_provider_access_after_refusal, cfg.issuer, claims)
            raise
        user = admin_store.upsert_oidc_user(
            cfg.issuer,
            str(claims["sub"]),
            email=str(claims.get("email") or ""),
            display_name=str(claims.get("name") or claims.get("email") or ""),
            path=ADMIN_STORE.path,
        )
        accounts.record_oidc_verification(str(user["id"]), claims.get("email_verified") is True, path=ADMIN_STORE.path)
        accounts.clear_signin_refusal(str(user["id"]), path=ADMIN_STORE.path)
        account_state = accounts.access(str(user["id"]), path=ADMIN_STORE.path)
        if account_state and (account_state["disabled_at"] is not None or account_state["removed_at"] is not None):
            return clear_browser_binding(JSONResponse({"error": {"code": "account_disabled", "message": "This account is disabled."}}, status_code=403), state)
        oidc_access_names = access_names_from_oidc_claims(
            claims,
            client_id=cfg.client_id,
            groups_claim=cfg.groups_claim,
        )
        admin_store.replace_user_identity_claims(
            str(user["id"]),
            oidc_access_names,
            path=ADMIN_STORE.path,
        )
        # Whether an owner already exists is decided inside the write's own
        # transaction, so two first sign-ins cannot both become owner.
        if bootstrap_owner and admin_store.claim_first_owner(
            str(user["id"]), granted_by="oidc-bootstrap", path=ADMIN_STORE.path,
        ):
            admin_store.seed_first_owner_plan(str(user["id"]), path=ADMIN_STORE.path)
        elif bootstrap_owner:
            # Another first sign-in won the owner role; this person is an ordinary one.
            decision, _ = await _decide_oidc_signin(cfg, claims, bootstrap_owner=False)
            if not decision.outcome.admitted:
                await asyncio.to_thread(_end_provider_access_after_refusal, cfg.issuer, claims)
                raise SignInRefused("sign-in rules do not let this person in")
        # Rule-derived grants are re-derived at every sign-in; a grant no rule
        # supports any more ends here. Grants the owner gave by hand stay.
        effective_grants = admin_store.reconcile_oidc_admin_roles(
            str(user["id"]), {"admin"} if decision.outcome.admin else set(),
            path=ADMIN_STORE.path,
        )
        signin_admin.sync_rule_plan(ADMIN_STORE.path, str(user["id"]), decision.outcome)
        effective_roles = {grant["role"] for grant in effective_grants}
        role = "owner" if "owner" in effective_roles else "admin" if "admin" in effective_roles else "none"
        label = user.get("email") or user.get("display_name") or user["id"]
        app = admin_store.ensure_personal_app_for_user(
            str(user["id"]),
            name=f"{label} personal access",
            path=ADMIN_STORE.path,
        )
        admin_store.record_audit(
            "app.self_create",
            actor_kind="user",
            actor_id=str(user["id"]),
            actor_label=str(user.get("display_name") or user.get("email") or user["id"]),
            target_kind="app",
            target_id=str(app["id"]),
            metadata={"email": user.get("email"), "via": "oidc_login",
                      "access_plan": app.get("access_plan")},
            path=ADMIN_STORE.path,
        )
        session_claims = {
            "sub": user["id"],
            "email": claims.get("email") or "",
        }
        session = session_from_claims(
            session_claims,
            role=role,
            cookie=cfg.cookie,
        )
        accounts.register_session(str(user["id"]), session.session_id, int(session.expires_at), path=ADMIN_STORE.path)
        response = RedirectResponse(_safe_admin_return_to(state.return_to), status_code=302)
        response.set_cookie(
            cfg.cookie.name,
            encode_session_cookie(session, signing_key=cfg.signing_key),
            max_age=cfg.cookie.max_age_seconds,
            secure=cfg.cookie.secure,
            httponly=cfg.cookie.http_only,
            samesite=cfg.cookie.same_site,
            path=cfg.cookie.path,
            domain=cfg.cookie.domain,
        )
        return clear_browser_binding(response, state)
    except (SessionError, IDTokenClaimsError, ValueError, httpx.HTTPError):
        response = _browser_signin_failure(
            request, return_to=state.return_to if state else None,
        ) or Response(
            content="OIDC authentication failed",
            status_code=400,
            media_type="text/plain; charset=utf-8",
        )
        return clear_browser_binding(response, state) if state else response


async def _decide_oidc_signin(cfg, claims: Mapping[str, Any], *, bootstrap_owner: bool | None = None):
    """The one sign-in decision: owner, invitation or rules (gateway.signin_rules)."""
    if bootstrap_owner is None:
        # Only the very first owner may be named by the bootstrap email, and
        # only while no owner grant has ever existed.
        never_owned = AdminRole.OWNER not in set(
            _existing_admin_grants(include_revoked=True).values())
        bootstrap_owner = never_owned and bootstrap_admin_role(
            str(claims.get("email") or ""),
            config=cfg,
            existing_roles={},
            issuer=str(claims.get("iss") or ""),
            email_verified=claims.get("email_verified") is True,
        ) == AdminRole.OWNER
    decision = await asyncio.to_thread(
        signin_admin.decide, ADMIN_STORE.path, claims, issuer=cfg.issuer, client_id=cfg.client_id,
        groups_claim=cfg.groups_claim, bootstrap_owner=bool(bootstrap_owner),
    )
    return decision, bool(bootstrap_owner)


@app.get("/auth/logout-confirm", include_in_schema=False)
async def logout_confirmation(request: Request):
    session = (await asyncio.to_thread(_oidc_session_from_request, request))
    if session is None:
        return RedirectResponse("/sign-in/", status_code=303)
    csrf = _csrf_token_for_oidc_session(session)
    return HTMLResponse(
        '<!doctype html><title>Sign out of Azizam</title>'
        '<form method="post" action="/logout">'
        f'<input type="hidden" name="csrf_token" value="{csrf}">'
        '<button type="submit">Sign out</button></form>',
        headers={"cache-control": "no-store", "referrer-policy": "no-referrer"},
    )


@app.post("/logout", include_in_schema=False)
async def admin_logout(request: Request):
    session = (await asyncio.to_thread(_oidc_session_from_request, request))
    if session is None:
        return JSONResponse({"error": {"code": "login_required", "message": "Sign in first."}}, status_code=401)
    supplied = request.headers.get("x-azizam-csrf") or ""
    if not supplied and request.headers.get("content-type", "").startswith("application/x-www-form-urlencoded"):
        values = await _setup_form_values(request)
        supplied = values.get("csrf_token", "")
    expected = _csrf_token_for_oidc_session(session)
    if not expected or not hmac.compare_digest(expected, supplied):
        return JSONResponse({"error": {"code": "csrf_required", "message": "Refresh the page before signing out."}}, status_code=403)
    accounts.revoke_session(session.session_id, int(session.expires_at), path=ADMIN_STORE.path)
    response = (JSONResponse({"next": "/sign-in/"}) if "application/json" in request.headers.get("accept", "")
                else RedirectResponse("/sign-in/", status_code=303))
    cookie = _browser_admin_cookie_config()
    response.delete_cookie(
        cookie.name,
        path=cookie.path,
        domain=cookie.domain,
    )
    return response


@app.post("/admin/api/config/reload", include_in_schema=False)
async def admin_config_reload(request: Request):
    """Hot-reload the runtime config from the DB service registry.

    Re-derives all backend host constants (KOBOLD_HOST,
    LLM_BACKEND_HOSTS, TTS_HOST, STT_HOST, EMBEDDINGS_HOST, COMFY_HOST …)
    without a process restart.  Requests that arrive after this returns will
    see the new values.

    Note: the LiteLLM subprocess still requires a separate restart to pick up
    its config-file changes.
    """
    ctx = _require_admin(ADMIN_AUTH, request)
    if isinstance(ctx, JSONResponse):
        return ctx
    try:
        updates = reload_runtime_config()
        return JSONResponse(
            status_code=200,
            content={
                "reloaded": True,
                "backends": {
                    "llm_hosts": updates["LLM_BACKEND_HOSTS"],
                    "kobold": updates["KOBOLD_HOST"],
                    "tts": updates["TTS_HOST"],
                    "stt": updates["STT_HOST"],
                    "embeddings": updates["EMBEDDINGS_HOST"],
                    "comfyui": updates["COMFY_HOST"],
                },
            },
        )
    except Exception as exc:  # noqa: BLE001
        return JSONResponse(
            status_code=500,
            content={"error": {"code": "reload_failed", "message": str(exc)}},
        )


# -----------------------------------------------------------------------------
# Restart drain (docs/ops/SAFE_RESTART.md). Driven by scripts/safe-restart.
# -----------------------------------------------------------------------------

_DRAIN_LOOPBACK_HOSTS = frozenset({"127.0.0.1", "::1", "::ffff:127.0.0.1", "localhost"})

DRAIN_STATE.register_job_counter("image", lambda: len(_image_media_job_tasks))
DRAIN_STATE.register_job_counter("audio", lambda: len(_audio_media_job_tasks))
DRAIN_STATE.register_job_counter("video", lambda: len(_video_media_job_tasks))


def _unfinished_openai_video_jobs(max_age_s: int = 2 * 3600) -> int:
    """Count /v1/videos jobs still rendering in ComfyUI.

    These live only in process memory (`_video_job_records`), so a restart
    orphans them. `completed_at` is stamped only when a client polls, so use
    the websocket progress state for terminal status, and ignore records older
    than `max_age_s` so a lost event cannot block a restart forever.
    """
    now = int(time.time())
    count = 0
    for prompt_id, record in list(_video_job_records.items()):
        if record.get("completed_at") is not None or record.get("deleted_at") is not None:
            continue
        media_job_id = record.get("media_job_id")
        video_job = media_jobs.get(media_job_id, audience="internal", path=media_jobs.DB_PATH) if media_job_id else None
        if video_job and video_job.get("status") in media_jobs.TERMINAL_STATUSES:
            continue
        created = record.get("created_at") or now
        if now - int(created) > max_age_s:
            continue
        if prompt_id in _video_records_restored:
            # Loaded from the store after a restart: this process never saw it
            # render, so there is nothing for the drain to wait for.
            continue
        status = (_video_progress.get(prompt_id) or {}).get("status")
        if status in ("succeeded", "failed"):
            continue
        progress = _video_progress.get(prompt_id) or {}
        expected = record.get("actual_seconds") or record.get("seconds") or 0
        try:
            expected_seconds = max(0, float(expected))
        except (TypeError, ValueError):
            expected_seconds = 0
        last_progress = progress.get("updated_at") or created
        stall_after = min(1800, max(300, expected_seconds + 300))
        if now - int(last_progress) > stall_after:
            continue
        count += 1
    return count


DRAIN_STATE.register_job_counter("openai_video", _unfinished_openai_video_jobs)


def _drain_peer_is_loopback(request: Request) -> bool:
    # The socket peer only. X-Forwarded-For is client-controlled and the
    # gateway also listens on a LAN address behind a reverse proxy.
    client = request.client
    return client is not None and client.host in _DRAIN_LOOPBACK_HOSTS


def _drain_error(status_code: int, code: str, message: str) -> JSONResponse:
    return JSONResponse(
        status_code=status_code,
        content={"error": {"code": code, "message": message}},
    )


def _drain_authorize(request: Request, *, write: bool) -> Response | None:
    try:
        ctx = ADMIN_AUTH(request)
    except AdminAuthError as exc:
        return Response(
            content=json.dumps({"error": {"code": exc.code, "message": exc.message}}),
            status_code=exc.status_code,
            media_type="application/json",
            headers={"WWW-Authenticate": "Bearer"},
        )
    if not _drain_peer_is_loopback(request):
        return _drain_error(
            403, "drain_local_only", "The drain control only accepts loopback callers."
        )
    # A browser session cookie could be replayed cross-site; changing the flag
    # needs an explicit admin bearer key.
    if write and getattr(ctx, "auth_method", "") != "bearer":
        return _drain_error(
            403, "drain_bearer_required", "Changing the drain flag needs an admin bearer key."
        )
    return None


@app.get("/admin/api/drain", include_in_schema=False)
async def admin_drain_status(request: Request):
    denied = await asyncio.to_thread(_drain_authorize, request, write=False)
    if denied is not None:
        return denied
    return JSONResponse(DRAIN_STATE.snapshot())


@app.post("/admin/api/drain", include_in_schema=False)
async def admin_drain_set(request: Request):
    """Set or clear the draining flag. Body: {"draining": bool, "ttl_s": num, "reason": str}."""
    denied = await asyncio.to_thread(_drain_authorize, request, write=True)
    if denied is not None:
        return denied
    try:
        raw = await request.body()
        payload = json.loads(raw) if raw.strip() else {}
    except ValueError:
        return _drain_error(400, "invalid_json", "Body must be a JSON object.")
    if not isinstance(payload, dict):
        return _drain_error(400, "invalid_json", "Body must be a JSON object.")
    draining = payload.get("draining", True)
    if not isinstance(draining, bool):
        return _drain_error(400, "invalid_draining", "draining must be a boolean.")
    ttl = payload.get("ttl_s")
    if ttl is not None and (
        isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or ttl <= 0
    ):
        return _drain_error(400, "invalid_ttl", "ttl_s must be a positive number.")
    reason = payload.get("reason", "")
    if not isinstance(reason, str):
        return _drain_error(400, "invalid_reason", "reason must be a string.")
    DRAIN_STATE.set_draining(draining, ttl_s=ttl, reason=reason)
    print(
        f"[proxy] drain {'ON' if draining else 'OFF'}"
        + (f" ttl={ttl}" if draining and ttl else "")
        + (f" reason={reason[:80]!r}" if draining and reason else ""),
        flush=True,
    )
    return JSONResponse(DRAIN_STATE.snapshot())



# Ephemeral keys that must NOT appear in the config export (they are runtime/
# health state, not operator-authored configuration).
_EXPORT_EPHEMERAL_KEYS = frozenset(
    {
        "health",
        "last_used",
        "last_used_at",
        "vram",
        "vram_used",
        "vram_gb_used",
        "probed_at",
        "probe_window",
        "health_history",
        "last_error",
        "live_status",
        "runtime",
    }
)


def _service_record_for_export(service_id: str, record: dict) -> dict:
    """Return a clean, export-safe copy of one service record.

    Strips ephemeral runtime keys so the export is reproducible and
    round-trippable via the seed-import path.
    """
    out: dict = {}
    for key, value in record.items():
        if key in _EXPORT_EPHEMERAL_KEYS:
            continue
        if isinstance(value, dict):
            # Recursively strip ephemeral keys from nested dicts (e.g. config).
            out[key] = {
                k: v for k, v in value.items() if k not in _EXPORT_EPHEMERAL_KEYS
            }
        else:
            out[key] = value
    return out


def _build_config_export_yaml() -> str:
    """Serialize the current DB service registry to canonical YAML.

    Returns a UTF-8 string suitable for committing to git.  Only
    operator-authored configuration is included; ephemeral runtime state
    (health history, last_used_at, probed windows, live VRAM readings) is
    explicitly excluded.

    Shape: matches the ``services`` block the seed-import path already
    understands, so ``import-from-file`` (existing seed path) can round-trip
    this export without modification.
    """
    registry = ADMIN_STORE.get_service_registry()
    services_raw = (registry.get("services") or {}) if isinstance(registry, dict) else {}

    services_export: dict = {}
    for svc_id, record in sorted(services_raw.items()):
        if not isinstance(record, dict):
            continue
        services_export[svc_id] = _service_record_for_export(svc_id, record)

    # The export goes through the same projection as every other management output (decision D31): a secret is a
    # configured entry, never a value and never a reference. A restorable backup of the secrets themselves is a
    # separate, encrypted operation that this export is not.
    export_doc = {
        "services": projection.project("RegistryDoc", {"services": services_export}).tree.get("services", {}),
    }

    header = (
        "# Gateway service registry — canonical export\n"
        "# Generated by GET /admin/api/config/export\n"
        "# This file reproduces the running gateway's service registry.\n"
        "# Ephemeral runtime state (health, last_used_at, VRAM) is excluded.\n"
        "# Secrets are configured entries: their values are in the gateway's secret store and are not exported.\n"
        "#\n"
        "# NOTE: full file-wins git reconcile (services.yml as the authoritative\n"
        "# source with UI-only overlay in services.local.yml) is roadmap.\n"
        "# For now: export is read-only; edits go through the admin UI or DB.\n"
        "#\n"
    )
    body = yaml.dump(
        export_doc,
        default_flow_style=False,
        allow_unicode=True,
        sort_keys=True,
    )
    return header + body


@app.get("/admin/api/config/export", include_in_schema=False)
async def admin_config_export(request: Request):
    """Export the canonical YAML reproducing the running gateway's service registry.

    Returns clean YAML containing every service's connection, capabilities,
    models, priority, role, and lifecycle — everything an operator would commit
    to reproduce this gateway.  Ephemeral runtime state (health history,
    last_used_at, probed windows, live VRAM) is excluded.

    The output is round-trippable: it matches the shape the existing
    seed-import path already understands.

    Owner only. It holds the public configuration and, for each secret, a configured entry; it never holds a
    secret value (decision D26), so it cannot restore a secret.
    """
    try:
        ctx = await asyncio.to_thread(ADMIN_AUTH, request)
        if "owner" not in ctx.roles:
            return JSONResponse(
                status_code=403,
                content={"error": {"code": "owner_required", "message": "Owner role required"}},
                headers={"Cache-Control": "no-store"},
            )
    except AdminAuthError as exc:
        return Response(
            content=json.dumps({"error": {"code": exc.code, "message": exc.message}}),
            status_code=exc.status_code,
            media_type="application/json",
            headers={"WWW-Authenticate": "Bearer"},
        )
    try:
        yaml_text = await asyncio.to_thread(_build_config_export_yaml)
        return Response(
            content=yaml_text,
            media_type="text/plain; charset=utf-8",
            headers={
                "Content-Disposition": 'attachment; filename="gateway-services.yml"',
            },
        )
    except Exception as exc:  # noqa: BLE001
        return JSONResponse(
            status_code=500,
            content={"error": {"code": "export_failed", "message": f"The export could not be built ({type(exc).__name__})."}},
        )


# Endpoint paths excluded from the firehose per-key request counter.
# These are health/status probes hammered by the dashboard itself or
# routes that don't represent real "API caller" activity.
_FIREHOSE_NO_RECORD_PREFIXES = (
    "/health",
    "/admin",
    "/status",
    "/me/",
    "/v1/status",
    "/v1/audio/health",
    "/_next/",
    "/favicon.ico",
    "/static/",
    "/SKILL.md",
    "/robots.txt",
    "/.well-known/",
)
# Exact paths (not prefixes) that should be excluded too.
_FIREHOSE_NO_RECORD_EXACT = {"/", "/llms.txt"}

# Map known successful-response paths to a synthesized event-type for the
# Recent activity timeline. We don't peek at request bodies — the path tells
# us enough ("chat completion happened") and the middleware already has the
# key name. Token counts are not visible here; we just stamp the path & status.
_FIREHOSE_EVENT_TYPES = {
    "/v1/chat/completions": "chat_completion",
    "/v1/completions": "chat_completion",
    "/v1/images/generations": "image_submit",
    "/v1/images/edits": "image_submit",
    "/v1/audio/speech": "tts_synthesize",
    "/v1/audio/transcriptions": "stt_transcribe",
    "/v1/audio/translations": "stt_translate",
    "/v1/rerank": "rerank",
    "/v2/rerank": "rerank",
    "/rerank": "rerank",
}


@app.middleware("http")
async def _firehose_request_counter(request: Request, call_next):
    """Record per-API-key request activity for the firehose status panel.

    Identity is resolved best-effort by hashing the bearer token against
    admin.db App credentials. Body is never read; this only inspects path +
    status.
    """
    path = request.url.path
    skip = (
        path in _FIREHOSE_NO_RECORD_EXACT
        or ui_routes.classify(path) is not None
        or any(path == p or path.startswith(p) for p in _FIREHOSE_NO_RECORD_PREFIXES)
    )
    t0 = time.monotonic()
    response = None
    try:
        response = await call_next(request)
        return response
    finally:
        if not skip:
            try:
                key_name: Optional[str] = None
                raw = get_client_api_key_from_headers(request.headers)
                if raw:
                    ident = await asyncio.to_thread(
                        runtime_identity_for_app_credential_hash, hash_api_key(raw), path=ADMIN_STORE.path)
                    if ident:
                        key_name = ident.name
                latency_ms = (time.monotonic() - t0) * 1000.0
                status_code = getattr(response, "status_code", 0) or 0
                firehose_metrics.record_request(key_name, path, status_code, latency_ms)
                # Mirror into the SQLite time-series so the status page can
                # render historical request rates / latencies. Best-effort.
                metrics_sampler.record_request(
                    "request",
                    latency_ms,
                    key=key_name,
                    path=path,
                    status=status_code,
                )
                # Synthesize a timeline event for known content endpoints when
                # the response was a success. Skip videos here — capture for
                # those happens deeper in the handler with workflow/size/seconds
                # metadata that isn't visible at the middleware boundary.
                if status_code and status_code < 400:
                    evt_type = _FIREHOSE_EVENT_TYPES.get(path)
                    if evt_type:
                        # Pull a model id from the response header if the
                        # downstream handler stamped one (chat completions do).
                        model_hdr = (
                            response.headers.get("x-model-resolved")
                            if response is not None and hasattr(response, "headers")
                            else None
                        )
                        firehose_metrics.record_event(
                            evt_type,
                            f"{path} · {model_hdr or '—'}",
                            path=path,
                            status=status_code,
                            latency_ms=round(latency_ms, 2),
                            key=key_name or "anonymous",
                            model=model_hdr,
                        )
            except Exception:
                pass


