# ---------------------------------------------------------------------------
# Rerank: Cohere / Jina / Voyage / TEI request shapes over an on-demand engine
# ---------------------------------------------------------------------------

_RERANK_POLICY_PATH = "/v1/rerank"
# Same policy as the route record in registry/protocol_frontends.yml. A populated admin.db owns its own
# route list and does not gain new seed routes, so without this fallback rerank would be open to every
# valid key (even one whose profile allows chat only) until an operator edits the DB.
_RERANK_DEFAULT_POLICY: dict[str, Any] = {
    "protocol": "openai.rerank",
    "intent": "text.embeddings",
    "backend": "rerank",
    "capability_exposure": "default",
    "capability_trust_tier": "stable",
    "capability_resource_tier": "interactive",
}


def _rerank_error(
    status: int,
    message: str,
    *,
    code: str,
    param: str | None = None,
    tei: bool = False,
    kind: str = "invalid_request_error",
    headers: Mapping[str, str] | None = None,
) -> Response:
    return Response(
        content=json.dumps(rerank_api.error_body(message, code=code, param=param, tei=tei, kind=kind)),
        status_code=status,
        media_type="application/json",
        headers=dict(headers or {}),
    )


async def _handle_rerank(request: Request, path: str) -> Response:
    auth_context = (await asyncio.to_thread(authenticate_request, request, path))
    if isinstance(auth_context, Response):
        return auth_context
    policy_response = (await asyncio.to_thread(_enforce_runtime_route_policy, auth_context,
        _RERANK_POLICY_PATH,
        policy=_RUNTIME_ROUTE_POLICY.get(_RERANK_POLICY_PATH) or _RERANK_DEFAULT_POLICY,))
    if policy_response is not None:
        return policy_response
    try:
        body = json.loads(await request.body())
    except (ValueError, UnicodeDecodeError):
        return _rerank_error(400, "Request body must be valid JSON.", code="invalid_json")
    tei = isinstance(body, Mapping) and "documents" not in body and "texts" in body

    requested_model = body.get("model") if isinstance(body, Mapping) else None
    if requested_model is not None and not isinstance(requested_model, str):
        return _rerank_error(400, "model must be a string.", code="invalid_request", param="model", tei=tei)
    try:
        resolution = resolve_stable_alias("rerank", requested_model or rerank_api.DEFAULT_MODEL)
    except stable_aliases.AliasUnavailableError as exc:
        return _rerank_error(503, str(exc), code=exc.code, tei=tei, kind="api_error")
    if resolution is None or resolution.engine is None:
        known = ", ".join(sorted(((config.get("model_aliases") or {}).get("rerank") or {}).get("stable") or {})) or "none"
        return _rerank_error(
            404,
            f"Model '{requested_model}' is not a rerank model on this gateway (use one of: {known}).",
            code="model_not_found",
            param="model",
            tei=tei,
        )
    spec = resolution.engine_spec or {}
    try:
        req = rerank_api.parse_request(
            body,
            max_documents=int(spec.get("max_documents") or rerank_api.DEFAULT_MAX_DOCUMENTS),
            max_document_chars=int(spec.get("max_document_chars") or rerank_api.DEFAULT_MAX_DOCUMENT_CHARS),
        )
    except rerank_api.RerankInputError as exc:
        return _rerank_error(400, str(exc), code=exc.code, param=exc.param, tei=tei)

    service_id = str(resolution.service or "")
    service = (config.get("backends") or {}).get(service_id) or {}
    if await _ensure_speech_service_ready(service_id, label="Rerank engine") is not None:
        return _rerank_error(
            503, "The rerank engine could not be started.", code="backend_unavailable",
            tei=tei, kind="api_error", headers={"Retry-After": "5"},
        )
    url = f"http://{service['host']}:{service['port']}/v1/rerank"
    timeout = float(service.get("timeout") or 120)
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(timeout, connect=10)) as client:
            upstream = await client.post(url, json=rerank_api.upstream_body(req, resolution.upstream_model))
    except httpx.HTTPError as exc:
        return _rerank_error(502, f"The rerank engine did not answer: {type(exc).__name__}.", code="backend_error", tei=tei, kind="api_error")
    if upstream.status_code != 200:
        status = 400 if upstream.status_code in (400, 413, 422) else 502
        detail = ""
        try:
            err = upstream.json().get("error")
            detail = str(err.get("message") if isinstance(err, Mapping) else err or "")[:300]
        except (ValueError, AttributeError):
            pass
        return _rerank_error(
            status,
            detail or f"The rerank engine answered HTTP {upstream.status_code}.",
            code="invalid_request" if status == 400 else "backend_error",
            tei=tei,
            kind="invalid_request_error" if status == 400 else "api_error",
        )
    try:
        payload = rerank_api.build_response(
            req,
            upstream.json(),
            model=resolution.requested,
            default_return_documents=path != "/v2/rerank",
        )
    except (ValueError, rerank_api.RerankUpstreamError) as exc:
        return _rerank_error(502, str(exc), code="backend_error", tei=tei, kind="api_error")
    return JSONResponse(payload, headers={"x-azizam-engine": resolution.engine or ""})


async def rerank_v1(request: Request):
    """Cohere, Jina and Voyage rerank."""
    return await _handle_rerank(request, "/v1/rerank")


async def rerank_v2(request: Request):
    """Cohere v2 rerank (no document echo unless asked)."""
    return await _handle_rerank(request, "/v2/rerank")


async def rerank_root(request: Request):
    """Jina and TEI style root path."""
    return await _handle_rerank(request, "/rerank")


# ---------------------------------------------------------------------------
# Realtime: WebSocket relay to the sibling Realtime service (gateway/realtime_proxy.py)
# ---------------------------------------------------------------------------

_REALTIME_SERVICE_ID = "realtime"
# A Realtime session listens, thinks and speaks, so a key needs all three routes the service calls.
_REALTIME_POLICY_PATHS = ("/v1/audio/transcriptions", "/v1/chat/completions", "/v1/audio/speech")


async def _deny_realtime(websocket: WebSocket, response: Response) -> None:
    """Refuse the upgrade with a normal HTTP answer, which is what SDKs and curl can read."""
    try:
        await websocket.send_denial_response(response)
    except RuntimeError:  # server without the denial extension: a bare close is still a 403
        await websocket.close(code=1008)


async def _fail_open_realtime(websocket: WebSocket, message: str, code: str) -> None:
    """End an accepted session the way OpenAI Realtime does: an ``error`` event, then close 1011."""
    try:
        await websocket.send_text(json.dumps(realtime_proxy.error_event(code, message)))
        await websocket.close(code=1011)
    except (RuntimeError, WebSocketDisconnect):
        pass


def _realtime_policy_denial(auth_context: AuthContext) -> Response | None:
    for path in _REALTIME_POLICY_PATHS:
        denied = _enforce_runtime_route_policy(auth_context, path)
        if denied is not None:
            return denied
    return None


async def _handle_realtime(websocket: WebSocket) -> None:
    offered = [p.strip() for p in websocket.headers.get("sec-websocket-protocol", "").split(",") if p.strip()]
    subprotocol_key = realtime_proxy.key_from_subprotocols(offered)
    caller: HTTPConnection = websocket
    if subprotocol_key and not get_client_api_key_from_headers(websocket.headers):
        headers = [(name, value) for name, value in websocket.scope["headers"] if name.lower() != b"authorization"]
        headers.append((b"authorization", f"Bearer {subprotocol_key}".encode()))
        caller = HTTPConnection({**websocket.scope, "headers": headers})
    auth_context = (await asyncio.to_thread(authenticate_request, caller, "/v1/realtime"))
    if isinstance(auth_context, Response):
        return await _deny_realtime(websocket, auth_context)
    denied = _realtime_policy_denial(auth_context)
    if denied is not None:
        return await _deny_realtime(websocket, denied)

    service = (config.get("backends") or {}).get(_REALTIME_SERVICE_ID)
    if not service or not service.get("port"):
        return await _deny_realtime(websocket, _tts_error("Realtime is not configured on this gateway.", 503, "realtime_not_configured"))
    admission = _dispatch_admission_response(
        "audio.realtime", auth_context=auth_context, resource_class="audio",
        service_id=_REALTIME_SERVICE_ID, service_available=True,
    )
    if admission is not None:
        return await _deny_realtime(websocket, admission)

    # Accept before starting the service: the server drops a handshake left open
    # for 10 s, and a cold start takes longer. Later failures are Realtime error events.
    await websocket.accept(subprotocol=realtime_proxy.accepted_subprotocol(offered))
    if await _ensure_speech_service_ready(_REALTIME_SERVICE_ID, label="Realtime service") is not None:
        return await _fail_open_realtime(websocket, "The Realtime service could not be started.", "backend_unavailable")
    url = realtime_proxy.upstream_url(str(service.get("host") or "127.0.0.1"), int(service["port"]), dict(websocket.query_params))
    try:
        upstream = await ws_connect(
            url, max_size=realtime_proxy.MAX_FRAME_BYTES, compression=None, open_timeout=10, ping_interval=20, ping_timeout=60,
        )
    except (OSError, TimeoutError, WebSocketException) as exc:
        print(f"[proxy] Realtime service refused the session: {type(exc).__name__}", flush=True)
        return await _fail_open_realtime(websocket, "The Realtime service did not accept the session.", "realtime_unavailable")
    await realtime_proxy.relay(websocket, upstream)


async def realtime_v1(websocket: WebSocket):
    """OpenAI Realtime over WebSocket, served by the sibling speech-to-speech service."""
    await _handle_realtime(websocket)


# Map image route paths to canonical intents for receipt construction.
_IMAGE_ROUTE_INTENTS = {
    "/v1/images/generations": "image.generate",
    "/v1/images/edits": "image.edit",
    "/v1/images/variations": "image.variation",
}


def start_image_route_receipt(
    path: str,
    auth_context: AuthContext,
) -> RouteReceipt:
    """Build an observational route receipt for an image endpoint after auth.

    The receipt records routing facts only: protocol, path, intent, key name,
    backend, and a placeholder policy decision rooted in the current proxy
    auth/profile model. It never reads the request body, so no prompts, file
    names, or uploaded bytes can leak into the receipt.
    """
    intent = _IMAGE_ROUTE_INTENTS.get(path, "image.generate")
    key_name = auth_context.identity.name if auth_context.identity else None
    app_id = auth_context.identity.app_id if auth_context.identity else None
    access = _access_for_auth_context(auth_context)
    receipt = RouteReceipt(
        protocol="openai.images",
        path=path,
        intent=intent,
        backend="comfyui",
        api_key_name=key_name,
        app_id=app_id,
        owner_key_hash=auth_context.identity.key_hash if auth_context.identity else None,
        app_profile=plan_ref(auth_context.identity),
        visibility=access.receipt_detail,
    )
    _apply_image_route_policy(receipt, auth_context)
    _begin_media_delivery(auth_context, receipt)
    return receipt


def _apply_image_route_policy(
    receipt: RouteReceipt,
    auth_context: AuthContext,
    *,
    model: str | None = None,
    workflow: str | None = None,
    manifest: Mapping[str, Any] | None = None,
) -> PolicyDecision:
    metadata = _image_manifest_policy_metadata(manifest)
    return evaluate_and_apply(
        auth_context.identity,
        make_policy_request(
            protocol="openai.images",
            intent=receipt.intent,
            model=model,
            workflow=workflow,
            backend=receipt.backend,
            capability_exposure=metadata["exposure"],
            capability_trust_tier=metadata["trust_tier"],
            capability_resource_tier=metadata["resource_tier"],
            capability_tags=metadata["tags"],
        ),
        receipt,
    )


def _image_manifest_policy_metadata(
    manifest: Mapping[str, Any] | None,
) -> dict[str, object]:
    if manifest is None:
        return {
            "exposure": "default",
            "trust_tier": "stable",
            "resource_tier": "batch",
            "tags": (),
        }

    trusted = bool(manifest.get("trusted", False))
    tags_raw = manifest.get("tags")
    tags: list[str] = []
    if isinstance(tags_raw, list):
        tags = [tag for tag in tags_raw if isinstance(tag, str) and tag]
    return {
        "exposure": _manifest_string_field(manifest, "exposure", "default"),
        "trust_tier": _manifest_string_field(
            manifest, "trust_tier", "stable" if trusted else "experimental"
        ),
        "resource_tier": _manifest_string_field(
            manifest, "resource_tier", "batch"
        ),
        "tags": tuple(dict.fromkeys(tags)),
    }


def _manifest_string_field(
    manifest: Mapping[str, Any], key: str, default: str
) -> str:
    value = manifest.get(key)
    if isinstance(value, str) and value:
        return value
    return default


def _policy_workflow_for_receipt(receipt: RouteReceipt | None) -> str | None:
    if receipt is None:
        return None
    return receipt.manifest_id or receipt.resolved_workflow or receipt.requested_workflow


def _policy_denied_response(decision: PolicyDecision) -> Response:
    """403 in the OpenAI error shape with the design §3.3 access code."""
    reason = decision.reasons[0] if decision.reasons else "This isn't in your access plan."
    error: dict[str, Any] = {"message": reason, "type": "access_error", "code": decision.code or "policy_denied"}
    if decision.side:
        error["details"] = {"side": decision.side, "plans": [s.split(":", 1)[1] for s in decision.sources
                                                         if s.startswith("access_plan:")]}
    return _gateway_refusal(Response(
        content=json.dumps({"error": error}),
        status_code=403,
        media_type="application/json",
    ), "authorization")


_RUNTIME_ROUTE_POLICY: dict[str, dict[str, Any]] = route_registry.runtime_route_policy(
    registry=_PROTOCOL_ROUTE_REGISTRY,
    proxy_config=config,
)


_ASSET_CONTENT_ROUTE_POLICY_BY_KIND: dict[str, dict[str, Any]] = (
    route_registry.asset_content_route_policy_by_kind(
        registry=_PROTOCOL_ROUTE_REGISTRY,
        proxy_config=config,
    )
)


def _asset_content_route_policy(asset_id: str) -> dict[str, Any] | None:
    parsed = _parse_asset_id(asset_id)
    if parsed is None:
        return None
    kind, _ = parsed
    return _ASSET_CONTENT_ROUTE_POLICY_BY_KIND.get(kind)


def _runtime_route_policy_decision(
    auth_context: AuthContext,
    request_path: str,
    *,
    policy: Mapping[str, Any] | None = None,
) -> PolicyDecision | None:
    route_policy = policy or _RUNTIME_ROUTE_POLICY.get(request_path)
    if route_policy is None:
        return None
    return evaluate_and_apply(
        auth_context.identity,
        make_policy_request(**route_policy),
    )


def _enforce_runtime_route_policy(
    auth_context: AuthContext,
    request_path: str,
    *,
    policy: Mapping[str, Any] | None = None,
) -> Response | None:
    decision = _runtime_route_policy_decision(
        auth_context,
        request_path,
        policy=policy,
    )
    if decision is not None and decision.denied:
        return _policy_denied_response(decision)
    return None


_SAFE_IMAGE_INPUT_NAMES = ("model", "size", "n", "response_format", "background", "prompt", "image")
_MASK_ROUTE_MANAGED_MANIFEST_INPUTS = ("source_mask", "mask_asset", "mask")


@dataclass(frozen=True)
class ImageEditMaskContext:
    source_image: bytes
    edit_mask: bytes
    source_size: tuple[int, int]
    mask_mode: str


def _image_error_response(message: str, *, param: str, code: str) -> Response:
    return Response(
        content=json.dumps({
            "error": {
                "message": message,
                "type": "invalid_request_error",
                "param": param,
                "code": code,
            }
        }),
        status_code=400,
        media_type="application/json",
    )


def _open_image_for_route(content: bytes, *, param: str):
    try:
        from PIL import Image
        import io

        image = Image.open(io.BytesIO(content))
        image.load()
        return image, None
    except Exception:
        return None, _image_error_response(
            f"{param} must be a valid image file",
            param=param,
            code="invalid_image",
        )


def _edit_mask_from_image(mask_image) -> tuple[Any, str]:
    """Return an L mask where white means "take generated pixels"."""
    if "A" in mask_image.getbands():
        alpha = mask_image.getchannel("A")
        return alpha.point(lambda value: 255 - value), "alpha"
    return mask_image.convert("L"), "grayscale"


def _prepare_image_edit_mask_context(
    *,
    source_image_content: bytes,
    mask_content: bytes,
) -> tuple[ImageEditMaskContext | None, Response | None]:
    source_image, source_error = _open_image_for_route(
        source_image_content,
        param="image",
    )
    if source_error is not None:
        return None, source_error

    mask_image, mask_error = _open_image_for_route(mask_content, param="mask")
    if mask_error is not None:
        return None, mask_error

    if mask_image.size != source_image.size:
        return None, _image_error_response(
            "mask must have the same dimensions as image",
            param="mask",
            code="invalid_mask_dimensions",
        )

    edit_mask, mode = _edit_mask_from_image(mask_image)
    return (
        ImageEditMaskContext(
            source_image=source_image_content,
            edit_mask=_image_to_png_bytes(edit_mask),
            source_size=source_image.size,
            mask_mode=mode,
        ),
        None,
    )


def _apply_edit_mask_as_source_alpha(context: ImageEditMaskContext) -> bytes:
    """Encode the OpenAI edit mask in source alpha for workflows that request it."""
    from PIL import Image
    import io

    source = Image.open(io.BytesIO(context.source_image)).convert("RGBA")
    source.load()
    edit_mask = Image.open(io.BytesIO(context.edit_mask)).convert("L")
    edit_mask.load()
    source.putalpha(edit_mask.point(lambda value: 255 - value))
    return _image_to_png_bytes(source)


def _image_to_png_bytes(image, metadata_from: bytes | None = None) -> bytes:
    """Encode ``image`` as PNG; ``metadata_from`` is a PNG whose text chunks
    (ComfyUI ``prompt``/``workflow``) must survive the re-encode."""
    import io

    output = io.BytesIO()
    image.save(output, format="PNG")
    encoded = output.getvalue()
    if metadata_from is not None:
        encoded = media_metadata.copy_png_text(metadata_from, encoded)
    return encoded


def _apply_image_edit_mask_composite(
    context: ImageEditMaskContext,
    generated_content: bytes,
) -> bytes:
    from PIL import Image
    import io

    generated = Image.open(io.BytesIO(generated_content)).convert("RGBA")
    generated.load()
    source = Image.open(io.BytesIO(context.source_image)).convert("RGBA")
    source.load()
    mask = Image.open(io.BytesIO(context.edit_mask)).convert("L")
    mask.load()

    if source.size != generated.size:
        source = source.resize(generated.size, Image.Resampling.LANCZOS)
    if mask.size != generated.size:
        mask = mask.resize(generated.size, Image.Resampling.LANCZOS)

    composited = Image.composite(generated, source, mask)
    return _image_to_png_bytes(composited, metadata_from=generated_content)


def _offset_image_bytes(
    content: bytes,
    *,
    x_fraction: float = 0.5,
    y_fraction: float = 0.5,
) -> bytes:
    from PIL import Image, ImageChops
    import io

    image = Image.open(io.BytesIO(content)).convert("RGBA")
    image.load()
    x_offset = int(round(image.width * x_fraction))
    y_offset = int(round(image.height * y_fraction))
    return _image_to_png_bytes(ImageChops.offset(image, x_offset, y_offset), metadata_from=content)


def _make_seam_cross_mask_png(
    width: int,
    height: int,
    *,
    seam_width: int,
) -> bytes:
    from PIL import Image, ImageDraw

    safe_width = max(1, min(int(seam_width), max(1, min(width, height))))
    image = Image.new("L", (width, height), 0)
    draw = ImageDraw.Draw(image)

    x0 = max(0, (width - safe_width) // 2)
    x1 = min(width - 1, x0 + safe_width - 1)
    y0 = max(0, (height - safe_width) // 2)
    y1 = min(height - 1, y0 + safe_width - 1)
    draw.rectangle((x0, 0, x1, height - 1), fill=255)
    draw.rectangle((0, y0, width - 1, y1), fill=255)
    return _image_to_png_bytes(image)


def _image_size_from_bytes(content: bytes) -> tuple[int, int]:
    from PIL import Image
    import io

    image = Image.open(io.BytesIO(content))
    image.load()
    return image.size


def _manifest_input_default(
    manifest: Mapping[str, Any] | None,
    name: str,
    fallback: Any,
) -> Any:
    if isinstance(manifest, Mapping):
        inputs = manifest.get("inputs")
        if isinstance(inputs, Mapping):
            spec = inputs.get(name)
            if isinstance(spec, Mapping) and "default" in spec:
                return spec["default"]
    return fallback


async def _upload_comfy_image_bytes(
    client: Any,
    headers: Mapping[str, str],
    content: bytes,
    *,
    filename: str,
    media_type: str = "image/png",
) -> tuple[str | None, Response | None]:
    files = {"image": (filename, content, media_type)}
    upload_resp = await client.post(
        f"{COMFY_HOST}/upload/image",
        headers=dict(headers),
        files=files,
    )
    if upload_resp.status_code != 200:
        return None, Response(
            content=json.dumps({
                "error": {
                    "message": f"Image upload failed: {upload_resp.text}",
                    "type": "api_error",
                }
            }),
            status_code=502,
            media_type="application/json",
        )

    uploaded_filename = upload_resp.json().get("name")
    if not uploaded_filename:
        return None, Response(
            content=json.dumps({
                "error": {
                    "message": "No filename returned from upload",
                    "type": "api_error",
                }
            }),
            status_code=502,
            media_type="application/json",
        )
    return str(uploaded_filename), None


def _gateway_image_generate_compose(manifest: Mapping[str, Any] | None) -> str | None:
    if not isinstance(manifest, Mapping):
        return None
    binding = (manifest.get("bindings") or {}).get("gateway")
    if not isinstance(binding, Mapping):
        return None
    compose = binding.get("compose")
    return str(compose) if isinstance(compose, str) and compose else None


def _gateway_image_model_id(record_manifest: Mapping[str, Any]) -> str | None:
    binding = (record_manifest.get("bindings") or {}).get("gateway")
    if not isinstance(binding, Mapping):
        return None
    model_id = binding.get("model_id")
    return str(model_id) if isinstance(model_id, str) and model_id else None


def _gateway_binding_value(
    manifest: Mapping[str, Any],
    name: str,
    *,
    fallback: str,
) -> str:
    binding = (manifest.get("bindings") or {}).get("gateway")
    if isinstance(binding, Mapping):
        value = binding.get(name)
        if isinstance(value, str) and value:
            return value
    return fallback


def _gateway_workflow_extension_values(
    *,
    body: Mapping[str, Any],
    manifest: Mapping[str, Any],
    receipt: RouteReceipt | None,
    standard_fields: frozenset[str],
) -> tuple[dict[str, Any], Response | None]:
    try:
        result = bind_workflow_extensions(
            body,
            manifest,
            "gateway",
            {},
            supported_names=_workflow_extension_supported_names(manifest, "gateway"),
            standard_fields=standard_fields,
        )
        if receipt is not None:
            record_image_extension_binding(receipt, result)
    except (ExtensionError, ManifestError, ValueError) as e:
        return {}, _image_extension_error_response(receipt, str(e))

    if result.unknown_top_level:
        name, reason = next(iter(result.unknown_top_level.items()))
        return {}, _image_extension_error_response(
            receipt,
            reason,
            param=name,
        )
    if result.validation.rejected:
        name, reason = next(iter(result.validation.rejected.items()))
        return {}, _image_extension_error_response(
            receipt,
            reason,
            param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{name}",
        )
    media_delivery.note_parameters(result.validation.accepted)
    return dict(result.validation.accepted), None


def _seed_field_for_workflow(workflow: Mapping[str, Any], seed_node: str | None) -> str:
    if seed_node and seed_node in workflow:
        inputs = workflow[seed_node].get("inputs", {})
        if isinstance(inputs, Mapping) and "noise_seed" in inputs:
            return "noise_seed"
    return "seed"


def _set_workflow_seed(
    workflow: Mapping[str, Any],
    *,
    seed_node: str | None,
    seed_field: str,
    seed: int | None,
) -> None:
    if not seed_node or seed_node not in workflow:
        return
    inputs = workflow[seed_node].get("inputs", {})
    if not isinstance(inputs, dict):
        return
    if seed is None:
        seed = random.randint(0, 2**32 - 1)
    inputs[seed_field] = int(seed)


async def _run_single_comfy_image(
    *,
    request: Request | None = None,
    client: httpx.AsyncClient,
    workflow: dict[str, Any],
    meta: Mapping[str, Any],
    headers: Mapping[str, str],
    label: str,
    seed: int | None = None,
) -> tuple[Response | None, bytes | None]:
    round_workflow = copy.deepcopy(workflow)
    apply_batch_size(round_workflow, dict(meta), 1)
    seed_node = meta.get("seed_node")
    seed_node_str = str(seed_node) if seed_node is not None else None
    _set_workflow_seed(
        round_workflow,
        seed_node=seed_node_str,
        seed_field=_seed_field_for_workflow(round_workflow, seed_node_str),
        seed=seed,
    )
    err, images = await _comfy_run_round(
        client,
        round_workflow,
        dict(headers),
        label,
        request=request,
    )
    if err is not None:
        return err, None
    if not images:
        return Response(
            content=json.dumps({
                "error": {
                    "message": "ComfyUI returned no images",
                    "type": "api_error",
                }
            }),
            status_code=502,
            media_type="application/json",
        ), None
    return None, images[0]


def _tile_seam_prompt(prompt: str, seam_prompt: Any) -> str:
    if isinstance(seam_prompt, str) and seam_prompt.strip():
        return seam_prompt.strip()
    return (
        f"{prompt}. Repair only the masked center seam cross so the texture "
        "wraps seamlessly on all edges. Preserve the source material, style, "
        "scale, lighting, and brush texture. Do not add borders, text, logos, "
        "objects, frames, or directional features."
    )


async def _proxy_offset_inpaint_tile_request(
    *,
    request: Request,
    body: Mapping[str, Any],
    auth_context: AuthContext,
    receipt: RouteReceipt | None,
    manifest: Mapping[str, Any] | None,
    prompt: str,
    model: str,
    size: str,
    n: int,
    response_format: str,
    headers: Mapping[str, str],
    output_format: str = "png",
    output_compression: Optional[int] = None,
    quality: str = "auto",
) -> Response:
    if manifest is None:
        return Response(
            content=json.dumps({
                "error": {
                    "message": f"Unknown gateway image workflow: {model}",
                    "type": "invalid_request_error",
                }
            }),
            status_code=400,
            media_type="application/json",
        )

    if receipt is not None:
        receipt.resolved_model = model
        receipt.requested_workflow = model
        receipt.resolved_workflow = str(manifest.get("id") or model)
        identity = manifest_identity(dict(manifest))
        receipt.attach_manifest(
            manifest_id=identity.id,
            manifest_version=identity.version,
            manifest_hash=identity.manifest_hash,
        )
        decision = _apply_image_route_policy(
            receipt,
            auth_context,
            model=model,
            workflow=_policy_workflow_for_receipt(receipt),
            manifest=manifest,
        )
        if decision.denied:
            return _policy_denied_response(decision)

    controls, control_error = _gateway_workflow_extension_values(
        body=body,
        manifest=manifest,
        receipt=receipt,
        standard_fields=STANDARD_IMAGE_GENERATE_FIELDS,
    )
    if control_error is not None:
        return control_error

    base_model = _gateway_binding_value(
        manifest,
        "base_model",
        fallback="flux2-klein-4b",
    )
    inpaint_model = _gateway_binding_value(
        manifest,
        "inpaint_model",
        fallback="flux2-klein-4b-inpaint",
    )
    base_workflow = load_comfy_workflow(base_model)
    inpaint_workflow = load_comfy_workflow(inpaint_model)
    base_manifest = _find_image_manifest("image.generate", base_model)
    inpaint_manifest = _find_image_manifest("image.edit", inpaint_model)
    if not base_workflow or not inpaint_workflow or base_manifest is None or inpaint_manifest is None:
        if receipt is not None:
            receipt.add_fallback_reason("offset_inpaint_tile_prerequisite_missing")
        return Response(
            content=json.dumps({
                "error": {
                    "message": (
                        "offset-inpaint tile generation requires the Flux2 "
                        "base and inpaint workflows plus their manifests"
                    ),
                    "type": "api_error",
                }
            }),
            status_code=503,
            media_type="application/json",
        )

    width, height = parse_size(size)

    base_workflow = copy.deepcopy(base_workflow)
    base_meta = base_workflow.pop("_meta", {})
    base_prompt_node = base_meta.get("prompt_node")
    if base_prompt_node and base_prompt_node in base_workflow:
        base_workflow[base_prompt_node]["inputs"]["text"] = prompt
    base_size_node = base_meta.get("size_node")
    if base_size_node and base_size_node in base_workflow:
        base_workflow[base_size_node]["inputs"]["width"] = width
        base_workflow[base_size_node]["inputs"]["height"] = height
    base_workflow = _apply_manifest_route_inputs(
        base_manifest,
        base_workflow,
        {"prompt": prompt, "width": width, "height": height},
    )
    base_extension_inputs = {
        name: value
        for name, value in controls.items()
        if name in {"steps", "guidance", "seed"}
    }
    if base_extension_inputs:
        base_workflow = bind_backend_request(
            base_manifest,
            "comfyui",
            base_workflow,
            base_extension_inputs,
        ).request
    set_workflow_background_removal(base_workflow, base_meta, False)

    fixed_seed = controls.get("seed")
    fixed_seed_int = int(fixed_seed) if isinstance(fixed_seed, int) and not isinstance(fixed_seed, bool) else None
    seam_width = int(_manifest_input_default(manifest, "seam_mask_width", 96))
    if "seam_mask_width" in controls:
        seam_width = int(controls["seam_mask_width"])
    seam_expand = int(_manifest_input_default(manifest, "seam_mask_expand", 0))
    if "seam_mask_expand" in controls:
        seam_expand = int(controls["seam_mask_expand"])
    seam_feather = int(_manifest_input_default(manifest, "seam_mask_feather", 32))
    if "seam_mask_feather" in controls:
        seam_feather = int(controls["seam_mask_feather"])
    seam_steps = int(_manifest_input_default(manifest, "seam_steps", 8))
    if "seam_steps" in controls:
        seam_steps = int(controls["seam_steps"])
    seam_guidance = float(_manifest_input_default(manifest, "seam_guidance", 4.0))
    if "seam_guidance" in controls:
        seam_guidance = float(controls["seam_guidance"])
    seam_denoise = float(_manifest_input_default(manifest, "seam_denoise", 0.58))
    if "seam_denoise" in controls:
        seam_denoise = float(controls["seam_denoise"])
    seam_prompt = _tile_seam_prompt(prompt, controls.get("seam_prompt"))

    images: list[bytes] = []
    response_headers: dict[str, str] = {
        "X-Image-Seamless-Tile-Strategy": "offset-inpaint",
        "X-Image-Seam-Mask-Width": str(seam_width),
    }
    rounds = 0

    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(COMFY_TIMEOUT, connect=10)) as client:
            for index in range(n):
                base_seed = (
                    fixed_seed_int + (index * 2)
                    if fixed_seed_int is not None
                    else None
                )
                seam_seed = base_seed + 1 if base_seed is not None else None
                err, base_image = await _run_single_comfy_image(
                    request=request,
                    client=client,
                    workflow=base_workflow,
                    meta=base_meta,
                    headers=headers,
                    label=f"offset tile base {index + 1}/{n}",
                    seed=base_seed,
                )
                rounds += 1
                if err is not None:
                    return err
                assert base_image is not None

                offset_image = _offset_image_bytes(base_image)
                actual_width, actual_height = _image_size_from_bytes(offset_image)
                mask = _make_seam_cross_mask_png(
                    actual_width,
                    actual_height,
                    seam_width=seam_width,
                )

                uploaded_image, upload_error = await _upload_comfy_image_bytes(
                    client,
                    headers,
                    offset_image,
                    filename=f"offset-tile-{index + 1}.png",
                )
                if upload_error is not None:
                    return upload_error
                uploaded_mask, upload_error = await _upload_comfy_image_bytes(
                    client,
                    headers,
                    mask,
                    filename=f"offset-tile-mask-{index + 1}.png",
                )
                if upload_error is not None:
                    return upload_error
                assert uploaded_image is not None
                assert uploaded_mask is not None

                edit_workflow = copy.deepcopy(inpaint_workflow)
                edit_meta = edit_workflow.pop("_meta", {})
                set_workflow_background_removal(edit_workflow, edit_meta, False)
                edit_workflow = bind_backend_request(
                    inpaint_manifest,
                    "comfyui",
                    edit_workflow,
                    {
                        "prompt": seam_prompt,
                        "source_image": uploaded_image,
                        "mask": uploaded_mask,
                        "width": actual_width,
                        "height": actual_height,
                        "steps": seam_steps,
                        "guidance": seam_guidance,
                        "denoise": seam_denoise,
                        "mask_expand": seam_expand,
                        "mask_feather": seam_feather,
                        "seed": seam_seed if seam_seed is not None else random.randint(0, 2**32 - 1),
                    },
                ).request

                err, repaired_offset = await _run_single_comfy_image(
                    request=request,
                    client=client,
                    workflow=edit_workflow,
                    meta=edit_meta,
                    headers=headers,
                    label=f"offset tile seam inpaint {index + 1}/{n}",
                    seed=seam_seed,
                )
                rounds += 1
                if err is not None:
                    return err
                assert repaired_offset is not None
                images.append(
                    _offset_image_bytes(
                        repaired_offset,
                        x_fraction=-0.5,
                        y_fraction=-0.5,
                    )
                )
    except httpx.TimeoutException:
        return Response(
            content=json.dumps({"error": {"message": "ComfyUI request timeout", "type": "api_error"}}),
            status_code=504,
            media_type="application/json",
        )
    except httpx.ConnectError:
        return Response(
            content=json.dumps({"error": {"message": f"ComfyUI unavailable at {COMFY_HOST}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json",
        )
    except Exception as e:
        return Response(
            content=json.dumps({"error": {"message": f"Gateway tile composition error: {e}", "type": "api_error"}}),
            status_code=502,
            media_type="application/json",
        )

    response_headers["X-Image-Rounds"] = str(rounds)
    response_headers["X-Image-Returned"] = str(len(images))
    return await asyncio.to_thread(_build_image_response_payload,
        request,
        images,
        response_format,
        response_headers,
        auth_context=auth_context,
        output_format=output_format,
        output_compression=output_compression,
        background="opaque",  # transparent is rejected earlier for this composed workflow
        quality=quality,
        size=str(size),
    )


def _manifest_uses_source_alpha_mask(manifest: Mapping[str, Any] | None) -> bool:
    if not isinstance(manifest, Mapping):
        return False
    bindings = manifest.get("bindings")
    comfyui = bindings.get("comfyui") if isinstance(bindings, Mapping) else None
    return bool(comfyui.get("mask_to_source_alpha")) if isinstance(comfyui, Mapping) else False


def _manifest_route_managed_mask_input(manifest: Mapping[str, Any] | None) -> str | None:
    if not isinstance(manifest, Mapping):
        return None
    inputs = manifest.get("inputs")
    binding = (manifest.get("bindings") or {}).get("comfyui")
    mapping = binding.get("map") if isinstance(binding, Mapping) else None
    if not isinstance(inputs, Mapping) or not isinstance(mapping, Mapping):
        return None
    for name in _MASK_ROUTE_MANAGED_MANIFEST_INPUTS:
        if name in inputs and name in mapping:
            return name
    return None


def _manifest_required_route_mask_input(manifest: Mapping[str, Any] | None) -> str | None:
    if not isinstance(manifest, Mapping):
        return None
    inputs = manifest.get("inputs")
    mask_name = _manifest_route_managed_mask_input(manifest)
    if not mask_name or not isinstance(inputs, Mapping):
        return None
    spec = inputs.get(mask_name)
    if isinstance(spec, Mapping) and spec.get("required"):
        return mask_name
    return None


def _apply_manifest_route_inputs(
    manifest: Mapping[str, Any] | None,
    workflow: Mapping[str, Any],
    values: Mapping[str, Any],
) -> dict[str, Any]:
    """Apply route-owned portable fields through a manifest when mapped.

    The image route owns OpenAI fields like ``size`` and turns them into
    portable ``width``/``height`` values. Some workflows need those values on
    more nodes than the historical hard-coded Flux ids, so reuse manifest
    bindings when they exist.
    """
    if not isinstance(manifest, Mapping):
        return dict(workflow)
    binding = (manifest.get("bindings") or {}).get("comfyui")
    mapping = binding.get("map") if isinstance(binding, Mapping) else None
    if not isinstance(mapping, Mapping):
        return dict(workflow)
    mapped_values = {
        name: value
        for name, value in values.items()
        if name in mapping
    }
    if not mapped_values:
        return dict(workflow)
    return bind_backend_request(
        dict(manifest),
        "comfyui",
        dict(workflow),
        mapped_values,
    ).request


def _prefer_inpaint_workflow_for_mask(model: str) -> str:
    if model.endswith("-inpaint"):
        return model
    base = model.removesuffix("-edit")
    candidate = f"{base}-inpaint"
    return candidate if load_comfy_workflow(candidate) else model


def _select_edit_workflow(model: str, *, image_count: int, has_mask: bool) -> str:
    """Resolve edit defaults while keeping explicit workflow selections intact."""
    selected = model
    if selected == IMAGE_MULTIREF_EDIT_DEFAULT_WORKFLOW:
        if has_mask:
            return _prefer_inpaint_workflow_for_mask(IMAGE_EDIT_DEFAULT_MODEL)
        return selected

    if not (selected.endswith("-edit") or selected.endswith("-inpaint")):
        direct_workflow = load_comfy_workflow(selected)
        direct_meta = direct_workflow.get("_meta", {}) if isinstance(direct_workflow, Mapping) else {}
        if not isinstance(direct_meta, Mapping) or not (direct_meta.get("image_node") or direct_meta.get("image_nodes")):
            selected = f"{selected}-edit"

    # A mask needs the mask-bound variant, which takes precedence over the
    # reference-pair workflow because the inpaint graph has one source slot.
    if has_mask:
        return _prefer_inpaint_workflow_for_mask(selected)

    if image_count > 1 and selected == IMAGE_EDIT_DEFAULT_MODEL:
        return IMAGE_MULTIREF_EDIT_DEFAULT_WORKFLOW
    return selected


def _attach_image_manifest_if_available(
    receipt: RouteReceipt | None,
    intent: str,
    resolved_model: str,
) -> None:
    """Best-effort: attach manifest identity if a manifest file matches the
    intent/model. Never raises; records a warning when unavailable."""
    if receipt is None:
        return
    try:
        manifest = _find_image_manifest(intent, resolved_model)
        if manifest is None:
            if not _MANIFEST_WORKFLOWS_DIR.is_dir():
                receipt.add_warning("manifest_identity_deferred:no_manifests_dir")
            else:
                receipt.add_warning("manifest_identity_deferred:no_match")
            return
        identity = manifest_identity(manifest)
        receipt.attach_manifest(
            manifest_id=identity.id,
            manifest_version=identity.version,
            manifest_hash=identity.manifest_hash,
        )
    except Exception:
        # Manifest attach is observational; never break the request.
        try:
            receipt.add_warning("manifest_identity_deferred:error")
        except Exception:
            pass


def _find_image_manifest(intent: str, resolved_model: str) -> dict[str, Any] | None:
    candidate_ids = {
        f"{intent}.{resolved_model}",
        f"{intent}.{resolved_model.removesuffix('-edit')}",
    }
    for record in GATEWAY_WORKFLOW_REGISTRY.records():
        manifest = record.manifest
        mid = str(manifest.get("id") or "")
        if manifest.get("intent") != intent:
            continue
        if mid in candidate_ids or mid.endswith(f".{resolved_model}"):
            return copy.deepcopy(dict(manifest))
    return None


def _record_unknown_image_fields(
    receipt: RouteReceipt | None,
    body: Mapping[str, Any],
    standard_fields: frozenset[str],
    *,
    extra_allowed_fields: set[str] | None = None,
) -> Response | None:
    allowed_fields = set(standard_fields)
    if extra_allowed_fields:
        allowed_fields.update(extra_allowed_fields)
    unknown = detect_unknown_top_level_fields(body, allowed_fields)
    if not unknown:
        return None
    for name, reason in unknown.items():
        _record_image_input(receipt, name, rejected_reason=reason)
    first_name = next(iter(unknown))
    return Response(
        content=json.dumps({
            "error": {
                "message": unknown[first_name],
                "type": "invalid_request_error",
                "param": first_name,
                "code": "unknown_parameter",
            }
        }),
        status_code=400,
        media_type="application/json",
    )


def _coerce_multipart_extension_value(value: Any) -> Any:
    if not isinstance(value, str):
        return value
    stripped = value.strip()
    if stripped == "":
        return value
    try:
        return json.loads(stripped)
    except json.JSONDecodeError:
        return value


def _multipart_bracket_parts(key: str) -> list[str] | None:
    if "[" not in key or not key.endswith("]"):
        return None
    root, rest = key.split("[", 1)
    if not root:
        return None
    parts = [root]
    cursor = rest
    while cursor:
        if "]" not in cursor:
            return None
        part, cursor = cursor.split("]", 1)
        if not part:
            return None
        parts.append(part)
        if cursor == "":
            break
        if not cursor.startswith("["):
            return None
        cursor = cursor[1:]
    return parts


def _merge_multipart_extension_bracket_field(
    body: dict[str, Any],
    key: str,
    value: Any,
) -> bool:
    parts = _multipart_bracket_parts(key)
    if not parts or parts[0] != "extensions" or len(parts) < 3:
        return False
    container = body.setdefault("extensions", {})
    if not isinstance(container, dict):
        return False
    cursor: dict[str, Any] = container
    for part in parts[1:-1]:
        existing = cursor.setdefault(part, {})
        if not isinstance(existing, dict):
            return False
        cursor = existing
    cursor[parts[-1]] = _coerce_multipart_extension_value(value)
    return True


def _manifest_ignores_prompt(manifest: Mapping[str, Any] | None) -> bool:
    if not isinstance(manifest, Mapping):
        return False
    inputs = manifest.get("inputs")
    return isinstance(inputs, Mapping) and "prompt" not in inputs


def _extension_asset_field_references(body: Mapping[str, Any]) -> dict[str, str]:
    """Return ``{extension_input: multipart_field}`` references from a body."""
    extensions = body.get("extensions")
    if not isinstance(extensions, Mapping):
        return {}
    block = extensions.get(WORKFLOW_EXTENSION_NAMESPACE)
    if not isinstance(block, Mapping):
        return {}

    references: dict[str, str] = {}
    for input_name, value in block.items():
        field_name = _extension_asset_multipart_field(value)
        if field_name:
            references[str(input_name)] = field_name
    return references


def _allowed_image_extension_asset_fields(
    *,
    request_body: Mapping[str, Any],
    manifest: Mapping[str, Any] | None,
    receipt: RouteReceipt | None,
) -> tuple[set[str], Response | None]:
    """Return multipart transport fields that are valid for this workflow.

    OpenAI image edits are multipart. Gateway workflow controls still belong
    under ``extensions.com.azizam.workflow``, but asset-valued controls such
    as a future ``control_image`` need a way to point at an additional file
    part without becoming top-level OpenAI parameters themselves.
    """
    references = _extension_asset_field_references(request_body)
    if not references:
        return set(), None

    if manifest is None:
        input_name = next(iter(references))
        return set(), _image_extension_error_response(
            receipt,
            "workflow extensions are not supported for the resolved image workflow",
            param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{input_name}",
        )

    inputs = manifest.get("inputs")
    if not isinstance(inputs, Mapping):
        return set(), _image_extension_error_response(
            receipt,
            "manifest must define an 'inputs' mapping",
        )

    supported = set(_workflow_extension_supported_names(manifest, "comfyui"))
    fields: set[str] = set()
    for input_name, field_name in references.items():
        spec = inputs.get(input_name)
        if input_name not in supported:
            return set(), _image_extension_error_response(
                receipt,
                f"{input_name} is not a supported asset extension input",
                param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{input_name}",
            )
        if not isinstance(spec, Mapping) or spec.get("type") != "asset":
            return set(), _image_extension_error_response(
                receipt,
                f"{input_name} is not an asset extension input",
                param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{input_name}",
            )
        if field_name in STANDARD_IMAGE_EDIT_FIELDS:
            return set(), _image_extension_error_response(
                receipt,
                f"multipart field {field_name!r} is reserved for OpenAI image edits",
                param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{input_name}",
            )
        fields.add(field_name)
    return fields, None


def _extension_asset_multipart_field(value: Any) -> str | None:
    if not isinstance(value, Mapping):
        return None
    field = value.get("multipart_field") or value.get("form_field")
    if not isinstance(field, str):
        return None
    field = field.strip()
    return field or None


def _extension_asset_id(value: Any) -> str | None:
    if not isinstance(value, Mapping):
        return None
    asset_id = value.get("asset_id")
    if not isinstance(asset_id, str):
        return None
    asset_id = asset_id.strip()
    return asset_id or None


def _request_without_top_level_fields(
    body: Mapping[str, Any],
    field_names: set[str],
) -> dict[str, Any]:
    if not field_names:
        return dict(body)
    return {
        str(key): value
        for key, value in body.items()
        if str(key) not in field_names
    }


def _workflow_extension_supported_names(manifest: Mapping[str, Any], backend: str) -> tuple[str, ...]:
    binding = (manifest.get("bindings") or {}).get(backend)
    if not isinstance(binding, Mapping):
        return ()
    mapping = binding.get("map")
    if not isinstance(mapping, Mapping):
        return ()
    # These are already handled by the OpenAI-shaped route itself. Keeping
    # them out of the extension supported set prevents manifest-required
    # portable fields from rejecting normal OpenAI requests.
    standard_portable_names = {
        "prompt",
        "source_image",
        "width",
        "height",
        *_MASK_ROUTE_MANAGED_MANIFEST_INPUTS,
    }
    route_bound = binding.get("route_bound_inputs")
    if isinstance(route_bound, list | tuple | set):
        standard_portable_names.update(
            str(name) for name in route_bound if isinstance(name, str) and name
        )
    return tuple(name for name in mapping.keys() if name not in standard_portable_names)


def _manifest_required_route_bound_inputs(
    manifest: Mapping[str, Any] | None, backend: str
) -> tuple[str, ...]:
    if not isinstance(manifest, Mapping):
        return ()
    bindings = manifest.get("bindings")
    binding = bindings.get(backend) if isinstance(bindings, Mapping) else None
    if not isinstance(binding, Mapping):
        return ()
    names = binding.get("route_bound_inputs")
    if not isinstance(names, list | tuple | set):
        return ()
    return tuple(name for name in names if isinstance(name, str) and name)


def _workflow_extensions_present(body: Mapping[str, Any]) -> bool:
    extensions = body.get("extensions")
    if not isinstance(extensions, Mapping):
        return extensions is not None
    missing = object()
    block = extensions.get(WORKFLOW_EXTENSION_NAMESPACE, missing)
    if block is missing:
        return False
    if isinstance(block, Mapping):
        # Gateway-level controls (metadata) are valid on every workflow.
        return not block or any(name not in provenance.RESERVED_GATEWAY_CONTROLS for name in block)
    return True


def _workflow_extension_integer(body: Mapping[str, Any], name: str) -> Optional[int]:
    extensions = body.get("extensions")
    if not isinstance(extensions, Mapping):
        return None
    block = extensions.get(WORKFLOW_EXTENSION_NAMESPACE)
    if not isinstance(block, Mapping):
        return None
    value = block.get(name)
    if isinstance(value, bool) or not isinstance(value, int):
        return None
    return value


def _image_extension_error_response(
    receipt: RouteReceipt | None,
    message: str,
    *,
    param: str = "extensions",
    status_code: int = 400,
) -> Response:
    _record_image_input(receipt, param, rejected_reason=message)
    return Response(
        content=json.dumps({
            "error": {
                "message": message,
                "type": "invalid_request_error",
                "param": param,
                "code": "invalid_extension",
            }
        }),
        status_code=status_code,
        media_type="application/json",
    )


async def _upload_image_workflow_extension_assets(
    *,
    form: Any,
    request_body: Mapping[str, Any],
    manifest: Mapping[str, Any] | None,
    client: Any,
    headers: Mapping[str, str],
    receipt: RouteReceipt | None,
    auth_context: AuthContext | None = None,
) -> tuple[dict[str, Any], Response | None]:
    """Upload extension-referenced image assets and replace them with filenames.

    The extension value shape is:

    ``{"multipart_field": "control_image"}``

    The top-level multipart field is only transport. It is removed before
    extension validation so it never becomes a public OpenAI-compatible field.
    """
    updated = dict(request_body)
    if manifest is None:
        return updated, None

    extensions = request_body.get("extensions")
    if not isinstance(extensions, Mapping):
        return updated, None
    block = extensions.get(WORKFLOW_EXTENSION_NAMESPACE)
    if not isinstance(block, Mapping):
        return updated, None

    inputs = manifest.get("inputs")
    if not isinstance(inputs, Mapping):
        return updated, None

    supported = set(_workflow_extension_supported_names(manifest, "comfyui"))
    allowed_fields, allow_error = _allowed_image_extension_asset_fields(
        request_body=request_body,
        manifest=manifest,
        receipt=receipt,
    )
    if allow_error is not None:
        return updated, allow_error
    next_block = dict(block)
    uploaded_any = False
    for input_name, value in block.items():
        field_name = _extension_asset_multipart_field(value)
        asset_id = _extension_asset_id(value)
        if field_name is None and asset_id is None:
            continue

        input_key = str(input_name)
        spec = inputs.get(input_key)
        if field_name is not None and field_name not in allowed_fields:
            continue
        if input_key not in supported or not isinstance(spec, Mapping):
            return updated, _image_extension_error_response(
                receipt,
                f"{input_key} is not a supported asset extension input",
                param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{input_key}",
            )
        if spec.get("type") != "asset":
            return updated, _image_extension_error_response(
                receipt,
                f"{input_key} is not an asset extension input",
                param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{input_key}",
            )

        if asset_id is not None:
            try:
                content, filename = _resolve_cached_image_asset(
                    asset_id,
                    auth_context,
                )
            except _InputReferenceError as exc:
                return updated, _image_extension_error_response(
                    receipt,
                    str(exc),
                    param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{input_key}",
                )
            content_type = asset_media_type(asset_id, asset_cache_path(asset_id))
        else:
            upload = form.get(field_name)
            read = getattr(upload, "read", None)
            if upload is None or not callable(read):
                return updated, _image_extension_error_response(
                    receipt,
                    f"multipart field {field_name!r} is required for {input_key}",
                    param=f"extensions.{WORKFLOW_EXTENSION_NAMESPACE}.{input_key}",
                )

            try:
                content = await read()
            except Exception as exc:  # noqa: BLE001
                return updated, _image_extension_error_response(
                    receipt,
                    f"could not read multipart field {field_name!r}: {exc}",
                    param=field_name,
                )

            filename = getattr(upload, "filename", None) or f"{field_name}.png"
            content_type = getattr(upload, "content_type", None) or "image/png"
        files = {"image": (filename, content, content_type)}
        upload_resp = await client.post(
            f"{COMFY_HOST}/upload/image",
            headers=dict(headers),
            files=files,
        )
        if upload_resp.status_code != 200:
            return updated, Response(
                content=json.dumps({
                    "error": {
                        "message": f"Image upload failed: {upload_resp.text}",
                        "type": "api_error",
                    }
                }),
                status_code=502,
                media_type="application/json",
            )

        uploaded_filename = upload_resp.json().get("name")
        if not uploaded_filename:
            return updated, Response(
                content=json.dumps({
                    "error": {
                        "message": "No filename returned from upload",
                        "type": "api_error",
                    }
                }),
                status_code=502,
                media_type="application/json",
            )

        next_block[input_key] = str(uploaded_filename)
        uploaded_any = True
        if field_name is not None:
            _record_image_input(receipt, field_name)

    if uploaded_any:
        next_extensions = dict(extensions)
        next_extensions[WORKFLOW_EXTENSION_NAMESPACE] = next_block
        updated["extensions"] = next_extensions
    return updated, None


async def _apply_workflow_extensions_to_image_request(
    *,
    request_body: Mapping[str, Any],
    manifest: Mapping[str, Any] | None,
    backend_request: Mapping[str, Any],
    standard_fields: frozenset[str],
    receipt: RouteReceipt | None,
    form: Any | None = None,
    client: Any | None = None,
    headers: Mapping[str, str] | None = None,
    extension_asset_fields: set[str] | None = None,
    auth_context: AuthContext | None = None,
) -> tuple[dict[str, Any] | None, Response | None]:
    asset_fields = extension_asset_fields or set()
    unknown_response = _record_unknown_image_fields(
        receipt,
        request_body,
        standard_fields,
        extra_allowed_fields=asset_fields,
    )
    if unknown_response is not None:
        return None, unknown_response

    extension_body = dict(request_body)
    if form is not None and client is not None:
        extension_body, upload_response = await _upload_image_workflow_extension_assets(
            form=form,
            request_body=request_body,
            manifest=manifest,
            client=client,
            headers=headers or {},
            receipt=receipt,
            auth_context=auth_context,
        )
        if upload_response is not None:
            return None, upload_response
    extension_body = _request_without_top_level_fields(extension_body, asset_fields)

    if manifest is None:
        if _workflow_extensions_present(extension_body):
            return None, _image_extension_error_response(
                receipt,
                "workflow extensions are not supported for the resolved image workflow",
            )
        return dict(backend_request), None

    try:
        result = bind_workflow_extensions(
            extension_body,
            manifest,
            "comfyui",
            backend_request,
            supported_names=_workflow_extension_supported_names(manifest, "comfyui"),
            standard_fields=standard_fields,
        )
        if receipt is not None:
            record_image_extension_binding(receipt, result)
    except (ExtensionError, ManifestError, ValueError) as e:
        return None, _image_extension_error_response(receipt, str(e))

    if result.unknown_top_level:
        name, reason = next(iter(result.unknown_top_level.items()))
        return None, _image_extension_error_response(receipt, reason, param=name)
    if result.validation.rejected:
        name, reason = next(iter(result.validation.rejected.items()))
        return None, _image_extension_error_response(
            receipt,
            reason,
            param=f"extensions.{result.namespace}.{name}",
        )
    return result.request or dict(backend_request), None


def _record_image_input(
    receipt: RouteReceipt | None,
    name: str,
    *,
    accepted: bool = True,
    rejected_reason: str | None = None,
    ignored_reason: str | None = None,
) -> None:
    if receipt is None:
        return
    try:
        if rejected_reason is not None:
            receipt.reject_input(name, rejected_reason)
        elif ignored_reason is not None:
            receipt.ignore_input(name, ignored_reason)
        elif accepted:
            receipt.accept_input(name)
    except Exception:
        pass


def _image_receipt_status(status_code: int) -> str:
    if 200 <= status_code < 300:
        return "ok"
    if 400 <= status_code < 500:
        return "rejected"
    return "error"


def finish_image_route_receipt(
    receipt: RouteReceipt,
    response: Response | None,
    *,
    status: str | None = None,
) -> None:
    """Finish the receipt and emit a body-free firehose event.

    ``status`` overrides the one derived from the response; a cancelled
    request has no response."""
    status_code = int(getattr(response, "status_code", 0) or 0)
    response_headers = getattr(response, "headers", {})
    if response_headers.get("X-ComfyUI-Models-Freed") == "true":
        receipt.metadata["comfyui_models_freed_for_vram"] = True
    receipt.finish(status or _image_receipt_status(status_code))
    try:
        receipt_store.record(receipt)
    except Exception as e:
        try:
            print(f"[proxy] receipt_store.record failed: {e}", flush=True)
        except Exception:
            pass
    try:
        firehose_metrics.record_event(
            "image_route_receipt",
            f"{receipt.intent} {receipt.status}",
            request_id=receipt.request_id,
            path=receipt.path,
            intent=receipt.intent,
            backend=receipt.backend,
            api_key_name=receipt.api_key_name,
            policy_decision=receipt.policy_decision,
            status=receipt.status,
            http_status=status_code,
            latency_ms=receipt.latency_ms,
            requested_model=receipt.requested_model,
            resolved_model=receipt.resolved_model,
            requested_workflow=receipt.requested_workflow,
            resolved_workflow=receipt.resolved_workflow,
            manifest_id=receipt.manifest_id,
            manifest_version=receipt.manifest_version,
            accepted_inputs=list(receipt.accepted_inputs),
            rejected_inputs=dict(receipt.rejected_inputs),
            ignored_inputs=dict(receipt.ignored_inputs),
            fallback_reasons=list(receipt.fallback_reasons),
            warnings=list(receipt.warnings),
        )
    except Exception:
        # Receipts are observational; never break the request path.
        pass


class _RequestUrlShim:
    def __init__(self, *, scheme: str, netloc: str) -> None:
        self.scheme = scheme
        self.netloc = netloc


class _JsonBodyRequestShim:
    """Small Request-shaped object for replaying JSON jobs off the HTTP path."""

    query_params: dict[str, str] = {}
    method = "POST"

    def __init__(
        self,
        *,
        body: Mapping[str, Any],
        headers: Mapping[str, str],
        scheme: str,
        netloc: str,
        scope: Mapping[str, Any] | None = None,
    ) -> None:
        self._body = copy.deepcopy(dict(body))
        self.headers = dict(headers)
        self.url = _RequestUrlShim(scheme=scheme, netloc=netloc)
        self.scope = dict(scope or {})

    async def json(self) -> dict[str, Any]:
        return copy.deepcopy(self._body)


class _FormBodyRequestShim(_JsonBodyRequestShim):
    """Request-shaped multipart form for replaying an edit off the HTTP path."""

    def __init__(self, *, form: FormData, scheme: str, netloc: str) -> None:
        super().__init__(body={}, headers={}, scheme=scheme, netloc=netloc)
        self._form = form

    async def form(self) -> FormData:
        return self._form


def _gateway_auth_context(request: Request, path: str) -> AuthContext | Response:
    auth_context = _auth_context_from_scope(request)
    if auth_context is not NO_AUTH_CONTEXT:
        return auth_context
    return authenticate_request(request, path)


def _safe_image_job_headers(request: Request) -> dict[str, str]:
    headers: dict[str, str] = {}
    for name in ("host", "x-forwarded-host", "x-forwarded-proto"):
        value = request.headers.get(name)
        if value:
            headers[name] = value
    return headers


def _image_media_job_payload_path(job_id: str) -> Path:
    return IMAGE_MEDIA_JOB_PAYLOAD_DIR / f"{job_id}.json"


def _prompt_migration_state_path() -> Path:
    return Path(media_jobs.DB_PATH).with_name("prompt_metadata_migration.db")


_PROMPT_PURGE_COLUMNS = {
    "payloads_pending": "INTEGER NOT NULL DEFAULT 1",
    "generation": "INTEGER NOT NULL DEFAULT 1",
    "queued_at": "INTEGER",
    "attempts": "INTEGER NOT NULL DEFAULT 0",
    "last_attempt_at": "INTEGER",
    "files_pending": "INTEGER",
    "last_error": "TEXT",
    "cutoff": "INTEGER NOT NULL DEFAULT 0",
}
# Set while the maintenance loop runs, so an erasure can start its file
# cleanup at once instead of at the next minute.
_PROMPT_PURGE_WAKE: tuple[asyncio.AbstractEventLoop, asyncio.Event] | None = None
_PROMPT_PURGE_DRAIN_LOCK = threading.Lock()


@contextlib.contextmanager
def _prompt_purge_queue() -> Iterable[Any]:
    import sqlite3
    path = _prompt_migration_state_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    with contextlib.closing(sqlite3.connect(path, timeout=5)) as conn, conn:
        # The write lock serializes the schema upgrade across threads and processes.
        conn.execute("BEGIN IMMEDIATE")
        conn.execute("CREATE TABLE IF NOT EXISTS prompt_purge_queue (person_id TEXT PRIMARY KEY)")
        conn.execute("CREATE TABLE IF NOT EXISTS prompt_purge_done (person_id TEXT PRIMARY KEY, cutoff INTEGER NOT NULL)")
        present = {row[1] for row in conn.execute("PRAGMA table_info(prompt_purge_queue)")}
        for name, ddl in _PROMPT_PURGE_COLUMNS.items():
            if name not in present:
                conn.execute(f"ALTER TABLE prompt_purge_queue ADD COLUMN {name} {ddl}")
        yield conn


def _queue_prompt_purge(person_id: str, cutoff: int) -> None:
    # A new request bumps the generation, so a drain that started earlier
    # cannot mark the newer request done. ``cutoff`` is the erasure time
    # the stripping covers; "*" is the household kill switch.
    with _prompt_purge_queue() as conn:
        conn.execute(
            "INSERT INTO prompt_purge_queue(person_id, generation, queued_at, cutoff) VALUES (?, 1, ?, ?) "
            "ON CONFLICT(person_id) DO UPDATE SET generation=generation+1, "
            "cutoff=MAX(cutoff, excluded.cutoff), payloads_pending=1",
            (person_id, int(time.time()), int(cutoff)),
        )


def _prompt_purge_covered(person_id: str) -> int:
    """Return the latest erasure cutoff already queued or stripped."""
    if not _prompt_migration_state_path().exists():
        return 0
    with _prompt_purge_queue() as conn:
        row = conn.execute(
            "SELECT MAX(COALESCE((SELECT cutoff FROM prompt_purge_queue WHERE person_id=?), 0), "
            "COALESCE((SELECT cutoff FROM prompt_purge_done WHERE person_id=?), 0))",
            (person_id, person_id),
        ).fetchone()
    return int(row[0] or 0)


def _pending_prompt_purges() -> list[str]:
    if not _prompt_migration_state_path().exists():
        return []
    with _prompt_purge_queue() as conn:
        return [row[0] for row in conn.execute("SELECT person_id FROM prompt_purge_queue ORDER BY queued_at, person_id")]


def _finish_prompt_purge(person_id: str, generation: int, cutoff: int, *, complete: bool,
                         files_pending: int | None, error: str | None) -> None:
    with _prompt_purge_queue() as conn:
        if complete:
            conn.execute(
                "INSERT INTO prompt_purge_done(person_id, cutoff) VALUES (?, ?) "
                "ON CONFLICT(person_id) DO UPDATE SET cutoff=MAX(cutoff, excluded.cutoff)",
                (person_id, int(cutoff)),
            )
            conn.execute("DELETE FROM prompt_purge_queue WHERE person_id=? AND generation=?", (person_id, generation))
        else:
            conn.execute(
                "UPDATE prompt_purge_queue SET attempts=attempts+1, last_attempt_at=?, files_pending=?, last_error=? "
                "WHERE person_id=?", (int(time.time()), files_pending, error, person_id),
            )


def _prompt_purge_status(person_id: str) -> dict[str, Any]:
    """Report queued cached-file cleanup for one person, household cleanup included.

    Rows carry error codes and counts only, never file names or prompt text.
    """
    rows = []
    if _prompt_migration_state_path().exists():
        with _prompt_purge_queue() as conn:
            rows = conn.execute(
                "SELECT queued_at, attempts, last_attempt_at, files_pending, last_error "
                "FROM prompt_purge_queue WHERE person_id IN (?, '*')", (person_id,),
            ).fetchall()
    if not rows:
        if person_id == "*":
            cutoff = prompt_memory.household_erasure_cutoff(admin_path=ADMIN_STORE.path) or 0
        else:
            cutoff = prompt_memory.recorded_erasure_cutoff(person_id, admin_path=ADMIN_STORE.path)
        if cutoff > _prompt_purge_covered(person_id):
            return {"pending": True, "retry_scheduled": True,
                    "metadata_stripping": {"status": "retrying", "last_error": "cleanup_not_queued"}}
        return {"pending": False, "metadata_stripping": {"status": "complete"}}
    attempts = max(row[1] for row in rows)
    counts = [row[3] for row in rows if row[3] is not None]
    return {"pending": True, "metadata_stripping": {
        "status": "retrying" if attempts else "queued",
        "queued_at": min((row[0] for row in rows if row[0] is not None), default=None),
        "attempts": attempts,
        "last_attempt_at": max((row[2] for row in rows if row[2] is not None), default=None),
        "files_pending": sum(counts) if counts else None,
        "last_error": next((row[4] for row in rows if row[4]), None),
    }}


def _person_prompt_owner_keys(person_id: str) -> set[str]:
    app_ids = {app["id"] for app in ADMIN_STORE.list_apps() if app.get("owner_user_id") == person_id}
    owner_keys = {f"app:{app_id}" for app_id in app_ids}
    for credential in admin_store.list_credentials(path=ADMIN_STORE.path):
        if credential.get("app_id") in app_ids:
            owner_keys.add(credential["hash"])
    return owner_keys


def _person_cached_asset_ids(person_id: str) -> set[str]:
    # Legacy assets have App attribution only. Their metadata is stripped for
    # that App's owner; new assets use explicit authenticated maker facts.
    owner_keys = _person_prompt_owner_keys(person_id)
    assets: set[str] = set()
    for asset_id in me_media.create_asset_catalog_provider(IMAGE_CACHE_DIR)():
        metadata = _read_asset_metadata(asset_id)
        if "maker_person_ids" in metadata:
            owned = person_id in metadata["maker_person_ids"]
        else:
            owned = bool(owner_keys.intersection(metadata.get("owner_key_hashes") or []))
        if owned:
            assets.add(asset_id)
    return assets


def _purge_prompt_payload_files(person_id: str | None = None, *, before: int | None = None) -> None:
    # ``before`` spares spools made after an erasure cutoff, such as jobs
    # started after a member turned memory back on.
    def spared(payload: Mapping[str, Any] | None) -> bool:
        return before is not None and int((payload or {}).get("created_at") or 0) > before

    with _MEDIA_PAYLOAD_LOCK:
        # Move active jobs to memory so they can finish without a durable prompt.
        if IMAGE_MEDIA_JOB_PAYLOAD_DIR.exists():
            for path in IMAGE_MEDIA_JOB_PAYLOAD_DIR.glob("mj_*.json"):
                job_id = path.stem
                payload = _load_image_media_job_payload(job_id)
                if person_id is not None and (payload or {}).get("auth", {}).get("person_id") != person_id:
                    continue
                if spared(payload):
                    continue
                job = media_jobs.get(job_id, audience="internal", path=media_jobs.DB_PATH)
                if job and job.get("status") not in media_jobs.TERMINAL_STATUSES and payload is not None and isinstance(payload.get("body"), dict):
                    payload["body"].setdefault("extensions", {})[prompt_memory.NAMESPACE] = {"mode": "forget"}
                    try:
                        _store_ephemeral_media_job_payload(job_id, payload)
                    except EphemeralMediaPayloadCapacityError:
                        media_jobs.update_status(
                            job_id,
                            media_jobs.STATUS_FAILED,
                            error="Privacy cleanup exceeded temporary payload capacity",
                            path=media_jobs.DB_PATH,
                        )
                path.unlink(missing_ok=True)
            # A partial spool cannot be resumed or reliably attributed.
            for path in IMAGE_MEDIA_JOB_PAYLOAD_DIR.glob("mj_*.json.tmp"):
                if person_id is None and (before is None or int(path.stat().st_mtime) <= before):
                    path.unlink(missing_ok=True)
        for payload in list(_EPHEMERAL_MEDIA_JOB_PAYLOADS.values()):
            if not isinstance(payload.get("body"), dict) or spared(payload):
                continue
            if person_id is None or payload.get("auth", {}).get("person_id") == person_id:
                payload["body"].setdefault("extensions", {})[prompt_memory.NAMESPACE] = {"mode": "forget"}


def _wake_prompt_purge_drain() -> None:
    wake = _PROMPT_PURGE_WAKE
    if wake is None:
        return
    loop, event = wake
    try:
        loop.call_soon_threadsafe(event.set)
    except RuntimeError:
        pass  # The loop closed; the next start drains the durable queue.


def _purge_person_prompt_memory(person_id: str, *, cutoff: int | None = None) -> dict[str, Any]:
    """Erase a person's saved prompts and chats now; queue their cached files.

    Stripping files can wait behind the migration's scan lock, so it runs in
    the background and stays visible through ``_prompt_purge_status``.
    """
    cutoff = prompt_memory.mark_person_erasure(person_id, admin_path=ADMIN_STORE.path, now=cutoff)
    _erase_person_prompts_before(person_id, cutoff)
    prompt_memory.complete_erasure(person_id, cutoff, admin_path=ADMIN_STORE.path)
    _wake_prompt_purge_drain()
    return _prompt_purge_status(person_id)


def _erase_person_prompts_before(person_id: str, cutoff: int) -> None:
    owner_keys = _person_prompt_owner_keys(person_id)
    media_jobs.erase_prompt_derivatives(owner_keys, before=cutoff, path=media_jobs.DB_PATH)
    prompt_memory.prune_person_before(person_id, cutoff)
    responses_store.delete_person_before(person_id, cutoff, path=responses_store.DB_PATH)
    # Persist retry intent before spool cleanup, which can fail independently.
    _queue_prompt_purge(person_id, cutoff)
    _purge_queued_payloads(person_id)


def _purge_prompt_memory_on_kill() -> dict[str, Any]:
    cutoff = prompt_memory.household_erasure_cutoff(admin_path=ADMIN_STORE.path)
    if cutoff is None:
        cutoff = prompt_memory.mark_person_erasure("*", admin_path=ADMIN_STORE.path)
    media_jobs.erase_prompt_derivatives({"*"}, before=cutoff, path=media_jobs.DB_PATH)
    prompt_memory.prune_all_before(cutoff)
    responses_store.delete_all_before(cutoff, path=responses_store.DB_PATH)
    _queue_prompt_purge("*", cutoff)
    _purge_queued_payloads("*")
    _wake_prompt_purge_drain()
    return _prompt_purge_status("*")


def _purge_queued_payloads(person_id: str) -> None:
    with _prompt_purge_queue() as conn:
        row = conn.execute("SELECT generation, cutoff, payloads_pending FROM prompt_purge_queue WHERE person_id=?", (person_id,)).fetchone()
    if row is None or not row[2]:
        return
    generation, cutoff, _ = row
    _purge_prompt_payload_files(None if person_id == "*" else person_id, before=cutoff)
    with _prompt_purge_queue() as conn:
        conn.execute("UPDATE prompt_purge_queue SET payloads_pending=0 WHERE person_id=? AND generation=?",
                     (person_id, generation))


def _strip_queued_prompt_files(person_id: str) -> None:
    with _prompt_purge_queue() as conn:
        row = conn.execute("SELECT generation, cutoff FROM prompt_purge_queue WHERE person_id=?", (person_id,)).fetchone()
    if row is None:
        return
    generation, cutoff = row
    try:
        _purge_queued_payloads(person_id)
        result = prompt_metadata_migration.strip_cached_assets(
            IMAGE_CACHE_DIR, _prompt_migration_state_path(),
            asset_ids=None if person_id == "*" else _person_cached_asset_ids(person_id),
            legacy_workdir=Path(__file__).resolve().parent / "cache" / "media_metadata",
        )
    except Exception as exc:
        _finish_prompt_purge(person_id, generation, cutoff, complete=False, files_pending=None, error=type(exc).__name__)
        raise
    _finish_prompt_purge(person_id, generation, cutoff, complete=result.complete, files_pending=result.pending,
                         error=min(result.errors.values(), default=None))


def _drain_prompt_purges() -> None:
    """Strip cached files for every queued erasure; failures stay queued."""
    # Only one drain at a time; the caller that loses leaves the work to it.
    if not _PROMPT_PURGE_DRAIN_LOCK.acquire(blocking=False):
        return
    try:
        for person_id in _pending_prompt_purges():
            try:
                _strip_queued_prompt_files(person_id)
            except Exception as exc:
                print(f"[proxy] prompt file cleanup pending: {type(exc).__name__}", flush=True)
    finally:
        _PROMPT_PURGE_DRAIN_LOCK.release()


def _maintain_household_prompt_memory() -> None:
    # Keep the fence for in-flight writes; replay cleanup only while unfinished.
    with prompt_memory.retention_guard(ADMIN_STORE.path) as household:
        cutoff = prompt_memory.household_erasure_cutoff(admin_path=ADMIN_STORE.path)
        pending = prompt_memory.erasure_pending("*", admin_path=ADMIN_STORE.path)
        needs_cleanup = cutoff is not None and (pending or cutoff > _prompt_purge_covered("*"))
        if needs_cleanup and household["never_keep"]:
            # Legacy rows may postdate the recorded switch. Erase them while
            # off, before a concurrent re-enable can allow fresh prompt writes.
            prompt_memory.delete_all()
            responses_store.delete_all(path=responses_store.DB_PATH)
    if needs_cleanup:
        media_jobs.erase_prompt_derivatives({"*"}, before=cutoff, path=media_jobs.DB_PATH)
        prompt_memory.prune_all_before(cutoff)
        responses_store.delete_all_before(cutoff, path=responses_store.DB_PATH)
        if cutoff > _prompt_purge_covered("*"):
            _queue_prompt_purge("*", cutoff)
            _purge_queued_payloads("*")
        prompt_memory.complete_erasure("*", cutoff, admin_path=ADMIN_STORE.path)
    prompt_memory.tighten_retention(household["retention_cap"])


def _maintain_person_prompt_memory(person_id: str) -> None:
    # The cutoff only rises to when memory went off, read in the same
    # transaction, so prompts saved after switching back on survive.
    cutoff = prompt_memory.settle_erasure_cutoff(person_id, admin_path=ADMIN_STORE.path)
    pending = prompt_memory.erasure_pending(person_id, admin_path=ADMIN_STORE.path)
    needs_cleanup = cutoff > 0 and (pending or cutoff > _prompt_purge_covered(person_id))
    if needs_cleanup:
        if cutoff > _prompt_purge_covered(person_id):
            # Retry a request whose cleanup stopped before it was queued.
            _erase_person_prompts_before(person_id, cutoff)
        else:
            owner_keys = _person_prompt_owner_keys(person_id)
            media_jobs.erase_prompt_derivatives(owner_keys, before=cutoff, path=media_jobs.DB_PATH)
            prompt_memory.prune_person_before(person_id, cutoff)
            responses_store.delete_person_before(person_id, cutoff, path=responses_store.DB_PATH)
    if needs_cleanup:
        prompt_memory.complete_erasure(person_id, cutoff, admin_path=ADMIN_STORE.path)
    with prompt_memory.retention_guard(ADMIN_STORE.path, person_id) as policy:
        retention = policy["retention"]
    prompt_memory.tighten_retention(retention, person_id=person_id)


def _maintain_prompt_memory() -> None:
    # Each step reads its own setting when it runs. A decision read at the
    # start of the pass can be stale by the time a slow step reaches it.
    operations = [_maintain_household_prompt_memory]
    for user in admin_store.list_users(path=ADMIN_STORE.path):
        operations.append(lambda person_id=user["id"]: _maintain_person_prompt_memory(person_id))
    operations.append(_drain_prompt_purges)
    for operation in operations:
        try:
            operation()
        except Exception as exc:
            print(f"[proxy] prompt privacy cleanup pending: {type(exc).__name__}", flush=True)
    prompt_memory.prune()
    _prune_orphaned_media_job_payloads()


async def _drain_prompt_purges_on_wake(stop_event: asyncio.Event, wake: asyncio.Event, seconds: float) -> None:
    loop = asyncio.get_running_loop()
    deadline = loop.time() + seconds
    while not stop_event.is_set() and (remaining := deadline - loop.time()) > 0:
        waiters = {asyncio.ensure_future(stop_event.wait()), asyncio.ensure_future(wake.wait())}
        try:
            await asyncio.wait(waiters, timeout=remaining, return_when=asyncio.FIRST_COMPLETED)
        finally:
            for waiter in waiters:
                waiter.cancel()
        if wake.is_set() and not stop_event.is_set():
            wake.clear()  # An erasure during this drain sets it again.
            try:
                await asyncio.to_thread(_drain_prompt_purges)
            except Exception as exc:
                print(f"[proxy] prompt file cleanup pending: {type(exc).__name__}", flush=True)


async def _prompt_memory_maintenance_loop(stop_event: asyncio.Event) -> None:
    global _PROMPT_PURGE_WAKE
    wake = asyncio.Event()
    _PROMPT_PURGE_WAKE = (asyncio.get_running_loop(), wake)
    try:
        while not stop_event.is_set():
            try:
                await asyncio.to_thread(_maintain_prompt_memory)
            except Exception as exc:
                print(f"[proxy] prompt privacy maintenance pending: {type(exc).__name__}", flush=True)
            await _drain_prompt_purges_on_wake(stop_event, wake, 60)
    finally:
        _PROMPT_PURGE_WAKE = None


_EPHEMERAL_MEDIA_JOB_PAYLOADS: dict[str, dict[str, Any]] = {}
_EPHEMERAL_MEDIA_JOB_PAYLOAD_SIZES: dict[str, int] = {}
_MEDIA_PAYLOAD_LOCK = threading.RLock()
_EPHEMERAL_MEDIA_JOB_MAX_COUNT = 256
_EPHEMERAL_MEDIA_JOB_MAX_BYTES = 64 * 1024 * 1024


class EphemeralMediaPayloadCapacityError(RuntimeError):
    """A forget payload cannot be retained safely in the bounded memory store."""


def _ephemeral_media_payload_size(payload: Mapping[str, Any]) -> int:
    return len(json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8"))


def _ephemeral_media_payload_busy_response() -> Response:
    return Response(
        content=json.dumps({
            "error": {
                "message": "The gateway is busy retaining private media jobs. Retry shortly.",
                "type": "service_unavailable",
                "code": "media_payload_capacity",
            }
        }),
        status_code=503,
        media_type="application/json",
    )


def _release_ephemeral_media_job_payload(job_id: str) -> None:
    _EPHEMERAL_MEDIA_JOB_PAYLOADS.pop(job_id, None)
    _EPHEMERAL_MEDIA_JOB_PAYLOAD_SIZES.pop(job_id, None)


def _store_ephemeral_media_job_payload(job_id: str, payload: dict[str, Any]) -> None:
    payload_size = _ephemeral_media_payload_size(payload)
    current_size = sum(_EPHEMERAL_MEDIA_JOB_PAYLOAD_SIZES.values())
    replacing_size = _EPHEMERAL_MEDIA_JOB_PAYLOAD_SIZES.get(job_id, 0)
    projected_count = len(_EPHEMERAL_MEDIA_JOB_PAYLOADS) + (
        0 if job_id in _EPHEMERAL_MEDIA_JOB_PAYLOADS else 1
    )
    if (projected_count > _EPHEMERAL_MEDIA_JOB_MAX_COUNT
            or current_size - replacing_size + payload_size > _EPHEMERAL_MEDIA_JOB_MAX_BYTES):
        raise EphemeralMediaPayloadCapacityError("ephemeral media payload capacity reached")
    _EPHEMERAL_MEDIA_JOB_PAYLOADS[job_id] = payload
    _EPHEMERAL_MEDIA_JOB_PAYLOAD_SIZES[job_id] = payload_size


def _cancel_media_job(job_id: str, *, audience: str, reason: str | None = None) -> dict[str, Any] | None:
    result = media_jobs.request_cancel(job_id, path=media_jobs.DB_PATH)
    if result is None:
        return None
    if media_jobs.is_terminal(result["status"]):
        _delete_image_media_job_payload(job_id)
    video_id = (result.get("metadata") or {}).get("upstream_video_id")
    prompt_id = _prompt_id_from_video_id(video_id) if isinstance(video_id, str) else None
    if prompt_id:
        prompt_memory.delete_asset(f"video_{prompt_id}")
    return media_jobs.get(job_id, audience=audience, path=media_jobs.DB_PATH)


def _has_image_media_job_payload(job_id: str) -> bool:
    return job_id in _EPHEMERAL_MEDIA_JOB_PAYLOADS or _image_media_job_payload_path(job_id).exists()


def _persist_image_media_job_payload(
    job_id: str, *, body: Mapping[str, Any], request: Request,
    auth_context: AuthContext,
) -> None:
    identity = auth_context.identity
    _spool_media_job_payload(job_id, {
        "schema_version": 1,
        "body": copy.deepcopy(dict(body)),
        "headers": _safe_image_job_headers(request),
        "url": {"scheme": request.url.scheme or "http",
                "netloc": getattr(request.url, "netloc", "") or request.headers.get("host", "127.0.0.1")},
        "auth": {"name": identity.name if identity else None,
                 "key_hash": identity.key_hash if identity else None,
                 "app_id": getattr(identity, "app_id", None), "person_id": _auth_person_id(auth_context),
                 "connection_id": getattr(identity, "connection_id", None),
                 "trusted_address": getattr(identity, "trusted_address", None)},
        "created_at": int(time.time()),
    })


def _spool_media_job_payload(job_id: str, payload: dict[str, Any]) -> None:
    """Keep a job's execution payload; on disk only if prompt memory allows it."""
    with _MEDIA_PAYLOAD_LOCK:
        person_id = payload["auth"].get("person_id")
        body = copy.deepcopy(payload["body"])
        memory = prompt_memory.decide_for_person(person_id, body, admin_path=ADMIN_STORE.path)
        with prompt_memory.retention_guard(ADMIN_STORE.path, person_id) as policy:
            # Service/LAN execution spools are temporary operational state. Their
            # prompt is required to resume, so retain it only until terminal state.
            # Explicit privacy choices always suppress durable execution payloads.
            durable = (memory.keep or memory.reason == "no_person") and not policy["never_keep"]
            if person_id and not policy["remember"]:
                durable = False
            if not durable:
                extensions = payload["body"].setdefault("extensions", {})
                extensions[prompt_memory.NAMESPACE] = {"mode": "forget"}
                _store_ephemeral_media_job_payload(job_id, payload)
                return
            _release_ephemeral_media_job_payload(job_id)
            IMAGE_MEDIA_JOB_PAYLOAD_DIR.mkdir(parents=True, exist_ok=True)
            path = _image_media_job_payload_path(job_id)
            tmp = path.with_suffix(".json.tmp")
            try:
                fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
                with os.fdopen(fd, "w", encoding="utf-8") as stream:
                    json.dump(payload, stream, sort_keys=True)
                tmp.replace(path)
            finally:
                tmp.unlink(missing_ok=True)


def _load_image_media_job_payload(job_id: str) -> dict[str, Any] | None:
    with _MEDIA_PAYLOAD_LOCK:
        if job_id in _EPHEMERAL_MEDIA_JOB_PAYLOADS:
            return _EPHEMERAL_MEDIA_JOB_PAYLOADS[job_id]
        path = _image_media_job_payload_path(job_id)
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            return None
        except Exception as exc:  # noqa: BLE001
            print(f"[proxy] image media job payload read failed for {job_id}: {exc}", flush=True)
            return None
        return data if isinstance(data, dict) else None


def _delete_image_media_job_payload(job_id: str) -> None:
    with _MEDIA_PAYLOAD_LOCK:
        _release_ephemeral_media_job_payload(job_id)
        for path in (_image_media_job_payload_path(job_id),
                     _image_media_job_payload_path(job_id).with_suffix(".json.tmp")):
            try:
                path.unlink(missing_ok=True)
            except Exception:
                pass


def _prune_orphaned_media_job_payloads() -> int:
    """Remove terminal-job spools; absent history may be in quarantine."""
    with _MEDIA_PAYLOAD_LOCK:
        removed = 0
        for job_id in list(_EPHEMERAL_MEDIA_JOB_PAYLOADS):
            job = media_jobs.get(job_id, audience="internal", path=media_jobs.DB_PATH)
            if job is not None and job.get("status") in media_jobs.TERMINAL_STATUSES:
                _release_ephemeral_media_job_payload(job_id)
                removed += 1
        if not IMAGE_MEDIA_JOB_PAYLOAD_DIR.exists():
            return removed
        for path in (*IMAGE_MEDIA_JOB_PAYLOAD_DIR.glob("mj_*.json"),
                     *IMAGE_MEDIA_JOB_PAYLOAD_DIR.glob("mj_*.json.tmp")):
            job_id = path.name.split(".json", 1)[0]
            job = media_jobs.get(job_id, audience="internal", path=media_jobs.DB_PATH)
            if job is not None and job.get("status") in media_jobs.TERMINAL_STATUSES:
                path.unlink(missing_ok=True)
                removed += 1
        return removed


def _image_job_body_has_seed(body: Mapping[str, Any]) -> bool:
    if isinstance(body.get("seed"), int) and not isinstance(body.get("seed"), bool):
        return True
    extensions = body.get("extensions")
    if not isinstance(extensions, Mapping):
        return False
    block = extensions.get(WORKFLOW_EXTENSION_NAMESPACE)
    if not isinstance(block, Mapping):
        return False
    seed = block.get("seed")
    return isinstance(seed, int) and not isinstance(seed, bool)


def _image_job_request_digest(body: Mapping[str, Any], auth_context: AuthContext) -> str:
    owner = _asset_owner_key(auth_context) or "anonymous"
    canonical = json.dumps(
        {"owner": owner, "body": body},
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    ).encode("utf-8")
    return hmac.new(_image_signing_secret(), canonical, hashlib.sha256).hexdigest()


def _image_media_job_request_id(
    *,
    body: Mapping[str, Any],
    auth_context: AuthContext,
    idempotency_key: str | None,
    fallback_request_id: str,
) -> tuple[str, str, str]:
    owner = _asset_owner_key(auth_context) or "anonymous"
    memory = prompt_memory.decide_for_person(_auth_person_id(auth_context), body, admin_path=ADMIN_STORE.path)
    if idempotency_key:
        identity = {"owner": owner, "idempotency_key": idempotency_key}
        if not memory.keep and memory.reason != "no_person":
            # A forget request must not return an earlier remembered job.
            identity["prompt_memory"] = "forget"
        canonical = json.dumps(
            identity,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        digest = hmac.new(_image_signing_secret(), canonical, hashlib.sha256).hexdigest()
        return f"imgjob_idem_{digest[:40]}", digest, "idempotency_key"
    if not memory.keep and memory.reason != "no_person":
        return fallback_request_id, uuid.uuid4().hex + uuid.uuid4().hex, "request"
    if _image_job_body_has_seed(body):
        digest = _image_job_request_digest(body, auth_context)
        return f"imgjob_seeded_{digest[:40]}", digest, "seeded_request"
    return fallback_request_id, uuid.uuid4().hex + uuid.uuid4().hex, "request"


def _safe_image_media_job_metadata(
    *,
    body: Mapping[str, Any],
    request_hash: str,
    idempotency: str,
) -> dict[str, Any]:
    try:
        n_value = int(body.get("n", 1))
    except (TypeError, ValueError):
        n_value = 1
    return {
        "mode": "async_image_generation",
        "request_hash": request_hash,
        "idempotency": idempotency,
        "requested_model": str(body.get("model", COMFY_DEFAULT_MODEL))[:160],
        "size": str(body.get("size", "1024x1024"))[:32],
        "n": max(1, min(n_value, 10)),
        "response_format": "url",
    }


def _image_media_job_client_payload(
    job: Mapping[str, Any],
    request: Request,
) -> dict[str, Any]:
    job_id = str(job.get("job_id") or "")
    client_job = {
        key: job[key]
        for key in media_jobs.CLIENT_VISIBLE_FIELDS
        if key in job
    }
    return {
        "object": "media.job",
        "id": job_id,
        **client_job,
        "poll_url": f"/gateway/v1/media/jobs/{job_id}",
        "content_url": f"/gateway/v1/media/jobs/{job_id}/content",
    }


def _image_media_job_response(
    job: Mapping[str, Any],
    request: Request,
    *,
    status_code: int | None = None,
) -> Response:
    status_value = str(job.get("status") or "")
    if status_code is None:
        status_code = 200 if status_value in media_jobs.TERMINAL_STATUSES else 202
    job_id = str(job.get("job_id") or "")
    return Response(
        content=json.dumps(_image_media_job_client_payload(job, request)),
        status_code=status_code,
        media_type="application/json",
        headers={"Location": f"/gateway/v1/media/jobs/{job_id}"},
    )


def _image_response_json(response: Response) -> dict[str, Any]:
    body = getattr(response, "body", b"")
    if isinstance(body, str):
        raw = body
    else:
        raw = bytes(body or b"").decode("utf-8", errors="replace")
    try:
        parsed = json.loads(raw or "{}")
    except json.JSONDecodeError:
        return {}
    return parsed if isinstance(parsed, dict) else {}


def _image_response_error(response: Response) -> tuple[str, str | None]:
    parsed = _image_response_json(response)
    error = parsed.get("error")
    if isinstance(error, Mapping):
        message = str(error.get("message") or "image generation failed")
        code = error.get("code")
        return message[:500], str(code) if code else None
    return f"image generation failed with HTTP {response.status_code}", None


_JOB_FAILURE_COPY = {
    "authorization": ("not_in_access_plan", "This workflow isn't in your access plan."),
    "invalid_input": ("invalid_input", "The gateway did not accept this job's inputs."),
    "capacity": ("capacity", "The gateway is too busy to run this job now. Try again later."),
    "timeout": ("timeout", "The backend did not finish this job in time."),
    "safety": ("content_policy_violation", "The backend refused this job's content."),
}
# Error codes a job may copy from a refusal: the gateway's own and the standard
# OpenAI ones. Any other code, even a plain token, may carry words from a prompt
# a backend echoed, so it becomes the category's default code.
_JOB_KNOWN_ERROR_CODES = frozenset({
    *ACCESS_ERROR_MESSAGES, NO_ACCESS_PLAN, NOT_IN_ACCESS_PLAN, CANNOT_START_MODEL,
    "resource_admission_denied", "vram_exhausted", "model_not_found", "invalid_value", "unknown_parameter",
    "invalid_prompt_mode", "unsupported_media_job_intent", "content_policy_violation", "rate_limit_exceeded",
})


def _gateway_refusal(response: Response, category: str) -> Response:
    """Mark a refusal the gateway itself made (``authorization``, ``capacity``).

    The mark lives on the in-process object only, so a job worker can tell the
    gateway's own refusal from an upstream failure. Nothing on the wire, which
    an upstream could imitate, decides that.
    """
    response.gateway_refusal = category  # type: ignore[attr-defined]
    return response


def _media_job_failure(response: Response) -> tuple[str, dict[str, Any]]:
    """The plain error sentence and typed facts (``media_jobs.ERROR_FIELDS``) of a failed attempt.

    Never backend error text, which may echo a prompt: the sentence is fixed
    copy, and an error code is kept only when it is one the gateway knows.
    """
    status = int(getattr(response, "status_code", 0) or 0)
    error = _image_response_json(response).get("error")
    code = error.get("code") if isinstance(error, Mapping) else None
    code = code if isinstance(code, str) and code in _JOB_KNOWN_ERROR_CODES else None
    category = getattr(response, "gateway_refusal", None)
    if category is None:
        if code == "content_policy_violation":
            category = "safety"
        elif status in (408, 504):
            category = "timeout"
        elif status == 429:
            category = "capacity"
        elif status in (400, 404, 409, 413, 415, 422):
            category = "invalid_input"
        else:
            category = "upstream"
    if category == "upstream":
        return f"Media generation failed (upstream HTTP {status}).", {
            "error_code": code or "upstream_error", "error_category": "upstream",
            "retryable": status >= 500, "upstream_http_status": status,
        }
    default_code, message = _JOB_FAILURE_COPY[category]
    if category == "capacity" and getattr(response, "gateway_refusal", None):
        message = _admission_refusal_message(response)
    return message, {"error_code": code or default_code, "error_category": category,
                     "retryable": category in ("capacity", "timeout")}


def _retry_after_seconds(response: Response) -> float | None:
    raw = response.headers.get("retry-after") if hasattr(response, "headers") else None
    if not raw:
        return None
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return None
    if value < 0:
        return None
    return min(value, IMAGE_MEDIA_JOB_RETRY_MAX_SECONDS)


def _image_media_job_retry_decision(
    response: Response,
    *,
    attempt: int,
    max_attempts: int = IMAGE_MEDIA_JOB_MAX_ATTEMPTS,
) -> tuple[str, float] | None:
    if attempt >= max_attempts:
        return None
    status_code = int(getattr(response, "status_code", 0) or 0)
    message, code = _image_response_error(response)
    text = message.lower()
    reason: str | None = None
    if status_code == 503 and (code == "vram_exhausted" or "vram" in text):
        reason = "vram_exhausted"
    elif status_code == 502 and "comfyui unavailable" in text:
        reason = "comfyui_unavailable"
    elif status_code == 502 and "gateway tile composition error" in text:
        reason = "tile_composition_error"
    elif status_code == 502 and "no prompt_id returned" in text:
        reason = "missing_prompt_id"
    elif status_code == 504:
        reason = "comfyui_timeout"
    elif status_code == 503 and "unavailable" in text:
        reason = "service_unavailable"

    if reason is None:
        return None
    retry_after = _retry_after_seconds(response)
    if retry_after is not None:
        return reason, retry_after
    backoff = IMAGE_MEDIA_JOB_RETRY_BASE_SECONDS * (2 ** max(0, attempt - 1))
    return reason, min(backoff, IMAGE_MEDIA_JOB_RETRY_MAX_SECONDS)


def _assets_from_image_response(response: Response) -> list[dict[str, Any]]:
    parsed = _image_response_json(response)
    data = parsed.get("data")
    if not isinstance(data, list):
        return []
    assets: list[dict[str, Any]] = []
    for item in data:
        if not isinstance(item, Mapping):
            continue
        asset: dict[str, Any] = {}
        for key in ("asset_id", "asset_url", "url", "media_type"):
            value = item.get(key)
            if isinstance(value, str) and value:
                asset[key] = value
        if asset.get("asset_id"):
            assets.append(asset)
    return assets


def _openai_image_payload_from_media_job(job: Mapping[str, Any]) -> dict[str, Any]:
    data: list[dict[str, Any]] = []
    for asset in job.get("assets") or []:
        if not isinstance(asset, Mapping):
            continue
        item = {
            key: asset[key]
            for key in ("asset_id", "asset_url", "url", "media_type")
            if isinstance(asset.get(key), str) and asset.get(key)
        }
        if item:
            data.append(item)
    return {
        "created": int(job.get("updated_at") or time.time()),
        "job_id": job.get("job_id"),
        "data": data,
    }


def _job_metadata_mode_patch() -> dict[str, str]:
    """Submit-time ``metadata`` choice, kept on the job so content GET honors it."""
    ctx = media_delivery.current()
    if ctx is not None and ctx.requested_mode:
        return {"metadata_mode": ctx.requested_mode}
    return {}


def _media_job_asset_items(
    job: Mapping[str, Any],
    request: Request,
    *,
    kind: str,
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for asset in job.get("assets") or []:
        if not isinstance(asset, Mapping):
            continue
        asset_id = asset.get("asset_id")
        if not isinstance(asset_id, str):
            continue
        parsed = _parse_asset_id(asset_id)
        if parsed is None or parsed[0] != kind:
            continue
        signed_url = build_signed_asset_url(request, asset_id)
        item = {
            key: asset[key]
            for key in ("asset_id", "media_type", "size_bytes", "index")
            if asset.get(key) is not None
        }
        item["url"] = signed_url
        item["asset_url"] = signed_url
        item["content_url"] = signed_url
        items.append(item)
    return items


def _openai_audio_payload_from_media_job(
    job: Mapping[str, Any],
    request: Request,
) -> dict[str, Any]:
    return {
        "object": "audio.generation",
        "created": int(job.get("updated_at") or time.time()),
        "job_id": job.get("job_id"),
        "data": _media_job_asset_items(job, request, kind="aud"),
    }


def _openai_video_payload_from_media_job(
    job: Mapping[str, Any],
    request: Request,
) -> dict[str, Any]:
    return {
        "object": "video.generation",
        "created": int(job.get("updated_at") or time.time()),
        "job_id": job.get("job_id"),
        "data": _media_job_asset_items(job, request, kind="vid"),
    }


def _media_job_content_route_policy(job: Mapping[str, Any]) -> dict[str, Any] | None:
    intent = str(job.get("intent") or "")
    if intent in ("image.generate", _IDENTITY_JOB_INTENT):
        return _RUNTIME_ROUTE_POLICY["/gateway/v1/media/jobs/{job_id}/content"]
    if intent in _AUDIO_MEDIA_JOB_INTENTS:
        return _ASSET_CONTENT_ROUTE_POLICY_BY_KIND.get("aud")
    if intent == INTENT_VIDEO_GENERATE:
        return _ASSET_CONTENT_ROUTE_POLICY_BY_KIND.get("vid")
    return None


def _media_job_content_preflight_response(auth_context: AuthContext) -> Response | None:
    # Before the lookup: the plans must allow some media capability at all.
    media_intents = ("image.generate", "video.generate", "audio.generate", "music.generate", "sfx.generate")
    decisions = [
        evaluate_and_apply(
            auth_context.identity,
            make_policy_request(protocol=_protocol_for_intent(intent), intent=intent),
        )
        for intent in media_intents
    ]
    if any(decision.allowed for decision in decisions):
        return None

    access = _access_for_auth_context(auth_context)
    return _policy_denied_response(
        PolicyDecision(
            decision=DENIED,
            sources=(*(f"access_plan:{plan_id}" for plan_id in access.plan_ids), "policy:media-job-content"),
            reasons=("Media isn't in your access plan.",),
            code="not_in_access_plan",
            visibility_level=access.receipt_detail,
        )
    )


_MEDIA_JOB_LOG = logging.getLogger("azizam.media_jobs")
_MEDIA_JOB_CRASHED = "The job stopped unexpectedly; please try again"
_MEDIA_JOB_CRASHED_INFO = {"error_code": "internal_error", "error_category": "internal", "retryable": True}


def _log_media_job_crash(job_id: str, exc: BaseException) -> None:
    """Log where a job's worker broke: the exception type and its stack.

    Not the exception's text, which may quote a prompt or a backend reply.
    """
    stack = "".join(traceback.format_tb(exc.__traceback__))
    _MEDIA_JOB_LOG.error("media job %s stopped with %s\n%s", job_id, type(exc).__name__, stack)


_MEDIA_JOB_CALLER_GONE = "The account that asked for this job can no longer use the gateway."
_MEDIA_JOB_CALLER_GONE_INFO = {"error_code": "caller_unavailable", "error_category": "authorization",
                               "retryable": False}


def _auth_context_from_image_job_payload(payload: Mapping[str, Any]) -> AuthContext | None:
    """The caller a media job was accepted for, rebuilt from the admin store.

    The worker runs as the same App, key name, plan and person as the request
    that made the job. The plan is the one the App holds now, and a revoked
    key, a disabled App or person, a revoked MCP connection, or a submitting
    address no longer trusted for the App returns None: the job must then fail,
    never run as someone else. A keyless caller's ``key_hash`` is
    ``app:<app id>``: with a person it is that person's session App (browser or
    MCP sign-in), without one an App trusted by client address. The worker's
    own network position never counts. Workers call this again before each
    step, so a change takes effect at the next one.
    """
    auth = payload.get("auth")
    if not isinstance(auth, Mapping):
        return None
    key_hash = auth.get("key_hash")
    if not isinstance(key_hash, str) or not key_hash:
        return None
    app_id = str(auth.get("app_id") or "")
    person_id = str(auth.get("person_id") or "")
    connection_id = str(auth.get("connection_id") or "")
    if app_id and key_hash == f"app:{app_id}":
        if person_id:
            identity = runtime_identity_for_session_app(app_id, person_id, path=ADMIN_STORE.path)
            # An MCP sign-in's work stops when its connection is revoked.
            if identity is not None and connection_id:
                if not (MCP_OAUTH_ENABLED and MCP_OAUTH.connection_active(connection_id, person_id)):
                    return None
                identity = replace(identity, connection_id=connection_id)
        else:
            identity = runtime_identity_for_trusted_app(app_id, str(auth.get("trusted_address") or ""),
                                                        path=ADMIN_STORE.path)
    else:
        identity = runtime_identity_for_app_credential_hash(key_hash, path=ADMIN_STORE.path)
    if identity is None or identity.denial:
        return None
    name = auth.get("name")
    # The name is display only: an MCP sign-in shows its client ("ChatGPT (MCP)").
    return AuthContext(identity=replace(identity, name=name) if isinstance(name, str) and name else identity)


def _request_shim_from_image_job_payload(payload: Mapping[str, Any]) -> _JsonBodyRequestShim | None:
    body = payload.get("body")
    if not isinstance(body, Mapping):
        return None
    url = payload.get("url")
    headers = payload.get("headers")
    if not isinstance(url, Mapping):
        url = {}
    if not isinstance(headers, Mapping):
        headers = {}
    replay_body = copy.deepcopy(dict(body))
    replay_body["response_format"] = "url"
    return _JsonBodyRequestShim(
        body=replay_body,
        headers={str(k): str(v) for k, v in headers.items()},
        scheme=str(url.get("scheme") or "http"),
        netloc=str(url.get("netloc") or headers.get("host") or "127.0.0.1"),
    )


def _recover_media_jobs() -> None:
    """Run on every startup, even when the operator disables resuming."""
    _resume_pending_image_media_jobs()
    _resume_pending_audio_media_jobs()
    _resume_pending_video_media_jobs()
    me_make.resume_jobs(runtime=_SESSION_MAKE_RUNTIME, jobs_path=media_jobs.DB_PATH,
                        enabled=IMAGE_MEDIA_JOB_RESUME_ON_START)
    supported = {"async_image_generation", "async_audio_generation", "async_video_generation", me_make.JOB_MODE}
    for job in media_jobs.unfinished(path=media_jobs.DB_PATH):
        if (job.get("metadata") or {}).get("mode") not in supported:
            media_jobs.update_status(job["job_id"], media_jobs.STATUS_FAILED,
                                     error="The gateway restarted; this job cannot be resumed",
                                     path=media_jobs.DB_PATH)


def _settle_native_job(run: Callable[[str], Awaitable[None]]) -> Callable[[str], Awaitable[None]]:
    async def settled(job_id: str) -> None:
        try:
            await run(job_id)
        except media_jobs.CancellationPending:
            # The executor has returned and its semaphore has been released.
            media_jobs.update_status(job_id, media_jobs.STATUS_CANCELED,
                                     error="Canceled by requester", path=media_jobs.DB_PATH)
            _delete_image_media_job_payload(job_id)
    return settled


def _mark_image_media_job_failed(
    job_id: str,
    message: str,
    *,
    http_status: int | None = None,
    error_info: Mapping[str, Any] | None = None,
) -> None:
    metadata_patch: dict[str, Any] = {}
    if http_status is not None:
        metadata_patch["last_http_status"] = int(http_status)
    try:
        media_jobs.update_status(
            job_id,
            media_jobs.STATUS_FAILED,
            error=message[:500],
            error_info=error_info,
            metadata_patch=metadata_patch or None,
            path=media_jobs.DB_PATH,
        )
    except Exception as exc:  # noqa: BLE001
        print(f"[proxy] image media job fail update failed for {job_id}: {exc}", flush=True)
    try:
        media_jobs.append_event(
            job_id,
            "failed",
            {
                "phase": "failed",
                "status": media_jobs.STATUS_FAILED,
                "progress": 100,
                "http_status": http_status or 0,
            },
            path=media_jobs.DB_PATH,
        )
    except Exception:
        pass
    _delete_image_media_job_payload(job_id)


@_settle_native_job
async def _run_image_media_job(job_id: str) -> None:
    async with _image_media_job_semaphore:
        job = media_jobs.get(job_id, audience="internal", path=media_jobs.DB_PATH)
        if not job:
            return
        if job.get("status") in media_jobs.TERMINAL_STATUSES:
            return

        if (job.get("metadata") or {}).get("cancel_requested_at"):
            raise media_jobs.CancellationPending()
        payload = _load_image_media_job_payload(job_id)
        request_shim = _request_shim_from_image_job_payload(payload or {})
        if payload is None or request_shim is None:
            _mark_image_media_job_failed(job_id, "Image media job payload is missing or invalid")
            return

        auth_context = _auth_context_from_image_job_payload(payload)
        if auth_context is None:
            _mark_image_media_job_failed(job_id, _MEDIA_JOB_CALLER_GONE, error_info=_MEDIA_JOB_CALLER_GONE_INFO)
            return
        admission = _media_job_admission_response(
            "image.generate", count_queue=False, auth_context=auth_context,
        )
        if admission is not None:
            message, error_info = _media_job_failure(admission)
            _mark_image_media_job_failed(job_id, message, error_info=error_info)
            return

        try:
            media_jobs.update_status(
                job_id,
                media_jobs.STATUS_RUNNING,
                progress=5,
                metadata_patch={"started_at": int(time.time())},
                path=media_jobs.DB_PATH,
            )
            media_jobs.append_event(
                job_id,
                "started",
                {
                    "phase": "running",
                    "status": media_jobs.STATUS_RUNNING,
                    "progress": 5,
                },
                path=media_jobs.DB_PATH,
            )
        except ValueError:
            return

        max_attempts = max(1, IMAGE_MEDIA_JOB_MAX_ATTEMPTS)
        for attempt in range(1, max_attempts + 1):
            current = media_jobs.get(job_id, path=media_jobs.DB_PATH) or {}
            if (current.get("metadata") or {}).get("cancel_requested_at"):
                _mark_image_media_job_failed(job_id, "Cancellation was requested; the backend stop could not be confirmed")
                return
            if attempt > 1:
                # A retry runs as the caller is now: a revoked key or connection
                # stops it here, and a new plan is checked by the route.
                auth_context = _auth_context_from_image_job_payload(payload)
                if auth_context is None:
                    _mark_image_media_job_failed(job_id, _MEDIA_JOB_CALLER_GONE, error_info=_MEDIA_JOB_CALLER_GONE_INFO)
                    return
            receipt = start_image_route_receipt("/v1/images/generations", auth_context)
            receipt.job_id = job_id
            try:
                if attempt > 1 or job.get("status") == media_jobs.STATUS_RUNNING:
                    job = media_jobs.begin_attempt(job_id, path=media_jobs.DB_PATH) or job
                receipt.attempt_number = job.get("attempt_number")
                receipt.mark_phase("started_at_ms")
                media_jobs.append_event(
                    job_id,
                    "attempt",
                    {
                        "phase": "running",
                        "status": media_jobs.STATUS_RUNNING,
                        "progress": min(95, 5 + (attempt - 1) * 10),
                        "attempt": attempt,
                        "total": max_attempts,
                    },
                    path=media_jobs.DB_PATH,
                )
                # Retry the same request, including its original retention clock.
                # Deletion fences must survive copied bodies and worker retries.
                token = _MEDIA_JOB_PROMPT_STARTED_AT.set(int(payload.get("created_at") or job["created_at"]))
                try:
                    worker_token = _ADMISSION_WORKER.set(True)
                    try:
                        response = await proxy_image_request(request_shim, auth_context, receipt=receipt)
                    finally:
                        _ADMISSION_WORKER.reset(worker_token)
                finally:
                    _MEDIA_JOB_PROMPT_STARTED_AT.reset(token)
                finish_image_route_receipt(receipt, response)
            except asyncio.CancelledError:
                # An interrupted attempt keeps its terminal receipt.
                finish_image_route_receipt(receipt, None, status="cancelled")
                raise
            except media_jobs.CancellationPending:
                finish_image_route_receipt(receipt, None, status="cancelled")
                raise
            except Exception as exc:  # noqa: BLE001
                finish_image_route_receipt(
                    receipt,
                    Response(
                        content=json.dumps({
                            "error": {
                                "message": f"image media job executor error: {type(exc).__name__}",
                                "type": "api_error",
                            }
                        }),
                        status_code=502,
                        media_type="application/json",
                    ),
                )
                if attempt < max_attempts:
                    delay = min(
                        IMAGE_MEDIA_JOB_RETRY_BASE_SECONDS * (2 ** max(0, attempt - 1)),
                        IMAGE_MEDIA_JOB_RETRY_MAX_SECONDS,
                    )
                    media_jobs.append_event(
                        job_id,
                        "retry",
                        {
                            "phase": "retrying",
                            "status": media_jobs.STATUS_RUNNING,
                            "progress": min(95, 10 + attempt * 10),
                            "attempt": attempt,
                            "total": max_attempts,
                            "reason": type(exc).__name__,
                            "retry_after_s": delay,
                        },
                        path=media_jobs.DB_PATH,
                    )
                    await asyncio.sleep(delay)
                    continue
                _mark_image_media_job_failed(
                    job_id,
                    f"Image media job executor error: {type(exc).__name__}",
                    http_status=502,
                )
                return

            current = media_jobs.get(job_id, path=media_jobs.DB_PATH) or {}
            if (current.get("metadata") or {}).get("cancel_requested_at") and 200 <= response.status_code < 300:
                raise media_jobs.CancellationPending()
            status_code = int(getattr(response, "status_code", 0) or 0)
            if 200 <= status_code < 300:
                assets = _assets_from_image_response(response)
                if not assets:
                    _mark_image_media_job_failed(
                        job_id,
                        "Image generation succeeded but returned no reusable assets",
                        http_status=status_code,
                    )
                    return
                media_jobs.update_status(
                    job_id,
                    media_jobs.STATUS_SUCCEEDED,
                    progress=100,
                    add_assets=assets,
                    metadata_patch={
                        "attempts": attempt,
                        "last_http_status": status_code,
                        "completed_at": int(time.time()),
                    },
                    path=media_jobs.DB_PATH,
                )
                media_jobs.append_event(
                    job_id,
                    "succeeded",
                    {
                        "phase": "complete",
                        "status": media_jobs.STATUS_SUCCEEDED,
                        "progress": 100,
                        "attempt": attempt,
                        "total": max_attempts,
                    },
                    path=media_jobs.DB_PATH,
                )
                _delete_image_media_job_payload(job_id)
                return

            retry = _image_media_job_retry_decision(
                response,
                attempt=attempt,
                max_attempts=max_attempts,
            )
            if retry is not None:
                reason, delay = retry
                media_jobs.update_status(
                    job_id,
                    media_jobs.STATUS_RUNNING,
                    progress=min(95, 10 + attempt * 10),
                    metadata_patch={
                        "attempts": attempt,
                        "last_http_status": status_code,
                        "last_retry_reason": reason,
                    },
                    path=media_jobs.DB_PATH,
                )
                media_jobs.append_event(
                    job_id,
                    "retry",
                    {
                        "phase": "retrying",
                        "status": media_jobs.STATUS_RUNNING,
                        "progress": min(95, 10 + attempt * 10),
                        "attempt": attempt,
                        "total": max_attempts,
                        "http_status": status_code,
                        "reason": reason,
                        "retry_after_s": delay,
                    },
                    path=media_jobs.DB_PATH,
                )
                await asyncio.sleep(delay)
                continue

            message, error_info = _media_job_failure(response)
            _mark_image_media_job_failed(
                job_id,
                message,
                http_status=status_code,
                error_info=error_info,
            )
            return


def _schedule_image_media_job(job_id: str) -> bool:
    if job_id in _image_media_job_scheduled:
        return False
    _image_media_job_scheduled.add(job_id)
    try:
        task = asyncio.create_task(_run_image_media_job(job_id))
    except BaseException:
        # A launch that never started must not leave the job looking scheduled.
        _image_media_job_scheduled.discard(job_id)
        raise
    _image_media_job_tasks.add(task)

    def _done(done_task: asyncio.Task) -> None:
        _image_media_job_tasks.discard(done_task)
        _image_media_job_scheduled.discard(job_id)
        try:
            exc = done_task.exception()
        except asyncio.CancelledError:
            return
        if exc is not None:
            _log_media_job_crash(job_id, exc)
            _mark_image_media_job_failed(job_id, _MEDIA_JOB_CRASHED, error_info=_MEDIA_JOB_CRASHED_INFO)

    task.add_done_callback(_done)
    return True


def _resume_pending_image_media_jobs() -> int:
    resumed = 0
    for job in media_jobs.unfinished(path=media_jobs.DB_PATH):
        if job.get("intent") != "image.generate":
            continue
        metadata = job.get("metadata") or {}
        if not isinstance(metadata, Mapping) or metadata.get("mode") != "async_image_generation":
            continue
        job_id = str(job.get("job_id") or "")
        if not job_id:
            continue
        if not _has_image_media_job_payload(job_id):
            _mark_image_media_job_failed(
                job_id,
                "Image media job payload missing after proxy restart",
            )
            continue
        from gateway.engine_protocol.dispatch import opted_in
        service = (ADMIN_STORE.get_service_registry().get("services") or {}).get(job.get("backend")) or {}
        if not IMAGE_MEDIA_JOB_RESUME_ON_START or (not opted_in(service) and not COMFY_ENABLED):
            _mark_image_media_job_failed(job_id, "The gateway restarted with job recovery turned off")
            continue
        if metadata.get("cancel_requested_at"):
            _mark_image_media_job_failed(job_id, "The gateway restarted before cancellation could be confirmed")
            continue
        if job.get("status") == media_jobs.STATUS_RUNNING:
            _mark_image_media_job_failed(job_id, "The gateway restarted before completion could be confirmed; this job was not run again")
            continue
        if _schedule_image_media_job(job_id):
            resumed += 1
    return resumed


def _image_generation_body_from_media_job_payload(
    payload: Mapping[str, Any],
) -> dict[str, Any] | None:
    if payload.get("intent") != "image.generate":
        return None
    request_body = payload.get("request")
    if not isinstance(request_body, Mapping):
        request_body = payload.get("parameters")
    if isinstance(request_body, Mapping):
        return _media_job_prompt_body(payload, request_body)
    if "prompt" not in payload:
        return None
    return _media_job_prompt_body(payload, {
        str(key): value
        for key, value in payload.items()
        if str(key) in STANDARD_IMAGE_GENERATE_FIELDS
    })


def _media_job_prompt_body(payload: Mapping[str, Any], body: Mapping[str, Any]) -> dict[str, Any]:
    """Honor a forget control on either side of the queued request envelope."""
    outer_mode = prompt_memory.requested_mode(payload)
    prompt_memory.requested_mode(body)
    result = dict(body)
    if outer_mode == "forget":
        result["extensions"] = {**(body.get("extensions") or {}),
                                prompt_memory.NAMESPACE: {"mode": "forget"}}
    return result


_ADMISSION_WORKER: contextvars.ContextVar[bool] = contextvars.ContextVar("admission_worker", default=False)

_MEDIA_JOB_QUEUE_KEY = "comfyui-media"
# Every intent the gateway runs as a media job, and its admission resource
# class. Jobs with these intents count toward the media queue depth.
_MEDIA_JOB_RESOURCE_CLASS_BY_INTENT = {
    "image.generate": "image",
    "image.edit": "image",
    _IDENTITY_JOB_INTENT: "image",
    "audio.generate": "audio",
    "music.generate": "audio",
    "sfx.generate": "audio",
    INTENT_VIDEO_GENERATE: "video",
}


def _optional_int_config(mapping: Mapping[str, Any], key: str) -> int | None:
    value = mapping.get(key)
    if value is None or value == "":
        return None
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        print(f"[proxy] ignoring non-integer {key} in media job admission config", flush=True)
        return None
    return max(0, parsed)


def _string_tuple_config(mapping: Mapping[str, Any], key: str) -> tuple[str, ...]:
    value = mapping.get(key)
    if value is None:
        return ()
    if isinstance(value, (str, bytes)):
        items = [str(value)]
    elif isinstance(value, Mapping):
        return ()
    elif isinstance(value, Iterable):
        items = [str(item) for item in value]
    else:
        return ()
    return tuple(item.strip() for item in items if item.strip())


def _media_job_queue_depth(
    max_queue_depth: int | None = None,
    *,
    admission_cfg: Mapping[str, Any] | None = None,
) -> int | None:
    cfg = admission_cfg if isinstance(admission_cfg, Mapping) else MEDIA_JOB_ADMISSION_CFG
    configured_scan_limit = _optional_int_config(cfg, "scan_limit") or 1000
    scan_limit = max(configured_scan_limit, max_queue_depth or 0)
    depth = 0
    for status_value in (media_jobs.STATUS_QUEUED, media_jobs.STATUS_RUNNING):
        try:
            rows = media_jobs.recent(
                limit=scan_limit,
                audience="internal",
                status=status_value,
                path=media_jobs.DB_PATH,
            )
        except Exception as exc:  # noqa: BLE001
            print(f"[proxy] media job admission load read failed: {type(exc).__name__}", flush=True)
            return None
        depth += sum(
            1
            for row in rows
            if str(row.get("intent") or "") in _MEDIA_JOB_RESOURCE_CLASS_BY_INTENT
        )
    return depth


def _media_job_app_load(app_id: str | None, limits: Mapping[str, int] | None) -> dict[str, int | None]:
    if not app_id or not limits or app_id not in limits:
        return {}
    try:
        return {app_id: media_jobs.active_count(
            app_id=app_id, intents=_MEDIA_JOB_RESOURCE_CLASS_BY_INTENT, path=media_jobs.DB_PATH,
        )}
    except Exception as exc:  # noqa: BLE001
        print(f"[proxy] media app admission load read failed: {type(exc).__name__}", flush=True)
        return {app_id: None}


def _dispatch_admission_response(
    intent: str, *, auth_context: AuthContext | None = None,
    service_id: str | None = None, service_available: bool | None = None,
    resource_class: str, protocol: str = "openai", receipt: RouteReceipt | None = None,
    queue_key: str | None = None,
) -> Response | None:
    """Apply configured admission before execution, without guessing runtime load.

    Availability is a declaration of route configuration, never a health/GPU
    measurement. Queue/app limits apply only to tracked media work. Other
    direct requests have no occupancy producer and do not use these limits.
    With no admission settings, the existing dispatch owns availability errors.
    """
    cfg = _effective_media_job_admission_cfg()
    override = _operator_service_availability_overrides().get(service_id, {})
    tracks_media = queue_key == _MEDIA_JOB_QUEUE_KEY
    configured = any(cfg.get(key) for key in (
        "disabled_intents", "disabled_resource_classes", "reserved_tokens",
    )) or (tracks_media and (bool(cfg.get("max_app_concurrency"))
                            or _optional_int_config(cfg, "max_queue_depth") is not None))
    enforce = configured or bool(override)
    state_name = str(override.get("state") or "").strip().lower()
    if state_name in {"disabled", "maintenance", "draining"}:
        service_available = False
    elif state_name in {"available", "degraded"}:
        service_available = True
    if service_available is None and service_id:
        service = (config.get("backends") or {}).get(service_id)
        if isinstance(service, Mapping):
            service_available = service.get("enabled", True) is not False
    identity = auth_context.identity if auth_context is not None else None
    count_media = tracks_media and not _ADMISSION_WORKER.get()
    app_id = identity.app_id if identity else (receipt.app_id if receipt else None)
    app_limits = cfg.get("max_app_concurrency") if count_media else None
    active_by_app = _media_job_app_load(app_id, app_limits)
    queue_limit = _optional_int_config(cfg, "max_queue_depth") if count_media else None
    queue_depths = ({queue_key: _media_job_queue_depth(queue_limit, admission_cfg=cfg)}
                    if queue_limit is not None and queue_key == _MEDIA_JOB_QUEUE_KEY else {})
    decision = resource_admission_http.advise_route_admission(
        intent=intent, resource_class=resource_class,
        service_available=service_available, service_degraded=state_name == "degraded",
        require_service_availability=enforce,
        service_retry_after=_optional_int_config(override, "retry_after_seconds"),
        service_reasons=_string_tuple_config(override, "reason"),
        app_id=app_id, active_by_app=active_by_app,
        queue_key=queue_key, queue_depths=queue_depths,
        observed_at=time.time(), load_quality="measured" if queue_depths or active_by_app else "unavailable",
        disabled_intents=_string_tuple_config(cfg, "disabled_intents"),
        disabled_resource_classes=_string_tuple_config(cfg, "disabled_resource_classes"),
        reserved_tokens=_string_tuple_config(cfg, "reserved_tokens"),
        max_queue_depth=queue_limit,
        max_app_concurrency=app_limits,
        constraint_retry_after=_optional_int_config(cfg, "retry_after_seconds"),
        load_retry_after=_optional_int_config(cfg, "queue_retry_after_seconds") or 30,
    )
    evidence = decision.details.as_dict(decision.outcome.value)
    evidence["wait_deadline"] = time.time() + 60
    if receipt is not None and enforce:
        receipt.resource_decision = evidence
    if decision.allowed:
        return None
    advised = resource_admission_http.admission_http_response(
        decision, wait_deadline=evidence["wait_deadline"], protocol=protocol,
    )
    return _gateway_refusal(Response(content=json.dumps(advised.body), status_code=advised.status_code,
                                     media_type="application/json", headers=dict(advised.headers)), "capacity")


def _model_dispatch_admission_response(
    auth_context: AuthContext, model: Any, *, intent: str = "chat.generate",
    resource_class: str = "chat", protocol: str = "openai",
) -> Response | None:
    if not _effective_media_job_admission_cfg() and not _operator_service_availability_overrides():
        return _dispatch_admission_response(
            intent, auth_context=auth_context, resource_class=resource_class, protocol=protocol,
        )
    # Resolution is declarative. Do not probe or start a backend to admit work.
    service_id = None
    available = None
    provider = provider_execution.provider_for_model(ADMIN_STORE.get_service_registry(), model)
    if provider is not None:
        service_id, available = provider.id, provider.configured
    else:
        try:
            target = _resolve_request_target(model)
        except AliasPolicyResolutionError:
            target = None
        if target is not None:
            service_id = target.logical_service_id
    return _dispatch_admission_response(
        intent, auth_context=auth_context, service_id=service_id,
        service_available=available, resource_class=resource_class, protocol=protocol,
    )


def _media_job_admission_response(
    intent: str, *, count_queue: bool = True, receipt: RouteReceipt | None = None,
    auth_context: AuthContext | None = None, path: str = "/gateway/v1/media/jobs",
) -> Response | None:
    """Return the operator's refusal for new media work, or None to admit it.

    ``count_queue=False`` skips the queue-depth limit, for a job that was
    already admitted and would otherwise count itself.
    """
    admission_cfg = _effective_media_job_admission_cfg()
    app_id = (auth_context.identity.app_id if auth_context and auth_context.identity
              else receipt.app_id if receipt else None)
    app_limits = admission_cfg.get("max_app_concurrency") if count_queue else None
    service_override = _operator_service_availability_overrides().get("comfyui", {})
    override_state = str(service_override.get("state") or "available")
    service_blocked = override_state in {"disabled", "maintenance", "draining"}
    service_degraded = override_state == "degraded"
    resource_class = _MEDIA_JOB_RESOURCE_CLASS_BY_INTENT.get(intent, "media")
    service_reasons_list: list[str] = []
    if not COMFY_ENABLED:
        service_reasons_list.append("ComfyUI media backend disabled")
    if service_blocked or service_degraded:
        reason = str(service_override.get("reason") or "").strip()
        service_reasons_list.append(reason or f"ComfyUI operator mode: {override_state}")
    max_queue_depth = _optional_int_config(admission_cfg, "max_queue_depth") if count_queue else None
    service_retry_after = (
        _optional_int_config(service_override, "retry_after_seconds")
        if isinstance(service_override, Mapping)
        else None
    )
    decision = resource_admission_http.advise_route_admission(
        intent=intent,
        observed_at=time.time(),
        load_quality="measured",
        service_available=COMFY_ENABLED and not service_blocked,
        service_degraded=service_degraded,
        service_retry_after=service_retry_after
        or (30 if (not COMFY_ENABLED or service_blocked) else None),
        service_reasons=tuple(service_reasons_list),
        resource_class=resource_class,
        app_id=app_id, active_by_app=_media_job_app_load(app_id, app_limits),
        max_app_concurrency=app_limits,
        queue_key=_MEDIA_JOB_QUEUE_KEY,
        requires_gpu=True,
        disabled_intents=_string_tuple_config(admission_cfg, "disabled_intents"),
        disabled_resource_classes=_string_tuple_config(
            admission_cfg,
            "disabled_resource_classes",
        ),
        reserved_tokens=_string_tuple_config(admission_cfg, "reserved_tokens"),
        max_queue_depth=max_queue_depth,
        constraint_retry_after=_optional_int_config(
            admission_cfg,
            "retry_after_seconds",
        ),
        queue_depths={
            _MEDIA_JOB_QUEUE_KEY: _media_job_queue_depth(
                max_queue_depth,
                admission_cfg=admission_cfg,
            )
        } if count_queue else {},
        load_retry_after=_optional_int_config(
            admission_cfg,
            "queue_retry_after_seconds",
        ) or 30,
    )
    evidence = decision.details.as_dict(decision.outcome.value)
    # A bounded retry window, not an ETA or a reservation.
    evidence["wait_deadline"] = time.time() + 60
    if receipt is not None:
        receipt.resource_decision = evidence
    if decision.allowed:
        return None
    if receipt is None and auth_context is not None:
        identity = auth_context.identity
        refused = RouteReceipt(protocol="gateway.media", intent=intent, path=path,
                               app_id=identity.app_id if identity else None,
                               owner_key_hash=identity.key_hash if identity else None,
                               api_key_name=identity.name if identity else None,
                               resource_decision=evidence)
        refused.finish("rejected")
        try:
            receipt_store.record(refused)
        except Exception as exc:  # Receipts are observational.
            print(f"[proxy] admission receipt failed: {type(exc).__name__}", flush=True)
    advised = resource_admission_http.admission_http_response(decision, wait_deadline=evidence["wait_deadline"])
    response = Response(content=json.dumps(advised.body), status_code=advised.status_code,
                        media_type="application/json", headers=dict(advised.headers))
    # Trusted in-process handoff for session submission's owned receipt.
    response.resource_decision = evidence
    return _gateway_refusal(response, "capacity")



_AUDIO_MEDIA_JOB_INTENTS = frozenset({"audio.generate", "music.generate", "sfx.generate"})
_audio_media_job_tasks: set[asyncio.Task] = set()
_audio_media_job_scheduled: set[str] = set()
_audio_media_job_semaphore = asyncio.Semaphore(IMAGE_MEDIA_JOB_CONCURRENCY)


def _audio_media_job_policy() -> dict[str, Any]:
    return _ASSET_CONTENT_ROUTE_POLICY_BY_KIND["aud"]


def _audio_generation_body_from_media_job_payload(
    payload: Mapping[str, Any],
) -> dict[str, Any] | None:
    intent = payload.get("intent")
    if intent not in _AUDIO_MEDIA_JOB_INTENTS:
        return None
    request_body = payload.get("request")
    if not isinstance(request_body, Mapping):
        request_body = payload.get("parameters")
    return _media_job_prompt_body(payload, request_body) if isinstance(request_body, Mapping) else None


def _persist_audio_media_job_payload(
    job_id: str,
    *,
    body: Mapping[str, Any],
    request: Request,
    auth_context: AuthContext,
) -> None:
    _persist_image_media_job_payload(
        job_id,
        body=body,
        request=request,
        auth_context=auth_context,
    )


def _load_audio_media_job_payload(job_id: str) -> dict[str, Any] | None:
    return _load_image_media_job_payload(job_id)


def _delete_audio_media_job_payload(job_id: str) -> None:
    _delete_image_media_job_payload(job_id)


def _request_shim_from_audio_job_payload(payload: Mapping[str, Any]) -> _JsonBodyRequestShim | None:
    body = payload.get("body")
    if not isinstance(body, Mapping):
        return None
    url = payload.get("url")
    headers = payload.get("headers")
    if not isinstance(url, Mapping):
        url = {}
    if not isinstance(headers, Mapping):
        headers = {}
    return _JsonBodyRequestShim(
        body=copy.deepcopy(dict(body)),
        headers={str(k): str(v) for k, v in headers.items()},
        scheme=str(url.get("scheme") or "http"),
        netloc=str(url.get("netloc") or headers.get("host") or "127.0.0.1"),
    )


def _mark_audio_media_job_failed(
    job_id: str,
    message: str,
    *,
    http_status: int | None = None,
    error_info: Mapping[str, Any] | None = None,
) -> None:
    metadata_patch: dict[str, Any] = {}
    if http_status is not None:
        metadata_patch["last_http_status"] = int(http_status)
    try:
        media_jobs.update_status(
            job_id,
            media_jobs.STATUS_FAILED,
            error=message[:500],
            error_info=error_info,
            metadata_patch=metadata_patch or None,
            path=media_jobs.DB_PATH,
        )
    except Exception as exc:  # noqa: BLE001
        print(f"[proxy] audio media job fail update failed for {job_id}: {exc}", flush=True)
    try:
        media_jobs.append_event(
            job_id,
            "failed",
            {
                "phase": "failed",
                "status": media_jobs.STATUS_FAILED,
                "progress": 100,
                "http_status": http_status or 0,
            },
            path=media_jobs.DB_PATH,
        )
    except Exception:
        pass
    _delete_audio_media_job_payload(job_id)


@_settle_native_job
async def _run_audio_media_job(job_id: str) -> None:
    async with _audio_media_job_semaphore:
        job = media_jobs.get(job_id, audience="internal", path=media_jobs.DB_PATH)
        if not job or job.get("status") in media_jobs.TERMINAL_STATUSES:
            return

        payload = _load_audio_media_job_payload(job_id)
        request_shim = _request_shim_from_audio_job_payload(payload or {})
        if payload is None or request_shim is None:
            _mark_audio_media_job_failed(job_id, "Audio media job payload is missing or invalid")
            return

        auth_context = _auth_context_from_image_job_payload(payload)
        if auth_context is None:
            _mark_audio_media_job_failed(job_id, _MEDIA_JOB_CALLER_GONE, error_info=_MEDIA_JOB_CALLER_GONE_INFO)
            return
        admission = _media_job_admission_response(
            str(job.get("intent") or "audio.generate"), count_queue=False, auth_context=auth_context,
        )
        if admission is not None:
            message, error_info = _media_job_failure(admission)
            _mark_audio_media_job_failed(job_id, message, error_info=error_info)
            return

        try:
            media_jobs.update_status(
                job_id,
                media_jobs.STATUS_RUNNING,
                progress=5,
                metadata_patch={"started_at": int(time.time())},
                path=media_jobs.DB_PATH,
            )
            media_jobs.append_event(
                job_id,
                "started",
                {
                    "phase": "running",
                    "status": media_jobs.STATUS_RUNNING,
                    "progress": 5,
                },
                path=media_jobs.DB_PATH,
            )
            worker_token = _ADMISSION_WORKER.set(True)
            try:
                response = await proxy_audio_generate(request_shim, auth_context, store_full=True)
            finally:
                _ADMISSION_WORKER.reset(worker_token)
        except asyncio.CancelledError:
            raise
        except Exception as exc:  # noqa: BLE001
            _mark_audio_media_job_failed(
                job_id,
                f"Audio media job executor error: {type(exc).__name__}",
                http_status=502,
            )
            return

        status_code = int(getattr(response, "status_code", 0) or 0)
        if not 200 <= status_code < 300:
            message, error_info = _media_job_failure(response)
            _mark_audio_media_job_failed(job_id, message, http_status=status_code, error_info=error_info)
            return

        content = bytes(getattr(response, "body", b"") or b"")
        media_type = str(getattr(response, "media_type", None) or "audio/wav")
        body = payload.get("body") if isinstance(payload, Mapping) else {}
        response_format = body.get("response_format") if isinstance(body, Mapping) else None
        artifacts = audio_media_jobs.audio_artifacts_from_result(
            content,
            response_format=str(response_format) if response_format else None,
            media_type=media_type,
        )
        assets = await asyncio.to_thread(audio_media_jobs.store_audio_artifacts,
            artifacts,
            store_asset=store_asset_bytes,
            owner_key_hash=_asset_owner_key(auth_context),
        )
        if not assets:
            _mark_audio_media_job_failed(
                job_id,
                "Audio generation succeeded but returned no reusable assets",
                http_status=status_code,
            )
            return

        media_jobs.update_status(
            job_id,
            media_jobs.STATUS_SUCCEEDED,
            progress=100,
            add_assets=assets,
            metadata_patch={"completed_at": int(time.time()), **_job_metadata_mode_patch()},
            path=media_jobs.DB_PATH,
        )
        media_jobs.append_event(
            job_id,
            "completed",
            {
                **audio_media_jobs.complete_audio_job_payload(assets),
                "status": media_jobs.STATUS_SUCCEEDED,
                "progress": 100,
            },
            path=media_jobs.DB_PATH,
        )
        _delete_audio_media_job_payload(job_id)


def _schedule_audio_media_job(job_id: str) -> bool:
    if job_id in _audio_media_job_scheduled:
        return False
    _audio_media_job_scheduled.add(job_id)
    try:
        task = asyncio.create_task(_run_audio_media_job(job_id))
    except BaseException:
        # A launch that never started must not leave the job looking scheduled.
        _audio_media_job_scheduled.discard(job_id)
        raise
    _audio_media_job_tasks.add(task)

    def _done(done_task: asyncio.Task) -> None:
        _audio_media_job_tasks.discard(done_task)
        _audio_media_job_scheduled.discard(job_id)
        try:
            exc = done_task.exception()
        except asyncio.CancelledError:
            return
        if exc is not None:
            _log_media_job_crash(job_id, exc)
            _mark_audio_media_job_failed(job_id, _MEDIA_JOB_CRASHED, error_info=_MEDIA_JOB_CRASHED_INFO)

    task.add_done_callback(_done)
    return True


def _resume_pending_audio_media_jobs() -> int:
    resumed = 0
    for job in media_jobs.unfinished(path=media_jobs.DB_PATH):
        if job.get("intent") not in _AUDIO_MEDIA_JOB_INTENTS:
            continue
        metadata = job.get("metadata") or {}
        if not isinstance(metadata, Mapping) or metadata.get("mode") != "async_audio_generation":
            continue
        job_id = str(job.get("job_id") or "")
        if not job_id:
            continue
        if not _has_image_media_job_payload(job_id):
            _mark_audio_media_job_failed(
                job_id,
                "Audio media job payload missing after proxy restart",
            )
            continue
        from gateway.engine_protocol.dispatch import opted_in
        service = (ADMIN_STORE.get_service_registry().get("services") or {}).get(job.get("backend")) or {}
        if not IMAGE_MEDIA_JOB_RESUME_ON_START or (not opted_in(service) and not COMFY_ENABLED):
            _mark_audio_media_job_failed(job_id, "The gateway restarted with job recovery turned off")
            continue
        if metadata.get("cancel_requested_at"):
            _mark_audio_media_job_failed(job_id, "The gateway restarted before cancellation could be confirmed")
            continue
        if job.get("status") == media_jobs.STATUS_RUNNING:
            _mark_audio_media_job_failed(job_id, "The gateway restarted before completion could be confirmed; this job was not run again")
            continue
        if _schedule_audio_media_job(job_id):
            resumed += 1
    return resumed


async def _submit_audio_media_job(
    *,
    request: Request,
    intent: str,
    body: Mapping[str, Any],
) -> Response:
    auth_context = _gateway_auth_context(request, "/gateway/v1/media/jobs")
    if isinstance(auth_context, Response):
        return auth_context

    policy_response = (await asyncio.to_thread(_enforce_runtime_route_policy, auth_context,
        "/gateway/v1/media/jobs",
        policy=_audio_media_job_policy(),))
    if policy_response is not None:
        return policy_response

    request_id = f"audjob_{uuid.uuid4().hex}"
    workflow_name, _workflow_cfg = _resolve_audio_workflow(str(body.get("model", AUDIO_DEFAULT_WORKFLOW)))
    if not workflow_name:
        requested_model = str(body.get("model", AUDIO_DEFAULT_WORKFLOW))
        return model_compatibility_error(
            ModelCompatibilityError(
                f"Model '{requested_model}' is not available for audio generation.",
                code="model_not_found",
            )
        )
    requested_model = body.get("model", AUDIO_DEFAULT_WORKFLOW)
    manifest = _load_audio_workflow_manifest(workflow_name)
    policy_decision = evaluate_and_apply(
        auth_context.identity,
        make_policy_request(
            protocol="openai.audio",
            intent=intent,
            model=str(requested_model) if requested_model is not None else None,
            workflow=f"audio.generate.{workflow_name}",
            backend="comfyui",
            capability_exposure="default",
            capability_trust_tier="stable",
            capability_resource_tier="batch",
        ),
    )
    if policy_decision.denied:
        return _policy_denied_response(policy_decision)
    admission_response = _media_job_admission_response(intent, auth_context=auth_context)
    if admission_response is not None:
        return admission_response
    target_decision = _workflow_target_policy_decision(
        auth_context,
        requested=str(requested_model) if requested_model is not None else None,
        resolved=workflow_name,
        manifest=manifest,
        extra_ids=(f"audio.generate.{workflow_name}",),
    )
    if target_decision is not None and target_decision.denied:
        return _policy_denied_response(target_decision)
    job = audio_media_jobs.audio_job_from_request(
        body,
        request_id=request_id,
        workflow=f"audio.generate.{workflow_name}",
        backend="comfyui",
        app_profile=plan_ref(auth_context.identity),
        api_key_name=auth_context.identity.name if auth_context.identity else None,
        parent_request_id=request_id,
    )
    job.intent = intent
    metadata = dict(job.metadata or {})
    metadata["mode"] = "async_audio_generation"
    job.metadata = metadata

    try:
        _persist_audio_media_job_payload(
            job.job_id,
            body=body,
            request=request,
            auth_context=auth_context,
        )
        job.owner_key_hash = auth_context.identity.key_hash if auth_context.identity else None
        job.app_id = auth_context.identity.app_id if auth_context.identity else None
        created = media_jobs.create(job, input_data=body, path=media_jobs.DB_PATH)
    except EphemeralMediaPayloadCapacityError:
        _delete_audio_media_job_payload(job.job_id)
        return _ephemeral_media_payload_busy_response()
    except Exception as exc:  # noqa: BLE001
        _delete_audio_media_job_payload(job.job_id)
        return Response(
            content=json.dumps({
                "error": {
                    "message": f"Could not create audio media job: {type(exc).__name__}",
                    "type": "api_error",
                }
            }),
            status_code=500,
            media_type="application/json",
        )

    try:
        media_jobs.append_event(
            job.job_id,
            "queued",
            {
                "phase": "queued",
                "status": media_jobs.STATUS_QUEUED,
                "progress": 0,
            },
            path=media_jobs.DB_PATH,
        )
    except Exception:
        pass
    _schedule_audio_media_job(job.job_id)
    return _image_media_job_response(created.to_dict("internal"), request, status_code=202)


_VIDEO_MEDIA_JOB_INTENTS = frozenset({INTENT_VIDEO_GENERATE})
_video_media_job_tasks: set[asyncio.Task] = set()
_video_media_job_scheduled: set[str] = set()
_video_media_job_semaphore = asyncio.Semaphore(1)
_VIDEO_MEDIA_JOB_POLL_INTERVAL_SECONDS = 5.0


def _video_media_job_policy() -> dict[str, Any]:
    return _ASSET_CONTENT_ROUTE_POLICY_BY_KIND["vid"]


def _video_route_policy() -> dict[str, Any]:
    """The same `openai.video`/`video.generate` policy every other
    `/v1/videos*` route already enforces (registry/protocol_frontends.yml).

    GET /v1/videos (list) and DELETE /v1/videos/{video_id} share a canonical
    path with POST /v1/videos and GET /v1/videos/{video_id} respectively, and
    `route_registry.runtime_route_policy()` keys its result by path alone
    (not path+method) -- a second registry entry at either path would
    silently overwrite the already-registered one instead of adding a
    method-specific policy. Enforcing this literal policy dict in-handler
    (via `_enforce_runtime_route_policy`'s `policy=` override) gets list and
    delete the same protection without touching that shared dict at all.
    """
    return _ASSET_CONTENT_ROUTE_POLICY_BY_KIND["vid"]


def _video_generation_body_from_media_job_payload(
    payload: Mapping[str, Any],
) -> dict[str, Any] | None:
    if payload.get("intent") != INTENT_VIDEO_GENERATE:
        return None
    request_body = payload.get("request")
    if not isinstance(request_body, Mapping):
        request_body = payload.get("parameters")
    return _media_job_prompt_body(payload, request_body) if isinstance(request_body, Mapping) else None


def _validate_video_media_job_body(body: Mapping[str, Any]) -> tuple[str | None, Response | None]:
    unknown_video_fields = detect_unknown_top_level_fields(
        body,
        STANDARD_VIDEO_CREATE_FIELDS,
    )
    if unknown_video_fields:
        first_name, first_reason = next(iter(unknown_video_fields.items()))
        return None, Response(
            content=json.dumps({"error": {
                "message": first_reason,
                "type": "invalid_request_error",
                "param": first_name,
                "code": "unknown_parameter",
            }}),
            status_code=400,
            media_type="application/json",
        )
    prompt = body.get("prompt")
    if not isinstance(prompt, str) or not prompt.strip():
        return None, Response(
            content=json.dumps({"error": {"message": "prompt is required", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )

    requested_model = body.get("model") or VIDEO_DEFAULT_WORKFLOW
    try:
        model_resolution = resolve_model_for_operation("videos", requested_model)
    except ModelCompatibilityError as exc:
        return None, model_compatibility_error(exc)
    workflow_candidate = (
        model_resolution.effective_model
        if model_resolution.is_openai_alias
        else requested_model
    )
    workflow_name, workflow_cfg = _resolve_video_workflow(workflow_candidate)
    if not workflow_cfg:
        return None, model_compatibility_error(
            ModelCompatibilityError(
                f"Model '{workflow_candidate}' is not available for video generation.",
                code="model_not_found",
            )
        )
    return str(workflow_name), None


def _persist_video_media_job_payload(
    job_id: str,
    *,
    body: Mapping[str, Any],
    request: Request,
    auth_context: AuthContext,
) -> None:
    _persist_image_media_job_payload(
        job_id,
        body=body,
        request=request,
        auth_context=auth_context,
    )


def _load_video_media_job_payload(job_id: str) -> dict[str, Any] | None:
    return _load_image_media_job_payload(job_id)


def _delete_video_media_job_payload(job_id: str) -> None:
    _delete_image_media_job_payload(job_id)


def _request_shim_from_video_job_payload(payload: Mapping[str, Any]) -> _JsonBodyRequestShim | None:
    body = payload.get("body")
    if not isinstance(body, Mapping):
        return None
    url = payload.get("url")
    headers = payload.get("headers")
    if not isinstance(url, Mapping):
        url = {}
    if not isinstance(headers, Mapping):
        headers = {}
    return _JsonBodyRequestShim(
        body=copy.deepcopy(dict(body)),
        headers={str(k): str(v) for k, v in headers.items()},
        scheme=str(url.get("scheme") or "http"),
        netloc=str(url.get("netloc") or headers.get("host") or "127.0.0.1"),
    )


def _mark_video_media_job_failed(
    job_id: str,
    message: str,
    *,
    http_status: int | None = None,
    error_info: Mapping[str, Any] | None = None,
) -> None:
    metadata_patch: dict[str, Any] = {}
    if http_status is not None:
        metadata_patch["last_http_status"] = int(http_status)
    try:
        media_jobs.update_status(
            job_id,
            media_jobs.STATUS_FAILED,
            error=message[:500],
            error_info=error_info,
            metadata_patch=metadata_patch or None,
            path=media_jobs.DB_PATH,
        )
    except Exception as exc:  # noqa: BLE001
        print(f"[proxy] video media job fail update failed for {job_id}: {exc}", flush=True)
    try:
        media_jobs.append_event(
            job_id,
            "failed",
            {
                "phase": "failed",
                "status": media_jobs.STATUS_FAILED,
                "progress": 100,
                "http_status": http_status or 0,
            },
            path=media_jobs.DB_PATH,
        )
    except Exception:
        pass
    _delete_video_media_job_payload(job_id)


def _video_response_status(response: Response) -> tuple[str | None, int]:
    parsed = _image_response_json(response)
    status_value = parsed.get("status")
    if status_value == "in_progress":
        status_value = media_jobs.STATUS_RUNNING
    elif status_value == "completed":
        status_value = media_jobs.STATUS_SUCCEEDED
    progress = parsed.get("progress", 0)
    try:
        progress_value = max(0, min(int(progress), 100))
    except (TypeError, ValueError):
        progress_value = 0
    return str(status_value) if status_value else None, progress_value


def _video_suffix_for_response(response: Response, *, filename: str | None = None) -> str:
    if filename:
        suffix = Path(filename).suffix.lower()
        if suffix in {".mp4", ".webm", ".mov", ".mkv"}:
            return suffix
    media_type = str(getattr(response, "media_type", None) or response.headers.get("content-type", ""))
    media_type = media_type.split(";", 1)[0].strip().lower()
    return {
        "video/mp4": ".mp4",
        "video/webm": ".webm",
        "video/quicktime": ".mov",
        "video/x-matroska": ".mkv",
    }.get(media_type, ".mp4")


def _video_filename_from_response(response: Response, *, default: str) -> str:
    disposition = response.headers.get("content-disposition", "")
    marker = "filename="
    if marker in disposition:
        raw = disposition.split(marker, 1)[1].strip().strip('"')
        if raw:
            return Path(raw).name
    suffix = _video_suffix_for_response(response)
    return f"{default}{suffix}"


@_settle_native_job
async def _run_video_media_job(job_id: str) -> None:
    async with _video_media_job_semaphore:
        job = media_jobs.get(job_id, audience="internal", path=media_jobs.DB_PATH)
        if not job or job.get("status") in media_jobs.TERMINAL_STATUSES:
            return

        payload = _load_video_media_job_payload(job_id)
        request_shim = _request_shim_from_video_job_payload(payload or {})
        if payload is None or request_shim is None:
            _mark_video_media_job_failed(job_id, "Video media job payload is missing or invalid")
            return

        auth_context = _auth_context_from_image_job_payload(payload)
        if auth_context is None:
            _mark_video_media_job_failed(job_id, _MEDIA_JOB_CALLER_GONE, error_info=_MEDIA_JOB_CALLER_GONE_INFO)
            return
        video_id = (job.get("metadata") or {}).get("upstream_video_id")
        if not video_id:
            # Admission is re-checked only before submitting new work; a job
            # resuming an already-submitted upstream video is not re-admitted.
            admission = _media_job_admission_response(
                INTENT_VIDEO_GENERATE, count_queue=False, auth_context=auth_context,
            )
            if admission is not None:
                message, error_info = _media_job_failure(admission)
                _mark_video_media_job_failed(job_id, message, error_info=error_info)
                return
            try:
                media_jobs.update_status(
                    job_id,
                    media_jobs.STATUS_RUNNING,
                    progress=2,
                    metadata_patch={"started_at": int(time.time())},
                    path=media_jobs.DB_PATH,
                )
                media_jobs.append_event(
                    job_id,
                    "started",
                    video_media_jobs.video_status_event(
                        status=media_jobs.STATUS_RUNNING,
                        progress=2,
                        phase="submitting",
                    ),
                    path=media_jobs.DB_PATH,
                )
                worker_token = _ADMISSION_WORKER.set(True)
                try:
                    submit_response = await proxy_comfy_video_create(request_shim, auth_context)
                finally:
                    _ADMISSION_WORKER.reset(worker_token)
            except asyncio.CancelledError:
                raise
            except Exception as exc:  # noqa: BLE001
                _mark_video_media_job_failed(
                    job_id,
                    f"Video media job executor error: {type(exc).__name__}",
                    http_status=502,
                )
                return

            submit_status = int(getattr(submit_response, "status_code", 0) or 0)
            if not 200 <= submit_status < 300:
                message, error_info = _media_job_failure(submit_response)
                _mark_video_media_job_failed(job_id, message, http_status=submit_status, error_info=error_info)
                return

            submit_payload = _image_response_json(submit_response)
            video_id = submit_payload.get("id")
            if not isinstance(video_id, str) or not video_id:
                _mark_video_media_job_failed(
                    job_id,
                    "Video generation succeeded at submit but returned no video id",
                    http_status=submit_status,
                )
                return

            prompt_id = _prompt_id_from_video_id(video_id)
            if prompt_id and prompt_id in _video_job_records:
                _video_job_records[prompt_id]["media_job_id"] = job_id
                _persist_video_record(prompt_id)

            media_jobs.update_status(
                job_id,
                media_jobs.STATUS_RUNNING,
                progress=5,
                metadata_patch={
                    "upstream_video_id": video_id,
                    "last_http_status": submit_status,
                },
                path=media_jobs.DB_PATH,
            )
            media_jobs.append_event(
                job_id,
                "submitted",
                video_media_jobs.video_status_event(
                    status=media_jobs.STATUS_RUNNING,
                    progress=5,
                    phase="queued",
                ),
                path=media_jobs.DB_PATH,
            )

        deadline = time.monotonic() + max(1, COMFY_VIDEO_TIMEOUT)
        last_progress = 5
        while time.monotonic() < deadline:
            await asyncio.sleep(_VIDEO_MEDIA_JOB_POLL_INTERVAL_SECONDS)
            current_job = media_jobs.get(job_id, audience="internal", path=media_jobs.DB_PATH)
            if current_job is None or current_job.get("status") in media_jobs.TERMINAL_STATUSES:
                _delete_image_media_job_payload(job_id)
                return
            step = _video_media_job_step_auth(payload, current_job)
            if isinstance(step, tuple):
                _mark_video_media_job_failed(job_id, step[0], error_info=step[1])
                return
            auth_context = step
            status_response = await proxy_comfy_video_status(video_id, auth_context)
            status_code = int(getattr(status_response, "status_code", 0) or 0)
            if status_code >= 500:
                message, error_info = _media_job_failure(status_response)
                _mark_video_media_job_failed(job_id, message, http_status=status_code, error_info=error_info)
                return
            status_value, progress = _video_response_status(status_response)
            if status_value in {"queued", "running"}:
                progress = max(last_progress, min(progress or last_progress, 95))
                if progress != last_progress:
                    last_progress = progress
                    media_jobs.update_status(
                        job_id,
                        media_jobs.STATUS_RUNNING,
                        progress=progress,
                        path=media_jobs.DB_PATH,
                    )
                    media_jobs.append_event(
                        job_id,
                        "progress",
                        video_media_jobs.video_status_event(
                            status=media_jobs.STATUS_RUNNING,
                            progress=progress,
                            phase=status_value,
                        ),
                        path=media_jobs.DB_PATH,
                    )
                continue
            if status_value == "failed":
                message, error_info = _media_job_failure(status_response)
                _mark_video_media_job_failed(job_id, message, http_status=status_code, error_info=error_info)
                return
            if status_value != "succeeded":
                continue

            step = _video_media_job_step_auth(payload, current_job)
            if isinstance(step, tuple):
                _mark_video_media_job_failed(job_id, step[0], error_info=step[1])
                return
            auth_context = step
            content_response = await proxy_comfy_video_content(video_id, auth_context, index_library=False, metadata_mode=provenance.METADATA_NONE)
            content_status = int(getattr(content_response, "status_code", 0) or 0)
            if not 200 <= content_status < 300:
                message, error_info = _media_job_failure(content_response)
                _mark_video_media_job_failed(job_id, message, http_status=content_status, error_info=error_info)
                return

            # A cancel that arrived during the fetch must not leave a stored asset behind.
            current = media_jobs.get(job_id, path=media_jobs.DB_PATH) or {}
            if (current.get("metadata") or {}).get("cancel_requested_at"):
                raise media_jobs.CancellationPending()

            content = bytes(getattr(content_response, "body", b"") or b"")
            filename = _video_filename_from_response(
                content_response,
                default=video_id,
            )
            suffix = _video_suffix_for_response(content_response, filename=filename)
            asset_id = await asyncio.to_thread(store_asset_bytes,
                content,
                kind="vid",
                suffix=suffix,
                owner_key_hash=_asset_owner_key(auth_context),
            )
            person_id = _auth_person_id(auth_context)
            if person_id:
                await asyncio.to_thread(prompt_memory.move, f"video_{_prompt_id_from_video_id(video_id)}", asset_id, person_id,
                                   admin_path=ADMIN_STORE.path)
                prompt_id = _prompt_id_from_video_id(video_id)
                if prompt_id and prompt_id in _video_job_records:
                    _video_job_records[prompt_id]["asset_id"] = asset_id
                    _persist_video_record(prompt_id)
            asset = video_media_job_http.completed_asset_from_stored_video(
                filename=filename,
                asset_id=asset_id,
                content_url=build_signed_asset_url(request_shim, asset_id),
                media_type=asset_media_type(asset_id),
            )
            media_jobs.update_status(
                job_id,
                media_jobs.STATUS_SUCCEEDED,
                progress=100,
                add_assets=[asset],
                metadata_patch={
                    "completed_at": int(time.time()),
                    "upstream_video_id": video_id,
                    **_job_metadata_mode_patch(),
                },
                path=media_jobs.DB_PATH,
            )
            media_jobs.append_event(
                job_id,
                "completed",
                video_media_jobs.video_status_event(
                    status=media_jobs.STATUS_SUCCEEDED,
                    progress=100,
                    phase="complete",
                    asset_count=1,
                ),
                path=media_jobs.DB_PATH,
            )
            _delete_video_media_job_payload(job_id)
            return

        _mark_video_media_job_failed(
            job_id,
            "Video media job timed out",
            http_status=504,
        )


def _schedule_video_media_job(job_id: str) -> bool:
    if job_id in _video_media_job_scheduled:
        return False
    _video_media_job_scheduled.add(job_id)
    try:
        task = asyncio.create_task(_run_video_media_job(job_id))
    except BaseException:
        # A launch that never started must not leave the job looking scheduled.
        _video_media_job_scheduled.discard(job_id)
        raise
    _video_media_job_tasks.add(task)

    def _done(done_task: asyncio.Task) -> None:
        _video_media_job_tasks.discard(done_task)
        _video_media_job_scheduled.discard(job_id)
        try:
            exc = done_task.exception()
        except asyncio.CancelledError:
            return
        if exc is not None:
            _log_media_job_crash(job_id, exc)
            _mark_video_media_job_failed(job_id, _MEDIA_JOB_CRASHED, error_info=_MEDIA_JOB_CRASHED_INFO)

    task.add_done_callback(_done)
    return True


def _resume_pending_video_media_jobs() -> int:
    resumed = 0
    for job in media_jobs.unfinished(path=media_jobs.DB_PATH):
        if job.get("intent") != INTENT_VIDEO_GENERATE:
            continue
        metadata = job.get("metadata") or {}
        if not isinstance(metadata, Mapping) or metadata.get("mode") != "async_video_generation":
            continue
        job_id = str(job.get("job_id") or "")
        if not job_id:
            continue
        if not _has_image_media_job_payload(job_id):
            _mark_video_media_job_failed(
                job_id,
                "Video media job payload missing after proxy restart",
            )
            continue
        from gateway.engine_protocol.dispatch import opted_in
        service = (ADMIN_STORE.get_service_registry().get("services") or {}).get(job.get("backend")) or {}
        if not IMAGE_MEDIA_JOB_RESUME_ON_START or (not opted_in(service) and not COMFY_ENABLED):
            _mark_video_media_job_failed(job_id, "The gateway restarted with job recovery turned off")
            continue
        if metadata.get("cancel_requested_at"):
            _mark_video_media_job_failed(job_id, "The gateway restarted before cancellation could be confirmed")
            continue
        if job.get("status") == media_jobs.STATUS_RUNNING and not metadata.get("upstream_video_id"):
            _mark_video_media_job_failed(job_id, "The gateway restarted before completion could be confirmed; this job was not run again")
            continue
        if _schedule_video_media_job(job_id):
            resumed += 1
    return resumed


def _video_job_policy_decision(auth_context: AuthContext, requested_model: Any, workflow_name: str) -> PolicyDecision:
    """The plan check of a video job, at submit and before each later step."""
    return evaluate_and_apply(
        auth_context.identity,
        make_policy_request(
            protocol="openai.video",
            intent=INTENT_VIDEO_GENERATE,
            model=str(requested_model) if requested_model is not None else None,
            workflow=f"video.generate.{workflow_name}",
            backend="comfyui",
            capability_exposure="default",
            capability_trust_tier="stable",
            capability_resource_tier="expensive",
        ),
    )


def _video_media_job_step_auth(
    payload: Mapping[str, Any], job: Mapping[str, Any],
) -> AuthContext | tuple[str, dict[str, Any]]:
    """The caller of a running video job, checked again before its next step.

    The same identity rebuild and plan checks as at submit: a revoked key or
    connection, or a plan that no longer allows the workflow, gives the
    failure (message, typed facts) to record instead of an AuthContext.
    """
    auth_context = _auth_context_from_image_job_payload(payload)
    if auth_context is None:
        return _MEDIA_JOB_CALLER_GONE, dict(_MEDIA_JOB_CALLER_GONE_INFO)
    body = payload.get("body") if isinstance(payload.get("body"), Mapping) else {}
    requested_model = body.get("model") or VIDEO_DEFAULT_WORKFLOW
    workflow_name = str(job.get("workflow") or "")
    decision = _video_job_policy_decision(auth_context, requested_model, workflow_name)
    if decision.denied:
        return _media_job_failure(_policy_denied_response(decision))
    target = _workflow_target_policy_decision(
        auth_context,
        requested=str(requested_model),
        resolved=workflow_name,
        extra_ids=(f"video.generate.{workflow_name}",),
    )
    if target is not None and target.denied:
        return _media_job_failure(_policy_denied_response(target))
    return auth_context


async def _submit_video_media_job(
    *,
    request: Request,
    body: Mapping[str, Any],
) -> Response:
    auth_context = _gateway_auth_context(request, "/gateway/v1/media/jobs")
    if isinstance(auth_context, Response):
        return auth_context

    policy_response = (await asyncio.to_thread(_enforce_runtime_route_policy, auth_context,
        "/gateway/v1/media/jobs",
        policy=_video_media_job_policy(),))
    if policy_response is not None:
        return policy_response

    workflow_name, error_response = _validate_video_media_job_body(body)
    if error_response is not None:
        return error_response
    assert workflow_name is not None
    requested_model = body.get("model") or VIDEO_DEFAULT_WORKFLOW
    policy_decision = _video_job_policy_decision(auth_context, requested_model, workflow_name)
    if policy_decision.denied:
        return _policy_denied_response(policy_decision)
    admission_response = _media_job_admission_response(INTENT_VIDEO_GENERATE, auth_context=auth_context)
    if admission_response is not None:
        return admission_response
    target_decision = _workflow_target_policy_decision(
        auth_context,
        requested=str(requested_model) if requested_model is not None else None,
        resolved=workflow_name,
        extra_ids=(f"video.generate.{workflow_name}",),
    )
    if target_decision is not None and target_decision.denied:
        return _policy_denied_response(target_decision)

    request_id = f"vidjob_{uuid.uuid4().hex}"
    job = video_media_job_http.job_from_openai_video_request(
        body,
        video_media_job_http.VideoRequestContext(
            workflow=workflow_name,
            backend="comfyui",
            request_id=request_id,
            idempotency_key=request.headers.get("idempotency-key"),
            app_profile=plan_ref(auth_context.identity),
            api_key_name=auth_context.identity.name if auth_context.identity else None,
            parent_request_id=request_id,
        ),
    )

    try:
        _persist_video_media_job_payload(
            job.job_id,
            body=body,
            request=request,
            auth_context=auth_context,
        )
        job.owner_key_hash = auth_context.identity.key_hash if auth_context.identity else None
        job.app_id = auth_context.identity.app_id if auth_context.identity else None
        created = media_jobs.create(job, input_data=body, path=media_jobs.DB_PATH)
    except EphemeralMediaPayloadCapacityError:
        _delete_video_media_job_payload(job.job_id)
        return _ephemeral_media_payload_busy_response()
    except Exception as exc:  # noqa: BLE001
        _delete_video_media_job_payload(job.job_id)
        return Response(
            content=json.dumps({
                "error": {
                    "message": f"Could not create video media job: {type(exc).__name__}",
                    "type": "api_error",
                }
            }),
            status_code=500,
            media_type="application/json",
        )

    try:
        media_jobs.append_event(
            job.job_id,
            "queued",
            video_media_jobs.video_status_event(
                status=media_jobs.STATUS_QUEUED,
                progress=0,
                phase="queued",
            ),
            path=media_jobs.DB_PATH,
        )
    except Exception:
        pass
    _schedule_video_media_job(job.job_id)
    return _image_media_job_response(created.to_dict("internal"), request, status_code=202)


def _unsupported_gateway_media_job_response(intent: str) -> Response:
    supported_intents = [
        "image.generate",
        "audio.generate",
        "music.generate",
        "sfx.generate",
        "video.generate",
    ]
    return Response(
        content=json.dumps({
            "error": {
                "message": (
                    f"Media job intent {intent!r} is not executable yet. "
                    f"Currently supported: {', '.join(supported_intents)}."
                ),
                "type": "invalid_request_error",
                "code": "unsupported_media_job_intent",
                "supported_intents": supported_intents,
            }
        }),
        status_code=400,
        media_type="application/json",
    )


async def _dispatch_gateway_media_job_submission(
    *,
    request: Request,
    payload: Mapping[str, Any],
    audience: str,
) -> Response | None:
    del audience
    intent = payload.get("intent")
    if not isinstance(intent, str) or not intent.strip():
        return None
    intent = intent.strip()
    try:
        audio_body = _audio_generation_body_from_media_job_payload({**payload, "intent": intent})
        video_body = _video_generation_body_from_media_job_payload({**payload, "intent": intent})
        body = _image_generation_body_from_media_job_payload({**payload, "intent": intent})
    except prompt_memory.PromptModeError as exc:
        return _json_error(400, str(exc), code="invalid_prompt_mode", param="extensions")
    if audio_body is not None:
        return await _submit_audio_media_job(request=request, intent=intent, body=audio_body)
    if video_body is not None:
        return await _submit_video_media_job(request=request, body=video_body)
    if body is None:
        if intent == "image.generate":
            return None
        return _unsupported_gateway_media_job_response(intent)
    headers = _safe_image_job_headers(request)
    idempotency_key = request.headers.get("idempotency-key")
    if idempotency_key:
        headers["idempotency-key"] = idempotency_key
    submit_request = _JsonBodyRequestShim(
        body=body,
        headers=headers,
        scheme=request.url.scheme or "http",
        netloc=getattr(request.url, "netloc", "") or request.headers.get("host", "127.0.0.1"),
        scope=getattr(request, "scope", {}),
    )
    return await gateway_image_generations_media_job(
        submit_request,  # type: ignore[arg-type]
    )


@app.post("/gateway/v1/media/jobs/image-generations")
async def gateway_image_generations_media_job(request: Request):
    """Submit durable, pollable image generation work through media jobs."""
    auth_context = _gateway_auth_context(
        request,
        "/gateway/v1/media/jobs/image-generations",
    )
    if isinstance(auth_context, Response):
        return auth_context

    receipt = start_image_route_receipt(
        "/gateway/v1/media/jobs/image-generations",
        auth_context,
    )
    decision = _apply_image_route_policy(receipt, auth_context)
    if decision.denied:
        response = _policy_denied_response(decision)
        finish_image_route_receipt(receipt, response)
        return response

    try:
        body = await request.json()
    except Exception:
        _record_image_input(receipt, "body", rejected_reason="invalid_json")
        response = Response(
            content=json.dumps({"error": {"message": "Invalid JSON body", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )
        finish_image_route_receipt(receipt, response)
        return response
    if not isinstance(body, Mapping):
        _record_image_input(receipt, "body", rejected_reason="not_object")
        response = Response(
            content=json.dumps({"error": {"message": "JSON body must be an object", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )
        finish_image_route_receipt(receipt, response)
        return response

    idempotency_key = request.headers.get("idempotency-key")
    invalid_controls = _note_media_metadata_body(body)
    if invalid_controls is not None:
        finish_image_route_receipt(receipt, invalid_controls)
        return invalid_controls
    # A full workflow id names the same workflow as its short name; the job
    # runs it by the short name the image route takes.
    requested_name = body.get("model")
    if isinstance(requested_name, str) and requested_name.startswith("image.generate."):
        short_name = requested_name.removeprefix("image.generate.")
        if _find_image_manifest("image.generate", short_name) is not None:
            body = {**body, "model": short_name}
    request_id, request_hash, idempotency = _image_media_job_request_id(
        body=body,
        auth_context=auth_context,
        idempotency_key=idempotency_key.strip() if idempotency_key else None,
        fallback_request_id=receipt.request_id,
    )
    existing = media_jobs.get_by_request_id(
        request_id,
        audience="internal",
        path=media_jobs.DB_PATH,
    )
    if existing is not None:
        if existing.get("status") in {media_jobs.STATUS_QUEUED, media_jobs.STATUS_RUNNING}:
            job_id = str(existing.get("job_id") or "")
            if job_id and _has_image_media_job_payload(job_id):
                _schedule_image_media_job(job_id)
        response = _image_media_job_response(existing, request)
        finish_image_route_receipt(receipt, response)
        return response

    from gateway.engine_protocol import dispatch as protocol_dispatch
    try:
        protocol_target = protocol_dispatch.resolve(ADMIN_STORE.get_service_registry(), body.get("model"), "images")
    except ProtocolError as error:
        response = _protocol_failure(error)
        finish_image_route_receipt(receipt, response)
        return response
    if protocol_target is not None:
        receipt.backend = protocol_target.engine_id
    model = str(body.get("model", COMFY_DEFAULT_MODEL))
    manifest = _find_image_manifest("image.generate", model)
    if receipt is not None:
        receipt.requested_workflow = model
        if manifest is not None:
            receipt.resolved_workflow = str(manifest.get("id") or model)
            identity = manifest_identity(manifest)
            receipt.attach_manifest(
                manifest_id=identity.id,
                manifest_version=identity.version,
                manifest_hash=identity.manifest_hash,
            )
        else:
            _attach_image_manifest_if_available(receipt, "image.generate", model)
    decision = _apply_image_route_policy(
        receipt,
        auth_context,
        model=model,
        workflow=_policy_workflow_for_receipt(receipt),
        manifest=manifest,
    )
    if decision.denied:
        response = _policy_denied_response(decision)
        finish_image_route_receipt(receipt, response)
        return response
    admission_response = _media_job_admission_response("image.generate", receipt=receipt)
    if admission_response is not None:
        finish_image_route_receipt(receipt, admission_response)
        return admission_response
    target_decision = _workflow_target_policy_decision(
        auth_context,
        requested=model,
        resolved=receipt.resolved_workflow if receipt is not None else None,
        manifest=manifest,
        extra_ids=(
            [_policy_workflow_for_receipt(receipt)]
            if _policy_workflow_for_receipt(receipt)
            else ()
        ),
    )
    if target_decision is not None and target_decision.denied:
        response = _policy_denied_response(target_decision)
        finish_image_route_receipt(receipt, response)
        return response

    job = media_jobs.MediaJob(
        intent="image.generate",
        workflow=f"image.generate.{model}",
        backend=receipt.backend,
        request_id=request_id,
        app_profile=plan_ref(auth_context.identity),
        api_key_name=auth_context.identity.name if auth_context.identity else None,
        parent_request_id=receipt.request_id,
        metadata=_safe_image_media_job_metadata(
            body=body,
            request_hash=request_hash,
            idempotency=idempotency,
        ),
    )

    try:
        _persist_image_media_job_payload(
            job.job_id,
            body=body,
            request=request,
            auth_context=auth_context,
        )
        job.owner_key_hash = auth_context.identity.key_hash if auth_context.identity else None
        job.app_id = auth_context.identity.app_id if auth_context.identity else None
        created = media_jobs.create(job, input_data=body, path=media_jobs.DB_PATH)
    except EphemeralMediaPayloadCapacityError:
        _delete_image_media_job_payload(job.job_id)
        response = _ephemeral_media_payload_busy_response()
        finish_image_route_receipt(receipt, response)
        return response
    except Exception as exc:  # noqa: BLE001
        _delete_image_media_job_payload(job.job_id)
        response = Response(
            content=json.dumps({
                "error": {
                    "message": f"Could not create image media job: {type(exc).__name__}",
                    "type": "api_error",
                }
            }),
            status_code=500,
            media_type="application/json",
        )
        finish_image_route_receipt(receipt, response)
        return response

    if created.job_id != job.job_id:
        _delete_image_media_job_payload(job.job_id)
        created_dict = created.to_dict("internal")
        response = _image_media_job_response(created_dict, request)
        finish_image_route_receipt(receipt, response)
        return response

    try:
        media_jobs.append_event(
            job.job_id,
            "queued",
            {
                "phase": "queued",
                "status": media_jobs.STATUS_QUEUED,
                "progress": 0,
            },
            path=media_jobs.DB_PATH,
        )
    except Exception:
        pass
    _schedule_image_media_job(job.job_id)
    created_dict = created.to_dict("internal")
    response = _image_media_job_response(created_dict, request, status_code=202)
    finish_image_route_receipt(receipt, response)
    return response


async def gateway_media_job_content(job_id: str, request: Request):
    """Return signed output asset handles for a completed gateway media job."""
    auth_context = _gateway_auth_context(
        request,
        "/gateway/v1/media/jobs/{job_id}/content",
    )
    if isinstance(auth_context, Response):
        return auth_context
    preflight_response = _media_job_content_preflight_response(auth_context)
    if preflight_response is not None:
        return preflight_response
    job = media_jobs.get(job_id, audience="internal", path=media_jobs.DB_PATH)
    if job is not None and not _gateway_record_authorizer(request, "media_job", job):
        return JSONResponse({"error": {"code": "media_job_not_found", "message": "Media job not found."}}, status_code=404)
    # Signed URLs minted below carry the delivery mode: the GET's own query
    # override, else the choice made when the job was submitted, else the
    # caller's profile default.
    delivery = _begin_media_delivery(auth_context)
    metadata_error = _note_media_metadata_query(request)
    if metadata_error is not None:
        return metadata_error
    if delivery.requested_mode is None and job is not None:
        submitted = (job.get("metadata") or {}).get("metadata_mode")
        if submitted in provenance.METADATA_MODES:
            delivery.requested_mode = submitted
    if job is None:
        return Response(
            content=json.dumps({
                "error": {
                    "message": f"media job {job_id!r} not found",
                    "type": "invalid_request_error",
                    "code": "media_job_not_found",
                }
            }),
            status_code=404,
            media_type="application/json",
        )
    route_policy = _media_job_content_route_policy(job)
    if route_policy is not None:
        policy_response = (await asyncio.to_thread(_enforce_runtime_route_policy, auth_context,
            "/gateway/v1/media/jobs/{job_id}/content",
            policy=route_policy,))
        if policy_response is not None:
            return policy_response
    status_value = str(job.get("status") or "")
    if status_value != media_jobs.STATUS_SUCCEEDED:
        return Response(
            content=json.dumps({
                "error": {
                    "message": f"media job is {status_value or 'unknown'}",
                    "type": "invalid_request_error",
                    "code": "media_job_not_ready",
                    "status": status_value,
                }
            }),
            status_code=409,
            media_type="application/json",
        )
    intent = str(job.get("intent") or "")
    if intent == "image.generate":
        payload = _openai_image_payload_from_media_job(job)
        missing_message = "media job has no image assets"
    elif intent == _IDENTITY_JOB_INTENT:
        payload = _identity_payload_from_media_job(job)
        missing_message = "media job has no image assets"
    elif intent in _AUDIO_MEDIA_JOB_INTENTS:
        payload = _openai_audio_payload_from_media_job(job, request)
        missing_message = "media job has no audio assets"
    elif intent == INTENT_VIDEO_GENERATE:
        payload = _openai_video_payload_from_media_job(job, request)
        missing_message = "media job has no video assets"
    else:
        return Response(
            content=json.dumps({
                "error": {
                    "message": f"media job content is not implemented for {intent or 'unknown'} jobs",
                    "type": "invalid_request_error",
                    "code": "unsupported_media_job_content",
                }
            }),
            status_code=400,
            media_type="application/json",
        )
    if not payload["data"]:
        return Response(
            content=json.dumps({
                "error": {
                    "message": missing_message,
                    "type": "api_error",
                    "code": "media_job_assets_missing",
                }
            }),
            status_code=502,
            media_type="application/json",
        )
    return Response(
        content=json.dumps(payload),
        status_code=200,
        media_type="application/json",
    )


async def images_generations(request: Request):
    """OpenAI-compatible image generation endpoint - routes to ComfyUI backend."""
    auth_context = (await asyncio.to_thread(authenticate_request, request, "/v1/images/generations"))
