@app.get("/gateway/v1/assets/{asset_id}")
async def gateway_asset_metadata(asset_id: str, request: Request):
    """Return gateway-native metadata for a generated asset handle."""
    auth_context = _gateway_auth_context(request, "/gateway/v1/assets/{asset_id}")
    if isinstance(auth_context, Response):
        return auth_context
    _begin_media_delivery(auth_context)  # content_url below carries the delivery mode
    metadata_error = _note_media_metadata_query(request)
    if metadata_error is not None:
        return metadata_error
    parsed = _parse_asset_id(asset_id)
    if parsed is None:
        return Response(
            content=json.dumps({"error": {"message": "Invalid asset id", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )
    route_policy = _asset_content_route_policy(asset_id)
    if route_policy is not None:
        policy_response = (await asyncio.to_thread(_enforce_runtime_route_policy, auth_context,
            "/gateway/v1/assets/{asset_id}",
            policy=route_policy,))
        if policy_response is not None:
            return policy_response
    cache_path = asset_cache_path(asset_id)
    if cache_path is None or not cache_path.exists():
        return Response(
            content=json.dumps({"error": {"message": "Asset not found (may have been evicted)", "type": "invalid_request_error"}}),
            status_code=404,
            media_type="application/json",
        )
    if auth_context is not None and not _asset_access_allowed(asset_id, auth_context):
        return Response(
            content=json.dumps({
                "error": {
                    "message": "Asset is not accessible for this API key",
                    "type": "invalid_request_error",
                }
            }),
            status_code=403,
            media_type="application/json",
        )
    return Response(
        content=json.dumps(_gateway_asset_metadata_payload(asset_id, request, cache_path=cache_path)),
        status_code=200,
        media_type="application/json",
    )


@app.get("/v1/assets/{asset_id}/thumbnail", openapi_extra=SIGNED_THUMBNAIL_OPENAPI, response_class=Response)
async def assets_thumbnail(asset_id: str, request: Request):
    """Serve a small WebP preview of an asset named by a signed thumbnail URL."""
    return await asyncio.to_thread(_signed_asset_thumbnail_response, asset_id, request)


def _signed_asset_thumbnail_response(asset_id: str, request: Request) -> Response:
    def refuse(status: int, message: str) -> Response:
        return Response(
            content=json.dumps({"error": {"message": message, "type": "invalid_request_error"}}),
            status_code=status, media_type="application/json",
        )

    try:
        expires = int(request.query_params.get("expires", ""))
    except ValueError:
        return refuse(400, "expires must be an integer")
    # Only a thumbnail-signed URL passes: a content URL's signature covers md=none|full.
    if not verify_asset_signature(asset_id, expires, request.query_params.get("sig", ""), thumbnails.THUMB_MODE):
        return refuse(403, "Invalid or expired signature")
    source = asset_cache_path(asset_id)
    if source is None:
        return refuse(400, "Invalid asset id")
    made = thumbnails.thumbnail_for(source)
    if made is None:
        return refuse(404, "No preview for this asset")
    stat = made.stat()
    etag = f'"{stat.st_mtime_ns:x}-{stat.st_size:x}"'
    headers = {"Cache-Control": "private, max-age=3600", "ETag": etag}
    if request.headers.get("if-none-match") == etag:
        return Response(status_code=304, headers=headers)
    return Response(content=made.read_bytes(), media_type=thumbnails.THUMB_MEDIA_TYPE, headers=headers)


@app.get("/gateway/v1/assets/{asset_id}/content")
async def gateway_asset_content(asset_id: str, request: Request):
    """Serve a cached generated asset through the gateway-native asset surface."""
    return await asyncio.to_thread(
        _signed_asset_content_response,
        asset_id,
        request,
        invalid_message="Invalid asset id",
        missing_message="Asset not found (may have been evicted)",
    )


def _signed_asset_content_response(
    asset_id: str,
    request: Request,
    *,
    invalid_message: str,
    missing_message: str,
    image_only: bool = False,
    auth_context: AuthContext | None = None,
) -> Response:
    expires_raw = request.query_params.get("expires", "")
    sig = request.query_params.get("sig", "")
    try:
        expires = int(expires_raw)
    except (TypeError, ValueError):
        return Response(
            content=json.dumps({"error": {"message": "expires must be an integer", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )
    if not sig:
        return Response(
            content=json.dumps({"error": {"message": "Signature required", "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )
    # md is covered by the signature. A URL without it predates the control and
    # is delivered metadata-free (safe default).
    md_raw = request.query_params.get("md")
    if md_raw is not None and md_raw not in provenance.METADATA_MODES:
        return Response(
            content=json.dumps({"error": {"message": "Invalid or expired signature", "type": "invalid_request_error"}}),
            status_code=403,
            media_type="application/json",
        )
    if not verify_asset_signature(asset_id, expires, sig, md_raw):
        return Response(
            content=json.dumps({"error": {"message": "Invalid or expired signature", "type": "invalid_request_error"}}),
            status_code=403,
            media_type="application/json",
        )

    cache_path = image_cache_path(asset_id) if image_only else asset_cache_path(asset_id)
    if cache_path is None:
        return Response(
            content=json.dumps({"error": {"message": invalid_message, "type": "invalid_request_error"}}),
            status_code=400,
            media_type="application/json",
        )
    if not cache_path.exists():
        return Response(
            content=json.dumps({"error": {"message": missing_message, "type": "invalid_request_error"}}),
            status_code=404,
            media_type="application/json",
        )
    if auth_context is not None and not _asset_access_allowed(asset_id, auth_context):
        return Response(
            content=json.dumps({
                "error": {
                    "message": "Asset is not accessible for this API key",
                    "type": "invalid_request_error",
                }
            }),
            status_code=403,
            media_type="application/json",
        )

    data = cache_path.read_bytes()
    if md_raw == provenance.METADATA_FULL:
        person_id: str | None = None
        if auth_context is None:
            checked = authenticate_request(request, "/v1/assets/{asset_id}/content")
            if not isinstance(checked, Response):
                auth_context = checked
        if auth_context is not None:
            person_id = _auth_person_id(auth_context)
        identity = getattr(auth_context, "identity", None)
        key_hash = getattr(identity, "key_hash", "") or ""
        if identity is None or (not getattr(identity, "app_id", None) and not key_hash.startswith("sha256:")):
            # A synthetic LAN/path identity has no person. A signed browser
            # session can supply one, but never override a real credential.
            session = _oidc_session_from_request(request)
            person_id = str(session.subject) if session is not None else None
        record = prompt_memory.get(asset_id, person_id) if person_id else None
        if record is None or prompt_memory.household_settings(admin_path=ADMIN_STORE.path)["never_keep"]:
            return JSONResponse({"error": {"code": "prompt_not_accessible", "message": "Full metadata is available only to the maker while their prompt is kept."}}, status_code=403)
        data = prompt_memory.restore_metadata(data, cache_path.suffix, record["metadata"])
    try:
        data = media_delivery.deliver_bytes(
            data, cache_path.suffix, md_raw or provenance.METADATA_NONE
        )
    except media_metadata.MediaMetadataError as exc:
        print(f"[proxy] metadata strip failed for {asset_id}: {exc}", flush=True)
        return Response(
            content=json.dumps({"error": {"message": "Could not prepare asset for delivery", "type": "api_error"}}),
            status_code=502,
            media_type="application/json",
        )
    return media_delivery.ranged_delivery_response(
        request,
        data,
        media_type=asset_media_type(asset_id, cache_path),
        cache_control="private, max-age=3600",
    )


async def _execute_video_manifest_workflow(request: Request, workflow_id: str, auth_context: AuthContext) -> Response:
    """Run an upload-driven video-edit manifest and return its rendered asset."""
    record = GATEWAY_WORKFLOW_REGISTRY.get(workflow_id)
    if record is None or record.intent != "video.edit":
        record = next(
            (item for item in GATEWAY_WORKFLOW_REGISTRY.records()
             if item.intent == "video.edit" and item.id.rsplit(".", 1)[-1] == workflow_id),
            None,
        )
    if record is None:
        return Response(
            content=json.dumps({"error": {"message": "Unknown video-edit workflow", "type": "invalid_request_error"}}),
            status_code=404, media_type="application/json",
        )
    admission = _dispatch_admission_response(
        "video.edit", auth_context=auth_context, service_id="comfyui",
        service_available=COMFY_ENABLED, resource_class="video", queue_key=_MEDIA_JOB_QUEUE_KEY,
    )
    if admission is not None:
        return admission
    binding = (record.manifest.get("bindings") or {}).get("comfyui")
    artifact = binding.get("workflow") if isinstance(binding, Mapping) else None
    if not isinstance(artifact, str):
        return Response(
            content=json.dumps({"error": {"message": "Workflow has no ComfyUI binding", "type": "api_error"}}),
            status_code=501, media_type="application/json",
        )
    workflow_path = Path(__file__).parent / artifact
    try:
        form = await request.form()
        input_specs = record.manifest.get("inputs") or {}
        _begin_media_delivery(auth_context)
        metadata_field = f"extensions[{WORKFLOW_EXTENSION_NAMESPACE}][{provenance.METADATA_CONTROL}]"
        form_fields = set(form.keys())
        prompt_mode_field = f"extensions[{prompt_memory.NAMESPACE}][mode]"
        controls = multipart_extensions(form.get("extensions"))
        if form.get(metadata_field) is not None:
            controls[WORKFLOW_EXTENSION_NAMESPACE] = {provenance.METADATA_CONTROL: form.get(metadata_field)}
        if form.get(prompt_mode_field) is not None:
            controls[prompt_memory.NAMESPACE] = {"mode": form.get(prompt_mode_field)}
        unknown_fields = form_fields - set(input_specs) - {"extensions", metadata_field, prompt_mode_field}
        if unknown_fields:
            raise ValueError(f"unknown workflow input: {sorted(unknown_fields)[0]}")
        supplied: dict[str, Any] = {}
        asset_uploads: dict[str, tuple[str, bytes, str]] = {}
        for name, spec in input_specs.items():
            raw = form.get(name)
            if spec.get("type") == "asset":
                if raw is None or not hasattr(raw, "read"):
                    continue
                raw_bytes = await raw.read()
                if not raw_bytes:
                    raise ValueError(f"{name} file is empty")
                asset_uploads[name] = (
                    Path(getattr(raw, "filename", name) or name).name,
                    raw_bytes,
                    getattr(raw, "content_type", None) or "application/octet-stream",
                )
                supplied[name] = "upload"
                continue
            if raw is None:
                continue
            try:
                input_type = spec.get("type", "string")
                if input_type == "integer":
                    supplied[name] = int(raw)
                elif input_type == "number":
                    supplied[name] = float(raw)
                elif input_type == "boolean":
                    lowered = str(raw).lower()
                    if lowered not in {"true", "false"}:
                        raise ValueError(f"{name} must be true or false")
                    supplied[name] = lowered == "true"
                else:
                    supplied[name] = str(raw)
            except (TypeError, ValueError) as exc:
                raise ValueError(f"invalid value for {name}") from exc
        memory_error = _note_media_metadata_body({**supplied, "extensions": controls})
        if memory_error is not None:
            return memory_error
        validation = validate_inputs(record.manifest, supplied)
        if validation.rejected:
            raise ValueError(next(iter(validation.rejected.values())))
        workflow_template = json.loads(workflow_path.read_text(encoding="utf-8"))
        workflow_template.pop("_meta", None)
    except ValueError as exc:
        return Response(
            content=json.dumps({"error": {"message": str(exc), "type": "invalid_request_error"}}),
            status_code=400, media_type="application/json",
        )
    except (OSError, json.JSONDecodeError, ManifestError) as exc:
        return Response(
            content=json.dumps({"error": {"message": f"Could not load workflow: {type(exc).__name__}", "type": "api_error"}}),
            status_code=500, media_type="application/json",
        )

    headers = configured_downstream_headers(auth_context, "comfyui")
    async with httpx.AsyncClient(timeout=httpx.Timeout(COMFY_TIMEOUT, connect=10)) as client:
        for input_name, (filename, raw_bytes, content_type) in asset_uploads.items():
            upload = await client.post(
                f"{COMFY_HOST}/upload/image", headers=headers,
                files={"image": (filename, raw_bytes, content_type)},
            )
            uploaded_name = upload.json().get("name") if upload.status_code == 200 else None
            if not uploaded_name:
                return Response(
                    content=json.dumps({"error": {"message": f"ComfyUI upload failed for {input_name}", "type": "api_error"}}),
                    status_code=502, media_type="application/json",
                )
            validation.accepted[input_name] = uploaded_name
        workflow = bind_backend_request(
            record.manifest, "comfyui", workflow_template, validation.accepted
        ).request

        async def submit_and_collect() -> tuple[dict[str, Any] | None, Response | None]:
            admission = _dispatch_admission_response(
                "video.edit", auth_context=auth_context, service_id="comfyui",
                service_available=COMFY_ENABLED, resource_class="video", queue_key=_MEDIA_JOB_QUEUE_KEY,
            )
            if admission is not None:
                return None, admission
            submitted = await client.post(
                f"{COMFY_HOST}/prompt", headers=headers,
                json=_build_comfy_submit_payload(workflow),
            )
            if submitted.status_code != 200:
                return None, Response(
                    content=json.dumps({"error": {"message": submitted.text[:500], "type": "api_error"}}),
                    status_code=502, media_type="application/json",
                )
            prompt_id = submitted.json().get("prompt_id")
            if not prompt_id:
                return None, Response(
                    content=json.dumps({"error": {"message": "ComfyUI returned no prompt_id", "type": "api_error"}}),
                    status_code=502, media_type="application/json",
                )
            for _ in range(COMFY_TIMEOUT * 2):
                await asyncio.sleep(0.5)
                history = await client.get(f"{COMFY_HOST}/history/{prompt_id}", headers=headers)
                job = history.json().get(prompt_id) if history.status_code == 200 else None
                if not isinstance(job, Mapping):
                    continue
                error_message = _comfy_execution_error_message(job)
                if error_message:
                    return dict(job), Response(
                        content=json.dumps({"error": {"message": error_message, "type": "api_error"}}),
                        status_code=502, media_type="application/json",
                    )
                if job.get("status", {}).get("completed"):
                    return dict(job), None
            return None, Response(
                content=json.dumps({"error": {"message": "Video workflow timed out", "type": "api_error"}}),
                status_code=504, media_type="application/json",
            )

        job, error = await submit_and_collect()
        if error is not None and IMAGE_FREE_VRAM_ON_EXHAUSTION:
            message = str((json.loads(error.body.decode("utf-8")).get("error") or {}).get("message", "")).lower()
            if any(marker in message for marker in ("cuda out of memory", "out of memory", "cuda oom")):
                if await _free_comfy_models_if_idle(client):
                    job, error = await submit_and_collect()
        if error is not None:
            return error
        file_info = _extract_video_output(job or {})
        if not file_info:
            return Response(
                content=json.dumps({"error": {"message": "Workflow returned no video output", "type": "api_error"}}),
                status_code=502, media_type="application/json",
            )
        params = {"filename": file_info["filename"], "type": file_info["type"]}
        if file_info.get("subfolder"):
            params["subfolder"] = file_info["subfolder"]
        rendered = await client.get(f"{COMFY_HOST}/view", headers=headers, params=params)
        if rendered.status_code != 200:
            return Response(
                content=json.dumps({"error": {"message": "ComfyUI could not read the rendered video", "type": "api_error"}}),
                status_code=502, media_type="application/json",
            )
        suffix = Path(file_info["filename"]).suffix.lower()
        media_type = {".mp4": "video/mp4", ".webm": "video/webm", ".mov": "video/quicktime", ".mkv": "video/x-matroska"}.get(suffix, "application/octet-stream")
        rendered_bytes = rendered.content
        try:
            if media_delivery.current_mode() == provenance.METADATA_NONE:
                rendered_bytes = await asyncio.to_thread(
                    media_delivery.deliver_bytes, rendered_bytes, suffix, provenance.METADATA_NONE
                )
            else:
                identity = manifest_identity(record.manifest)
                rendered_bytes = await asyncio.to_thread(
                    media_delivery.attach_provenance,
                    rendered_bytes,
                    suffix,
                    provenance.build_provenance_record(
                        kind="video",
                        requested_model=workflow_id,
                        resolved_model=record.id,
                        workflow_id=identity.id,
                        workflow_version=identity.version,
                        workflow_hash=identity.manifest_hash,
                        backend="comfyui",
                        parameters=validation.accepted,
                    ),
                )
        except media_metadata.MediaMetadataError as exc:
            print(f"[proxy] workflow run metadata rewrite failed: {exc}", flush=True)
            return Response(
                content=json.dumps({"error": {"message": "Could not prepare video for delivery", "type": "api_error"}}),
                status_code=502, media_type="application/json",
            )
        return Response(
            content=rendered_bytes, status_code=200, media_type=media_type,
            headers={"Content-Disposition": f'inline; filename="{Path(file_info["filename"]).name}"', "X-Workflow-ID": record.id},
        )


@app.post("/gateway/v1/workflows/{workflow_id}/run")
async def run_video_manifest_workflow(workflow_id: str, request: Request):
    auth_context = _gateway_auth_context(request, "/gateway/v1/workflows/{workflow_id}/run")
    if isinstance(auth_context, Response):
        return auth_context
    if not COMFY_ENABLED:
        return Response(status_code=503, content=json.dumps({"error": {"message": "ComfyUI media backend is disabled", "type": "service_unavailable"}}), media_type="application/json")
    policy_response = (await asyncio.to_thread(_enforce_runtime_route_policy, auth_context, "/gateway/v1/workflows/{workflow_id}/run"))
    if policy_response is not None:
        return policy_response
    record = GATEWAY_WORKFLOW_REGISTRY.get(workflow_id)
    if record is None:
        record = next(
            (item for item in GATEWAY_WORKFLOW_REGISTRY.records()
             if item.intent == "video.edit" and item.id.rsplit(".", 1)[-1] == workflow_id),
            None,
        )
    if record is not None:
        target_decision = _workflow_target_policy_decision(
            auth_context,
            requested=workflow_id,
            resolved=record.id,
            manifest=record.manifest,
            extra_ids=(record.id,),
        )
        if target_decision is not None and target_decision.denied:
            return _policy_denied_response(target_decision)
    return await _execute_video_manifest_workflow(request, workflow_id, auth_context)


